def _bmrbd_versioned_html(raw_bytes):
    """Inject BMRBD_VERSION into a served HTML shell (bytes in/out)."""
    return raw_bytes.replace(b"__BMRBD_VERSION__", BMRBD_VERSION.encode("utf-8"))


OLLAMA_CEILING_GB = 58.0


def v62_engine_for_size(size_gb):
    """Engine routing by size class. Returns (engine, reason)."""
    if size_gb is None:
        return "llama-server", "size unverified — llama-server mmap path (verify first)"
    if size_gb <= OLLAMA_CEILING_GB:
        return "ollama", "%.1f GB <= 58 GB Ollama ceiling" % size_gb
    return "llama-server", "%.1f GB > 58 GB — Ollama refuses (VRAM+RAM ~61 GB); llama-server mmap" % size_gb


def v62_engine_for_model(mid):
    src = MODEL_SWITCH_SOURCES.get(mid) or {}
    if src.get("engine"):
        return src["engine"], src.get("note") or ""
    est = src.get("est_gb") or src.get("size_gb")
    return v62_engine_for_size(est)

def _v62_gguf_metadata(gguf_path, want_keys):
    """Pure-python GGUF header parse (no llama.cpp needed). Reads the
    metadata key/values whose full keys are in want_keys; returns a dict
    (missing keys are absent). The file's own metadata is the authority."""
    import struct
    out = {}
    try:
        with open(gguf_path, "rb") as f:
            head = f.read(1 << 20)
        magic, _ver, _tcount, kv_count = struct.unpack_from("<I I Q Q", head, 0)
        if magic != 0x46554747:  # "GGUF"
            return out
        off = 24
        arch = None
        for _ in range(kv_count):
            if off + 8 > len(head):
                break
            klen = struct.unpack_from("<Q", head, off)[0]
            off += 8
            if off + klen > len(head):
                break
            key = head[off:off + klen].decode("utf-8", "replace")
            off += klen
            if off + 4 > len(head):
                break
            mtype = struct.unpack_from("<I", head, off)[0]
            off += 4
            val = None
            if mtype == 10:  # string
                if off + 8 > len(head):
                    break
                slen = struct.unpack_from("<Q", head, off)[0]
                off += 8
                val = head[off:off + slen].decode("utf-8", "replace")
                off += slen
            elif mtype == 4:
                val = struct.unpack_from("<I", head, off)[0]
                off += 4
            elif mtype == 5:
                val = struct.unpack_from("<i", head, off)[0]
                off += 4
            elif mtype == 6:
                val = struct.unpack_from("<f", head, off)[0]
                off += 4
            elif mtype == 7:
                val = struct.unpack_from("<B", head, off)[0]
                off += 1
            elif mtype == 8:
                val = struct.unpack_from("<Q", head, off)[0]
                off += 8
            elif mtype == 9:
                val = struct.unpack_from("<q", head, off)[0]
                off += 8
            elif mtype == 11:  # array — skip (only string arrays are common)
                if off + 12 > len(head):
                    break
                atype = struct.unpack_from("<I", head, off)[0]
                off += 4
                alen = struct.unpack_from("<Q", head, off)[0]
                off += 8
                esize = {4: 4, 5: 4, 6: 4, 7: 1, 8: 8, 9: 8, 0: 8, 1: 8, 2: 8, 3: 8}.get(atype, 8)
                for _ in range(alen):
                    if atype == 10:
                        if off + 8 > len(head):
                            break
                        sl = struct.unpack_from("<Q", head, off)[0]
                        off += 8 + sl
                    else:
                        off += esize
            else:
                break
            if key == "general.architecture":
                arch = val
            if key in want_keys:
                out[key] = val
            if arch and key == arch + ".context_length":
                out["__ctx__"] = val
        return out
    except Exception:
        return out


def _v62_gguf_context_length(gguf_path):
    """<arch>.context_length from a GGUF file's own metadata. None if the
    file cannot be read or carries no ctx (then the caller must not guess)."""
    md = _v62_gguf_metadata(gguf_path, set())
    return md.get("__ctx__")


def _v62_kv_bytes_per_token(gguf_path):
    """Rough q8_0 KV-cache bytes/token from GGUF metadata (layers x kv heads
    x head dim x 2 (K+V) x 1 byte; MLA models use the compressed latent
    cache: layers x (kv_lora_rank + qk_rope_head_dim) x 2). Used ONLY for
    the RAM cap, never for a speed claim. Falls back to a conservative
    300,000 B/token when the metadata is missing."""
    md = _v62_gguf_metadata(gguf_path, set())
    arch = None
    for k in md:
        if k.endswith(".block_count"):
            arch = k.rsplit(".block_count", 1)[0]
            break
    if not arch:
        return 300000
    layers = md.get(arch + ".block_count")
    if not layers:
        return 300000
    rope = md.get(arch + ".attention.qk_rope_head_dim") or 64
    lora = md.get(arch + ".attention.kv_lora_rank")
    if lora:  # MLA (DeepSeek): compressed latent KV cache
        return int(layers * (lora + rope) * 2)
    kv_heads = md.get(arch + ".attention.head_count_kv") or md.get(arch + ".attention.head_count") or 8
    head_dim = md.get(arch + ".attention.key_length") or md.get(arch + ".attention.value_length") or 128
    return int(layers * kv_heads * head_dim * 2)


def _v62_ctx_ram_cap(gguf_path):
    """Max ctx tokens the kernel's RAM can hold as KV cache (half of
    MemAvailable / KV-per-token). None when RAM cannot be read."""
    try:
        avail = None
        with open("/proc/meminfo") as f:
            for line in f:
                if line.startswith("MemAvailable:"):
                    avail = int(line.split()[1]) * 1024
                    break
        if not avail:
            return None
        kv = _v62_kv_bytes_per_token(gguf_path)
        return max(1024, int((avail * 0.5) // kv))
    except Exception:
        return None


def v62_effective_ctx(model_id, gguf_path=None, catalog_ctx=None):
    """Context for a model: catalog ctx first (MODEL_SWITCH_SOURCES row
    when catalog_ctx is not given), else the GGUF file's own metadata.
    NEVER a small fixed default — returns None (and logs why) when
    neither source has a ctx. When a GGUF path is given, the value is
    RAM-capped (min(ctx, floor(0.5 * free RAM / KV-per-token)) and the cap
    is logged honestly — the model's max ctx is NOT the kernel's real ctx."""
    ctx = catalog_ctx
    source = "catalog" if ctx else None
    if ctx is None:
        try:
            ctx = (MODEL_SWITCH_SOURCES.get(model_id) or {}).get("ctx")
            source = "catalog" if ctx else None
        except Exception:
            pass
    if ctx is None and gguf_path:
        ctx = _v62_gguf_context_length(gguf_path)
        source = "gguf-metadata" if ctx else None
    if ctx is None:
        return None
    if gguf_path:
        cap = _v62_ctx_ram_cap(gguf_path)
        if cap is not None and ctx > cap:
            ctx = cap
    return ctx


def v62_ollama_ctx(row, est=None):
    """Ollama-path num_ctx for hot-swap (bridge) and the notebook: the
    catalog ctx (per model), capped at 65536 — a VRAM-safe cap for 2xT4.
    Falls back to the old size bucket ONLY when the catalog carries no ctx
    (never invents a ctx, and never silently uses 4096 for a model whose
    catalog ctx is known)."""
    c = (row or {}).get("ctx")
    if c:
        return min(int(c), 65536)
    return 4096 if (est and est > 24.5) else 24576



def v62_build_llama_server_cmd(gguf_path, ctx_size=None, chat_template=None,
                               moe_cache_mib=10000, n_cpu_moe=None):
    """Corrected llama-server launch command (C1/C2). ctx_size is REQUIRED:
    resolve it with v62_effective_ctx() first — passing None raises loudly
    (llama-server's own 4096 default is never used silently)."""
    if ctx_size is None:
        raise ValueError("v62: ctx_size is required — resolve it with v62_effective_ctx() (catalog ctx, GGUF-metadata fallback, RAM cap); llama-server's own 4096 default is never used silently")
    cmd = ["llama-server", "-m", str(gguf_path),
           "--port", str(LLAMA_SERVER_PORT),
           "--load-mode", "mmap",
           "--fit", "off",
           "--cpu-moe",
           "--moe-cache-mib", str(moe_cache_mib),
           "--ctx-size", str(ctx_size),
           "--n-gpu-layers", "999",
           "--flash-attn", "on",
           "--cache-type-k", "q8_0", "--cache-type-v", "q8_0",
           "--no-warmup",
           "--batch-size", "512"]
    if n_cpu_moe:
        cmd += ["--n-cpu-moe", str(n_cpu_moe)]
    if chat_template:
        cmd += ["--chat-template", str(chat_template)]
    return cmd


def _v62_active_engine_info():
    """Which engine serves the CURRENT model, and why. The v62 notebook
    boot writes {"engine": ...} into /tmp/active_model_info.json; if it
    is absent (pre-v62 boot) fall back to the size lookup."""
    info = {}
    try:
        _p = Path("/tmp/active_model_info.json")
        if _p.exists():
            info = json.loads(_p.read_text(encoding="utf-8")) or {}
    except Exception:
        info = {}
    eng = str(info.get("engine") or "").strip()
    mid = str(info.get("model") or info.get("model_id") or "") or get_live_ollama_model()
    if eng in ("ollama", "llama-server", "colibri", "strata"):
        return eng, mid, "recorded by the v62 boot"
    eng2, why = v62_engine_for_model(mid)
    return eng2, mid, why


def _active_engine_base_url():
    eng, _mid, _why = _v62_active_engine_info()
    if eng == "colibri":
        return COLIBRI_URL
    if eng == "strata":
        return STRATA_URL
    return LLAMA_SERVER_URL if eng == "llama-server" else OLLAMA_URL


def _kill_engine_processes():
    """V10-23: kill every engine process on a remote stop.

    llama-server is launched by the notebook as a DETACHED daemon
    (start_new_session=True, its PID in /tmp/llama-server.pid), so it
    does NOT die when the bridge exits — it survives as an orphan until
    container teardown, holding the GPU + the port. Kill it three ways
    (best effort, never raises): (1) the PID file, (2) a ``pkill -f
    llama-server`` sweep as a backup for a stale/missing PID file, (3)
    the old ollama + cloudflared pkills. Every kill is wrapped, so a
    missing binary or a dead PID can never swallow the stop. The bridge
    argv is ``python3 /tmp/smart_bridge.py`` (and the kernel argv has no
    "llama-server" in it), so the pkill -f patterns cannot match the
    bridge itself. Returns the list of actions attempted.
    """
    actions = []
    for _pf in ("/tmp/llama-server.pid", "/tmp/llama_server.pid",
                "/tmp/ollama-server.pid", "/tmp/colibri-server.pid", "/tmp/strata-server.pid"):
        try:
            _pid = int(Path(_pf).read_text(encoding="utf-8").strip())
        except Exception:
            continue
        try:
            os.kill(_pid, 9)
            actions.append("kill -9 %d (from %s)" % (_pid, _pf))
        except Exception:
            pass
        try:
            Path(_pf).unlink(missing_ok=True)
        except Exception:
            pass
    for _pat in ("llama-server", "ollama", "cloudflared", "coli serve", "qwen38", "strata launch", "serve.server"):
        try:
            subprocess.run(["pkill", "-9", "-f", _pat], check=False)
            actions.append("pkill -9 -f %s" % _pat)
        except Exception:
            pass
    return actions


def _engine_verify(engine_url, pid, gguf_basename, probe_secs=60):
    """Q6 protocol, step by step. probe_secs is clamped to [5, 300].
    Returns a dict; overall pass needs models_ok AND chat_ok (mmap is
    reported, and a missing pid is reported as skipped, never faked)."""
    probe_secs = max(5, min(300, int(probe_secs or 60)))
    steps = {}
    # 1. /v1/models on the engine
    try:
        with urllib.request.urlopen(engine_url.rstrip("/") + "/v1/models", timeout=10) as r:
            _mj = json.loads(r.read().decode("utf-8", errors="ignore"))
            _ids = [str(d.get("id")) for d in (_mj.get("data") or []) if isinstance(d, dict)]
            steps["models"] = {"ok": True, "ids": _ids[:10], "count": len(_ids)}
    except Exception as e:
        steps["models"] = {"ok": False, "error": str(e)[:200]}
    # 2. /proc/<pid>/maps contains the gguf basename (mmap proof; a symlink
    #    resolves, so compare the basename, not the merged-dir path — C6.5)
    if pid:
        try:
            _maps = Path("/proc/%d/maps" % int(pid)).read_text(errors="ignore")
            _hit = bool(gguf_basename) and (gguf_basename in _maps)
            steps["mmap"] = {"ok": bool(_hit), "pid": int(pid),
                             "gguf": gguf_basename,
                             "note": "basename match in /proc/<pid>/maps" if _hit else "gguf basename NOT in maps — engine may not have the file mmap'd"}
        except Exception as e:
            steps["mmap"] = {"ok": False, "pid": int(pid), "error": str(e)[:200]}
    else:
        steps["mmap"] = {"ok": None, "skipped": True,
                         "note": "no engine pid recorded — mmap check skipped, not passed"}
    # 3. nvidia-smi
    try:
        _sm = subprocess.run(["nvidia-smi", "--query-gpu=memory.used,memory.total",
                              "--format=csv,noheader"], capture_output=True, text=True, timeout=15)
        steps["nvidia_smi"] = {"ok": _sm.returncode == 0,
                               "output": (_sm.stdout or _sm.stderr or "").strip()[:300]}
    except Exception as e:
        steps["nvidia_smi"] = {"ok": False, "error": str(e)[:200]}
    # 4. chat probe (non-streaming, tiny prompt) — tok/s is ESTIMATED until
    #    the live Q6 test measures it on the real kernel.
    t0 = time.time()
    try:
        _body = json.dumps({"model": "verify-probe", "messages": [{"role": "user", "content": "Reply with the single word OK."}], "max_tokens": 8, "stream": False}).encode("utf-8")
        _req = urllib.request.Request(engine_url.rstrip("/") + "/v1/chat/completions",
                                      data=_body, headers={"Content-Type": "application/json"}, method="POST")
        with urllib.request.urlopen(_req, timeout=probe_secs) as r:
            _cj = json.loads(r.read().decode("utf-8", errors="ignore"))
        _txt = ""
        try:
            _txt = str(_cj["choices"][0]["message"]["content"])
        except Exception:
            _txt = ""
        _dt = time.time() - t0
        steps["chat_probe"] = {"ok": True, "latency_s": round(_dt, 2),
                               "reply_preview": _txt[:40],
                               "tok_s": "ESTIMATED — single tiny probe, not a benchmark"}
    except Exception as e:
        steps["chat_probe"] = {"ok": False, "latency_s": round(time.time() - t0, 2),
                               "error": str(e)[:200]}
    overall = bool(steps["models"]["ok"] and steps["chat_probe"]["ok"])
    return {"ok": overall, "engine_url": engine_url, "probe_secs": probe_secs,
            "fit_off_warning": "--fit off does NOT cleanly abort (Issue #27872): a passing probe means the engine is up NOW, not that an unfit model will stay up.",
            "steps": steps}



# v61.1 clean default system prompt (natural, multilingual). This is the
# default for ALL turns; the old biased coding default was deleted.
_CLEAN_SYSTEM_PROMPT = "You are BMRBD Ai, a helpful, natural multilingual assistant. Answer directly and accurately in the user's language — natural, fluent Bengali when asked in Bengali, natural English when asked in English, and the same natural tone in any other language the user writes in. Be concise unless the user asks for detail, and write production-grade code when the user asks for code. When you are asked to change something in an earlier reply, never rewrite that reply in place: write a new reply with the updated section, a short summary, and a table titled 'Exactly which numbers changed?' (old value -> new value) for every change. If you cannot recall a fact from memory or the conversation, say so plainly — never invent an answer."
def _read_saved_active_model():
    # BMRBD v61.20 UI-FIX (2026-11-17): the GPU notebook's Cell 3 writes
    # /tmp/active_model_info.json with the TRUE loaded model id
    # ("model": MODEL_PRESET + "-mtp", e.g. deepseek-v4.1-flash-coder-back-mtp).
    # Read it FIRST so DEFAULT_MODEL (and /health, the UI pill, the catalog)
    # carry the real "-mtp" name instead of the bare preset. Falls back to
    # the env/file/preset chain below when the info file is absent.
    try:
        _ip = Path("/tmp/active_model_info.json")
        if _ip.exists():
            _saved = json.loads(_ip.read_text(encoding="utf-8"))
            if isinstance(_saved, dict):
                for _k in ("model", "model_id"):
                    _v = str(_saved.get(_k) or "").strip()
                    if _v:
                        return _v
                _preset = str(_saved.get("preset") or "").strip()
                if _preset:
                    return _preset + "-mtp"
    except Exception:
        pass
    env_m = os.environ.get("ACTIVE_MODEL_ID", "").strip()
    if env_m:
        return env_m
    try:
        p = Path("/tmp/active_model_id.txt")
        if p.exists():
            txt = p.read_text(encoding="utf-8").strip()
            if txt:
                return txt
    except Exception:
        pass
    return os.environ.get("MODEL_PRESET", "").strip() or "deepseek-v4.1-flash-552b-uncensored-mtp"

DEFAULT_MODEL = _read_saved_active_model()
_LIVE_MODEL_CACHE = {"model": DEFAULT_MODEL, "ts": 0.0, "installed": set()}
_LIVE_MODEL_LOCK = threading.Lock()

def get_live_ollama_model(requested_model=None):
    """
    Bulletproof Live GPU Model Resolver (v33 Zero-404 Guarantee):
      1. Checks `/api/ps` for any currently loaded GPU model.
      2. Checks `/api/tags` for installed models—if `DEFAULT_MODEL` is not in `/api/tags`
         (for example, when a cached model was linked under its `hf.co/...` tag),
         automatically switches `DEFAULT_MODEL` to the installed tag so `HTTP 404: model not found` NEVER occurs!
    """
    global DEFAULT_MODEL
    now = time.time()
    with _LIVE_MODEL_LOCK:
        if now - _LIVE_MODEL_CACHE["ts"] > 3.0:
            _LIVE_MODEL_CACHE["ts"] = now
            found_ps = False
            try:
                with urllib.request.urlopen(f"{OLLAMA_URL}/api/ps", timeout=1.2) as r:
                    ps_data = json.loads(r.read().decode("utf-8", errors="ignore"))
                    ps_models = ps_data.get("models") or []
                    if ps_models:
                        hot_name = str(ps_models[0].get("name") or ps_models[0].get("model") or "").strip()
                        if hot_name:
                            hot_clean = hot_name[:-7] if hot_name.endswith(":latest") else hot_name
                            _LIVE_MODEL_CACHE["model"] = hot_clean
                            DEFAULT_MODEL = hot_clean
                            found_ps = True
            except Exception:
                pass
            if not found_ps:
                try:
                    with urllib.request.urlopen(f"{OLLAMA_URL}/api/tags", timeout=1.5) as rt:
                        t_data = json.loads(rt.read().decode("utf-8", errors="ignore"))
                        t_models = t_data.get("models") or []
                        installed_names = []
                        for tm in t_models:
                            tn = str(tm.get("name") or tm.get("model") or "").strip()
                            if tn:
                                installed_names.append(tn[:-7] if tn.endswith(":latest") else tn)
                                installed_names.append(tn)
                        if installed_names:
                            if DEFAULT_MODEL not in installed_names and _LIVE_MODEL_CACHE["model"] not in installed_names:
                                best_inst = installed_names[0]
                                _LIVE_MODEL_CACHE["model"] = best_inst
                                DEFAULT_MODEL = best_inst
                except Exception:
                    pass
        return _LIVE_MODEL_CACHE["model"] or DEFAULT_MODEL

def get_true_model_identity_info():
    """
    Reads `/tmp/active_model_info.json` (written by Cell 3) + live Ollama `/api/ps` so the model
    ALWAYS knows its TRUE name, preset, HuggingFace GGUF repo, and 3-Tier hardware setup,
    and NEVER claims to be a fake model like Claude Sonnet/Opus or GPT-4o!
    """
    live_m = get_live_ollama_model()
    info = {
        "preset": os.environ.get("MODEL_PRESET", live_m),
        "model_id": live_m,
        "source_gguf": os.environ.get("SOURCE_MODEL", live_m),
        "speed_range": "50–85 tok/s (3B–6B Active MoE Turbo)" if "30b" in live_m or "48b" in live_m or "35b" in live_m else "22–45 tok/s (3-Tier GPU+RAM+SSD)",
        "safe_gpu_layers": int(os.environ.get("SAFE_GPU_LAYERS", "999")),
    }
    try:
        p = Path("/tmp/active_model_info.json")
        if p.exists():
            saved = json.loads(p.read_text(encoding="utf-8"))
            if isinstance(saved, dict):
                info.update({k: v for k, v in saved.items() if v is not None})
                # BMRBD v61.20 UI-FIX (2026-11-17): the saved file carries
                # "model" (with "-mtp") but not always "model_id" — keep
                # model_id in sync so the Models page JSON and the UI show
                # the true "-mtp" name, never the bare preset.
                _mid = str(saved.get("model_id") or saved.get("model") or "").strip()
                if _mid:
                    info["model_id"] = _mid
    except Exception:
        pass
    return info

def inspect_attached_media_b64(b64_or_url, media_hint="image"):
    """
    Server-side Multimodal Vision & File Inspector:
    Analyzes attached base64/URL images, icons, screenshots, or video frames using Python PIL (if available)
    or binary header inspection so even text/coding models get exact dimensions, format, color palette,
    and visual metadata alongside Ollama's native `images` array!
    """
    try:
        raw_b64 = str(b64_or_url or "").strip()
        if raw_b64.startswith("data:"):
            parts = raw_b64.split(",", 1)
            header = parts[0]
            raw_b64 = parts[1] if len(parts) > 1 else ""
        else:
            header = ""
        if not raw_b64 or raw_b64.startswith("http"):
            return None, f"[Attached Media URL: {raw_b64[:120]}]"
        img_bytes = base64.b64decode(raw_b64)
        summary = f"[Attached {media_hint.upper()}: {len(img_bytes)//1024} KB"
        try:
            from PIL import Image, ImageStat
            im = Image.open(io.BytesIO(img_bytes))
            w, h = im.size
            fmt = im.format or "PNG"
            mode = im.mode
            rgb_im = im.convert("RGB")
            stat = ImageStat.Stat(rgb_im)
            r_m, g_m, b_m = [int(x) for x in stat.mean[:3]]
            hex_avg = f"#{r_m:02x}{g_m:02x}{b_m:02x}"
            summary += f" | Format: {fmt} | Dimensions: {w}x{h}px ({mode}) | Dominant/Avg Color: {hex_avg} RGB({r_m},{g_m},{b_m})]"
        except Exception:
            summary += "]"
        return raw_b64, summary
    except Exception:
        return None, "[Attached Media File]"


