def _style_dir():
    # Looked up per call, not at import: a fresh kernel extracts the
    # asset after the bridge module is already imported, and tests
    # re-point MEDIA_STORE_DIR.
    return MEDIA_STORE_DIR / "styles"


def _style_catalog_payload():
    # Graceful degradation: if the styles asset was never extracted
    # (dir missing), answer with empty lists — never a 500 — and the
    # dashboard shows no style cards. Entries whose file is missing
    # from disk are dropped, so every returned URL is a real file.
    _sd = _style_dir()
    if not _sd.is_dir():
        return {"trending": [], "templates": []}
    _out = {}
    for _key in ("trending", "templates"):
        _rows = []
        for _e in _STYLE_CATALOG.get(_key, []):
            if (_sd / _e["image"]).is_file():
                _rows.append({
                    "id": _e["id"], "name": _e["name"], "desc": _e["desc"],
                    "prompt": _e["prompt"],
                    "needs_photo": bool(_e.get("needs_photo")),
                    "verbatim": bool(_e.get("verbatim")),
                    "url": "/media/styles/" + _e["image"],
                })
        _out[_key] = _rows
    return _out
