# v61.1 password storage: bcrypt when available, else per-user salted sha256
# with a fresh random salt per user. The old fixed salt ("bmrbd_salt") is NEVER
# used for new hashes; _verify_password only still recognises it so accounts
# restored from pre-v61.1 vaults can log in once and be upgraded.
def _hash_password(plain: str) -> str:
    try:
        import bcrypt
        return "bcrypt$" + bcrypt.hashpw(str(plain).encode("utf-8"), bcrypt.gensalt()).decode("ascii")
    except Exception:
        salt = os.urandom(16).hex()
        digest = hashlib.sha256((salt + "|" + str(plain)).encode("utf-8")).hexdigest()
        return "sha256$" + salt + "$" + digest

def _verify_password(plain: str, stored) -> bool:
    try:
        if not stored:
            return False
        if str(stored).startswith("bcrypt$"):
            import bcrypt
            return bcrypt.checkpw(str(plain).encode("utf-8"), str(stored)[7:].encode("ascii"))
        if str(stored).startswith("sha256$"):
            _, salt, digest = str(stored).split("$")
            return hmac.compare_digest(hashlib.sha256((salt + "|" + str(plain)).encode("utf-8")).hexdigest(), str(digest))
        # Legacy pre-v61.1 fixed-salt hash: verify only, caller upgrades it.
        return hmac.compare_digest(str(stored), hashlib.sha256((str(plain) + "|bmrbd_salt").encode("utf-8")).hexdigest())
    except Exception:
        return False

def _maybe_upgrade_pass_hash(u_obj: dict, plain: str) -> None:
    try:
        stored = str(u_obj.get("pass_hash") or "")
        if stored and not stored.startswith(("bcrypt$", "sha256$")):
            u_obj["pass_hash"] = _hash_password(plain)
            _save_bmrbd_state_local(push_peer=False)
    except Exception:
        pass
