def _encrypt_vault_bytes(raw_bytes: bytes) -> bytes:
    key = hashlib.pbkdf2_hmac("sha256", VAULT_SECRET_KEY.encode("utf-8"), b"bmrbd_vault_salt_v41", 50000, dklen=32)
    nonce = os.urandom(16)
    out = bytearray(len(raw_bytes))
    for blk_i in range(0, len(raw_bytes), 32):
        ks = hashlib.sha256(key + nonce + blk_i.to_bytes(8, "big")).digest()
        chunk = raw_bytes[blk_i:blk_i+32]
        for j, b_val in enumerate(chunk):
            out[blk_i + j] = b_val ^ ks[j]
    mac = hashlib.sha256(key + nonce + bytes(out)).digest()
    return b"BMRBDV41" + nonce + mac + bytes(out)

def _decrypt_vault_bytes(enc_bytes: bytes) -> bytes:
    if not enc_bytes or not enc_bytes.startswith(b"BMRBDV41") or len(enc_bytes) < 56:
        return b""
    key = hashlib.pbkdf2_hmac("sha256", VAULT_SECRET_KEY.encode("utf-8"), b"bmrbd_vault_salt_v41", 50000, dklen=32)
    nonce = enc_bytes[8:24]
    mac = enc_bytes[24:56]
    cipher = enc_bytes[56:]
    if hashlib.sha256(key + nonce + cipher).digest() != mac:
        return b""
    out = bytearray(len(cipher))
    for blk_i in range(0, len(cipher), 32):
        ks = hashlib.sha256(key + nonce + blk_i.to_bytes(8, "big")).digest()
        chunk = cipher[blk_i:blk_i+32]
        for j, b_val in enumerate(chunk):
            out[blk_i + j] = b_val ^ ks[j]
    return bytes(out)

_BMRBD_STATE.setdefault("user_skills", {})
_BMRBD_STATE.setdefault("user_connectors", {})
_BMRBD_STATE.setdefault("user_memory", {})
_BMRBD_STATE.setdefault("user_settings", {})
# BMRBD v61.15a WD2: shared scratch state that used to live only in RAM
# / /tmp and died with the kernel on rotation; it now travels inside
# the vault (vault.enc) exactly like users, threads and memories.
_BMRBD_STATE.setdefault("shared_browser_threads", [])
_BMRBD_STATE.setdefault("shared_schedules", [])
_BMRBD_STATE.setdefault("shared_chats", {})
# BMRBD v61.16 COORD (B3): scheduled + background tasks travel in the
# vault exactly like shared chats (v61.15a WD2) — their /tmp files die
# with the kernel on rotation.
_BMRBD_STATE.setdefault("scheduled_tasks", {})
_BMRBD_STATE.setdefault("bg_tasks", {})
_BMRBD_STATE.setdefault("scheduled_recommended_dismissed", {})  # BMRBD v61.17 TASK: dismissed Recommended keys travel in the vault
_BMRBD_STATE.setdefault("message_feedback", [])  # BMRBD v61.16 P2 (P2C): ratings + feedback travel in the vault
# BMRBD v76 §4 (Agent B): managed API keys + invites travel in the vault
# exactly like users (whole-state JSON in vault.enc + the locked zip; the
# Drive-persistence bundle holds the same whole state). Project-level usage
# is one shared window, so a new key never resets project quota.
_BMRBD_STATE.setdefault("api_keys", {})
_BMRBD_STATE.setdefault("api_key_project_usage", {"window_start": 0.0, "window_requests": 0, "window_tokens": 0, "tokens_total": 0})
_BMRBD_STATE.setdefault("invites", {})

def _build_locked_vault_zip_bytes() -> bytes:
    """
    v50 Password-Locked & AES/PBKDF2-Encrypted `.ZIP` Database Generator (`bmrbd_encrypted_user_vault.zip`):
    Packages all user accounts, chats, projects, custom skills, connectors, and schedules inside an encrypted
    `.zip` container locked with `VAULT_SECRET_KEY` so user data is 100% private and portable across
    Google Drive and Kaggle Datasets!
    """
    raw_state = json.dumps(_BMRBD_STATE, ensure_ascii=False, indent=2).encode("utf-8")
    enc_blob = _encrypt_vault_bytes(raw_state)
    zbuf = io.BytesIO()
    with zipfile.ZipFile(zbuf, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        zf.writestr("vault.enc", enc_blob)
        # Also store per-user encrypted chat snapshots inside `users_locked/`
        for uname, u_threads in (_BMRBD_STATE.get("user_threads") or {}).items():
            u_payload = json.dumps({
                "username": uname,
                "threads": u_threads,
                "projects": (_BMRBD_STATE.get("user_projects") or {}).get(uname, ["Default Project"]),
                "skills": (_BMRBD_STATE.get("user_skills") or {}).get(uname, []),
                "connectors": (_BMRBD_STATE.get("user_connectors") or {}).get(uname, {}),
                # BMRBD v61.15a WD2: the per-user snapshot used to omit
                # memory + settings (vault.enc had them, this copy did not).
                "memory": (_BMRBD_STATE.get("user_memory") or {}).get(uname, []),
                "settings": (_BMRBD_STATE.get("user_settings") or {}).get(uname, {}),
                "updated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
            }, ensure_ascii=False).encode("utf-8")
            zf.writestr(f"users_locked/{uname}.enc", _encrypt_vault_bytes(u_payload))
        # Also preserve recent generated downloadable files & media in `media_store/` (up to 15 MB total) so files NEVER disappear!
        if MEDIA_STORE_DIR.exists():
            total_m_bytes = 0
            for mp in sorted(MEDIA_STORE_DIR.iterdir(), key=lambda p: p.stat().st_mtime if p.exists() else 0, reverse=True):
                if mp.is_file() and mp.stat().st_size <= 4 * 1024 * 1024 and (total_m_bytes + mp.stat().st_size) <= 15 * 1024 * 1024:
                    try:
                        zf.writestr(f"media_store/{mp.name}", mp.read_bytes())
                        total_m_bytes += mp.stat().st_size
                    except Exception:
                        pass
        zf.writestr("VAULT_LOCK_INFO.txt", b"BMRBD Ai v60 Stealth Encrypted User & Media Database Vault (LOCKED)")
    return zbuf.getvalue()

def _push_vault_to_peer_domain_async():
    """
    Automatically pushes the encrypted vault to the peer BMRBD domain.
    BMRBD v61.9: the CPU peer domain was dropped 2026-11-10 - only the GPU domain remains.
    """
    def _worker():
        my_pub = str(os.environ.get("PUBLIC_URL") or "").lower()
        peers = ["https://ai2.bmrbd.xyz"]  # BMRBD v61.9: CPU peer dropped
        raw_state = json.dumps(_BMRBD_STATE, ensure_ascii=False).encode("utf-8")
        enc_b64 = base64.b64encode(_encrypt_vault_bytes(raw_state)).decode("ascii")
        body_b = json.dumps({"vault_b64": enc_b64, "ts": time.time()}).encode("utf-8")
        for p_url in peers:
            if p_url in my_pub:
                continue
            try:
                req = urllib.request.Request(
                    f"{p_url}/api/vault/peer_sync",
                    data=body_b,
                    headers={"Content-Type": "application/json", "User-Agent": "BMRBDAi-VaultSync/50.0", "Authorization": "Bearer " + MASTER_API_KEY},
                    method="POST"
                )
                urllib.request.urlopen(req, timeout=4).close()
            except Exception:
                pass
    threading.Thread(target=_worker, daemon=True).start()

def _pull_vault_from_peer_domain():
    my_pub = str(os.environ.get("PUBLIC_URL") or "").lower()
    peers = ["https://ai2.bmrbd.xyz"]  # BMRBD v61.9: CPU peer dropped
    for p_url in peers:
        if p_url in my_pub:
            continue
        try:
            req = urllib.request.Request(
                f"{p_url}/api/vault/peer_pull",
                headers={"User-Agent": "BMRBDAi-VaultSync/50.0", "Authorization": "Bearer " + MASTER_API_KEY}
            )
            with urllib.request.urlopen(req, timeout=4) as r:
                j = json.loads(r.read().decode("utf-8", errors="ignore"))
                vb64 = str(j.get("vault_b64") or "")
                if vb64:
                    dec = _decrypt_vault_bytes(base64.b64decode(vb64))
                    if dec:
                        peer_state = json.loads(dec.decode("utf-8"))
                        if isinstance(peer_state, dict) and "users" in peer_state:
                            for k_sec in ("user_threads", "user_projects", "user_skills", "user_connectors", "user_memory", "user_settings", "shared_chats", "scheduled_tasks", "bg_tasks", "scheduled_recommended_dismissed", "message_feedback"):  # BMRBD v61.16 COORD (B3) + BMRBD v61.17 TASK
                                if isinstance(peer_state.get(k_sec), dict):
                                    _BMRBD_STATE.setdefault(k_sec, {}).update(peer_state[k_sec])
                            for k_l in ("shared_browser_threads", "shared_schedules", "bug_reports"):
                                if isinstance(peer_state.get(k_l), list):
                                    _BMRBD_STATE[k_l] = list(peer_state[k_l])
                            _bmrbd_refresh_shared_state_from_vault()  # BMRBD v61.15a WD2; _c3_merge_auth_state(peer_state)  # BMRBD v76.5 C3: users/user_sessions merge without dropping the live login
                            return True
        except Exception:
            pass
    return False

def _save_bmrbd_state_local(push_peer: bool = True, mark_cloud_dirty: bool = True):
    try:
        raw = json.dumps(_BMRBD_STATE, ensure_ascii=False).encode("utf-8")
        BMRBD_STATE_FILE.write_bytes(raw)
        (BMRBD_DATA_DIR / "vault.enc").write_bytes(_encrypt_vault_bytes(raw))
        (BMRBD_DATA_DIR / "bmrbd_encrypted_user_vault.zip").write_bytes(_build_locked_vault_zip_bytes())
        if push_peer:
            _push_vault_to_peer_domain_async()
        # BMRBD v61.15a WD2: this local save is newer than the last cloud
        # push — the flush daemon picks it up. The cloud sync itself
        # passes mark_cloud_dirty=False so its own save cannot re-arm it.
        if mark_cloud_dirty:
            _bmrbd_mark_vault_cloud_dirty()
    except Exception:
        pass

def sync_bmrbd_vault_to_cloud() -> str:
    """
    Syncs encrypted user accounts, chats, projects, and quotas to:
      1. 1TB Google Drive (via `rclone` if configured in `GDRIVE_RCLONE_REMOTE`)
      2. Encrypted Kaggle Dataset (`marupibneyalid/bmrbd-ai-encrypted-vault`) so switching Kaggle accounts
         automatically preserves 100% of users, chats, and projects!
    """
    # BMRBD v61.15a WD2: dirty-flag bookkeeping for the flush daemon
    # (cleared at the tail of this function). The local save here must
    # not re-arm the flag, or every push would schedule another push.
    global _VAULT_CLOUD_LAST_SYNC_TS, _VAULT_CLOUD_DIRTY
    _bmrbd_cloud_sync_started_ts = time.time()
    _save_bmrbd_state_local(mark_cloud_dirty=False)
    notes = ["Saved locally"]
    webhook_u = (_BMRBD_STATE.get("settings") or {}).get("gdrive_webhook_url") or os.environ.get("GDRIVE_WEBHOOK_URL", "").strip()
    if webhook_u and webhook_u.startswith("https://script.google.com/macros/"):
        try:
            z_b64 = base64.b64encode(_build_locked_vault_zip_bytes()).decode("ascii")
            req_gd = urllib.request.Request(
                webhook_u,
                data=json.dumps({"action": "upload", "zip_b64": z_b64, "folder_id": GDRIVE_FOLDER_ID}).encode("utf-8"),
                headers={"Content-Type": "application/json", "User-Agent": "BMRBDAi-GDriveVault/53.0"},
                method="POST"
            )
            with urllib.request.urlopen(req_gd, timeout=20) as r_gd:
                notes.append(f"Synced to Google Drive Folder ({GDRIVE_FOLDER_ID})")
        except Exception as gd_e:
            notes.append(f"GDrive webhook note: {gd_e}")
    if GDRIVE_RCLONE_REMOTE and shutil.which("rclone"):
        try:
            subprocess.run(["rclone", "copy", str(BMRBD_DATA_DIR), f"{GDRIVE_RCLONE_REMOTE}:BMRBD_Ai_Vault"], timeout=30, check=False)
            notes.append("Synced to 1TB Google Drive")
        except Exception:
            pass
    if shutil.which("kaggle") and KAGGLE_VAULT_OWNER:
        try:
            stage = Path("/tmp/bmrbd_vault_stage")
            shutil.rmtree(stage, ignore_errors=True)
            stage.mkdir(parents=True, exist_ok=True)
            shutil.copy2(str(BMRBD_DATA_DIR / "vault.enc"), str(stage / "vault.enc"))
            meta = {
                "title": "BMRBD Ai Encrypted Vault Sync",
                "id": f"{KAGGLE_VAULT_OWNER}/{KAGGLE_VAULT_SLUG}",
                "licenses": [{"name": "CC0-1.0"}]
            }
            (stage / "dataset-metadata.json").write_text(json.dumps(meta, indent=2), encoding="utf-8")
            r1 = subprocess.run(["kaggle", "datasets", "create", "-p", str(stage), "--dir-mode", "tar", "-q"], capture_output=True, text=True, timeout=25)
            if r1.returncode != 0:
                subprocess.run(["kaggle", "datasets", "version", "-p", str(stage), "-m", "Auto-sync BMRBD Ai vault", "--dir-mode", "tar", "-q"], capture_output=True, text=True, timeout=25)
            shutil.rmtree(stage, ignore_errors=True)
            notes.append(f"Synced to Encrypted Kaggle Vault ({KAGGLE_VAULT_OWNER}/{KAGGLE_VAULT_SLUG})")
        except Exception:
            pass
    # BMRBD v61.15a WD2: this push just uploaded the current state —
    # clear the dirty flag unless a mutation landed mid-push (its
    # fresher timestamp keeps it dirty for the next flush) — and
    # restart the flush-interval clock so a manual/admin sync is not
    # immediately followed by a daemon re-upload of the same state.
    _VAULT_CLOUD_LAST_SYNC_TS = time.time()
    if _VAULT_CLOUD_DIRTY_TS <= _bmrbd_cloud_sync_started_ts:
        _VAULT_CLOUD_DIRTY = False
    return " · ".join(notes)

# ── BMRBD v61.15a WD2: vault cloud flush (A10) ──
# Every local save marks the cloud vault dirty; this daemon flushes it
# through the SAME sync_bmrbd_vault_to_cloud() after a short quiet
# period and at most once per interval, so a burst of thread edits
# costs one upload and a rotation at most ~quiet+interval of recent
# edits (a graceful shutdown sync is still the only lossless path).
_VAULT_CLOUD_DIRTY = False
_VAULT_CLOUD_DIRTY_TS = 0.0
_VAULT_CLOUD_LAST_SYNC_TS = time.time()
_VAULT_CLOUD_QUIET_S = 30.0
_VAULT_CLOUD_MIN_INTERVAL_S = 120.0
_VAULT_CLOUD_DAEMON_TICK_S = 30.0


def _bmrbd_mark_vault_cloud_dirty():
    """Mark the cloud vault stale after a local save. Cheap, idempotent."""
    global _VAULT_CLOUD_DIRTY, _VAULT_CLOUD_DIRTY_TS
    _VAULT_CLOUD_DIRTY = True
    _VAULT_CLOUD_DIRTY_TS = time.time()


def _bmrbd_vault_cloud_flush_daemon():
    """Background vault flusher: uploads the encrypted vault to Drive /
    Kaggle only when something changed, after _VAULT_CLOUD_QUIET_S of no
    further edits, and at most once per _VAULT_CLOUD_MIN_INTERVAL_S.
    The sleep is at the END of the loop so the first check runs at
    thread start instead of after a blind first tick, and it is
    capped at 0.5s and re-read from the global every iteration, so
    the loop notices a new save (or a changed tick) within ~0.5s;
    the quiet/interval gates above still throttle actual uploads."""
    while True:
        try:
            if _VAULT_CLOUD_DIRTY:
                _now = time.time()
                if _now - _VAULT_CLOUD_DIRTY_TS >= _VAULT_CLOUD_QUIET_S and _now - _VAULT_CLOUD_LAST_SYNC_TS >= _VAULT_CLOUD_MIN_INTERVAL_S:
                    sync_bmrbd_vault_to_cloud()
        except Exception:
            pass
        time.sleep(min(0.5, _VAULT_CLOUD_DAEMON_TICK_S))


def _bmrbd_sync_shared_state_to_vault():
    """Mirror the live shared scratch globals into _BMRBD_STATE and save
    locally (which marks the cloud vault dirty for the flush daemon)."""
    try:
        g = globals()
        if "_SHARED_BROWSER_THREADS" in g:
            _BMRBD_STATE["shared_browser_threads"] = list(_SHARED_BROWSER_THREADS)[:80]
        if "_SHARED_SCHEDULES" in g:
            _BMRBD_STATE["shared_schedules"] = list(_SHARED_SCHEDULES)
        if "_SHARED_CHATS" in g:
            _BMRBD_STATE["shared_chats"] = dict(_SHARED_CHATS)
        _save_bmrbd_state_local(push_peer=False)
    except Exception:
        pass


def _bmrbd_refresh_shared_state_from_vault():
    """Copy vault-restored shared lists/chats into the live module
    globals (and the /tmp share file). Safe to call before those
    globals exist (boot): it silently does nothing then; their
    definitions seed them from _BMRBD_STATE instead."""
    try:
        g = globals()
        if "_SHARED_BROWSER_THREADS" in g and "_SHARED_SYNC_LOCK" in g and isinstance(_BMRBD_STATE.get("shared_browser_threads"), list):
            with _SHARED_SYNC_LOCK:
                _SHARED_BROWSER_THREADS[:] = list(_BMRBD_STATE["shared_browser_threads"])[:80]
        if "_SHARED_SCHEDULES" in g and "_SHARED_SYNC_LOCK" in g and isinstance(_BMRBD_STATE.get("shared_schedules"), list):
            with _SHARED_SYNC_LOCK:
                _SHARED_SCHEDULES[:] = list(_BMRBD_STATE["shared_schedules"])
        if "_SHARED_CHATS" in g and isinstance(_BMRBD_STATE.get("shared_chats"), dict):
            for _k, _v in _BMRBD_STATE["shared_chats"].items():
                _SHARED_CHATS.setdefault(_k, _v)
            _save_shared_chats()
        # BMRBD v61.16 COORD (B3): rehydrate the scheduled/bg task stores
        # from the vault-restored state — their /tmp files die with the
        # kernel, so a fresh kernel only gets them back through here.
        if "_sched_tasks_load" in g and isinstance(_BMRBD_STATE.get("scheduled_tasks"), dict) and _BMRBD_STATE["scheduled_tasks"]:
            _sched_tasks_load()
        if "_bg_tasks_load" in g and isinstance(_BMRBD_STATE.get("bg_tasks"), dict) and _BMRBD_STATE["bg_tasks"]:
            _bg_tasks_load()
        if "_sched_dismissed_load" in g and isinstance(_BMRBD_STATE.get("scheduled_recommended_dismissed"), dict) and _BMRBD_STATE["scheduled_recommended_dismissed"]:
            _sched_dismissed_load()  # BMRBD v61.17 TASK
    except Exception:
        pass


threading.Thread(target=_bmrbd_vault_cloud_flush_daemon, daemon=True).start()


def _restore_from_vault_zip_bytes(zip_bytes: bytes) -> bool:
    global _BMRBD_STATE
    try:
        _vault_present = False
        _vault_ok = False
        with zipfile.ZipFile(io.BytesIO(zip_bytes), "r") as zf:
            if "vault.enc" in zf.namelist():
                _vault_present = True
                dec = _decrypt_vault_bytes(zf.read("vault.enc"))
                if dec:
                    loaded = json.loads(dec.decode("utf-8")); _c3_live_toks = _c3_snapshot_live_tokens()  # BMRBD v76.5 C3: never roll the live login token back to a stale vault copy
                    if isinstance(loaded, dict) and "users" in loaded:
                        # BMRBD v61.15a WD2: dict sections merge (a
                        # restore never drops a section the vault
                        # predates); list sections replace wholesale
                        # (a list has no merge).
                        for k_s in ("users", "user_threads", "user_projects", "user_skills", "user_connectors", "settings", "user_memory", "user_settings", "shared_chats", "scheduled_tasks", "bg_tasks", "scheduled_recommended_dismissed", "message_feedback", "api_keys", "api_key_project_usage", "invites"):  # BMRBD v61.16 COORD (B3) + BMRBD v61.17 TASK + BMRBD v76 §4 (Agent B): keys/invites survive a vault restore
                            if isinstance(loaded.get(k_s), dict):
                                _BMRBD_STATE.setdefault(k_s, {}).update(loaded[k_s])
                        # BMRBD v76.4 Q1: login sessions survive a
                        # vault-zip restore too. Before this the merge
                        # list omitted user_sessions entirely, so every
                        # boot that restored from the Drive webhook or
                        # a peer pull dropped ALL login sessions (and
                        # could roll users back to a pre-login token):
                        # a signed-in browser then got 401 on
                        # /api/account + /api/usage while still looking
                        # signed in ("Sign in to view your account" +
                        # "Usage could not be loaded from the server").
                        # Sessions merge by token (union with the live
                        # list, never a wipe), keeping only sessions
                        # that can still authenticate: created within
                        # _SESSION_MAX_AGE_S, or dateless (grandfathered,
                        # exactly as _session_user_from_token does).
                        # Expired sessions are NOT resurrected.
                        if isinstance(loaded.get("user_sessions"), dict):
                            try:
                                _sess_cutoff = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(time.time() - _SESSION_MAX_AGE_S))
                            except Exception:
                                _sess_cutoff = ""
                            _live_sess = _BMRBD_STATE.setdefault("user_sessions", {})
                            for _uname, _slist in loaded["user_sessions"].items():
                                if not isinstance(_slist, list):
                                    continue
                                _have = {str(_s.get("token") or "") for _s in (_live_sess.get(str(_uname)) or []) if isinstance(_s, dict)}
                                _merged = list(_live_sess.get(str(_uname)) or [])
                                for _s in _slist:
                                    if not isinstance(_s, dict):
                                        continue
                                    _tok = str(_s.get("token") or "")
                                    if not _tok or _tok in _have:
                                        continue
                                    _created = str(_s.get("created_at") or "")
                                    if _created and _sess_cutoff and _created < _sess_cutoff:
                                        continue
                                    _merged.append(dict(_s))
                                    _have.add(_tok)
                                if _merged:
                                    _live_sess[str(_uname)] = _merged
                        for k_l in ("shared_browser_threads", "shared_schedules", "bug_reports"):
                            if isinstance(loaded.get(k_l), list):
                                _BMRBD_STATE[k_l] = list(loaded[k_l])
                        _vault_ok = True; _c3_restore_live_tokens(_c3_live_toks)  # BMRBD v76.5 C3
            MEDIA_STORE_DIR.mkdir(parents=True, exist_ok=True)
            for name in zf.namelist():
                if name.startswith("media_store/") and len(name) > len("media_store/"):
                    fname = Path(name).name
                    target_mp = MEDIA_STORE_DIR / fname
                    if not target_mp.exists():
                        target_mp.write_bytes(zf.read(name))
        # BMRBD v61.15a WD2: a vault.enc that is present but
        # undecryptable (e.g. a different VAULT_SECRET after an account
        # rotation) is a FAILED restore, not a success. The old code
        # returned True here, so boot carried on with an empty state
        # and overwrote the local vault files; the next cloud sync
        # would then have uploaded the empty state over the good vault.
        # Returning False lets boot fall through to the next source
        # (local file, /kaggle/input, Kaggle dataset). A zip with no
        # vault.enc at all (media-only) still counts as restored.
        return _vault_ok or not _vault_present
    except Exception:
        return False

# ═════════════════════════════════════════════════════════════════════════════
# BMRBD v76 §4 — DRIVE PERSISTENCE (snapshot / resumable upload / auto-restore)
# ═════════════════════════════════════════════════════════════════════════════
# Layer built ON TOP of the existing vault: a versioned bundle holds the
# encrypted vault zip itself (users + API keys + settings + sessions +
# threads/memories + schedules, i.e. the whole _BMRBD_STATE) plus the
# status/incident log. Snapshot -> Drive (resumable upload) -> on the next
# run (another Kaggle account) everything restores AUTOMATICALLY by default,
# size/hash-verified, with a pre-restore safety snapshot. A changed admin
# password restores as the NEW password (overwrite, never merge).
# Live Drive verification is a §9 item: the code below talks to Drive
# through a small client protocol; tests exercise it with a mock client.
# Scope requested: drive.file (files the app creates) — never full Drive.
_DRIVE_PERSIST_SCOPE = "https://www.googleapis.com/auth/drive.file"
_DRIVE_PERSIST_BUNDLE_VERSION = 1
_DRIVE_PERSIST_BUNDLE_NAME = "bmrbd-ai-state-bundle-v1.zip"
_DRIVE_PERSIST_APP_KEY = "bmrbd_ai_state_bundle"  # appProperties marker
_DRIVE_PERSIST_CHUNK_SIZE = 256 * 1024  # 256 KiB — Drive resumable unit
_DRIVE_PERSIST_LARGE_THRESHOLD = 5 * 1024 * 1024  # >5 MB => resumable
_DRIVE_PERSIST_MAX_FILE_BYTES = 5 * 1024 ** 4  # Drive per-file ceiling: 5 TB
_DRIVE_PERSIST_MAX_24H_BYTES = 750 * 1024 ** 3  # Drive rolling-24h upload ceiling: 750 GB
_DRIVE_PERSIST_SESSION_MAX_AGE_S = 7 * 24 * 3600  # resumable session URI expires after 1 week
_DRIVE_PERSIST_MAX_ATTEMPTS = 5  # bounded retries only; never infinite
_DRIVE_PERSIST_BASE_DELAY_S = 1.0
_DRIVE_PERSIST_MAX_DELAY_S = 32.0
_DRIVE_PERSIST_LAST_RESTORE = {"ok": None, "reason": "never-run", "at": 0.0}


class DrivePersistError(Exception):
    """Drive HTTP error. status=None means a transport/network failure."""

    def __init__(self, message, status=None, reason="", retry_after=None):
        super().__init__(message)
        self.status = status
        self.reason = str(reason or "")
        self.retry_after = retry_after


def _drive_persist_sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _drive_persist_md5(data: bytes) -> str:
    return hashlib.md5(data).hexdigest()


def _drive_persist_chunk_plan(total_size: int, chunk_size: int = _DRIVE_PERSIST_CHUNK_SIZE):
    """Chunk (start, end) plan for a resumable upload.

    Every intermediate chunk is a multiple of 256 KiB (Drive returns an
    immediate HTTP 400 for a non-aligned intermediate chunk); only the
    final chunk may be shorter. Raises ValueError on a bad plan."""
    if total_size < 0:
        raise ValueError("drive-persist: negative size")
    if chunk_size <= 0 or chunk_size % (256 * 1024) != 0:
        raise ValueError("drive-persist: chunk_size must be a 256 KiB multiple")
    plan = []
    start = 0
    while start < total_size:
        end = min(start + chunk_size, total_size)
        if end < total_size and (end - start) % (256 * 1024) != 0:
            raise ValueError("drive-persist: intermediate chunk not 256 KiB aligned")
        plan.append((start, end))
        start = end
    return plan or [(0, 0)]


def _drive_persist_should_retry(err: DrivePersistError) -> bool:
    """Retryable = transient network / rate-limit / 5xx ONLY, bounded.

    Auth/permission/quota errors are NEVER retried indefinitely: 400/401
    and 403 (other than rate-limit reasons) return False immediately.
    A 403 whose reason is rateLimitExceeded/userRateLimitExceeded is a
    rate limit, so it IS retried — bounded, honoring Retry-After."""
    if err.status is None:
        return True  # transport failure
    if err.status in (429, 500, 502, 503, 504):
        return True
    if err.status == 403 and ("ratelimitexceeded" in err.reason.lower().replace(" ", "")):
        return True
    return False


def _drive_persist_backoff_delay(attempt: int, retry_after=None) -> float:
    """Bounded exponential backoff + jitter; honors Retry-After (seconds)."""
    try:
        if retry_after is not None and float(retry_after) > 0:
            return min(float(retry_after), _DRIVE_PERSIST_MAX_DELAY_S) + random.uniform(0, 1.0)
    except Exception:
        pass
    delay = min(_DRIVE_PERSIST_MAX_DELAY_S, _DRIVE_PERSIST_BASE_DELAY_S * (2 ** max(0, attempt)))
    return delay + random.uniform(0, 1.0)


def _drive_persist_check_upload_ceiling(size_bytes: int, bytes_uploaded_24h: int = 0) -> None:
    """Refuse an upload that would exceed Drive's ceilings (do not attempt)."""
    if size_bytes > _DRIVE_PERSIST_MAX_FILE_BYTES:
        raise ValueError("drive-persist: file exceeds Drive 5 TB per-file ceiling")
    if bytes_uploaded_24h + size_bytes > _DRIVE_PERSIST_MAX_24H_BYTES:
        raise ValueError("drive-persist: upload would exceed Drive 750 GB rolling-24h ceiling")


def _drive_persist_transfer_state_path(name: str) -> Path:
    return BMRBD_DATA_DIR / ("drive_persist_transfer_%s.json" % re.sub(r"[^A-Za-z0-9_.-]", "_", str(name)))


def _drive_persist_save_transfer_state(state: dict) -> Path:
    """Persist restartable transfer state in an owner-only file (0600)."""
    p = _drive_persist_transfer_state_path(state.get("name") or "bundle")
    BMRBD_DATA_DIR.mkdir(parents=True, exist_ok=True)
    tmp = p.with_suffix(".tmp")
    tmp.write_text(json.dumps(state, ensure_ascii=False, indent=2), encoding="utf-8")
    try:
        os.chmod(tmp, 0o600)
    except Exception:
        pass
    os.replace(tmp, p)
    try:
        os.chmod(p, 0o600)
    except Exception:
        pass
    return p


def _drive_persist_load_transfer_state(name: str):
    try:
        p = _drive_persist_transfer_state_path(name)
        if p.is_file():
            return json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        pass
    return None


def _drive_persist_status_log_entries():
    """Status/incident log entries from live state (status-page agent's
    `status_incidents` key if present, else `status_log`, else [])."""
    for key in ("status_incidents", "status_log"):
        v = _BMRBD_STATE.get(key)
        if isinstance(v, list):
            return list(v)
    return []


def drive_persist_build_bundle() -> bytes:
    """Snapshot: export vault + settings + sessions + status log into ONE
    versioned bundle zip. Manifest carries size + SHA-256 + MD5 per file.
    The vault itself is the existing encrypted zip (_build_locked_vault_zip_bytes)
    — no second storage system is invented."""
    vault_bytes = _build_locked_vault_zip_bytes()
    status_bytes = json.dumps(
        {"status_incidents": _drive_persist_status_log_entries(),
         "exported_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())},
        ensure_ascii=False, indent=2).encode("utf-8")
    files = {
        "vault.zip": vault_bytes,
        "status_log.json": status_bytes,
    }
    manifest = {
        "bundle_version": _DRIVE_PERSIST_BUNDLE_VERSION,
        "app": "bmrbd-ai",
        "created_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "files": [
            {"name": name, "size": len(data),
             "sha256": _drive_persist_sha256(data),
             "md5": _drive_persist_md5(data)}
            for name, data in files.items()
        ],
    }
    zbuf = io.BytesIO()
    with zipfile.ZipFile(zbuf, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        zf.writestr("manifest.json", json.dumps(manifest, ensure_ascii=False, indent=2).encode("utf-8"))
        for name, data in files.items():
            zf.writestr(name, data)
    return zbuf.getvalue()


def drive_persist_verify_bundle(bundle_bytes: bytes):
    """Verify a bundle WITHOUT restoring: manifest present, every file
    present with recorded size + SHA-256 + MD5. Returns (ok, manifest, err).
    NEVER auto-restore without this passing."""
    try:
        if not bundle_bytes:
            return False, None, "empty bundle"
        with zipfile.ZipFile(io.BytesIO(bundle_bytes), "r") as zf:
            names = set(zf.namelist())
            if "manifest.json" not in names:
                return False, None, "missing manifest.json"
            manifest = json.loads(zf.read("manifest.json").decode("utf-8"))
            if manifest.get("bundle_version") != _DRIVE_PERSIST_BUNDLE_VERSION:
                return False, None, "unsupported bundle_version %r" % (manifest.get("bundle_version"),)
            for entry in manifest.get("files") or []:
                name = entry.get("name")
                if name not in names:
                    return False, None, "missing file %s" % name
                data = zf.read(name)
                if len(data) != entry.get("size"):
                    return False, None, "size mismatch %s: got %d expected %s" % (name, len(data), entry.get("size"))
                if _drive_persist_sha256(data) != entry.get("sha256"):
                    return False, None, "sha256 mismatch %s" % name
                if _drive_persist_md5(data) != entry.get("md5"):
                    return False, None, "md5 mismatch %s" % name
            if "vault.zip" not in names:
                return False, None, "missing vault.zip"
            return True, manifest, ""
    except DrivePersistError:
        raise
    except Exception as e:
        return False, None, "verify error: %s" % e


def _drive_persist_extract_vault_state(vault_zip_bytes: bytes):
    """Decrypt vault.enc inside a bundle's vault.zip -> state dict (or {})."""
    try:
        with zipfile.ZipFile(io.BytesIO(vault_zip_bytes), "r") as zf:
            if "vault.enc" not in zf.namelist():
                return {}
            dec = _decrypt_vault_bytes(zf.read("vault.enc"))
            if not dec:
                return {}
            loaded = json.loads(dec.decode("utf-8"))
            return loaded if isinstance(loaded, dict) else {}
    except Exception:
        return {}


def drive_persist_restore_bundle(bundle_bytes: bytes, safety_snapshot: bool = True) -> str:
    """Restore a verified bundle into live state. Returns 'ok' or an
    'error: ...' string. Refuses on ANY verification failure. Takes a
    pre-restore safety snapshot of the CURRENT vault first. The restored
    admin credential OVERWRITES the old one (no merge, no old-password
    confusion): a changed admin password works on the next run."""
    ok, manifest, err = drive_persist_verify_bundle(bundle_bytes)
    if not ok:
        return "error: bundle refused: %s" % err
    snapshot_path = None
    try:
        if safety_snapshot:
            try:
                snap = _build_locked_vault_zip_bytes()
                BMRBD_DATA_DIR.mkdir(parents=True, exist_ok=True)
                snapshot_path = BMRBD_DATA_DIR / ("drive_persist_pre_restore_%d.zip" % int(time.time()))
                snapshot_path.write_bytes(snap)
                try:
                    os.chmod(snapshot_path, 0o600)
                except Exception:
                    pass
            except Exception:
                pass
        with zipfile.ZipFile(io.BytesIO(bundle_bytes), "r") as zf:
            vault_bytes = zf.read("vault.zip")
            status_bytes = zf.read("status_log.json") if "status_log.json" in zf.namelist() else b""
        restored_state = _drive_persist_extract_vault_state(vault_bytes)
        if not restored_state or "users" not in restored_state:
            return "error: bundle vault has no users section"
        if not _restore_from_vault_zip_bytes(vault_bytes):
            return "error: vault restore failed (undecryptable vault?)"
        # Admin credential OVERWRITE (not merge): the restored admin record
        # replaces the live one wholesale, so a changed admin password is
        # the one that works on the next run and the old hash is gone.
        try:
            new_admin = (restored_state.get("users") or {}).get(ADMIN_DEFAULT_USER); _c3_admin_live_tok = str((_BMRBD_STATE.get("users", {}).get(ADMIN_DEFAULT_USER) or {}).get("token") or "")  # BMRBD v76.5 C3
            if isinstance(new_admin, dict) and new_admin.get("pass_hash"):
                _BMRBD_STATE.setdefault("users", {})[ADMIN_DEFAULT_USER] = dict(new_admin); _c3_restore_live_tokens({ADMIN_DEFAULT_USER: _c3_admin_live_tok})  # BMRBD v76.5 C3: a bundle restore must not roll the live admin token back
        except Exception:
            pass
        # Sessions + settings OVERWRITE (not merge): the vault's own
        # _restore_from_vault_zip_bytes merges most dict sections but
        # omits `user_sessions` entirely and key-merges `settings`, so
        # a snapshot restore would otherwise drop every login session
        # and keep stale deleted settings. A snapshot restore is
        # wholesale by definition — the bundle's copy wins.
        try:
            if isinstance(restored_state.get("user_sessions"), dict):
                _c3_merge_user_sessions(_BMRBD_STATE.setdefault("user_sessions", {}), restored_state["user_sessions"])  # BMRBD v76.5 C3: merge, never wipe live sessions
            if isinstance(restored_state.get("settings"), dict):
                _BMRBD_STATE["settings"] = dict(restored_state["settings"])
        except Exception:
            pass
        # Status/incident log restores wholesale from the bundle.
        try:
            if status_bytes:
                slog = json.loads(status_bytes.decode("utf-8"))
                if isinstance(slog.get("status_incidents"), list):
                    _BMRBD_STATE["status_incidents"] = list(slog["status_incidents"])
        except Exception:
            pass
        _save_bmrbd_state_local(push_peer=False)
        return "ok"
    except Exception as e:
        return "error: restore failed: %s" % e


def drive_persist_reconcile_remote(client, parent_id, expected=None):
    """Reconcile remote state BEFORE restarting an upload/download.
    Search by parent ID + appProperties. Returns (status, file_info, err):
      'none'        — no remote artifact; safe to start fresh.
      'adopt'       — exactly one verified artifact; adopt it (no re-upload).
      'fail_closed' — several artifacts; refuse (human must resolve)."""
    try:
        found = client.search_files(parent_id, {_DRIVE_PERSIST_APP_KEY: "1"})
    except DrivePersistError as e:
        return "error", None, "remote search failed: %s" % e
    except Exception as e:
        return "error", None, "remote search failed: %s" % e
    found = [f for f in (found or []) if isinstance(f, dict)]
    if not found:
        return "none", None, ""
    if len(found) > 1:
        return "fail_closed", None, "duplicate remote artifacts: %d found" % len(found)
    info = found[0]
    if expected:
        try:
            if expected.get("size") is not None and int(info.get("size") or -1) != int(expected["size"]):
                return "fail_closed", None, "remote size mismatch: %s vs expected %s" % (info.get("size"), expected.get("size"))
            if expected.get("md5") and info.get("md5Checksum") and str(info["md5Checksum"]).lower() != str(expected["md5"]).lower():
                return "fail_closed", None, "remote md5 mismatch"
        except DrivePersistError:
            raise
        except Exception as e:
            return "fail_closed", None, "remote verification error: %s" % e
    return "adopt", info, ""


def drive_persist_upload_resumable(client, data: bytes, name=None, parent_id=None,
                                   bytes_uploaded_24h: int = 0, sleep_fn=None):
    """Resumable upload (uploadType=resumable) of one artifact.

    Initiate -> save session URI -> upload in 256 KiB-multiple chunks ->
    handle 308 Resume Incomplete + Range header. Transfer state (file ID,
    expected size, expected SHA-256, session URI, server-confirmed offset,
    session creation time, retry state) is persisted owner-only after every
    confirmed chunk, so a killed run resumes instead of restarting.
    Returns the Drive file dict on success. Raises DrivePersistError /
    ValueError on refusal (ceilings, duplicates, non-retryable errors)."""
    sleep = sleep_fn or time.sleep
    name = name or _DRIVE_PERSIST_BUNDLE_NAME
    if len(data) == 0:
        raise ValueError("drive-persist: cannot upload an empty artifact")
    _drive_persist_check_upload_ceiling(len(data), bytes_uploaded_24h)
    expected = {"size": len(data), "sha256": _drive_persist_sha256(data),
                "md5": _drive_persist_md5(data)}
    # Reconcile remote state BEFORE starting: adopt an identical artifact,
    # fail closed on duplicates, otherwise start fresh.
    status, info, err = drive_persist_reconcile_remote(client, parent_id, expected)
    if status == "adopt":
        return dict(info, adopted=True)
    if status == "fail_closed":
        raise DrivePersistError("drive-persist: upload refused: %s" % err)
    if status == "error":
        raise DrivePersistError("drive-persist: upload refused: %s" % err)
    # Resume a persisted session if one is alive (< 1 week old); otherwise
    # start a fresh session (an expired URI restarts from byte zero).
    tstate = _drive_persist_load_transfer_state(name)
    session_uri = None
    confirmed = 0
    file_id = None
    if tstate and tstate.get("session_uri") and tstate.get("expected_sha256") == expected["sha256"]:
        age = time.time() - float(tstate.get("created_at") or 0)
        if age < _DRIVE_PERSIST_SESSION_MAX_AGE_S:
            session_uri = tstate["session_uri"]
            confirmed = int(tstate.get("confirmed_offset") or 0)
            file_id = tstate.get("file_id")
    if session_uri is None:
        session_uri = client.initiate_resumable(
            name, "application/zip", len(data), parent_id,
            {_DRIVE_PERSIST_APP_KEY: "1"})
        confirmed = 0
        file_id = None
        tstate = {"name": name, "file_id": file_id, "expected_size": len(data),
                  "expected_sha256": expected["sha256"], "session_uri": session_uri,
                  "confirmed_offset": 0, "created_at": time.time(),
                  "retries": 0, "status": "uploading"}
        _drive_persist_save_transfer_state(tstate)
    plan = _drive_persist_chunk_plan(len(data))
    for (start, end) in plan:
        if end <= confirmed:
            continue  # already server-confirmed; skip
        if start < confirmed < end:
            start = confirmed  # partial chunk: resume mid-chunk
        chunk = data[start:end]
        attempt = 0
        while True:
            try:
                res = client.upload_chunk(session_uri, chunk, start, len(data))
                break
            except DrivePersistError as e:
                if not _drive_persist_should_retry(e) or attempt >= _DRIVE_PERSIST_MAX_ATTEMPTS - 1:
                    tstate["status"] = "failed"
                    tstate["retries"] = attempt + 1
                    _drive_persist_save_transfer_state(tstate)
                    raise
                attempt += 1
                tstate["retries"] = attempt
                _drive_persist_save_transfer_state(tstate)
                sleep(_drive_persist_backoff_delay(attempt, getattr(e, "retry_after", None)))
        st = int(res.get("status") or 0)
        if st in (200, 201):
            file_id = res.get("file_id") or file_id
            confirmed = len(data)
            tstate.update({"file_id": file_id, "confirmed_offset": confirmed,
                           "status": "complete"})
            _drive_persist_save_transfer_state(tstate)
            return {"id": file_id, "name": name, "size": len(data),
                    "md5Checksum": expected["md5"], "sha256": expected["sha256"]}
        if st == 308:
            # Resume Incomplete: Range header tells the confirmed offset.
            confirmed = int(res.get("range_end") or start) + 1 if res.get("range_end") is not None else end
            if confirmed > len(data):
                confirmed = len(data)
            tstate.update({"confirmed_offset": confirmed, "file_id": file_id})
            _drive_persist_save_transfer_state(tstate)
            continue
        raise DrivePersistError("drive-persist: unexpected upload status %s" % st, status=st)
    # All chunks sent but no 200/201 seen: query the session to settle it.
    try:
        q = client.query_upload(session_uri, len(data))
        if int(q.get("status") or 0) in (200, 201):
            confirmed = len(data)
            tstate.update({"file_id": q.get("file_id") or file_id,
                           "confirmed_offset": confirmed, "status": "complete"})
            _drive_persist_save_transfer_state(tstate)
            return {"id": q.get("file_id") or file_id, "name": name, "size": len(data),
                    "md5Checksum": expected["md5"], "sha256": expected["sha256"]}
    except DrivePersistError:
        pass
    raise DrivePersistError("drive-persist: upload incomplete at %d/%d bytes" % (confirmed, len(data)))


def drive_persist_snapshot_to_drive(client, parent_id=None, bytes_uploaded_24h: int = 0,
                                    sleep_fn=None):
    """Build the current-state bundle and upload it to Drive (resumable
    when >5 MB, single-shot otherwise — the same code path handles both:
    a small bundle is one chunk). Returns the Drive file dict."""
    bundle = drive_persist_build_bundle()
    if len(bundle) <= _DRIVE_PERSIST_LARGE_THRESHOLD:
        # Small bundle: still go through the resumable path (one chunk) so
        # transfer-state persistence + reconcile apply uniformly.
        pass
    return drive_persist_upload_resumable(client, bundle, _DRIVE_PERSIST_BUNDLE_NAME,
                                          parent_id, bytes_uploaded_24h, sleep_fn)


def drive_persist_restore_from_drive(client, parent_id=None, expected=None, work_dir=None):
    """Background-restore job (synchronous core; wrap in a thread for boot):
    check free disk -> stream the artifact to a UNIQUE temp dir (never
    overwrite) -> verify recorded size + MD5/SHA-256 -> pass to the restore
    engine with a pre-restore safety snapshot -> delete temp files after
    success OR failure. Returns a result dict; never raises."""
    import tempfile
    result = {"ok": False, "reason": "", "at": time.time()}
    tmpdir = None
    try:
        status, info, err = drive_persist_reconcile_remote(client, parent_id, expected)
        if status == "fail_closed":
            result["reason"] = "refused: %s" % err
            return result
        if status == "error":
            result["reason"] = "remote error: %s" % err
            return result
        if status == "none":
            result["reason"] = "no remote bundle found"
            return result
        file_id = info.get("id")
        remote_size = int(info.get("size") or 0)
        if remote_size <= 0:
            result["reason"] = "remote bundle has no size"
            return result
        # Free-disk check: need the bundle plus headroom for the unpack.
        try:
            free = shutil.disk_usage(work_dir or str(BMRBD_DATA_DIR)).free
        except Exception:
            free = 0
        if free and free < remote_size * 2 + 64 * 1024 * 1024:
            result["reason"] = "insufficient free disk: %d free, need %d" % (free, remote_size * 2 + 64 * 1024 * 1024)
            return result
        tmpdir = tempfile.mkdtemp(prefix="bmrbd_drive_restore_", dir=work_dir)
        dest = Path(tmpdir) / _DRIVE_PERSIST_BUNDLE_NAME
        client.download_to_path(file_id, str(dest))
        data = dest.read_bytes()
        if len(data) != remote_size:
            result["reason"] = "size mismatch after download: %d vs %d" % (len(data), remote_size)
            return result
        if expected and expected.get("sha256") and _drive_persist_sha256(data) != expected["sha256"]:
            result["reason"] = "sha256 mismatch after download"
            return result
        if expected and expected.get("md5") and _drive_persist_md5(data) != expected["md5"]:
            result["reason"] = "md5 mismatch after download"
            return result
        if info.get("md5Checksum") and _drive_persist_md5(data) != str(info["md5Checksum"]).lower():
            result["reason"] = "md5 mismatch vs remote metadata"
            return result
        res = drive_persist_restore_bundle(data)
        if res != "ok":
            result["reason"] = res
            return result
        result["ok"] = True
        result["reason"] = "restored %d bytes from Drive file %s" % (len(data), file_id)
        return result
    except DrivePersistError as e:
        result["reason"] = "drive error: %s" % e
        return result
    except Exception as e:
        result["reason"] = "restore error: %s" % e
        return result
    finally:
        if tmpdir:
            shutil.rmtree(tmpdir, ignore_errors=True)


def drive_persist_start_restore_job(client, parent_id=None, expected=None):
    """Start the Drive auto-restore as a background daemon thread (boot
    path). The outcome lands in _DRIVE_PERSIST_LAST_RESTORE. Returns the
    Thread (or None when there is no client — restore is skipped, never
    faked)."""
    if client is None:
        _DRIVE_PERSIST_LAST_RESTORE.update({"ok": False, "reason": "skipped:no-drive-client", "at": time.time()})
        return None

    def _worker():
        try:
            res = drive_persist_restore_from_drive(client, parent_id, expected)
        except Exception as e:
            res = {"ok": False, "reason": "restore job crashed: %s" % e, "at": time.time()}
        _DRIVE_PERSIST_LAST_RESTORE.update(res)

    t = threading.Thread(target=_worker, daemon=True)
    t.start()
    return t


def drive_persist_auto_restore_on_boot(client=None, parent_id=None, expected=None):
    """Boot hook: restore EVERYTHING automatically by default on the next
    run (another Kaggle account) — but ONLY after size/hash verification
    (drive_persist_restore_from_drive enforces it). Returns the restore
    thread, or None when no Drive client is configured."""
    return drive_persist_start_restore_job(client, parent_id, expected)


class _DriveHttpClient:
    """Minimal Google Drive v3 client over urllib (drive.file scope).
    Only used when a real access token is supplied; tests use a mock
    implementing the same five methods. Retries live in the callers
    (bounded, honoring Retry-After); this class surfaces one attempt."""

    _BASE = "https://www.googleapis.com"

    def __init__(self, access_token):
        self._token = str(access_token or "")

    def _req(self, url, method="GET", data=None, headers=None, follow_redirects=True):
        h = {"Authorization": "Bearer " + self._token}
        if headers:
            h.update(headers)
        req = urllib.request.Request(url, data=data, headers=h, method=method)
        if follow_redirects:
            opener = urllib.request.build_opener()
        else:
            # Drive resumable uploads answer 308 Resume Incomplete with a
            # Range header — that is NOT a redirect to follow; a stock
            # opener would chase it (or fail) and lose the Range header.
            class _NoRedirect(urllib.request.HTTPRedirectHandler):
                def redirect_request(self, req, fp, code, msg, hdrs, newurl):
                    return None
            opener = urllib.request.build_opener(_NoRedirect())
        try:
            with opener.open(req, timeout=60) as r:
                return r.status, r.read(), dict(r.headers or {})
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", errors="ignore") if hasattr(e, "read") else ""
            if e.code == 308 and not follow_redirects:
                return 308, b"", dict(e.headers or {})
            ra = None
            try:
                ra = e.headers.get("Retry-After") if e.headers else None
            except Exception:
                pass
            raise DrivePersistError("drive http %s: %s" % (e.code, body[:300]),
                                    status=e.code, reason=body[:300], retry_after=ra)
        except Exception as e:
            raise DrivePersistError("drive transport error: %s" % e, status=None)

    def initiate_resumable(self, name, mime, size, parent_id, app_properties):
        meta = {"name": name, "mimeType": mime, "appProperties": app_properties or {}}
        if parent_id:
            meta["parents"] = [parent_id]
        st, body, hdrs = self._req(
            self._BASE + "/upload/drive/v3/files?uploadType=resumable", "POST",
            json.dumps(meta).encode("utf-8"),
            {"Content-Type": "application/json; charset=UTF-8",
             "X-Upload-Content-Type": mime,
             "X-Upload-Content-Length": str(size)})
        loc = hdrs.get("Location") or hdrs.get("location")
        if st not in (200, 201) or not loc:
            raise DrivePersistError("drive: resumable initiate failed (%s)" % st, status=st)
        return loc

    def upload_chunk(self, session_uri, data, start, total):
        end = start + len(data) - 1
        st, body, hdrs = self._req(
            session_uri, "PUT", data,
            {"Content-Type": "application/octet-stream",
             "Content-Length": str(len(data)),
             "Content-Range": "bytes %d-%d/%d" % (start, end, total)},
            follow_redirects=False)
        if st in (200, 201):
            try:
                fid = json.loads(body.decode("utf-8", errors="ignore") or "{}").get("id")
            except Exception:
                fid = None
            return {"status": st, "file_id": fid}
        if st == 308:
            return {"status": 308, "range_end": self._range_end(hdrs)}
        raise DrivePersistError("drive: chunk upload status %s" % st, status=st)

    @staticmethod
    def _range_end(headers):
        try:
            rng = (headers or {}).get("Range") or (headers or {}).get("range") or ""
            if rng.startswith("bytes=0-"):
                return int(rng[len("bytes=0-"):].split(",")[0])
        except Exception:
            pass
        return None

    def query_upload(self, session_uri, total):
        st, body, hdrs = self._req(
            session_uri, "PUT", b"",
            {"Content-Length": "0",
             "Content-Range": "bytes */%d" % total},
            follow_redirects=False)
        if st in (200, 201):
            try:
                fid = json.loads(body.decode("utf-8", errors="ignore") or "{}").get("id")
            except Exception:
                fid = None
            return {"status": st, "file_id": fid}
        if st == 308:
            return {"status": 308, "range_end": self._range_end(hdrs)}
        return {"status": st}

    def search_files(self, parent_id, app_properties):
        q_parts = ["trashed = false"]
        if parent_id:
            q_parts.append("'%s' in parents" % parent_id)
        for k, v in (app_properties or {}).items():
            q_parts.append("appProperties has { key = '%s' and value = '%s' }" % (k, v))
        import urllib.parse as _up
        url = (self._BASE + "/drive/v3/files?q=" + _up.quote(" and ".join(q_parts))
               + "&fields=files(id,name,size,md5Checksum,appProperties)&pageSize=10")
        st, body, _h = self._req(url, "GET")
        if st != 200:
            raise DrivePersistError("drive: search failed (%s)" % st, status=st)
        return json.loads(body.decode("utf-8", errors="ignore") or "{}").get("files") or []

    def download_to_path(self, file_id, dest_path):
        import urllib.parse as _up
        url = self._BASE + "/drive/v3/files/%s?alt=media" % _up.quote(str(file_id))
        req = urllib.request.Request(url, headers={"Authorization": "Bearer " + self._token}, method="GET")
        try:
            with urllib.request.urlopen(req, timeout=120) as r, open(dest_path, "wb") as f:
                while True:
                    chunk = r.read(1024 * 1024)
                    if not chunk:
                        break
                    f.write(chunk)
        except urllib.error.HTTPError as e:
            raise DrivePersistError("drive: download failed (%s)" % e.code, status=e.code)
        except Exception as e:
            raise DrivePersistError("drive download error: %s" % e, status=None)

def restore_bmrbd_vault_on_boot():
    global _BMRBD_STATE
    # 0. Try restoring from Google Drive Webhook (`GDRIVE_WEBHOOK_URL`) first so accounts & media files are immediately ready!
    webhook_u = os.environ.get("GDRIVE_WEBHOOK_URL", "").strip()
    if webhook_u and webhook_u.startswith("https://script.google.com/macros/"):
        try:
            req_gd = urllib.request.Request(webhook_u, headers={"User-Agent": "BMRBDAi-GDriveVault/53.0"})
            with urllib.request.urlopen(req_gd, timeout=12) as r_gd:
                j_gd = json.loads(r_gd.read().decode("utf-8", errors="ignore"))
                if j_gd.get("ok") and j_gd.get("zip_b64"):
                    if _restore_from_vault_zip_bytes(base64.b64decode(j_gd["zip_b64"])):
                        _save_bmrbd_state_local(push_peer=False)
                        return
        except Exception:
            pass
    # 1. Check local file first
    if BMRBD_STATE_FILE.is_file():
        try:
            loaded = json.loads(BMRBD_STATE_FILE.read_text(encoding="utf-8"))
            if isinstance(loaded, dict) and "users" in loaded:
                _BMRBD_STATE.update(loaded)
                return
        except Exception:
            pass
    # 2. Check attached /kaggle/input or remote Kaggle Encrypted Vault dataset
    for p_enc in Path("/kaggle/input").rglob("vault.enc") if Path("/kaggle/input").exists() else []:
        try:
            dec = _decrypt_vault_bytes(p_enc.read_bytes())
            if dec:
                _BMRBD_STATE.update(json.loads(dec.decode("utf-8")))
                _save_bmrbd_state_local()
                return
        except Exception:
            pass
    if shutil.which("kaggle") and KAGGLE_VAULT_OWNER:
        try:
            tmp_v = Path("/tmp/bmrbd_vault_restore")
            shutil.rmtree(tmp_v, ignore_errors=True)
            tmp_v.mkdir(parents=True, exist_ok=True)
            res = subprocess.run(["kaggle", "datasets", "download", "-d", f"{KAGGLE_VAULT_OWNER}/{KAGGLE_VAULT_SLUG}", "-p", str(tmp_v), "--unzip", "-q"], capture_output=True, timeout=15)
            if res.returncode == 0 and (tmp_v / "vault.enc").is_file():
                dec = _decrypt_vault_bytes((tmp_v / "vault.enc").read_bytes())
                if dec:
                    _BMRBD_STATE.update(json.loads(dec.decode("utf-8")))
                    _save_bmrbd_state_local()
            shutil.rmtree(tmp_v, ignore_errors=True)
        except Exception:
            pass
    _save_bmrbd_state_local()

restore_bmrbd_vault_on_boot()
try:
    _pull_vault_from_peer_domain()
except Exception:
    pass

# ── BMRBD v76 SECURITY (S1): session cookie ──
# A browser navigation sends no Authorization header, so page shells are
# gated with a cookie. The cookie carries a PER-LOGIN session token from
# _BMRBD_STATE["user_sessions"] — NEVER the persistent user token and
# NEVER the master key. Cookie auth only ever resolves session tokens.
_SESSION_COOKIE_NAME = "bmrbd_session"


def _parse_session_cookie(cookie_header):
    """Extract the bmrbd_session value from a Cookie header ("" when absent)."""
    try:
        for _part in str(cookie_header or "").split(";"):
            _part = _part.strip()
            if _part.startswith(_SESSION_COOKIE_NAME + "="):
                return _part[len(_SESSION_COOKIE_NAME) + 1:].strip().strip('"')
    except Exception:
        pass
    return ""


def _session_cookie_header(token):
    return "%s=%s; HttpOnly; SameSite=Lax; Path=/; Secure" % (_SESSION_COOKIE_NAME, str(token or ""))


def _expire_session_cookie_header():
    return "%s=; HttpOnly; SameSite=Lax; Path=/; Secure; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT" % _SESSION_COOKIE_NAME


# BMRBD v76.2 BUGHUNT: login sessions expire after 30 days. Before this,
# a session token stayed valid forever (no expiry anywhere in the file),
# so a leaked token was a permanent login.
_SESSION_MAX_AGE_S = 30 * 24 * 3600


def _session_user_from_token(tok):
    """Resolve a per-login session token to its user (sessions list only).

    Sessions older than _SESSION_MAX_AGE_S no longer authenticate.
    Sessions without a created_at are grandfathered (old vault restores
    may lack the field) rather than locking the user out.
    """
    _cutoff = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(time.time() - _SESSION_MAX_AGE_S))
    for _uname, _sess_list in (_BMRBD_STATE.get("user_sessions") or {}).items():
        for _s in (_sess_list or []):
            if isinstance(_s, dict) and hmac.compare_digest(str(_s.get("token") or ""), str(tok or "")):
                _created = str(_s.get("created_at") or "")
                if _created and _created < _cutoff:
                    continue
                _uo = _BMRBD_STATE["users"].get(_uname)
                if _uo and not _uo.get("banned") and _uo.get("approved", True):
                    return _uo
    return None


def _get_user_by_token(auth_header: str, api_key_header: str = "", cookie_header: str = ""):
    tok = str(auth_header or "").replace("Bearer ", "").replace("bearer ", "").strip()
    if not tok and api_key_header:
        tok = str(api_key_header or "").strip()
    if not tok:
        # No Bearer/x-api-key: the session cookie is the only remaining credential.
        _ctok = _parse_session_cookie(cookie_header)
        if _ctok:
            return _session_user_from_token(_ctok)
        return None
    master_k = str((_BMRBD_STATE.get("settings") or {}).get("master_api_key") or MASTER_API_KEY).strip()
    if tok == master_k:
        return _BMRBD_STATE["users"].get(ADMIN_DEFAULT_USER)
    for u_obj in _BMRBD_STATE["users"].values():
        if u_obj.get("token") == tok and not u_obj.get("banned") and u_obj.get("approved", True):
            return u_obj
    # BMRBD v61.16 SETTINGS-B: per-login session tokens also authenticate.
    # (The primary token above stays the fast path; sessions are the list
    # the Security page revokes one by one.)
    _su = _session_user_from_token(tok)
    if _su:
        return _su
    # BMRBD v76 SECURITY (S1): fall back to the session cookie (per-login
    # session tokens only — never the persistent token, never the master key).
    _ctok = _parse_session_cookie(cookie_header)
    if _ctok and _ctok != tok:
        return _session_user_from_token(_ctok)
    return None

def _require_valid_token(handler):
    """A valid user token (or the master key, which maps to the admin user).

    BMRBD v76 SECURITY (S1): also accepts the bmrbd_session cookie, so
    server-side shell gating works for plain browser navigations."""
    return _get_user_by_token(handler.headers.get("Authorization"), handler.headers.get("x-api-key"), handler.headers.get("Cookie"))

# ── BMRBD v76 SECURITY (S1): login-only page + server-side shell gate ──
