def _shell_gate(handler, admin=False):
    """Server-side shell gate. Returns True when the request may proceed.

    Unauthenticated -> 302 to /login. Authenticated non-admin on an admin
    shell -> 403 page. API routes are NOT gated here (Bearer/x-api-key)."""
    try:
        _u = _require_admin(handler) if admin else _require_valid_token(handler)
    except Exception:
        _u = None
    if _u:
        return True
    _presented = bool(_parse_session_cookie(handler.headers.get("Cookie"))
                      or str(handler.headers.get("Authorization") or "").strip()
                      or str(handler.headers.get("x-api-key") or "").strip())
    if admin and _presented:
        handler._send_bytes(403, "text/html; charset=utf-8",
            b"<!doctype html><html><body style=\"font-family:sans-serif;padding:40px;\"><h2>403 - Admin only</h2><p>This page requires an admin account. <a href=\"/login\">Sign in</a></p></body></html>")
        return False
    handler._send_bytes(302, "text/html; charset=utf-8", b"", extra_headers={"Location": "/login"})
    return False


# ── BMRBD v61.18 LOGIN-BRIDGE: unauthenticated access is REMOVED
# (Marup's order, 2026-11-11 — reverses the v61.2 unauthenticated-chat
# allowance and the v61.14 unauthenticated-thread stash). There is no
# unauthenticated user class any more: every data route returns 401
# without a valid token. The same-origin Origin/Referer check and every
# per-IP unauthenticated rate limiter are deleted with it; only GET
# /health (liveness probe) and the login/create-account auth endpoints
# stay public. BMRBD v76 SECURITY (S1): the HTML shells are now ALSO
# gated server-side (_shell_gate, session cookie); the client-side login
# wall remains as the in-app fallback only.
# ── BMRBD v61.9 shared chats (real share links) ──
# A shared chat is a public link (the id is the secret, like ChatGPT shared
# chats). Stored in memory + /tmp JSON so a bridge restart inside the same
# kernel session keeps the links. Capped so one kernel cannot grow without
# bound. No auth tokens or user data beyond the chat text itself.
_SHARED_CHATS_FILE = Path("/tmp/bmrbd_shared_chats.json")
_SHARED_CHATS = {}
_SHARED_CHATS_MAX = 200
_SHARED_CHAT_MAX_BYTES = 200 * 1024
# BMRBD v76.2 LEFTOVER R24: /api/zip caps — the zip is built in memory,
# so an unbounded files map is an OOM vector (the 50 MB body cap alone
# still admits ~50 MB of zip content). 10 MB total / 200 files is far
# above any real generated code project.
_ZIP_MAX_TOTAL_BYTES = 10 * 1024 * 1024  # 10 MB uncompressed, all files
_ZIP_MAX_FILES = 200
try:
    if _SHARED_CHATS_FILE.exists():
        _SHARED_CHATS = json.loads(_SHARED_CHATS_FILE.read_text(encoding="utf-8")) or {}
        if not isinstance(_SHARED_CHATS, dict):
            _SHARED_CHATS = {}
except Exception:
    _SHARED_CHATS = {}
# BMRBD v61.15a WD2: merge the vault-restored share links (the /tmp
# file is authoritative for ids it already holds; a fresh kernel has
# no file and takes the vault copy wholesale), then persist the
# merged set.
try:
    _seed_sc = _BMRBD_STATE.get("shared_chats")
    if isinstance(_seed_sc, dict):
        for _sc_k, _sc_v in _seed_sc.items():
            _SHARED_CHATS.setdefault(_sc_k, _sc_v)
        if _seed_sc:
            _BMRBD_STATE["shared_chats"] = dict(_SHARED_CHATS)
            _save_shared_chats()
except Exception:
    pass


def _save_shared_chats():
    try:
        _tmp = _SHARED_CHATS_FILE.with_suffix(".json.tmp")
        _tmp.write_text(json.dumps(_SHARED_CHATS, ensure_ascii=False), encoding="utf-8")
        _tmp.replace(_SHARED_CHATS_FILE)
        # BMRBD v61.15a WD2: share links also travel in the vault now
        # (the /tmp file alone died with the kernel on rotation).
        _BMRBD_STATE["shared_chats"] = dict(_SHARED_CHATS)
        _save_bmrbd_state_local(push_peer=False)
    except Exception:
        pass


def _zip_sanitize_filename(name):
    """BMRBD v76.2 LEFTOVER R24: make an untrusted filename safe for a zip.

    Drops drive letters, absolute roots and every ``.`` / ``..`` segment
    (zip-slip: ``../evil`` would otherwise escape the extract dir), and
    collapses separators. Returns "" when nothing safe remains."""
    _s = str(name or "").replace("\\", "/")
    _s = re.sub(r"^[A-Za-z]:", "", _s)
    _parts = [p for p in _s.split("/") if p not in ("", ".", "..")]
    return "/".join(_parts)


def _new_share_id():
    return "sh_" + uuid.uuid4().hex[:12]


# ── BMRBD v61.15a WE: server-side background tasks (A13) ──
# POST /api/tasks/start returns a task id at once and runs the work in a
# daemon thread; progress + result persist to a JSON file (same /tmp
# atomic-write pattern as _SHARED_CHATS, so a bridge restart inside the
# same kernel session keeps them); GET /api/tasks[/<id>] lets the
# dashboard resume them. The executor is deliberately simple —
# sequential steps, each a short non-streaming local-model call via
# _bmrbd_short_llm (never raises, "" on any failure) — the plumbing
# (background thread + persistence + resume) is the deliverable, not
# model quality.
_BG_TASKS_FILE = Path("/tmp/bmrbd_bg_tasks.json")
_BG_TASKS = {}
_BG_TASKS_MAX = 50
_BG_TASKS_RUNNING_MAX = 3
_BG_TASKS_MAX_STEPS = 20  # BMRBD v61.16 COORD (B4): a background build has at most 20 steps — more is declined plainly at start, never silently truncated.
_BG_TASKS_LOCK = threading.RLock()


def _bg_now():
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def _bg_task_public(t):
    try:
        _pub = {
            "id": t.get("id"), "title": t.get("title"), "goal": t.get("goal"),
            "status": t.get("status"), "progress": int(t.get("progress") or 0),
            "steps": [{"text": s.get("text"), "status": s.get("status"),
                       "output": s.get("output", "")} for s in (t.get("steps") or [])],
            "result": t.get("result", ""), "error": t.get("error", ""),
            "log": list(t.get("log") or [])[-50:],
            "created_at": t.get("created_at"), "updated_at": t.get("updated_at"),
        }
        # BMRBD v61.17 TASK: a setup background task carries its link
        # back to the scheduled task (and its kind) so the Scheduled
        # page can render "Running — 45%" inline. Only present when
        # set — ordinary A13 tasks keep the exact old shape, and the
        # fields persist because _bg_tasks_save snapshots via this fn.
        if t.get("kind"):
            _pub["kind"] = t.get("kind")
        if t.get("scheduled_task_id"):
            _pub["scheduled_task_id"] = t.get("scheduled_task_id")
        return _pub
    except Exception:
        return {"id": t.get("id"), "title": t.get("title"), "status": "error",
                "progress": 0, "steps": [], "result": "", "error": "unreadable task",
                "log": [], "created_at": None, "updated_at": None}


def _bg_tasks_save():
    # Atomic tmp+replace, same pattern as _save_shared_chats. Uses an
    # RLock, so callers may already hold it (the runner saves while
    # holding the lock; the save itself only snapshots).
    try:
        with _BG_TASKS_LOCK:
            snap = {k: _bg_task_public(v) for k, v in _BG_TASKS.items()}
        tmp = _BG_TASKS_FILE.with_suffix(".json.tmp")
        tmp.write_text(json.dumps(snap, ensure_ascii=False), encoding="utf-8")
        tmp.replace(_BG_TASKS_FILE)
        # BMRBD v61.16 COORD (B3): bg-task history travels in the vault.
        try:
            _BMRBD_STATE["bg_tasks"] = dict(snap)
            _bmrbd_mark_vault_cloud_dirty()
        except Exception:
            pass
    except Exception:
        pass


def _bg_tasks_load():
    # Reload the persisted store (bridge-restart resume). Tasks that were
    # mid-flight when the process died can never finish — their thread
    # died with it — so they come back as honest errors, not phantom
    # "running" tasks that never move.
    # BMRBD v61.16 COORD (B3): the vault state is the source of truth
    # (the /tmp file dies with the kernel on rotation). Load the UNION
    # of state and file — state wins on id conflict; the file is the
    # migration path for records a pre-v61.16 kernel wrote.
    global _BG_TASKS
    try:
        _file_data = {}
        if _BG_TASKS_FILE.exists():
            _file_data = json.loads(_BG_TASKS_FILE.read_text(encoding="utf-8")) or {}
            if not isinstance(_file_data, dict):
                _file_data = {}
    except Exception:
        _file_data = {}
    _state_data = _BMRBD_STATE.get("bg_tasks")
    data = dict(_file_data)
    if isinstance(_state_data, dict):
        data.update(_state_data)
    with _BG_TASKS_LOCK:
        _BG_TASKS = {}
        _changed = False
        for tid, t in data.items():
            if not isinstance(t, dict):
                continue
            t = dict(t)
            t["id"] = str(tid)
            if t.get("status") in ("queued", "running"):
                t["status"] = "error"
                t["error"] = "Interrupted by bridge restart while the task was running."
                (t.setdefault("log", [])).append({"t": _bg_now(), "text": "Bridge restarted — task interrupted."})
                for s in (t.get("steps") or []):
                    if isinstance(s, dict) and s.get("status") == "doing":
                        s["status"] = "todo"
                _changed = True
            _BG_TASKS[str(tid)] = t
    if _changed:
        _bg_tasks_save()


def _bg_tasks_start_next():
    # BMRBD v61.16 COORD (B4): start the oldest queued build when a slot
    # frees. Called from _run_bg_task's finally (done AND error). The
    # picked task is marked "running" under the lock BEFORE its thread
    # starts, so two completions racing cannot start a fourth build.
    try:
        with _BG_TASKS_LOCK:
            _running = sum(1 for _x in _BG_TASKS.values() if _x.get("status") == "running")
            if _running >= _BG_TASKS_RUNNING_MAX:
                return
            _queued = sorted(((_v.get("created_at") or "", _k) for _k, _v in _BG_TASKS.items() if _v.get("status") == "queued"), key=lambda kv: kv[0])
            if not _queued:
                return
            _tid = _queued[0][1]
            _BG_TASKS[_tid]["status"] = "running"
            _BG_TASKS[_tid].setdefault("log", []).append({"t": _bg_now(), "text": "Dequeued — a build slot freed up, starting now."})
            _bg_tasks_save()
        threading.Thread(target=_run_bg_task, args=(_tid,), daemon=True).start()
    except Exception:
        pass


def _run_bg_task(task_id):
    # Daemon-thread executor: sequential steps, each one short
    # non-streaming local-model call. Never raises out of the thread —
    # a failure marks the task error and persists it.
    with _BG_TASKS_LOCK:
        t = _BG_TASKS.get(task_id)
        if not t:
            return
        t["status"] = "running"
        t["updated_at"] = _bg_now()
        t.setdefault("log", []).append({"t": _bg_now(), "text": "Task started on the server."})
        _bg_tasks_save()
    # BMRBD v61.21 BUG-2: "full" mode — one long autonomous-task
    # completion (same task-mode prompt the foreground stream uses),
    # then package fenced code blocks into real download links.
    if str(t.get("mode") or "steps") == "full":
        try:
            with _BG_TASKS_LOCK:
                _st0 = (t.get("steps") or [{}])[0]
                if isinstance(_st0, dict):
                    _st0["status"] = "doing"
                t["progress"] = 5
                t["updated_at"] = _bg_now()
                _bg_tasks_save()
            # BMRBD v76.2 TASKUI: the single _bmrbd_full_llm call below
            # blocks up to 900 s with no intermediate signal, so the
            # old code left progress frozen at 5% and Steps 0/4 for
            # the whole run \u2014 the Tasks page looked dead. A daemon
            # heartbeat advances staged, elapsed-time progress (never
            # past 85% \u2014 100% is only set by the real completion
            # below) and walks the step markers, so polling shows real
            # movement. It stops the moment the call returns and never
            # writes a terminal state itself. Interval is
            # _BG_TASK_HEARTBEAT_S when defined, else 20 s.
            _hb_stop = threading.Event()
            _hb_interval = float(globals().get("_BG_TASK_HEARTBEAT_S", 20) or 20)

            def _hb_tick():
                try:
                    while not _hb_stop.wait(_hb_interval):
                        with _BG_TASKS_LOCK:
                            if t.get("status") != "running":
                                return
                            _p = int(t.get("progress") or 0)
                            if _p >= 85:
                                continue
                            _p = min(85, _p + 10)
                            t["progress"] = _p
                            _steps_hb = t.get("steps") or []
                            _doing = 0 if _p < 25 else (1 if _p < 55 else 2)
                            for _i, _s in enumerate(_steps_hb):
                                if isinstance(_s, dict):
                                    _s["status"] = "done" if _i < _doing else ("doing" if _i == _doing else "todo")
                            t["updated_at"] = _bg_now()
                            _bg_tasks_save()
                except Exception:
                    pass

            threading.Thread(target=_hb_tick, daemon=True).start()
            _goal = str(t.get("goal") or t.get("title") or "")
            _sys = ("You are BMRBD Ai, an autonomous coding agent. "
                    "Complete the entire task thoroughly in one continuous run. "
                    "Write 100% complete, functional files inside fenced code blocks "
                    "with filenames (e.g. ```index.html, ```styles.css, ```app.js, "
                    "```main.py) so the server packages them into direct downloadable "
                    "files and a .ZIP bundle. OUTSIDE the fenced file blocks, give only "
                    "a brief summary (what was built, file names, download links) — "
                    "NEVER paste the full code again in chat text. "
                    "Keep any reasoning SHORT, inside ONE <think>...</think> block "
                    "(at most ~20% of the reply), and ALWAYS write the complete final "
                    "answer — including every fenced file block — AFTER the closing "
                    "</think> tag. NEVER put the final answer or the code files inside "
                    "the <think> block.")
            _out = _bmrbd_full_llm(_sys, _goal, max_tokens=12000, timeout_s=900)
            if not _out:
                raise RuntimeError("The model answered but produced no visible text for this task (reasoning only, even after a direct-answer retry). Try Chat mode, or rephrase the task more specifically.")
            # BMRBD v76.2 TASKUI: an unclosed fence here means the reply
            # was cut off mid-file even after continuation \u2014 remember
            # it so the stored result can say so plainly (checked before
            # packaging strips the fences out of the prose below).
            _truncated = _out.count("```") % 2 == 1
            try:
                _packaged = package_code_blocks_from_text_to_media_links(_out, force_package_all=True, user_query=_goal)
            except Exception:
                _packaged = ""
            if _packaged:
                # The packager returns ONLY the download chips — keep the
                # model's own brief summary (code blocks stripped) above them.
                _prose = re.sub(r"```[a-zA-Z0-9_./-]*\n[\s\S]*?```", "", _out).strip()
                _out = (_prose + "\n\n" + _packaged).strip() if _prose else _packaged
            if _truncated:
                _out = (_out + "\n\n\u26a0\ufe0f The reply was cut off at the length limit \u2014 the file above may be incomplete. Split the task into smaller parts and try again.").strip()
            with _BG_TASKS_LOCK:
                for _s in (t.get("steps") or []):
                    if isinstance(_s, dict):
                        _s["status"] = "done"
                        if not _s.get("output"):
                            _s["output"] = "Done."
                t["status"] = "done"
                t["progress"] = 100
                t["result"] = _out[:60000]
                t.setdefault("log", []).append({"t": _bg_now(), "text": "Task finished."})
                t["updated_at"] = _bg_now()
                _bg_tasks_save()
        except Exception as e:
            with _BG_TASKS_LOCK:
                t["status"] = "error"
                t["error"] = str(e)[:500]
                t.setdefault("log", []).append({"t": _bg_now(), "text": "Task failed: " + str(e)[:200]})
                t["updated_at"] = _bg_now()
                _bg_tasks_save()
        finally:
            _hb_stop.set()
            _bg_tasks_start_next()
        return
    try:
        steps = t.get("steps") or []
        total = max(1, len(steps))
        outputs = []
        for i, st in enumerate(steps):
            with _BG_TASKS_LOCK:
                st["status"] = "doing"
                t["progress"] = int(i * 100 / total)
                t["updated_at"] = _bg_now()
                _bg_tasks_save()
            out = _bmrbd_short_llm(
                "You are BMRBD Ai, working one step of a background task. "
                "Answer briefly and concretely (under 120 words).",
                str(st.get("text") or ""), max_tokens=120, timeout_s=8)
            if not out:
                out = "(no reply from the local model for this step)"
            with _BG_TASKS_LOCK:
                st["status"] = "done"
                st["output"] = out[:2000]
                outputs.append(out[:2000])
                t["progress"] = int((i + 1) * 100 / total)
                t["updated_at"] = _bg_now()
                _bg_tasks_save()
        with _BG_TASKS_LOCK:
            t["status"] = "done"
            t["progress"] = 100
            t["result"] = "\n\n".join(outputs)[:8000]
            t.setdefault("log", []).append({"t": _bg_now(), "text": "Task finished."})
            t["updated_at"] = _bg_now()
            _bg_tasks_save()
    except Exception as e:
        with _BG_TASKS_LOCK:
            t["status"] = "error"
            t["error"] = str(e)[:500]
            t.setdefault("log", []).append({"t": _bg_now(), "text": "Task failed: " + str(e)[:200]})
            t["updated_at"] = _bg_now()
            _bg_tasks_save()
    finally:
        _bg_tasks_start_next()  # BMRBD v61.16 COORD (B4): free the slot for the next queued build, done or error.


_bg_tasks_load()
# ── BMRBD v61.16 SCHEDULED store ──
# Per-user scheduled tasks: GET/POST /api/scheduled-tasks. Persisted to
# a JSON file (same /tmp atomic-write pattern as _BG_TASKS, so a bridge
# restart inside the same kernel session keeps them). Owner is the token
# user's username (fallback email). BMRBD v61.18 LOGIN-BRIDGE: no unauthenticated owner — callers without a valid token get 401.
# Statuses: active / paused / completed. Frequencies: daily / weekly /
# one-time. next_run is computed server-side from frequency + time
# (+ date for one-time), server time, human-readable "YYYY-MM-DD HH:MM".
_SCHED_TASKS_FILE = Path("/tmp/bmrbd_scheduled_tasks.json")
_SCHED_TASKS = {}
_SCHED_CLOUD_FORCE_TS = 0.0  # BMRBD v61.21 BUG-1: last forced cloud flush after a scheduled-task mutation
_SCHED_TASKS_LOCK = threading.RLock()
_SCHED_FREQUENCIES = ("daily", "weekly", "one-time", "hourly")  # BMRBD v61.17 TASK: "every hour" parses to hourly
_SCHED_WEEKDAYS = ("Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday")
_SCHED_STATUSES = ("active", "paused", "completed")


def _sched_now_iso():
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def _sched_parse_time(s):
    try:
        parts = str(s or "").strip().split(":")
        h, m = int(parts[0]), int(parts[1])
        if 0 <= h <= 23 and 0 <= m <= 59:
            return (h, m)
    except Exception:
        pass
    return None


# BMRBD v76.2 TASKUI (R2): scheduled times are DHAKA wall time, not
# server-local time. The Kaggle kernel runs UTC, so the old
# time.localtime/time.mktime math fired a 07:00 task at 13:00 Dhaka.
# Bangladesh has no DST, so a fixed UTC+6 offset is exact — no tzdata
# dependency (zoneinfo is not guaranteed on the kernel). All
# _sched_next_run inputs/outputs are Dhaka wall times; the stored
# next_run_ts stays an epoch (tz-independent), and the label is Dhaka.
_SCHED_TZ_NAME = "Asia/Dhaka"
_SCHED_TZ = timezone(timedelta(hours=6))


def _sched_dhaka_dt(epoch_s):
    return datetime.fromtimestamp(epoch_s, tz=_SCHED_TZ)


def _sched_epoch_of_dhaka(y, mo, d, h, mi):
    return datetime(y, mo, d, h, mi, tzinfo=_SCHED_TZ).timestamp()


def _sched_valid_date(date_str):
    # Strict YYYY-MM-DD: strptime alone accepts "2026-1-5", so require
    # the round-trip to be identical (R4).
    try:
        ds = str(date_str or "").strip()
        return bool(ds) and datetime.strptime(ds, "%Y-%m-%d").strftime("%Y-%m-%d") == ds
    except Exception:
        return False


def _sched_next_run(frequency, time_str, date_str, weekday=None):
    # Returns (next_run_ts, next_run_label). Daily: today at time, else
    # tomorrow. Weekly: today at time, else same weekday next week —
    # or, when a weekday is given (BMRBD v61.17 TASK: "every Saturday"),
    # the next occurrence of THAT weekday at the time. Hourly: the next
    # whole hour.
    # One-time: the given date at time (defaults to tomorrow when no
    # date is supplied); a past one-time slot is kept as given — the
    # honest-limit note on the page says such a task runs only while
    # the server is up, so a missed slot is visible, never silently moved.
    # R4: a PROVIDED but invalid one-time date raises ValueError (the
    # POST handler turns it into a 400) instead of silently becoming
    # tomorrow 07:00. All wall times are Dhaka (R2).
    hm = _sched_parse_time(time_str) or (7, 0)
    h, m = hm
    now = time.time()
    if frequency == "one-time":
        ds = str(date_str or "").strip()
        if ds and not _sched_valid_date(ds):
            raise ValueError("Invalid date %r — use YYYY-MM-DD" % ds)
    try:
        _now_dh = _sched_dhaka_dt(now)
        if frequency == "one-time":
            ds = str(date_str or "").strip()
            if ds:
                _st = datetime.strptime(ds, "%Y-%m-%d")
                cand = _sched_epoch_of_dhaka(_st.year, _st.month, _st.day, h, m)
            else:
                _tom = _now_dh + timedelta(days=1)
                cand = _sched_epoch_of_dhaka(_tom.year, _tom.month, _tom.day, h, m)
        elif frequency == "hourly":
            _nx = (_now_dh.replace(minute=0, second=0, microsecond=0) + timedelta(hours=1))
            cand = _nx.timestamp()
        elif frequency == "weekly" and weekday in _SCHED_WEEKDAYS:
            _ahead = (_SCHED_WEEKDAYS.index(weekday) - _now_dh.weekday()) % 7
            _day = _now_dh + timedelta(days=_ahead)
            cand = _sched_epoch_of_dhaka(_day.year, _day.month, _day.day, h, m)
            if cand <= now:
                cand = _sched_epoch_of_dhaka(_day.year, _day.month, _day.day, h, m) + 7 * 86400
        else:
            cand = _sched_epoch_of_dhaka(_now_dh.year, _now_dh.month, _now_dh.day, h, m)
            if cand <= now:
                cand += 86400 if frequency == "daily" else 7 * 86400
    except Exception:
        _tom = _sched_dhaka_dt(now) + timedelta(days=1)
        cand = _sched_epoch_of_dhaka(_tom.year, _tom.month, _tom.day, h, m)
    return (cand, _sched_dhaka_dt(cand).strftime("%Y-%m-%d %H:%M"))


def _sched_new_task(owner, title, prompt, frequency, time_str, date_str, weekday=None):
    freq = frequency if frequency in _SCHED_FREQUENCIES else "daily"
    hm = _sched_parse_time(time_str) or (7, 0)
    tstr = "%02d:%02d" % hm
    _ts, _label = _sched_next_run(freq, tstr, date_str, weekday)
    _now = _sched_now_iso()
    return {
        "id": "schedtask_" + uuid.uuid4().hex[:12],
        "owner": owner,
        "title": str(title or "Scheduled task")[:200],
        "prompt": str(prompt or "")[:2000],
        "frequency": freq,
        "time": tstr,
        "date": str(date_str or "")[:10],
        "weekday": str(weekday or "")[:10],  # BMRBD v61.17 TASK: e.g. "Saturday" for weekly tasks
        "status": "active",
        "next_run": _label,
        "next_run_ts": _ts,
        "last_run": "",
        "last_result": "",
        "last_bg_task_id": "",
        "created_at": _now,
        "updated_at": _now,
    }


def _sched_public(t):
    try:
        return {
            "id": t.get("id"), "title": t.get("title"), "prompt": t.get("prompt"),
            "frequency": t.get("frequency"), "time": t.get("time"),
            "date": t.get("date"), "weekday": t.get("weekday", ""), "status": t.get("status"),
            "next_run": t.get("next_run"), "next_run_ts": t.get("next_run_ts"),
            "last_run": t.get("last_run", ""), "last_result": t.get("last_result", ""),
            "last_bg_task_id": t.get("last_bg_task_id", ""),
            "created_at": t.get("created_at"), "updated_at": t.get("updated_at"),
        }
    except Exception:
        return {"id": t.get("id"), "title": t.get("title"), "status": "error",
                "frequency": "daily", "time": "07:00", "date": "", "weekday": "",
                "next_run": "", "next_run_ts": 0, "last_run": "", "last_result": "",
                "last_bg_task_id": "", "created_at": None, "updated_at": None}


def _sched_tasks_save():
    # Atomic tmp+replace, same pattern as _bg_tasks_save. The persisted
    # record is the public view PLUS owner: without owner, a bridge
    # restart would make every task invisible to its own user (the list
    # endpoint filters by owner). Owner never leaves the server — the
    # public view sent to the browser omits it.
    try:
        with _SCHED_TASKS_LOCK:
            snap = {}
            for k, v in _SCHED_TASKS.items():
                rec = _sched_public(v)
                rec["owner"] = v.get("owner") or ""  # BMRBD v61.18 LOGIN-BRIDGE: no unauthenticated owner
                snap[k] = rec
        tmp = _SCHED_TASKS_FILE.with_suffix(".json.tmp")
        tmp.write_text(json.dumps(snap, ensure_ascii=False), encoding="utf-8")
        tmp.replace(_SCHED_TASKS_FILE)
        # BMRBD v61.16 COORD (B3): scheduled tasks travel in the vault.
        try:
            _BMRBD_STATE["scheduled_tasks"] = dict(snap)
            _save_bmrbd_state_local(push_peer=False)
        except Exception:
            pass
        # BMRBD v61.21 BUG-1: a scheduled task must survive the next
        # kernel rotation. The flush daemon uploads only after a quiet
        # interval, and a kernel can be replaced before that elapses —
        # force a cloud flush right after a scheduled-task mutation
        # (throttled: at most once per 30s).
        try:
            global _SCHED_CLOUD_FORCE_TS
            _now_f = time.time()
            if _now_f - _SCHED_CLOUD_FORCE_TS >= 30:
                _SCHED_CLOUD_FORCE_TS = _now_f
                threading.Thread(target=sync_bmrbd_vault_to_cloud, daemon=True).start()
        except Exception:
            pass
    except Exception:
        pass


def _sched_tasks_load():
    # Reload the persisted store (bridge-restart resume). Records written
    # before owner was persisted (none in practice — save always writes
    # it) default to "" (ownerless — visible to no user).
    # BMRBD v61.16 COORD (B3): the vault state is the source of truth
    # (the /tmp file dies with the kernel on rotation). Load the UNION
    # of state and file — state wins on id conflict; the file is the
    # migration path for records a pre-v61.16 kernel wrote.
    global _SCHED_TASKS
    try:
        _file_data = {}
        if _SCHED_TASKS_FILE.exists():
            _file_data = json.loads(_SCHED_TASKS_FILE.read_text(encoding="utf-8")) or {}
            if not isinstance(_file_data, dict):
                _file_data = {}
    except Exception:
        _file_data = {}
    _state_data = _BMRBD_STATE.get("scheduled_tasks")
    data = dict(_file_data)
    if isinstance(_state_data, dict):
        data.update(_state_data)
    with _SCHED_TASKS_LOCK:
        _SCHED_TASKS = {}
        for tid, t in data.items():
            if not isinstance(t, dict):
                continue
            t = dict(t)
            t["id"] = str(tid)
            if t.get("status") not in _SCHED_STATUSES:
                t["status"] = "active"
            t.setdefault("owner", "")  # BMRBD v61.18 LOGIN-BRIDGE
            _SCHED_TASKS[str(tid)] = t


def _sched_owner_of(handler):
    # BMRBD v61.18 LOGIN-BRIDGE: token user -> username (fallback email);
    # anything else -> None (caller returns 401). There is no
    # unauthenticated owner any more — callers without a valid token own
    # nothing.
    u = _require_valid_token(handler)
    if u:
        return str(u.get("username") or u.get("email") or "user")
    return None


def _sched_mine(owner):
    with _SCHED_TASKS_LOCK:
        mine = [_sched_public(t) for t in _SCHED_TASKS.values() if t.get("owner") == owner]
    mine.sort(key=lambda x: x.get("next_run_ts") or 0)
    return mine
# ── END BMRBD v61.16 SCHEDULED store ──

_sched_tasks_load()
# ── BMRBD v76.2 TASKUI (R1): the per-user scheduled-task daemon ──
# Before this, NO daemon, thread or loop ever scanned _SCHED_TASKS: a
# scheduled task could be created, listed ("Next run: ...") and edited,
# but never executed — the only scheduler daemon served _SHARED_SCHEDULES.
# This daemon scans _SCHED_TASKS every 20 s (same cadence) and fires due
# tasks as linked background tasks (mode "full": the fixed Task engine,
# result + files packaged, progress visible inline via
# _v6117_bg_link_for). A task whose previous run is still active is
# skipped this slot (no pile-up). One-time tasks complete at fire time;
# recurring tasks advance to their next Dhaka slot at fire time, so a
# bridge restart can never double-fire a slot. last_run is stamped at
# fire time; a watcher thread writes last_result when the run finishes.
_SCHED_DAEMON_INTERVAL_S = 20
_SCHED_WATCH_INTERVAL_S = 15


def _sched_due_task_ids(now_ts=None):
    # IDs of active tasks whose slot has come, excluding tasks with a
    # run still active (running/queued linked bg task). Pure scan —
    # unit-tested; takes no locks beyond snapshot reads.
    _now = time.time() if now_ts is None else float(now_ts)
    try:
        with _SCHED_TASKS_LOCK:
            _tasks = list(_SCHED_TASKS.values())
        with _BG_TASKS_LOCK:
            _active_linked = {str(_x.get("scheduled_task_id") or "") for _x in _BG_TASKS.values() if _x.get("status") in ("running", "queued") and _x.get("scheduled_task_id")}
    except Exception:
        return []
    return [str(_t.get("id") or "") for _t in _tasks
            if _t.get("status") == "active"
            and float(_t.get("next_run_ts") or 0) <= _now
            and str(_t.get("id") or "") not in _active_linked
            and str(_t.get("id") or "")]


def _sched_start_run_bg_task(sched_task):
    # Start one execution as a linked bg task (same creation shape as
    # POST /api/tasks/start: 3-slot cap, queue when full). kind
    # "scheduled_run" + scheduled_task_id link it back so the Tasks
    # page shows its progress inline. Returns the bg task id ("" on
    # any failure — the schedule itself was already advanced).
    try:
        _goal = str(sched_task.get("prompt") or "")[:20000]
        _steps = ["Understand the request", "Plan the work", "Build the full result", "Verify and package files"]
        with _BG_TASKS_LOCK:
            _running = sum(1 for _x in _BG_TASKS.values() if _x.get("status") == "running")
            _start_now = _running < _BG_TASKS_RUNNING_MAX
            _tid = "task_" + uuid.uuid4().hex[:12]
            _now = _bg_now()
            _BG_TASKS[_tid] = {
                "id": _tid,
                "title": "Scheduled: " + str(sched_task.get("title") or "Scheduled task")[:160],
                "goal": _goal,
                "mode": "full",
                "kind": "scheduled_run",
                "scheduled_task_id": sched_task.get("id"),
                "status": "running" if _start_now else "queued",
                "progress": 0,
                "steps": [{"text": s, "status": "todo", "output": ""} for s in _steps],
                "result": "", "error": "", "log": [],
                "created_at": _now, "updated_at": _now,
            }
            while len(_BG_TASKS) > _BG_TASKS_MAX:
                _old = sorted(((_v.get("updated_at") or "", _k) for _k, _v in _BG_TASKS.items()
                               if _v.get("status") in ("done", "error")), key=lambda kv: kv[0])
                if not _old:
                    break
                del _BG_TASKS[_old[0][1]]
            _bg_tasks_save()
        if _start_now:
            _runner = globals().get("_run_bg_task")
            if callable(_runner):
                threading.Thread(target=_runner, args=(_tid,), daemon=True).start()
        return _tid
    except Exception:
        return ""


def _sched_fire_task(task_id):
    # Fire ONE due task by id: re-read it fresh under the lock (the
    # store can be reloaded under us), start its run, stamp last_run,
    # advance or complete it, save. Returns the bg task id ("" when
    # there was nothing to fire). Never raises out of the daemon.
    try:
        with _SCHED_TASKS_LOCK:
            _t = _SCHED_TASKS.get(str(task_id))
            if not isinstance(_t, dict) or _t.get("status") != "active":
                return ""
            if float(_t.get("next_run_ts") or 0) > time.time():
                return ""
            _t = dict(_t)
        _bg_id = _sched_start_run_bg_task(_t)
        _now_iso = _sched_now_iso()
        with _SCHED_TASKS_LOCK:
            _live = _SCHED_TASKS.get(str(task_id))
            if not isinstance(_live, dict):
                return _bg_id
            _live["last_run"] = _now_iso
            _live["last_bg_task_id"] = _bg_id
            if str(_live.get("frequency") or "") == "one-time":
                _live["status"] = "completed"
            else:
                try:
                    _ts, _label = _sched_next_run(_live.get("frequency"), _live.get("time"), _live.get("date"), _live.get("weekday"))
                except ValueError:
                    _ts, _label = _live.get("next_run_ts") or 0, _live.get("next_run") or ""
                _live["next_run_ts"] = _ts
                _live["next_run"] = _label
            _live["updated_at"] = _now_iso
        _sched_tasks_save()
        if _bg_id:
            threading.Thread(target=_sched_watch_bg_task, args=(str(task_id), _bg_id), daemon=True).start()
        return _bg_id
    except Exception:
        return ""


def _sched_watch_bg_task(sched_id, bg_id):
    # Watch one fired run until it finishes, then write its result back
    # onto the scheduled task as last_result (first 1500 chars, or a
    # short failure note). Best-effort: never raises. Poll interval is
    # _SCHED_WATCH_INTERVAL_S when defined, else 15 s.
    try:
        _interval = float(globals().get("_SCHED_WATCH_INTERVAL_S", 15) or 15)
        while True:
            time.sleep(_interval)
            with _BG_TASKS_LOCK:
                _b = _BG_TASKS.get(str(bg_id))
                _st = str((_b or {}).get("status") or "")
                _res = str((_b or {}).get("result") or "")
                _err = str((_b or {}).get("error") or "")
            if _st not in ("done", "error"):
                if _b is None:
                    return
                continue
            _note = (_res[:1500] if _st == "done" else ("Failed: " + _err[:500])) or ""
            with _SCHED_TASKS_LOCK:
                _live = _SCHED_TASKS.get(str(sched_id))
                if isinstance(_live, dict):
                    _live["last_result"] = _note
                    _live["updated_at"] = _sched_now_iso()
            _sched_tasks_save()
            return
    except Exception:
        return


def _sched_tasks_daemon():
    # Every 20 s: fire each due per-user scheduled task once.
    while True:
        try:
            for _tid in _sched_due_task_ids():
                _sched_fire_task(_tid)
        except Exception:
            pass
        time.sleep(_SCHED_DAEMON_INTERVAL_S)


threading.Thread(target=_sched_tasks_daemon, daemon=True).start()

# ── BMRBD v61.17 TASK ──
# Task creation from chat + Recommended dismiss persistence +
# completed-task edit guard + A13 surfacing data for the Scheduled
# page (bridge half of the v61.17 hubhu rebuild; the dashboard half
# lives in the v61.17 dashboard fragment).
#
# The bridge imports `re` nowhere else — this block imports it here
# (module level, so the name is visible to the whole bridge).
import re

# ── Recommended automations (study, card texts; the news card's SENT
# text is the one observed in the study — the other five canonical
# prompts are the card descriptions, since the study only ever
# clicked + on News. The parse works on whatever text the dashboard
# actually sends; these are the fallback when the chat message
# arrives empty.)
_V6117_RECOMMENDED = {
    "news": {
        "title": "Update me on the news",
        "prompt": "Send me a daily briefing on the topics I'm interested in, or a roundup of major news if you don't know my interests yet.",
        "frequency": "daily", "weekday": "", "time": "09:00",
    },
    "email": {
        "title": "Email monitor",
        "prompt": "Scan my emails and let me know anything that needs my attention",
        "frequency": "daily", "weekday": "", "time": "09:00",
    },
    "weekend-reads": {
        "title": "Find me a great weekend read",
        "prompt": "Send me a great article to read every Saturday.",
        "frequency": "weekly", "weekday": "Saturday", "time": "09:00",
    },
    "price-alerts": {
        "title": "Tell me when the price drops",
        "prompt": "Check prices daily and alert me when my item costs less.",
        "frequency": "daily", "weekday": "", "time": "09:00",
    },
    "concerts": {
        "title": "Find concerts I'd love to see",
        "prompt": "Check weekly for new concerts that match my taste.",
        "frequency": "weekly", "weekday": "", "time": "09:00",
    },
    "plan-weekend": {
        "title": "Find something fun for my weekend",
        "prompt": "Send me local weekend ideas every Thursday.",
        "frequency": "weekly", "weekday": "Thursday", "time": "09:00",
    },
}
_V6117_RECOMMENDED_KEYS = tuple(_V6117_RECOMMENDED.keys())

# ── Dismissed Recommended automations (per-user, disk + vault) ──
# Same persistence pattern as the scheduled-task store: own /tmp JSON
# file (atomic tmp+replace, own lock, load-on-boot) + a mirror in
# _BMRBD_STATE so the vault (vault.enc) carries it across kernels.
_SCHED_DISMISSED_FILE = Path("/tmp/bmrbd_scheduled_dismissed.json")
_SCHED_DISMISSED = {}
_SCHED_DISMISSED_LOCK = threading.RLock()


def _sched_dismissed_save():
    try:
        with _SCHED_DISMISSED_LOCK:
            snap = {str(k): sorted(set(str(x) for x in (v or [])))
                    for k, v in _SCHED_DISMISSED.items()}
        tmp = _SCHED_DISMISSED_FILE.with_suffix(".json.tmp")
        tmp.write_text(json.dumps(snap, ensure_ascii=False), encoding="utf-8")
        tmp.replace(_SCHED_DISMISSED_FILE)
        # BMRBD v61.17 TASK (B3): dismissed keys travel in the vault
        # exactly like scheduled tasks and bg tasks.
        try:
            _BMRBD_STATE["scheduled_recommended_dismissed"] = dict(snap)
            _save_bmrbd_state_local(push_peer=False)
        except Exception:
            pass
    except Exception:
        pass


def _sched_dismissed_load():
    # Union of file + vault state; state wins per owner (same rule as
    # _sched_tasks_load / _bg_tasks_load).
    global _SCHED_DISMISSED
    try:
        _file_data = {}
        if _SCHED_DISMISSED_FILE.exists():
            _file_data = json.loads(_SCHED_DISMISSED_FILE.read_text(encoding="utf-8")) or {}
            if not isinstance(_file_data, dict):
                _file_data = {}
    except Exception:
        _file_data = {}
    _state_data = _BMRBD_STATE.get("scheduled_recommended_dismissed")
    data = dict(_file_data)
    if isinstance(_state_data, dict):
        data.update(_state_data)
    with _SCHED_DISMISSED_LOCK:
        _SCHED_DISMISSED = {}
        for owner, keys in data.items():
            if not isinstance(keys, list):
                continue
            _SCHED_DISMISSED[str(owner)] = sorted(set(str(k) for k in keys if str(k) in _V6117_RECOMMENDED_KEYS))


def _sched_dismissed_for(owner):
    with _SCHED_DISMISSED_LOCK:
        return list(_SCHED_DISMISSED.get(owner) or [])


def _sched_dismiss_recommended(owner, key):
    # Returns the owner's updated dismissed list, or None for an
    # unknown key (the caller answers 400).
    key = str(key or "").strip().lower()
    if key not in _V6117_RECOMMENDED_KEYS:
        return None
    with _SCHED_DISMISSED_LOCK:
        cur = _SCHED_DISMISSED.setdefault(owner, [])
        if key not in cur:
            cur.append(key)
        cur[:] = sorted(set(cur))
        out = list(cur)
    _sched_dismissed_save()
    return out


# ── Completed-task edit guard (study: a Completed task's Edit dialog
# has Title / Prompt / Frequency / Date / Time disabled; only a status
# change is allowed, via the proper action) ──
_V6117_EDIT_BLOCKED_FIELDS = ("title", "prompt", "frequency", "time", "date", "weekday")


def _v6117_edit_rejected(task, payload):
    if not isinstance(task, dict) or task.get("status") != "completed":
        return False
    if not isinstance(payload, dict):
        return False
    return any(payload.get(k) is not None for k in _V6117_EDIT_BLOCKED_FIELDS)


# ── A13 surfacing data: bg progress for a scheduled task ──
def _v6117_bg_link_for(sched_id):
    # Newest A13 background task linked to this scheduled task, or
    # (None, None). The link is the bg record's `scheduled_task_id`
    # (BMRBD v61.17 TASK); a plain A13 task has no such field.
    try:
        with _BG_TASKS_LOCK:
            _linked = [_x for _x in _BG_TASKS.values() if _x.get("scheduled_task_id") == sched_id]
        if not _linked:
            return (None, None)
        _linked.sort(key=lambda _x: _x.get("created_at") or "", reverse=True)
        _newest = _linked[0]
        return (int(_newest.get("progress") or 0), str(_newest.get("status") or ""))
    except Exception:
        return (None, None)


def _v6117_enrich_sched_list(tasks):
    # Copies each public task and adds bg_progress / bg_status so the
    # dashboard can render "Running — 45%" inline in the Active list.
    # No new panel, no new endpoint — just enriched fields.
    out = []
    for t in (tasks or []):
        try:
            t = dict(t)
            _prog, _st = _v6117_bg_link_for(t.get("id"))
            t["bg_progress"] = _prog
            t["bg_status"] = _st
        except Exception:
            pass
        out.append(t)
    return out


# ── Scheduling-intent parser (deterministic, no model call) ──
def _v6117_smart_title(raw):
    # First sentence, smart-truncated to ~60 chars at a word boundary.
    t = " ".join(str(raw or "").split())
    if not t:
        return "Scheduled task"
    m = re.search(r"[.!?](?:\s|$)", t)
    if m:
        t = t[:m.start()].strip()
    if len(t) > 60:
        cut = t[:60]
        sp = cut.rfind(" ")
        if sp > 30:
            cut = cut[:sp]
        t = cut.rstrip(" ,;:") + "…"
    return t or "Scheduled task"


def _v6117_extract_time(low):
    # "5:09 PM" -> "17:09"; "17:00" -> "17:00"; "9am" -> "09:00".
    # A bare hour with no am/pm ("at 5") is ambiguous — ignored, the
    # caller falls back to the 09:00 default.
    m = re.search(r"(\d{1,2}):(\d{2})\s*([ap])\.?m\.?", low)
    if m:
        h, mi, ap = int(m.group(1)), int(m.group(2)), m.group(3)
        if 1 <= h <= 12 and 0 <= mi <= 59:
            if ap == "p" and h != 12:
                h += 12
            if ap == "a" and h == 12:
                h = 0
            return "%02d:%02d" % (h, mi)
        return None
    m = re.search(r"(\d{1,2}):(\d{2})", low)
    if m:
        h, mi = int(m.group(1)), int(m.group(2))
        if 0 <= h <= 23 and 0 <= mi <= 59:
            return "%02d:%02d" % (h, mi)
        return None
    m = re.search(r"(\d{1,2})\s*([ap])\.?m\.?", low)
    if m:
        h, ap = int(m.group(1)), m.group(2)
        if 1 <= h <= 12:
            if ap == "p" and h != 12:
                h += 12
            if ap == "a" and h == 12:
                h = 0
            return "%02d:00" % h
    return None


def _v6117_parse_schedule_intent(text):
    # Deterministic parse of the scheduling intent from the message
    # text: title (first sentence / first ~60 chars), frequency
    # keywords, a time if present else "09:00".
    raw = str(text or "").strip()
    low = raw.lower()
    time_str = _v6117_extract_time(low) or "09:00"
    frequency = "daily"
    weekday = ""
    if "every hour" in low or "hourly" in low:
        frequency = "hourly"
    else:
        for wd in _SCHED_WEEKDAYS:
            if wd.lower() in low:
                frequency = "weekly"
                weekday = wd
                break
        else:
            if "every day" in low or "daily" in low:
                frequency = "daily"
            elif "weekly" in low or "every week" in low:
                frequency = "weekly"
    return {"title": _v6117_smart_title(raw), "prompt": raw,
            "frequency": frequency, "weekday": weekday, "time": time_str}


def _v6117_freq_phrase(intent):
    f = intent.get("frequency")
    if f == "hourly":
        return "every hour"
    if f == "weekly" and intent.get("weekday"):
        return "every " + intent["weekday"]
    if f == "weekly":
        return "weekly"
    if f == "one-time":
        return "once"
    return "daily"


def _v6117_confirmation_text(intent):
    # Honest confirmation naming the title + frequency + time. In
    # live this text comes from the model; the deterministic text here
    # is the stub-harness reply and the fallback when the model is
    # unreachable. Hourly has no meaningful "at" time, so it says so.
    title = intent.get("title") or "Scheduled task"
    if intent.get("frequency") == "hourly":
        return ("I'll run '%s' every hour. You can pause, edit or delete "
                "it anytime from Scheduled." % title)
    return ("I'll run '%s' %s at %s. You can pause, edit or delete it "
            "anytime from Scheduled." % (title, _v6117_freq_phrase(intent),
                                         intent.get("time") or "09:00"))


# ── A13 setup background task for a chat-created schedule ──
def _v6117_start_setup_bg_task(sched_task):
    # Same creation shape as POST /api/tasks/start (3-slot cap, queue
    # when full, prune finished tasks past the cap, _bg_tasks_save).
    # kind 'scheduled_setup' + scheduled_task_id link the record to
    # its scheduled task so GET /api/scheduled-tasks can surface its
    # progress inline. Returns the bg task id ("" on any failure —
    # the schedule itself was already created and saved).
    try:
        with _BG_TASKS_LOCK:
            _running = sum(1 for _x in _BG_TASKS.values() if _x.get("status") == "running")
            _start_now = _running < _BG_TASKS_RUNNING_MAX
            _tid = "task_" + uuid.uuid4().hex[:12]
            _now = _bg_now()
            _BG_TASKS[_tid] = {
                "id": _tid,
                "title": "Set up: " + str(sched_task.get("title") or "Scheduled task")[:160],
                "goal": str(sched_task.get("prompt") or "")[:20000],
                "kind": "scheduled_setup",
                "scheduled_task_id": sched_task.get("id"),
                "status": "running" if _start_now else "queued",
                "progress": 0,
                "steps": [{"text": "Create the schedule", "status": "todo", "output": ""},
                          {"text": "Confirm the schedule is active", "status": "todo", "output": ""}],
                "result": "", "error": "", "log": [],
                "created_at": _now, "updated_at": _now,
            }
            while len(_BG_TASKS) > _BG_TASKS_MAX:
                _old = sorted(((_v.get("updated_at") or "", _k) for _k, _v in _BG_TASKS.items()
                               if _v.get("status") in ("done", "error")), key=lambda kv: kv[0])
                if not _old:
                    break
                del _BG_TASKS[_old[0][1]]
            _bg_tasks_save()
        if _start_now:
            # _run_bg_task is looked up at call time (not import time)
            # so this block also works in a stub harness that never
            # starts the thread.
            _runner = globals().get("_run_bg_task")
            if callable(_runner):
                threading.Thread(target=_runner, args=(_tid,), daemon=True).start()
        return _tid
    except Exception:
        return ""


def _v6117_last_user_text(parsed_body):
    # Last user-role message, plain string or content-parts list.
    try:
        msgs = parsed_body.get("messages") or []
        if not isinstance(msgs, list):
            return ""
        for m in reversed(msgs):
            if not isinstance(m, dict) or m.get("role") != "user":
                continue
            c = m.get("content")
            if isinstance(c, str) and c.strip():
                return c.strip()
            if isinstance(c, list):
                parts = [str(p.get("text") or "") for p in c
                         if isinstance(p, dict) and p.get("type") == "text" and str(p.get("text") or "").strip()]
                if parts:
                    return " ".join(parts).strip()
        return ""
    except Exception:
        return ""


def _v6117_send_task_reply(handler, reply, requested_model, is_stream, req_id):
    # Normal chat-completion-shaped reply (same shape as the instant
    # auxiliary replies): the dashboard renders it as an ordinary
    # assistant message.
    chat_id = "chatcmpl-" + uuid.uuid4().hex[:20]
    if is_stream:
        c1 = {"id": chat_id, "object": "chat.completion.chunk", "created": int(time.time()), "model": requested_model, "choices": [{"index": 0, "delta": {"role": "assistant", "content": reply}, "finish_reason": None}]}
        c2 = {"id": chat_id, "object": "chat.completion.chunk", "created": int(time.time()), "model": requested_model, "choices": [{"index": 0, "delta": {}, "finish_reason": "stop"}], "usage": {"prompt_tokens": 12, "completion_tokens": 5, "total_tokens": 17}}
        sse = ("data: " + json.dumps(c1) + "\n\ndata: " + json.dumps(c2) + "\n\ndata: [DONE]\n\n").encode("utf-8")
        return handler._send_bytes(200, "text/event-stream; charset=utf-8", sse, req_id=req_id)
    return handler._send_json(200, {
        "id": chat_id,
        "object": "chat.completion",
        "created": int(time.time()),
        "model": requested_model,
        "choices": [{"index": 0, "message": {"role": "assistant", "content": reply}, "finish_reason": "stop"}],
        "usage": {"prompt_tokens": 12, "completion_tokens": 5, "total_tokens": 17}
    }, req_id=req_id)


def _v6117_handle_task_create(handler, parsed_body, requested_model, is_stream, req_id):
    # BMRBD v61.17 TASK: POST /v1/chat/completions with task_create:
    # true never runs a normal completion. Deterministically parse the
    # scheduling intent, create the scheduled task, start the A13
    # setup task, and answer with a confirmation in chat-completion
    # shape. Auth was enforced by the /v1/* gate (BMRBD v61.18 LOGIN-BRIDGE: token-only now)
    # before this hook runs; _sched_owner_of re-checks and fails
    # closed (401) if somehow unauthenticated.
    owner = _sched_owner_of(handler)
    if owner is None:
        return handler._send_json(401, {"error": "Valid token required"}, req_id=req_id)
    text = _v6117_last_user_text(parsed_body)
    task_key = str(parsed_body.get("task_key") or "").strip().lower()
    task_source = str(parsed_body.get("task_source") or "").strip().lower()
    rec = _V6117_RECOMMENDED.get(task_key) if task_source == "recommended" else None
    if not text and rec:
        text = rec["prompt"]
    if not text:
        return _v6117_send_task_reply(
            handler,
            "Tell me what you'd like scheduled — what should it do, and when?",
            requested_model, is_stream, req_id)
    intent = _v6117_parse_schedule_intent(text)
    with _SCHED_TASKS_LOCK:
        _mine_n = sum(1 for _x in _SCHED_TASKS.values() if _x.get("owner") == owner)
    if _mine_n >= 50:
        return _v6117_send_task_reply(
            handler,
            "I couldn't create that schedule — you already have 50 scheduled tasks, the maximum. Delete or complete one first, then ask again.",
            requested_model, is_stream, req_id)
    with _SCHED_TASKS_LOCK:
        _nt = _sched_new_task(owner, intent["title"], text,
                              intent["frequency"], intent["time"], "", intent["weekday"])
        _SCHED_TASKS[_nt["id"]] = _nt
    _sched_tasks_save()
    _v6117_start_setup_bg_task(_nt)
    return _v6117_send_task_reply(handler, _v6117_confirmation_text(intent),
                                  requested_model, is_stream, req_id)
# ── END BMRBD v61.17 TASK ──

_sched_dismissed_load()
# ── BMRBD v61.13 P7+P8: per-user memory + settings (vault-backed) ──
# Stored INSIDE _BMRBD_STATE ("user_memory" / "user_settings", keyed by
# username) so they persist exactly like chats: _save_bmrbd_state_local()
