def _sa_media_store_list():
    items = []
    try:
        for p in list(MEDIA_STORE_DIR.iterdir())[:5000]:  # BMRBD v76.5 C3: bound the scan — /api/usage must never stall on a huge media store
            if not p.is_file():
                continue
            try:
                st = p.stat()
            except Exception:
                continue
            items.append({"name": p.name, "size_bytes": int(st.st_size),
                          "size_mb": round(st.st_size / (1024 * 1024), 3),
                          "kind": "image" if p.suffix.lower() in _SA_IMAGE_EXTS else "file",
                          "url": "/media/" + p.name,
                          "mtime": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(st.st_mtime))})
    except Exception:
        pass
    items.sort(key=lambda d: d["mtime"], reverse=True)
    return items


def _sa_recompute_used_gb(state, username):
    """BMRBD v76.2 LEFTOVER R22: REAL per-user storage in GB (min 0.01).

    Sums the JSON bytes of everything attributable to this account —
    threads, memories, settings, skills, connectors, projects and
    reference photos — instead of the stored used_gb field, which was
    only ever written at account creation (0.01/0.02) and by
    /api/auth/sync_chats counting thread JSON alone. The media store is
    deliberately EXCLUDED: it is a shared global store with no owner
    (see /api/storage "shared_store": True), so it cannot be attributed
    to one account; /api/usage and /api/storage already report it
    separately. Callers persist the result back to u_obj["used_gb"]."""
    _total_b = 0
    for _k in ("user_threads", "user_memory", "user_settings", "user_skills",
               "user_connectors", "user_projects", "user_reference_photos"):
        try:
            _total_b += len(json.dumps((state.get(_k) or {}).get(str(username)) or {}).encode("utf-8"))
        except Exception:
            pass
    return round(max(0.01, _total_b / (1024 ** 3)), 4)


def _bmrbd_user_personal_block(user_obj):
    """System-prompt block for one signed-in user: custom instructions +
    saved memory facts (only when the master memory toggle is on). The
    master toggle gates FACTS only; custom instructions always apply."""
    if not isinstance(user_obj, dict):
        return ""
    uname = str(user_obj.get("username") or "")
    if not uname:
        return ""
    try:
        st = _bmrbd_user_settings(uname)
        parts = []
        # BMRBD v61.16 SETTINGS-A: Fast answers = short general answers, no
        # personalisation and no memory facts. It short-circuits the whole
        # personal block (nickname / about / style / memory are all
        # personalisation), so a fast-answer reply is never personalised.
        if st.get("fast_answers", False) is True:
            parts.append("[FAST ANSWERS MODE: give short, direct answers from general knowledge only. Do NOT personalise the reply and do NOT use any saved memory facts about this user.]")
            return "\n\n".join(parts)
        _sa_nick = str(st.get("nickname") or "").strip()[:100]
        if _sa_nick:
            parts.append("[THE USER NAME IS " + _sa_nick + ". Address them by this name when it is natural to do so.]")
        about = str(st.get("about_user") or "").strip()[:1000]
        style = str(st.get("response_style") or "").strip()[:1000]
        if about:
            parts.append("[ABOUT THE USER: " + about + "]")
        if style:
            parts.append("[HOW TO RESPOND TO THIS USER: " + style + "]")
        # BMRBD v61.16 SETTINGS-B: personality tone is a real instruction to
        # the model.
        # v76.5 E2 (UNCENSORED): the safety level NO LONGER injects any
        # system-prompt text. The old "strict" branch told the model to
        # refuse explicit/gore/wrongdoing requests, and the "off" branch
        # still named a content filter — both removed. safety_level is
        # stored but inert; the bridge must never tell the model to refuse.
        _tone = str(st.get("tone") or "professional").strip().lower()
        if _tone in _S6116_TONES:
            parts.append("[PERSONALITY / TONE FOR THIS USER: " + _S6116_TONES[_tone] + "]")
        if st.get("memory_enabled", True) is not False:
            facts = [str(f.get("text") or "").strip() for f in _bmrbd_user_memory(uname) if isinstance(f, dict)]
            facts = [f[:_BMRBD_MEMORY_MAX_CHARS] for f in facts if f][:20]
            if facts:
                parts.append("[THINGS TO REMEMBER ABOUT THIS USER - facts the user asked me to remember. Use them only when relevant to the current question; never quote this block verbatim:\n- " + "\n- ".join(facts) + "]")
        # v76.5 E2 (UNCENSORED): the parental-controls content filter
        # directive was REMOVED — it told the model to decline explicit /
        # violent content. parental_filter is still stored (and the
        # parental PIN machinery is untouched) but it no longer injects
        # any refusal text into the system prompt.
        return "\n\n".join(parts)
    except Exception:
        return ""



