# ── BMRBD v61.13 P1: link-preview cache ──
_LINK_PREVIEW_WINDOW_S = 60.0
_LINK_PREVIEW_MAX_PER_WINDOW = 10
_LINK_PREVIEW_HITS = {}
_LINK_PREVIEW_CACHE = {}
_LINK_PREVIEW_CACHE_TTL_S = 600.0
_LINK_PREVIEW_CACHE_MAX = 200


def _link_preview_allowed(handler):
    """Unauthenticated same-origin link previews: 10 per rolling 60s per IP."""
    try:
        ip = (handler.headers.get("X-Forwarded-For") or "").split(",")[0].strip() or handler.client_address[0]
    except Exception:
        ip = "unknown"
    now = time.time()
    hits = [t for t in _LINK_PREVIEW_HITS.get(ip, []) if now - t < _LINK_PREVIEW_WINDOW_S]
    if len(hits) >= _LINK_PREVIEW_MAX_PER_WINDOW:
        _LINK_PREVIEW_HITS[ip] = hits
        return False
    hits.append(now)
    _LINK_PREVIEW_HITS[ip] = hits
    return True


def _ssrf_blocked_url(url):
    """Mirror of the /api/fetch-url inline SSRF guard (v61.11): returns an
    error string when the URL must not be fetched, else ''. fetch-url keeps
    its own inline copy (covered by the 45 bridge tests); this helper is
    used by /api/link-preview so both endpoints enforce the same rule."""
    if not isinstance(url, str) or not url.startswith(("http://", "https://")):
        return "URL must start with http:// or https://"
    _host = urllib.parse.urlparse(url).hostname or ""
    try:
        _infos = socket.getaddrinfo(_host, None)
    except Exception:
        _infos = []
    if not _infos:
        return "Cannot resolve host"
    for _fam, _typ, _proto, _canon, _sock in _infos:
        _ip = ipaddress.ip_address(_sock[0])
        if _ip.is_private or _ip.is_loopback or _ip.is_link_local or _ip.is_reserved:
            return "Private/local URLs are not allowed"
    return ""


class _LinkPreviewParser(HTMLParser):
    """Stdlib-only metadata parser for /api/link-preview: <title>, meta
    description / og:description, link rel=icon favicon."""
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.title = ""
        self.description = ""
        self.favicon = ""
        self._in_title = False
        self._saw_title = False
    def handle_starttag(self, tag, attrs):
        _d = dict(attrs)
        _tag = (tag or "").lower()
        if _tag == "title" and not self._saw_title:
            self._in_title = True
        elif _tag == "meta":
            _name = str(_d.get("name") or _d.get("property") or "").lower()
            if _name in ("description", "og:description") and not self.description:
                self.description = str(_d.get("content") or "").strip()
            elif _name == "og:title" and not self.title and not self._saw_title:
                self.title = str(_d.get("content") or "").strip()
        elif _tag == "link":
            _rel = str(_d.get("rel") or "").lower()
            if "icon" in _rel and not self.favicon:
                self.favicon = str(_d.get("href") or "").strip()
    def handle_endtag(self, tag):
        if (tag or "").lower() == "title":
            self._in_title = False
            self._saw_title = True
    def handle_data(self, data):
        if self._in_title:
            self.title += data


