def _ollama_get(path, timeout=15):
    _req = urllib.request.Request(OLLAMA_URL + path, method="GET")
    with urllib.request.urlopen(_req, timeout=timeout) as _resp:
        return json.loads(_resp.read().decode("utf-8", errors="ignore"))


def _ollama_post(path, payload, timeout=60):
    _data = json.dumps(payload).encode("utf-8")
    _req = urllib.request.Request(OLLAMA_URL + path, data=_data,
                                  headers={"Content-Type": "application/json"}, method="POST")
    with urllib.request.urlopen(_req, timeout=timeout) as _resp:
        return json.loads(_resp.read().decode("utf-8", errors="ignore"))


def _hot_swap_set_status(info_p, status, **extra):
    try:
        cur = {}
        if info_p.exists():
            cur = json.loads(info_p.read_text(encoding="utf-8")) or {}
        cur["hot_swap_status"] = status
        cur.update(extra)
        info_p.write_text(json.dumps(cur, indent=2), encoding="utf-8")
    except Exception:
        pass


def _hot_swap_run(target_id):
    info_p = Path("/tmp/active_model_info.json")
    old_model = None
    started = time.time()
    try:
        src = MODEL_SWITCH_SOURCES.get(target_id) or {}
        est = src.get("est_gb")
        _hot_swap_set_status(info_p, "starting:" + target_id, preset=target_id,
                             model_id=target_id,
                             started_at=time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()))
        try:
            ps = _ollama_get("/api/ps", timeout=15) or {}
            loaded = [m.get("model") for m in (ps.get("models") or []) if m.get("model")]
        except Exception:
            loaded = []
        old_model = loaded[0] if loaded else None
        try:
            tags = _ollama_get("/api/tags", timeout=30) or {}
            have = {str(m.get("name")) for m in (tags.get("models") or [])}
        except Exception:
            have = set()
        pulled_tag = target_id if target_id in have else None
        if not pulled_tag:
            for cand in [src.get("source")] + list(src.get("fallbacks") or []):
                if not cand:
                    continue
                pull_target = str(cand).strip()
                if pull_target and not pull_target.startswith("hf.co/") and "/" in pull_target:
                    pull_target = "hf.co/" + pull_target
                _hot_swap_set_status(info_p, "pulling:" + pull_target, preset=target_id)
                try:
                    subprocess.run(["ollama", "pull", pull_target], check=True, timeout=1800)
                except Exception as e:
                    _hot_swap_set_status(info_p, "pull_failed:" + pull_target + " (" + str(e)[:120] + ")", preset=target_id)
                    continue
                pulled_tag = pull_target
                break
            if not pulled_tag:
                raise RuntimeError("pull failed for all sources of " + target_id)
        _hot_swap_set_status(info_p, "creating:" + target_id, preset=target_id)
        ctx = v62_ollama_ctx(src, est)
        modelfile = ("FROM %s\nPARAMETER num_ctx %d\nPARAMETER num_batch 2048\n"
                     "PARAMETER num_gpu 999\nPARAMETER num_keep -1\nPARAMETER num_thread 4\n" % (pulled_tag, ctx))
        try:
            Path("/tmp/Modelfile.hotswap").write_text(modelfile, encoding="utf-8")
            subprocess.run(["ollama", "create", target_id, "-f", "/tmp/Modelfile.hotswap"],
                           check=True, timeout=600)
        except Exception:
            subprocess.run(["ollama", "cp", pulled_tag, target_id], check=True, timeout=600)
        if old_model and old_model != target_id:
            _hot_swap_set_status(info_p, "unloading:" + str(old_model), preset=target_id)
            try:
                _ollama_post("/api/generate", {"model": old_model, "prompt": "ok", "keep_alive": 0, "options": {"num_predict": 1}}, timeout=60)
            except Exception:
                pass
            for _i in range(12):
                try:
                    ps2 = _ollama_get("/api/ps", timeout=15) or {}
                    still = [m.get("model") for m in (ps2.get("models") or []) if m.get("model") == old_model]
                    if not still:
                        break
                except Exception:
                    break
                time.sleep(5)
            else:
                raise RuntimeError("could not unload " + str(old_model) + " - VRAM still busy")
        _hot_swap_set_status(info_p, "probing:" + target_id, preset=target_id)
        probe = _ollama_post("/api/chat", {"model": target_id,
                                          "messages": [{"role": "user", "content": "Reply with one word: Ready."}],
                                          "stream": False, "keep_alive": -1,
                                          "options": {"temperature": 0.5, "num_predict": 8}}, timeout=600)
        if not isinstance(probe, dict) or not (probe.get("message") or {}).get("content"):
            raise RuntimeError("probe returned no reply from " + target_id)
        globals()["DEFAULT_MODEL"] = target_id
        try:
            Path("/tmp/active_model_id.txt").write_text(target_id, encoding="utf-8")
        except Exception:
            pass
        try:
            with _LIVE_MODEL_LOCK:
                _LIVE_MODEL_CACHE["model"] = target_id
                _LIVE_MODEL_CACHE["ts"] = time.time()
        except Exception:
            pass
        _hot_swap_set_status(info_p, "ready", preset=target_id, model_id=target_id,
                             switched_at=time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                             elapsed_sec=round(time.time() - started, 1))
    except Exception as e:
        reason = str(e)[:200]
        try:
            ps3 = _ollama_get("/api/ps", timeout=15) or {}
            loaded3 = [m.get("model") for m in (ps3.get("models") or []) if m.get("model")]
            if not loaded3 and old_model:
                _ollama_post("/api/chat", {"model": old_model,
                                          "messages": [{"role": "user", "content": "Reply with one word: Ready."}],
                                          "stream": False, "keep_alive": -1,
                                          "options": {"temperature": 0.5, "num_predict": 4}}, timeout=300)
                globals()["DEFAULT_MODEL"] = old_model
        except Exception:
            pass
        _hot_swap_set_status(info_p, "error:" + reason, preset=target_id)


def _v62_dataset_slug(mid):
    """Kaggle dataset slug for a v62 dataset (llama-server) model — the
    SAME rule as the GPU notebook cell 1 (MODEL_DATASET_SLUG):
    'uncensored-cache-<preset>', lowercased, sanitised, truncated to 50
    chars. 'uncensored-cache-deepseek-v4.1-flash-552b-uncensored' is 52
    chars, so it is truncated to the 50-char form
    'uncensored-cache-deepseek-v4-1-flash-552b-uncensor' (dots become
    dashes, tail cut). Create the dataset with the TRUNCATED slug."""
    return re.sub(r"[^a-z0-9-]+", "-", ("uncensored-cache-" + str(mid)).lower()).strip("-")[:50].rstrip("-")


def _v62_dataset_ready(mid):
    """True when this model's dataset shards are staged under /kaggle/input
    (the mount the notebook's cell 3 globs: /kaggle/input/*<preset>*).
    Mirrors the notebook: the exact slug dir, or any dir whose name
    contains the preset id, containing at least one *.gguf."""
    try:
        root = "/kaggle/input"
        if not os.path.isdir(root):
            return False
        slug = _v62_dataset_slug(mid)
        cands = [os.path.join(root, slug)]
        cands += glob.glob(os.path.join(root, "*%s*" % mid))
        for d in cands:
            if os.path.isdir(d) and glob.glob(os.path.join(d, "*.gguf")):
                break
        else:
            return False
        # BMRBD v62 FIX (2026-11-11): every catalog extra_datasets slug
        # (e.g. the V4.1 Flash Engram dataset) must also be staged with at
        # least one *.gguf — the Engram is shard 6 and a boot without it is
        # expected to fail.
        for _xds in ((MODEL_SWITCH_SOURCES.get(mid) or {}).get("extra_datasets") or []):
            _xd = os.path.join(root, _xds)
            if not os.path.isdir(_xd) or not glob.glob(os.path.join(_xd, "*.gguf")):
                return False
        return True
    except Exception:
        return False


def _v62_persist_selected_model(mid):
    """Persist a model selection for the NEXT kernel start into the
    cluster-state file the bridge serves (the download endpoint serves
    /kaggle/working/bmrbd_cluster_state.json) — the same record the
    rotator's USE_LAST_SELECTED reads. Writes every candidate location
    that exists; returns the first path written, or "" on failure.
    NOTE (2026-11-11): the GitHub workflow does NOT currently download
    this file before a push, so a UI selection alone does not yet reach
    the next push — the repo's bmrbd_cluster_state.json (or the baked-in
    default) is still the push-time source of truth. This write makes
    the selection durable on the kernel and ready for any future
    workflow download step."""
    written = ""
    try:
        cands = []
        if os.path.isdir("/kaggle/working"):
            cands.append(Path("/kaggle/working/bmrbd_cluster_state.json"))
        cands.append(Path("/tmp/bmrbd_cluster_state.json"))
        for _p in cands:
            try:
                _st = {}
                if _p.exists():
                    _st = json.loads(_p.read_text(encoding="utf-8")) or {}
                    if not isinstance(_st, dict):
                        _st = {}
                _st["selected_model"] = mid
                _st["selected_model_source"] = "admin-ui-next-boot"
                _st["updated_at"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
                _p.write_text(json.dumps(_st, indent=2), encoding="utf-8")
                if not written:
                    written = str(_p)
            except Exception:
                continue
    except Exception:
        pass
    return written


def _hot_swap_status_payload():
    info = {}
    try:
        info_p = Path("/tmp/active_model_info.json")
        if info_p.exists():
            info = json.loads(info_p.read_text(encoding="utf-8")) or {}
    except Exception:
        info = {}
    try:
        tags = _ollama_get("/api/tags", timeout=3) or {}
        installed = {str(m.get("name")) for m in (tags.get("models") or [])}
    except Exception:
        installed = set()
    cur = get_live_ollama_model()
    models = []
    _seen_mids = set()
    for mid in CATALOG_MODELS:
        # CATALOG_MODELS lists the default model twice (once as the
        # DEFAULT_MODEL variable, once as a literal) - dedupe so the
        # picker never shows the same model on two rows.
        if mid in _seen_mids:
            continue
        _seen_mids.add(mid)
        src = MODEL_SWITCH_SOURCES.get(mid)
        if not src:
            continue
        est = src.get("est_gb")
        kv = 0.6 if (est and est > 24.5) else 3.7
        need = (est + kv) if est else None
        _v62cat = src.get("v62_category") or src.get("category") or ""
        _tier = src.get("tier") or ""
        _eng = src.get("engine") or v62_engine_for_size(est)[0]
        _run = src.get("runnable", True)
        if _run is False:
            _fit = "Disabled in the v62 catalog: " + str(src.get("note") or "not runnable")
        elif _eng == "llama-server":
            _fit = ("llama-server (mmap) — too big for Ollama (61 GB ceiling); "
                    "boots at the next kernel start from dataset shards")
        elif est and est > 30.0:
            _fit = "Ollama with CPU offload — fits in VRAM+RAM (~61 GB), slower"
        else:
            _fit = "Ollama — fits in VRAM"
        # BMRBD v62 FIX (2026-11-11): dataset readiness per model. A
        # llama-server model with staged shards is selectable ('Use at
        # next boot'); without them the reason names the missing dataset
        # slug instead of a bare 'Unavailable'.
        _ds_ready = False
        _ds_slug = ""
        if _eng == "llama-server":
            _ds_slug = _v62_dataset_slug(mid)
            _ds_ready = _v62_dataset_ready(mid)
            if _ds_ready:
                _fit = "Dataset staged in /kaggle/input — boots at the next kernel start"
            else:
                _fit = ("llama-server (mmap) — too big for Ollama (61 GB ceiling); "
                        "boots at the next kernel start from dataset shards — dataset "
                        "'%s' is not staged under /kaggle/input yet" % _ds_slug)
        models.append({"id": mid, "est_gb": est, "category": src.get("category") or "",
                       "speed_range": src.get("speed_range") or "",
                       "installed": mid in installed,
                       "too_big": bool(need and need > 30.0),
                       "need_gb": round(need, 1) if need else None,
                       "v62_category": _v62cat, "tier": _tier, "engine": _eng,
                       "runnable": bool(_run), "fit_reason": _fit,
                       "dataset_ready": bool(_ds_ready), "dataset_slug": _ds_slug,
                       "ctx": src.get("ctx"), "default": bool(src.get("default")),
                       "target_default": bool(src.get("target_default")),
                       "chat_template": src.get("chat_template") or "",
                       "best": list(src.get("best") or [])})
    models.sort(key=lambda m: (m["est_gb"] is None, m["est_gb"] or 0))
    return {"ok": True, "current_model": cur,
            "hot_swap_status": info.get("hot_swap_status") or "ready",
            "models": models}


def _capture_kernel_session_info():
    """BMRBD v61.6 (2026-11-10): capture EVERYTHING this kernel knows about its
    own session. The public Kaggle API exposes NO session id anywhere (status
    returns only a status string, list returns only metadata), so the only
    channel is the kernel itself. Returns {"kernel_session_id": int|None,
    "env_keys": [names only, no values]}. Only digit-only values of SESSION-ish
    env keys are ever returned; TOKEN/KEY/SECRET/PASSWORD keys are never read."""
    keys = sorted(os.environ.keys())
    sid = None
    for _cand in ("KAGGLE_KERNEL_SESSION_ID", "KAGGLE_SESSION_ID", "KERNEL_SESSION_ID", "SESSION_ID"):
        _v = (os.environ.get(_cand) or "").strip()
        if _v.isdigit():
            sid = int(_v)
            break
    if sid is None:
        for _k in keys:
            _uk = _k.upper()
            if "SESSION" in _uk and not any(_b in _uk for _b in ("TOKEN", "KEY", "SECRET", "PASSWORD", "AUTH")):
                _v = (os.environ.get(_k) or "").strip()
                if _v.isdigit():
                    sid = int(_v)
                    break
    return {"kernel_session_id": sid, "env_keys": keys}


def _require_admin(handler):
    """Admin user, or the master API key (which _get_user_by_token maps to admin)."""
    u = _require_valid_token(handler)
    return u if (u and u.get("role") == "admin") else None


# ═════════════════════════════════════════════════════════════════════════════
# BMRBD v76 §4 — ADMIN API-KEY MANAGEMENT + ADMIN USER MANAGEMENT (2026-11-19)
# Agent B. Code-side only. Checklist items:
#   "Admin API key management — create keys, set expiry (time), token quota
#    (million tokens or unlimited), usage limits, edit / increase later"
#   "Admin user management — BAN accounts + CREATE accounts (public
#    registration stays CLOSED)"
# Design (per V76-RECHECK §6, OpenAI/Anthropic admin-API shape):
#   * Keys live in the vault: _BMRBD_STATE["api_keys"] (restored by
#     _restore_from_vault_zip_bytes — section added to its merge list).
#     ONLY a sha256 hash is stored; the full secret is shown ONCE at
#     creation/rotation and never again.
#   * Two independent ceilings per key — requests/min AND tokens/min —
#     plus a lifetime token quota (millions, or None = unlimited) and
#     project-level caps in settings (api_project_rpm / api_project_tpm /
#     api_project_token_quota_millions). Per-key "unlimited" means no
#     per-key cap; the project cap still applies. A new key does NOT
#     reset quota (limits belong to the project, not the key).
#   * Usage is charged at request time on prompt-estimate + requested
#     max_tokens, and reconciled with real engine usage for non-stream
#     replies (see the proxy hook). last_used_at + lifetime totals are
#     kept on every key from day one.
#   * "Edit / increase" = rotate to a new key OR raise the quota. There
#     is NO way to extend expires_at after issue (OpenAI documents none):
#     _v76_apikey_update REFUSES any later expiry (or removing expiry).
#   * Key creation/rotation/update is SESSION-ONLY admin (browser login
#     cookie + role=admin via _v76_require_session_admin). The master API
#     key ("ollama") and managed bmrbd_sk_ keys NEVER pass that gate, and
#     managed keys are deliberately NOT resolved by _get_user_by_token,
#     so they cannot reach any admin endpoint. Admin credential and chat
#     credential are separate, both directions.
#   * Ban = banned=True + status="banned" + all sessions revoked via
#     _s6116_prune_sessions — NEVER delete the row. Last-admin guard:
#     the primary owner and the last remaining admin cannot be banned.
#   * Invites: admin-issued, expire after 21 days, single use, email-bound.
#     They are the ONLY way in while public registration stays closed.
# ═════════════════════════════════════════════════════════════════════════════
_V76_APIKEY_MAX_EXPIRY_SECONDS = 31536000  # 365 days (OpenAI Admin API max)
# BMRBD v76.2 LEFTOVER R19: admin-created keys used to default to
# never-expiring + unlimited quota. The /api/admin/api-keys create
# handler now applies these defaults when the admin omits a value; the
# low-level _v76_apikey_create keeps None = unlimited (pinned by
# test_v76_admin_keys_users.py: a default create has expires_at None),
# so explicit programmatic calls are unaffected.
_V76_APIKEY_DEFAULT_EXPIRY_SECONDS = 90 * 24 * 3600  # 90 days
_V76_APIKEY_DEFAULT_QUOTA_MILLIONS = 1.0  # 1M lifetime tokens
_V76_APIKEY_ROLES = ("user", "developer", "billing", "admin")
_V76_INVITE_TTL_SECONDS = 21 * 24 * 3600  # Anthropic Admin API: invites expire after 21 days
_V76_UNSET = object()  # sentinel: "argument not passed" (vs explicit None = unlimited)
_V76_APIKEY_SAVE_CLOCK = {"ts": 0.0}  # throttled vault save for key-usage durability


def _v76_now_iso():
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def _v76_apikey_new_secret():
    """A fresh full secret (shown once, never stored). No new import: uuid + os.urandom."""
    raw = hashlib.sha256(os.urandom(32) + str(time.time()).encode("utf-8") + uuid.uuid4().hex.encode("ascii")).hexdigest()
    return "bmrbd_sk_" + raw[:48]


def _v76_apikey_hash(secret):
    return hashlib.sha256(str(secret or "").encode("utf-8")).hexdigest()


def _v76_apikey_public(rec):
    """Public view of a key record: no hash, no pending-charge internals."""
    if not isinstance(rec, dict):
        return {}
    out = {k: v for k, v in rec.items() if k not in ("key_hash", "_pending_charge", "_pending_at", "_pending_charges")}
    u = rec.get("usage")
    out["usage"] = dict(u) if isinstance(u, dict) else {"requests_total": 0, "tokens_total": 0, "window_start": 0.0, "window_requests": 0, "window_tokens": 0}
    return out


def _v76_apikey_create(state, name, owner, created_by, expires_in_seconds=None, token_quota_millions=None, rpm=None, tpm=None):
    """Create a managed API key. Returns (public_record, full_secret_once).

    expires_in_seconds: 1..31536000, or None = no expiry. token_quota_millions:
    None = unlimited lifetime tokens. rpm/tpm: None = no per-key ceiling."""
    name = str(name or "").strip()
    if not name:
        raise ValueError("key name is required")
    if len(name) > 80:
        raise ValueError("key name is too long (max 80 chars)")
    owner = str(owner or "").strip()
    users = state.get("users") or {}
    if owner not in users:
        raise ValueError("owner user not found: %s" % owner)
    expires_ts = None
    expires_at = None
    if expires_in_seconds is not None:
        try:
            expires_in_seconds = int(expires_in_seconds)
        except Exception:
            raise ValueError("expires_in_seconds must be an integer number of seconds")
        if expires_in_seconds < 1 or expires_in_seconds > _V76_APIKEY_MAX_EXPIRY_SECONDS:
            raise ValueError("expires_in_seconds must be 1..31536000 (max 365 days)")
        expires_ts = time.time() + expires_in_seconds
        expires_at = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(expires_ts))
    if token_quota_millions is not None:
        try:
            token_quota_millions = float(token_quota_millions)
        except Exception:
            raise ValueError("token_quota_millions must be a number (millions) or null for unlimited")
        if token_quota_millions < 0:
            raise ValueError("token_quota_millions cannot be negative")
    for _lim_name, _lim_val in (("rpm", rpm), ("tpm", tpm)):
        if _lim_val is not None:
            try:
                _lim_val = int(_lim_val)
            except Exception:
                raise ValueError("%s must be an integer or null for unlimited" % _lim_name)
            if _lim_val <= 0:
                raise ValueError("%s must be > 0 or null for unlimited" % _lim_name)
            if _lim_name == "rpm":
                rpm = _lim_val
            else:
                tpm = _lim_val
    secret = _v76_apikey_new_secret()
    key_id = "key_" + uuid.uuid4().hex[:16]
    keys = state.setdefault("api_keys", {})
    while key_id in keys:
        key_id = "key_" + uuid.uuid4().hex[:16]
    rec = {
        "id": key_id,
        "name": name,
        "owner": owner,
        "created_by": str(created_by or ""),
        "created_at": _v76_now_iso(),
        "expires_at": expires_at,
        "expires_ts": expires_ts,
        "token_quota_millions": token_quota_millions,
        "rpm": rpm,
        "tpm": tpm,
        "status": "active",
        "last_used_at": None,
        "key_hash": _v76_apikey_hash(secret),
        "key_prefix": secret[:12],
        "usage": {"requests_total": 0, "tokens_total": 0, "window_start": 0.0, "window_requests": 0, "window_tokens": 0},
        "_pending_charge": 0,
        "_pending_at": 0.0,
        "_pending_charges": {},
    }
    keys[key_id] = rec
    return _v76_apikey_public(rec), secret


def _v76_apikey_find_by_secret(state, secret):
    """Resolve a presented secret to its record (hash compare only). None when unknown."""
    if not secret or not str(secret).startswith("bmrbd_sk_"):
        return None
    h = _v76_apikey_hash(secret)
    for rec in (state.get("api_keys") or {}).values():
        if isinstance(rec, dict) and hmac.compare_digest(str(rec.get("key_hash") or ""), h):
            return rec
    return None


def _v76_apikey_authenticate(state, secret):
    """Validate a managed key for chat use. Returns (record, error_code|None).

    error codes: key_not_found / key_inactive / key_expired / owner_not_found / owner_banned."""
    rec = _v76_apikey_find_by_secret(state, secret)
    if rec is None:
        return None, "key_not_found"
    if rec.get("status") != "active":
        return None, "key_inactive"
    exp_ts = rec.get("expires_ts")
    if exp_ts is not None and time.time() > float(exp_ts):
        return None, "key_expired"
    owner = (state.get("users") or {}).get(str(rec.get("owner") or ""))
    if owner is None:
        return None, "owner_not_found"
    if owner.get("banned") or not owner.get("approved", True):
        return None, "owner_banned"
    return rec, None


def _v76_apikey_window(rec, now):
    """Rolling 60s window for one key (resets when the minute turns over)."""
    u = rec.setdefault("usage", {"requests_total": 0, "tokens_total": 0, "window_start": 0.0, "window_requests": 0, "window_tokens": 0})
    for _k in ("requests_total", "tokens_total", "window_requests", "window_tokens"):
        u.setdefault(_k, 0)
    u.setdefault("window_start", 0.0)
    if now - float(u.get("window_start") or 0.0) >= 60.0:
        u["window_start"] = now
        u["window_requests"] = 0
        u["window_tokens"] = 0
    return u


def _v76_apikey_project_window(state, now):
    """Rolling 60s window for the whole project (limits belong to the project, not the key)."""
    pu = state.setdefault("api_key_project_usage", {"window_start": 0.0, "window_requests": 0, "window_tokens": 0, "tokens_total": 0})
    for _k in ("window_requests", "window_tokens", "tokens_total"):
        pu.setdefault(_k, 0)
    pu.setdefault("window_start", 0.0)
    if now - float(pu.get("window_start") or 0.0) >= 60.0:
        pu["window_start"] = now
        pu["window_requests"] = 0
        pu["window_tokens"] = 0
    return pu


def _v76_apikey_ratelimit_headers(state, rec, now=None):
    """x-ratelimit-* headers: remaining requests/tokens + reset (seconds).

    A ceiling that is None (unlimited) simply has no remaining header."""
    now = time.time() if now is None else now
    u = _v76_apikey_window(rec, now)
    reset = max(0, int(60 - (now - float(u.get("window_start") or 0.0))))
    headers = {"x-ratelimit-reset-tokens": str(reset)}
    if rec.get("rpm") is not None:
        headers["x-ratelimit-remaining-requests"] = str(max(0, int(rec["rpm"]) - int(u.get("window_requests") or 0)))
    if rec.get("tpm") is not None:
        headers["x-ratelimit-remaining-tokens"] = str(max(0, int(rec["tpm"]) - int(u.get("window_tokens") or 0)))
    return headers


def _v76_apikey_check_and_charge(state, rec, prompt_tokens, requested_output_tokens, now=None, request_id=None):
    """Enforce both ceilings + lifetime quota + project caps, then charge.

    Returns (allowed, headers, error_dict|None). The charge is the request-time
    estimate (prompt + requested output); _v76_apikey_reconcile replaces it
    with real engine usage — streams included (the old docstring admitted
    streams kept the estimate). The pending charge is stored PER REQUEST
    (rec["_pending_charges"][request_id], capped at the 32 most recent);
    the old single-slot rec["_pending_charge"] is kept only as the most
    recent charge for backward-compatible readers."""
    now = time.time() if now is None else now
    charge = max(0, int(prompt_tokens or 0)) + max(0, int(requested_output_tokens or 0))
    u = _v76_apikey_window(rec, now)
    pu = _v76_apikey_project_window(state, now)
    settings = state.get("settings") or {}
    reset = max(0, int(60 - (now - float(u.get("window_start") or 0.0))))

    def _deny(code, message, retry_after):
        err = {"error": {"type": "rate_limit_error", "code": code, "message": message}}
        if retry_after is not None:
            err["error"]["retry_after"] = retry_after
        return False, _v76_apikey_ratelimit_headers(state, rec, now), err

    if rec.get("rpm") is not None and int(u.get("window_requests") or 0) + 1 > int(rec["rpm"]):
        return _deny("rate_limit_exceeded", "API key request limit exceeded (%s requests/min). Retry in %ss." % (rec["rpm"], reset), reset)
    if rec.get("tpm") is not None and int(u.get("window_tokens") or 0) + charge > int(rec["tpm"]):
        return _deny("rate_limit_exceeded", "API key token limit exceeded (%s tokens/min). Retry in %ss." % (rec["tpm"], reset), reset)
    quota_m = rec.get("token_quota_millions")
    if quota_m is not None and int(u.get("tokens_total") or 0) + charge > float(quota_m) * 1000000:
        return _deny("quota_exceeded", "API key lifetime token quota exceeded (%s million tokens). Raise the quota or rotate the key." % (quota_m,), None)
    proj_rpm = settings.get("api_project_rpm")
    if proj_rpm is not None and int(pu.get("window_requests") or 0) + 1 > int(proj_rpm):
        return _deny("rate_limit_exceeded", "Project request limit exceeded (%s requests/min). A new key does not reset project quota." % (proj_rpm,), reset)
    proj_tpm = settings.get("api_project_tpm")
    if proj_tpm is not None and int(pu.get("window_tokens") or 0) + charge > int(proj_tpm):
        return _deny("rate_limit_exceeded", "Project token limit exceeded (%s tokens/min). A new key does not reset project quota." % (proj_tpm,), reset)
    proj_quota_m = settings.get("api_project_token_quota_millions")
    if proj_quota_m is not None and int(pu.get("tokens_total") or 0) + charge > float(proj_quota_m) * 1000000:
        return _deny("quota_exceeded", "Project lifetime token quota exceeded (%s million tokens)." % (proj_quota_m,), None)
    u["window_requests"] = int(u.get("window_requests") or 0) + 1
    u["window_tokens"] = int(u.get("window_tokens") or 0) + charge
    u["requests_total"] = int(u.get("requests_total") or 0) + 1
    u["tokens_total"] = int(u.get("tokens_total") or 0) + charge
    pu["window_requests"] = int(pu.get("window_requests") or 0) + 1
    pu["window_tokens"] = int(pu.get("window_tokens") or 0) + charge
    pu["tokens_total"] = int(pu.get("tokens_total") or 0) + charge
    rec["last_used_at"] = _v76_now_iso()
    rec["_pending_charge"] = charge
    rec["_pending_at"] = now
    if request_id:
        _pc = rec.setdefault("_pending_charges", {})
        if not isinstance(_pc, dict):
            _pc = {}
            rec["_pending_charges"] = _pc
        _pc[str(request_id)] = charge
        while len(_pc) > 32:
            _pc.pop(next(iter(_pc)), None)
    return True, _v76_apikey_ratelimit_headers(state, rec, now), None


def _v76_apikey_reconcile(state, key_id, prompt_tokens, completion_tokens, request_id=None):
    """Replace a request-time estimate charge with real engine usage.

    Streams included: callers pass the request-time prompt estimate plus the
    ACTUAL completion tokens, so a Max/Challenge stream is charged for what
    it really returned, not the requested max_tokens. The pending slot is
    per-request (request_id): concurrent requests on one key no longer
    overwrite each other, and a reconcile applies its delta to the exact
    request that was charged. Without request_id it falls back to the legacy
    single slot (old records / old callers). A reconcile that finds no
    pending charge is a no-op, never a double refund.

    Returns True when a pending charge was actually reconciled."""
    rec = (state.get("api_keys") or {}).get(str(key_id or ""))
    if not isinstance(rec, dict):
        return False
    actual = max(0, int(prompt_tokens or 0)) + max(0, int(completion_tokens or 0))
    if actual <= 0:
        return False
    pending = 0
    _pc = rec.get("_pending_charges")
    if request_id and isinstance(_pc, dict) and str(request_id) in _pc:
        pending = int(_pc.pop(str(request_id)) or 0)
        # The legacy slot always holds the MOST RECENT charge: clear it
        # when it is the charge just reconciled, so a later legacy
        # fallback cannot refund the same charge a second time.
        if int(rec.get("_pending_charge") or 0) == pending:
            rec["_pending_charge"] = 0
    elif request_id:
        # A request_id was given but has no pending slot (already
        # reconciled, or charged before this patch deployed): NEVER fall
        # back to the legacy slot — that would apply this request's delta
        # to a DIFFERENT request's charge, the exact race being fixed.
        return False
    elif int(rec.get("_pending_charge") or 0) > 0:
        pending = int(rec.get("_pending_charge") or 0)
        rec["_pending_charge"] = 0
    if pending <= 0:
        return False
    delta = actual - pending
    u = rec.setdefault("usage", {"requests_total": 0, "tokens_total": 0, "window_start": 0.0, "window_requests": 0, "window_tokens": 0})
    u["window_tokens"] = max(0, int(u.get("window_tokens") or 0) + delta)
    u["tokens_total"] = max(0, int(u.get("tokens_total") or 0) + delta)
    pu = state.get("api_key_project_usage") or {}
    if pu:
        pu["window_tokens"] = max(0, int(pu.get("window_tokens") or 0) + delta)
        pu["tokens_total"] = max(0, int(pu.get("tokens_total") or 0) + delta)
    return True


def _v76_apikey_reconcile_self(handler, prompt_tokens, completion_tokens):
    """Reconcile the CURRENT request's pending charge, from a handler method.

    Reads the managed-key id + per-request charge id the do_POST charge step
    stashed on the handler (H12c). Never raises and never breaks the reply:
    returns False when there is no managed key, no pending charge, or any
    error. prompt_tokens is the engine-reported prompt count when the reply
    carries real usage (chat completions / proxy), else the request-time
    estimate (Messages/Responses report a placeholder input_tokens of 64).
    completion_tokens is the actual streamed/returned count.
    """
    try:
        _kid = getattr(handler, "_v76_apikey_id", "") or ""
        if not _kid:
            return False
        return _v76_apikey_reconcile(_BMRBD_STATE, _kid, int(prompt_tokens or 0), int(completion_tokens or 0), request_id=getattr(handler, "_v76_charge_req_id", "") or None)
    except Exception:
        return False


def _v76_apikey_rotate(state, key_id, rotated_by):
    """Rotate = issue a NEW key with the same settings, deactivate the old one.

    The new key inherits the old expiry (never extended) and quota. Returns
    (new_public_record, new_full_secret_once)."""
    old = (state.get("api_keys") or {}).get(str(key_id or ""))
    if not isinstance(old, dict):
        raise ValueError("key not found: %s" % key_id)
    secret = _v76_apikey_new_secret()
    new_id = "key_" + uuid.uuid4().hex[:16]
    keys = state.setdefault("api_keys", {})
    while new_id in keys:
        new_id = "key_" + uuid.uuid4().hex[:16]
    # BMRBD v76.2 BUGHUNT: the new key inherits the old key's LIFETIME
    # usage. Before this the usage reset to zero, so rotating a key reset
    # its lifetime token quota — an unlimited-quota bypass by rotation.
    _old_usage = old.get("usage") if isinstance(old.get("usage"), dict) else {}
    try:
        _carry_req = int(_old_usage.get("requests_total") or 0)
        _carry_tok = int(_old_usage.get("tokens_total") or 0)
    except Exception:
        _carry_req, _carry_tok = 0, 0
    new = {
        "id": new_id,
        "name": str(old.get("name") or ""),
        "owner": str(old.get("owner") or ""),
        "created_by": str(rotated_by or ""),
        "created_at": _v76_now_iso(),
        "expires_at": old.get("expires_at"),
        "expires_ts": old.get("expires_ts"),
        "token_quota_millions": old.get("token_quota_millions"),
        "rpm": old.get("rpm"),
        "tpm": old.get("tpm"),
        "status": "active",
        "last_used_at": None,
        "key_hash": _v76_apikey_hash(secret),
        "key_prefix": secret[:12],
        "usage": {"requests_total": _carry_req, "tokens_total": _carry_tok, "window_start": 0.0, "window_requests": 0, "window_tokens": 0},
        "_pending_charge": 0,
        "_pending_at": 0.0,
        "_pending_charges": {},
        "rotated_from": str(old.get("id") or ""),
    }
    old["status"] = "rotated"
    old["rotated_to"] = new_id
    keys[new_id] = new
    return _v76_apikey_public(new), secret


def _v76_apikey_update(state, key_id, name=_V76_UNSET, token_quota_millions=_V76_UNSET, rpm=_V76_UNSET, tpm=_V76_UNSET, status=_V76_UNSET, expires_ts=_V76_UNSET):
    """Edit a key: rename, raise/lower quota or ceilings, activate/deactivate.

    expires_ts may only move EARLIER (or be added where there was none).
    Extending expiry — or removing it — raises ValueError: rotate instead."""
    rec = (state.get("api_keys") or {}).get(str(key_id or ""))
    if not isinstance(rec, dict):
        raise ValueError("key not found: %s" % key_id)
    if name is not _V76_UNSET:
        name = str(name or "").strip()
        if not name:
            raise ValueError("key name is required")
        rec["name"] = name[:80]
    if token_quota_millions is not _V76_UNSET:
        if token_quota_millions is not None:
            token_quota_millions = float(token_quota_millions)
            if token_quota_millions < 0:
                raise ValueError("token_quota_millions cannot be negative")
        rec["token_quota_millions"] = token_quota_millions
    for _lim_name, _lim_val in (("rpm", rpm), ("tpm", tpm)):
        if _lim_val is not _V76_UNSET:
            if _lim_val is not None:
                _lim_val = int(_lim_val)
                if _lim_val <= 0:
                    raise ValueError("%s must be > 0 or null for unlimited" % _lim_name)
            rec[_lim_name] = _lim_val
    if status is not _V76_UNSET:
        if status not in ("active", "inactive"):
            raise ValueError("status must be 'active' or 'inactive'")
        rec["status"] = status
    if expires_ts is not _V76_UNSET:
        old_ts = rec.get("expires_ts")
        if expires_ts is not None:
            expires_ts = float(expires_ts)
            if expires_ts <= time.time():
                raise ValueError("expires_ts must be in the future")
        if old_ts is not None and (expires_ts is None or float(expires_ts) > float(old_ts)):
            raise ValueError("expires_at cannot be extended after a key is issued (and cannot be removed) — rotate the key instead")
        rec["expires_ts"] = expires_ts
        rec["expires_at"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(expires_ts)) if expires_ts is not None else None
    return _v76_apikey_public(rec)


def _v76_admin_user_create(state, username, password, email="", role="user", quota_gb=25.0, created_by="admin"):
    """Admin-created account. New members start as user; role must be one of
    user/developer/billing/admin. Raises ValueError on bad role, bad name,
    bad password (<8 chars), bad email, bad quota, or duplicate."""
    if role not in _V76_APIKEY_ROLES:
        raise ValueError("role must be one of: %s" % (", ".join(_V76_APIKEY_ROLES),))
    username = re.sub(r"[^a-zA-Z0-9_.-]+", "", str(username or "").strip())[:32]
    if len(username) < 2:
        raise ValueError("Username must be at least 2 characters.")
    if username in (state.get("users") or {}):
        raise ValueError("Username already exists: %s" % username)
    # BMRBD v76.2 LEFTOVER R20/R21: minimum password 4 -> 8 (8 is the
    # highest value that keeps the pinned test behaviour — "secretpw"
    # (8 chars) must stay valid, "123" must stay rejected — and keeps
    # the admin UI's 'bmrbd123' fallback working); email is validated
    # when supplied; a garbage quota is a clean ValueError (400 at the
    # HTTP layer), not a raw float() traceback.
    password = str(password or "").strip()
    if len(password) < 8:
        raise ValueError("Password must be at least 8 characters.")
    email = str(email or "").strip()
    if email and not re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", email):
        raise ValueError("Invalid email address.")
    try:
        quota_gb = float(quota_gb or 25.0)
    except (TypeError, ValueError):
        raise ValueError("quota_gb must be a number")
    if quota_gb < 0:
        raise ValueError("quota_gb cannot be negative")
    u_obj = {
        "username": username,
        "email": email,
        "pass_hash": _hash_password(password),
        "role": role,
        "approved": True,
        "status": "active",
        "plan": "Pro Unlimited (Admin Created)",
        "quota_gb": quota_gb,
        "used_gb": 0.01,
        "banned": False,
        "created_at": time.strftime("%Y-%m-%d %H:%M:%S"),
        "token": "bmrbd_u_" + hashlib.sha256((username + str(time.time()) + VAULT_SECRET_KEY).encode("utf-8")).hexdigest()[:24],
    }
    state.setdefault("users", {})[username] = u_obj
    return {k: v for k, v in u_obj.items() if k not in ("pass_hash", "token")}


def _v76_admin_user_ban(state, username, actor_username):
    """Ban = deactivate + revoke every session. NEVER deletes the row.

    Refuses the primary owner and the last remaining admin. Returns
    {"banned": True, "sessions_revoked": N}."""
    users = state.get("users") or {}
    tgt = users.get(str(username or ""))
    if tgt is None:
        raise ValueError("user not found: %s" % username)
    if str(username) == ADMIN_DEFAULT_USER:
        raise ValueError("cannot ban the primary owner (%s)" % ADMIN_DEFAULT_USER)
    if str(tgt.get("role") or "") == "admin":
        others = [u for n, u in users.items()
                  if n != str(username) and str(u.get("role") or "") == "admin" and not u.get("banned")]
        if not others:
            raise ValueError("cannot ban the last admin — at least one admin must remain")
    revoked = 0
    try:
        revoked = int(_s6116_prune_sessions(str(username), keep_token=None) or 0)
    except Exception:
        revoked = 0
    tgt["banned"] = True
    tgt["status"] = "banned"
    return {"banned": True, "sessions_revoked": revoked}


def _v76_admin_user_unban(state, username):
    """Lift a ban. If the ban revoked the persistent token, mint a fresh one."""
    users = state.get("users") or {}
    tgt = users.get(str(username or ""))
    if tgt is None:
        raise ValueError("user not found: %s" % username)
    tgt["banned"] = False
    tgt["status"] = "active"
    if not str(tgt.get("token") or ""):
        tgt["token"] = "bmrbd_u_" + hashlib.sha256((str(username) + str(time.time()) + VAULT_SECRET_KEY).encode("utf-8")).hexdigest()[:24]
    return {"banned": False}


def _v76_admin_invite_create(state, email, role="user", created_by="admin"):
    """Admin-issued invite: single use, email-bound, expires after 21 days.

    Returns (public_invite, token_once). Only the token hash is stored."""
    if role not in _V76_APIKEY_ROLES:
        raise ValueError("role must be one of: %s" % (", ".join(_V76_APIKEY_ROLES),))
    email = str(email or "").strip().lower()
    if "@" not in email or "." not in email.split("@")[-1]:
        raise ValueError("a valid email is required for the invite")
    token = "bmrbd_inv_" + hashlib.sha256(os.urandom(32) + str(time.time()).encode("utf-8") + uuid.uuid4().hex.encode("ascii")).hexdigest()[:40]
    inv_id = "inv_" + uuid.uuid4().hex[:16]
    invites = state.setdefault("invites", {})
    while inv_id in invites:
        inv_id = "inv_" + uuid.uuid4().hex[:16]
    exp_ts = time.time() + _V76_INVITE_TTL_SECONDS
    rec = {
        "id": inv_id,
        "email": email,
        "role": role,
        "created_by": str(created_by or ""),
        "created_at": _v76_now_iso(),
        "expires_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(exp_ts)),
        "expires_ts": exp_ts,
        "token_hash": _v76_apikey_hash(token),
        "used_by": None,
        "used_at": None,
    }
    invites[inv_id] = rec
    pub = {k: v for k, v in rec.items() if k != "token_hash"}
    return pub, token


def _v76_admin_invite_validate(state, token, email):
    """Validate an invite token for registration: unexpired, unused, email matches.

    Returns the invite record or None. (Consumption is the register handler's job.)"""
    if not token or not str(token).startswith("bmrbd_inv_"):
        return None
    h = _v76_apikey_hash(token)
    for inv in (state.get("invites") or {}).values():
        if not isinstance(inv, dict) or not hmac.compare_digest(str(inv.get("token_hash") or ""), h):
            continue
        if inv.get("used_by"):
            return None
        exp_ts = inv.get("expires_ts")
        if exp_ts is not None and time.time() > float(exp_ts):
            return None
        if str(inv.get("email") or "").lower() != str(email or "").strip().lower():
            return None
        return inv
    return None


def _v76_admin_session_user(state, cookie_header):
    """Session-cookie-only admin resolution (credential separation).

    Only a live browser-login session (bmrbd_session cookie) for an admin
    user passes. Bearer master key, per-user tokens and managed bmrbd_sk_
    keys all return None here — they must never manage keys/users."""
    tok = ""
    try:
        for _part in str(cookie_header or "").split(";"):
            _part = _part.strip()
            if _part.startswith(_SESSION_COOKIE_NAME + "="):
                tok = _part[len(_SESSION_COOKIE_NAME) + 1:].strip().strip('"')
                break
    except Exception:
        return None
    if not tok:
        return None
    _cutoff = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(time.time() - _SESSION_MAX_AGE_S))
    for _uname, _sess_list in (state.get("user_sessions") or {}).items():
        for _s in (_sess_list or []):
            if isinstance(_s, dict) and hmac.compare_digest(str(_s.get("token") or ""), str(tok or "")):
                _created = str(_s.get("created_at") or "")
                if _created and _created < _cutoff:
                    continue
                _uo = (state.get("users") or {}).get(_uname)
                if _uo and str(_uo.get("role") or "") == "admin" and not _uo.get("banned") and _uo.get("approved", True):
                    return _uo
    return None


def _v76_require_session_admin(handler):
    """Handler wrapper: session-cookie admin only (see _v76_admin_session_user)."""
    return _v76_admin_session_user(_BMRBD_STATE, handler.headers.get("Cookie"))


