_MEDIA_LOCK = threading.Lock()

def _find_cached_media_weights(slug_part: str):
    """Checks `/kaggle/input` and `/opt/media_models` for pre-cached multi-GB media models."""
    for base_d in [Path("/kaggle/input"), Path("/opt/media_models"), Path("/var/tmp/media_models")]:
        if base_d.exists():
            for p in base_d.rglob("*"):
                if slug_part.lower() in p.name.lower():
                    return p
    return None

def _image_gen_fresh_seed():
    """Fresh random seed for ONE image request. v76.2 IMAGE2 (DUP).

    Pure randomness from random.SystemRandom (os.urandom) - NEVER
    derived from the prompt or the clock. The old Pollinations seed was
    hash(prompt)+milliseconds, so two identical prompts in the same
    millisecond produced the same seed; the HF Router calls sent NO seed
    at all; the ZeroGPU payload hard-coded seed 0 - so the same prompt
    returned the same image twice. Returns an int in [100000, 9099999).
    """
    try:
        return 100000 + random.SystemRandom().randrange(8999999)
    except Exception:
        return 100000 + (int(time.time() * 1000) % 8999999)

def try_run_local_diffusers_image(pos_prompt: str, neg_prompt: str, w: int, h: int, model_key: str, force: bool = False):
    """
    Runs a REAL local multi-GB PyTorch `diffusers` pipeline — SDXL ONLY
    (`RealVisXL_V5.0` / `Juggernaut-XL-v9`). FLUX is NOT run locally here: the
    `flux` arch entries fall back to RealVisXL. Only active when
    ENABLE_LOCAL_DIFFUSERS=1 or run_mode IMAGE_ONLY_MAX — unless
    force=True (an explicit local-only request bypasses that gate;
    the CUDA requirement below still applies).
    """
    if not force and os.environ.get("ENABLE_LOCAL_DIFFUSERS", "0") != "1" and _ACTIVE_LOCAL_PIPELINES["run_mode"] != "IMAGE_ONLY_MAX":
        return None
    try:
        import torch
        if not torch.cuda.is_available() and _ACTIVE_LOCAL_PIPELINES["run_mode"] != "IMAGE_ONLY_MAX":
            return None
        from diffusers import StableDiffusionXLPipeline, DPMSolverMultistepScheduler
        info = DEDICATED_MEDIA_CATALOG["image_models"].get(model_key) or DEDICATED_MEDIA_CATALOG["image_models"]["realvisxl-v5-fp16"]
        target_repo = info["hf_repo"]
        if info.get("arch") not in ("sdxl", "hybrid"):
            target_repo = "SG161222/RealVisXL_V5.0"
        with _MEDIA_LOCK:
            if _ACTIVE_LOCAL_PIPELINES["sdxl_pipe"] is None or _ACTIVE_LOCAL_PIPELINES["sdxl_repo"] != target_repo:
                dev = "cuda:1" if torch.cuda.device_count() > 1 else ("cuda:0" if torch.cuda.is_available() else "cpu")
                dt = torch.float16 if "cuda" in dev else torch.float32
                pipe = StableDiffusionXLPipeline.from_pretrained(
                    target_repo, torch_dtype=dt, variant="fp16" if "cuda" in dev else None, use_safetensors=True
                ).to(dev)
                pipe.scheduler = DPMSolverMultistepScheduler.from_config(pipe.scheduler.config, use_karras_sigmas=True)
                pipe.enable_vae_tiling()
                _ACTIVE_LOCAL_PIPELINES["sdxl_pipe"] = pipe
                _ACTIVE_LOCAL_PIPELINES["sdxl_repo"] = target_repo
            pipe = _ACTIVE_LOCAL_PIPELINES["sdxl_pipe"]
            # v76.2 IMAGE2 (DUP): explicit fresh seed per request —
            # never rely on the global torch RNG state to differ.
            _img_gen = torch.Generator(device=pipe.device).manual_seed(_image_gen_fresh_seed())
            im = pipe(
                prompt=pos_prompt,
                negative_prompt=neg_prompt,
                width=(w // 8) * 8,
                height=(h // 8) * 8,
                num_inference_steps=24,
                guidance_scale=5.5,
                generator=_img_gen
            ).images[0]
            buf = io.BytesIO()
            im.save(buf, format="PNG")
            return buf.getvalue(), f"Local-GPU ({target_repo})"
    except Exception as e:
        diag_log("WARN", f"Local diffusers note: {e}")
        return None

def _verify_genuine_photo_bytes(raw_bytes: bytes) -> bool:
    """Guarantees we NEVER accept a blank, corrupted, or JSON error payload as an image."""
    if not raw_bytes or len(raw_bytes) < 12000:
        return False
    head = raw_bytes[:64].lstrip()
    if head.startswith(b"{") or head.startswith(b"<"):
        return False
    try:
        from PIL import Image
        import numpy as np
        im = Image.open(io.BytesIO(raw_bytes)).convert("RGB")
        arr = np.asarray(im, dtype=np.float32)
        if arr.std() < 12.0:
            return False
        return True
    except Exception:
        return False


def save_media_and_get_url(raw_bytes: bytes, ext: str = "png", prefix: str = "img") -> str:
    """
    Saves generated binary media (PNG/GIF/WAV) to `/tmp/generated_media/<id>.<ext>`
    and returns a clean, short relative URL `/media/<id>.<ext>` so chat interfaces NEVER
    dump 250,000 characters of raw Base64 code into the conversation!
    """
    MEDIA_STORE_DIR.mkdir(parents=True, exist_ok=True)
    # v76.2 A-P1: content-hash URL — identical bytes map to ONE URL, so the
    # gallery/chat URL-keyed dedupe actually works (time+uuid minted a fresh
    # URL per save and defeated it). Existing files are reused, not rewritten.
    _media_digest = hashlib.sha256(raw_bytes).hexdigest()[:16]
    fname = f"{prefix}_{_media_digest}.{ext.lstrip('.')}"
    fpath = MEDIA_STORE_DIR / fname
    if not fpath.exists():
        fpath.write_bytes(raw_bytes)
    return f"/media/{fname}"

