def _postprocess_and_strip_watermark_pil(raw_img_bytes: bytes, target_w: int, target_h: int, cropped_extra_h: int = 0) -> bytes:
    """
    v41 Distortion-Free Aspect Ratio Scaler (`ImageOps.fit` with `centering=(0.5, 0.5)`):
    NEVER stretches or squishes faces/bodies ('বাঁকা তেরা / সাইড দিয়ে মোটা') when switching between
    16:9 Widescreen, 1:1 Square, 9:16 Vertical, or 4:3 Classic!
    """
    from PIL import Image, ImageEnhance, ImageOps
    im = Image.open(io.BytesIO(raw_img_bytes)).convert("RGB")
    iw, ih = im.size
    if cropped_extra_h > 0 and ih > target_h + 20:
        im = im.crop((0, 0, iw, ih - cropped_extra_h))
    elif ih > 320:
        cut_px = max(44, int(ih * 0.055))
        im = im.crop((0, 0, iw, ih - cut_px))
    if im.size != (target_w, target_h):
        resample_mode = Image.Resampling.LANCZOS if hasattr(Image, "Resampling") else Image.LANCZOS
        im = ImageOps.fit(im, (target_w, target_h), method=resample_mode, centering=(0.5, 0.5))
    im = ImageEnhance.Sharpness(im).enhance(1.16)
    im = ImageEnhance.Contrast(im).enhance(1.04)
    out_b = io.BytesIO()
    im.save(out_b, format="PNG", optimize=True)
    return out_b.getvalue()

def generate_synthesized_wav_bytes(text_input, duration_sec=2.0):
    import wave, struct, math
    sample_rate = 22050
    words = max(1, len(str(text_input or "AI").split()))
    dur = max(1.2, min(8.0, words * 0.35))
    n_samples = int(sample_rate * dur)
    buf = io.BytesIO()
    with wave.open(buf, "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sample_rate)
        frames = bytearray()
        for i in range(n_samples):
            t = i / sample_rate
            freq = 440.0 + 110.0 * math.sin(2.0 * math.pi * 2.5 * t)
            env = min(1.0, i / 800.0, (n_samples - i) / 1200.0)
            val = int(12000 * env * math.sin(2.0 * math.pi * freq * t))
            frames.extend(struct.pack("<h", max(-32767, min(32767, val))))
        wf.writeframes(bytes(frames))
    return buf.getvalue()

