# ── BMRBD v62 NATURAL AI TTS: Kokoro-82M (Marup 2026-11-11 13:30) ──
# Kokoro-82M (hexgrad/Kokoro-82M, Apache-2.0): natural AI TTS, OpenAI-TTS
# class. Voices are per language; NO Bengali voice exists, so Bengali
# stays on Edge Neural. Best-effort everywhere: any failure returns None.
_KOKORO_LANGS = {"en": "a", "es": "e", "fr": "f", "it": "i", "pt": "p", "zh": "z", "hi": "h", "ja": "j"}
_KOKORO_VOICES = {
    "a": ("af_heart", "am_adam"),      # English (US)
    "e": ("ef_dora", "em_alex"),       # Spanish
    "f": ("ff_siwis", "ff_siwis"),     # French (female voice for both; no male voice published)
    "i": ("if_sara", "im_nicola"),     # Italian
    "p": ("pf_dora", "pm_alex"),       # Portuguese
    "z": ("zf_xiaobei", "zm_yunjian"), # Mandarin
    "h": ("hf_alpha", "hm_omega"),     # Hindi
    "j": ("jf_alpha", "jm_kumo"),      # Japanese
}


def _v62_kokoro_tts(text, lang="en", gender="female"):
    """Kokoro-82M natural AI TTS. Returns WAV bytes (16-bit PCM, 24 kHz
    mono) or None. The kokoro library fetches kokoro-v1_0.pth + the voice
    file from HF (hexgrad/Kokoro-82M) on first use. Any error -> None."""
    try:
        from kokoro import KPipeline
        import numpy as np
    except Exception:
        return None
    code = _KOKORO_LANGS.get(lang or "en", "a")
    pair = _KOKORO_VOICES.get(code, ("af_heart", "am_adam"))
    voice = pair[1] if gender == "male" else pair[0]
    try:
        pipe = KPipeline(lang_code=code)
        chunks = []
        for _gs, _ps, audio in pipe(text, voice=voice):
            chunks.append(np.asarray(audio))
        if not chunks:
            return None
        audio = np.concatenate(chunks)
        pcm = (np.clip(audio, -1.0, 1.0) * 32767).astype(np.int16).tobytes()
        import io
        import wave
        buf = io.BytesIO()
        with wave.open(buf, "wb") as w:
            w.setnchannels(1)
            w.setsampwidth(2)
            w.setframerate(24000)
            w.writeframes(pcm)
        return buf.getvalue()
    except Exception:
        return None


# ── BMRBD v76 VOICE (A11): Piper TTS path tracking ──
# _LAST_TTS_PATH names the engine that produced the last speech audio
# (kokoro-en / edge-neural / piper-bn_BD / google-tts / espeak-ng /
# beep-fallback). The /v1/audio/speech handler records it in the
# recent-requests note, so it is visible in /v1/health.
_LAST_TTS_PATH = ""
# BMRBD v76.2 LEFTOVER R16: TTS silently truncated to 1500 chars, so a
# long answer read aloud stopped mid-way with no notice. The cap stays
# (every engine in the chain caps out around there), but the truncation
# is now reported: _tts_truncate_notice returns the kept text plus a
# notice dict, and generate_elevenlabs_voice_or_clone_wav records it in
# _LAST_TTS_TRUNCATED for the /v1/audio/speech headers, the
# /api/audio/voice_clone JSON and the in-chat audio message.
_TTS_MAX_CHARS = 1500
_LAST_TTS_TRUNCATED = {"truncated": False, "original_chars": 0, "spoken_chars": 0, "notice": ""}


def _tts_truncate_notice(text):
    """Truncate over-long TTS input to _TTS_MAX_CHARS and report it.

    Returns (kept_text, info) where info has truncated / original_chars /
    spoken_chars / notice ("" when nothing was cut)."""
    _raw = str(text or "")
    if len(_raw) <= _TTS_MAX_CHARS:
        return _raw, {"truncated": False, "original_chars": len(_raw),
                      "spoken_chars": len(_raw), "notice": ""}
    _kept = _raw[:_TTS_MAX_CHARS]
    return _kept, {"truncated": True, "original_chars": len(_raw),
                   "spoken_chars": len(_kept),
                   "notice": "Only the first %d of %d characters were read aloud; the rest was cut off." % (_TTS_MAX_CHARS, len(_raw))}


def _find_piper():
    """Locate (piper_binary, bn_BD_voice_onnx) or (None, None).

    Env BMRBD_PIPER_DIR (default <voice-models dir>/piper); falls back to
    a `piper` binary on PATH for the binary, but the bn_BD voice must be a
    staged .onnx file. Absence is normal when Piper is not staged — the
    caller skips it cleanly and continues down the TTS chain."""
    _base = os.environ.get("BMRBD_PIPER_DIR") or str(
        Path(os.environ.get("BMRBD_WHISPER_MODEL_DIR") or "/kaggle/input/voice-models") / "piper")
    _bin = Path(_base) / "piper"
    if not _bin.is_file():
        _w = shutil.which("piper")
        _bin = Path(_w) if _w else None
    _voice = None
    try:
        _cands = sorted(Path(_base).glob("bn_BD-*.onnx"))
        if not _cands:
            _cands = sorted(Path(_base).glob("**/bn_BD-*.onnx"))
        if _cands:
            _voice = _cands[0]
    except Exception:
        _voice = None
    return (str(_bin) if _bin else None, str(_voice) if _voice else None)


def _piper_tts_bn(text, speed=1.0):
    """Offline Piper bn_BD TTS -> WAV bytes, or None when Piper/voice is absent.

    Never raises; absence or failure is logged and the caller continues
    down the TTS chain. Bengali only (the staged voice is bn_BD)."""
    try:
        _bin, _voice = _find_piper()
        if not _bin or not _voice:
            return None
        _tmp = Path(f"/tmp/tts_piper_{uuid.uuid4().hex[:8]}.wav")
        try:
            _ls = 1.0 / max(0.5, min(2.0, float(speed or 1.0)))
        except Exception:
            _ls = 1.0
        _piper_txt, _piper_info = _tts_truncate_notice(str(text or ""))
        if _piper_info.get("truncated"):
            globals()["_LAST_TTS_TRUNCATED"] = dict(_piper_info)
        subprocess.run([_bin, "--model", _voice, "--output_file", str(_tmp),
                        "--length_scale", str(round(_ls, 3))],
                       input=_piper_txt.encode("utf-8"),
                       timeout=30, capture_output=True)
        if _tmp.is_file() and _tmp.stat().st_size > 512:
            _b = _tmp.read_bytes()
            _tmp.unlink(missing_ok=True)
            return _b
        _tmp.unlink(missing_ok=True)
        return None
    except Exception as _e:
        try:
            diag_log("WARNING", "Piper TTS failed: %s" % _e)
        except Exception:
            pass
        return None


def generate_elevenlabs_voice_or_clone_wav(text_input: str, voice_preset: str = "auto", ref_audio_b64: str = "", speed: float = 1.0) -> bytes:
    """
    v49 Humanized Neural TTS & Voice Engine (100% Real Human Speech — ZERO Robotic Beep!):
      1. Cleans markdown symbols (`*`, `#`, backticks, URLs) so speech sounds completely natural.
      2. Runs Microsoft Edge Neural TTS (`python3 -m edge_tts` / `edge-tts`) with 10+ selectable Male & Female
         Bengali (`bn-BD-NabanitaNeural`, `bn-BD-PradeepNeural`, `bn-IN-TanishaaNeural`, `bn-IN-BashkarNeural`)
         and English (`en-US-AvaMultilingualNeural`, `en-US-AndrewMultilingualNeural`) humanized voices!
      3. Falls back to Google Neural TTS (`translate.googleapis.com/translate_tts`) so even without `edge_tts`,
         it ALWAYS returns crystal-clear human Bengali/English audio!
    BMRBD v76 VOICE (A11) chain: Kokoro (English, offline) -> Edge Neural
    (Bengali/English, internet) -> Piper bn_BD (Bengali, OFFLINE) ->
    Google TTS (internet) -> espeak-ng -> beep (LAST resort, always logged).
    Every path sets _LAST_TTS_PATH and logs via diag_log; the beep fallback
    is NEVER silent.
    """
    global _LAST_TTS_PATH, _LAST_TTS_TRUNCATED
    raw_txt = str(text_input or "Hello, I am ready.").strip()
    # Strip markdown code blocks, URLs, and formatting symbols so TTS reads naturally
    clean_speech = re.sub(r"```[\s\S]*?```", " [কোড ব্লক] ", raw_txt)
    clean_speech = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", clean_speech)
    clean_speech = re.sub(r"https?://\S+", "", clean_speech)
    clean_speech = re.sub(r"[#*_`~>|]+", " ", clean_speech)
    clean_speech, _tts_info = _tts_truncate_notice(re.sub(r"\s{2,}", " ", clean_speech).strip() or "Ready.")
    _LAST_TTS_TRUNCATED = dict(_tts_info)
    has_bangla = bool(re.search(r"[\u0980-\u09FF]", clean_speech))

    vp = str(voice_preset or "auto").strip()
    if vp in ("auto", "", "default", "female"):
        v_edge = "bn-BD-NabanitaNeural" if has_bangla else "en-US-AvaMultilingualNeural"
    elif vp == "male":
        v_edge = "bn-BD-PradeepNeural" if has_bangla else "en-US-AndrewMultilingualNeural"
    elif vp in HUMANIZED_VOICE_CATALOG:
        # If user selected an English voice but text is in Bengali (and not a Multilingual voice), use Bengali voice of same gender
        if has_bangla and not vp.startswith("bn-") and "Multilingual" not in vp:
            is_male = HUMANIZED_VOICE_CATALOG[vp].get("gender") == "Male"
            v_edge = "bn-BD-PradeepNeural" if is_male else "bn-BD-NabanitaNeural"
        else:
            v_edge = vp
    else:
        v_edge = "bn-BD-NabanitaNeural" if has_bangla else "en-US-AvaMultilingualNeural"

    rate_pct = int(round((float(speed or 1.0) - 1.0) * 100))
    rate_str = f"{rate_pct:+d}%"

    # v62: Kokoro-82M natural AI TTS FIRST for supported languages (Marup
    # 13:30 — voice must NOT be plain simple TTS). Bengali has no Kokoro
    # voice, and non-Latin scripts are misread by the English pipeline, so
    # those stay on Edge Neural below. Any Kokoro failure falls through.
    if not has_bangla and not bool(re.search(r"[\u0400-\u04FF\u0600-\u06FF\u4E00-\u9FFF\u3040-\u30FF\uAC00-\uD7AF]", clean_speech)):
        try:
            _kok = _v62_kokoro_tts(clean_speech, lang="en", gender=("male" if vp == "male" else "female"))
            if _kok:
                _LAST_TTS_PATH = "kokoro-en"
                try:
                    diag_log("INFO", "TTS path used: kokoro-en")
                except Exception:
                    pass
                return _kok
        except Exception:
            pass

    # 1. Try `python3 -m edge_tts` or `edge-tts` CLI (Returns high-quality neural MP3/WAV)
    tmp_mp3 = Path(f"/tmp/tts_edge_{uuid.uuid4().hex[:8]}.mp3")
    for cmd_list in [
        [sys.executable, "-m", "edge_tts", "--voice", v_edge, f"--rate={rate_str}", "--text", clean_speech, "--write-media", str(tmp_mp3)],
        ([shutil.which("edge-tts"), "--voice", v_edge, f"--rate={rate_str}", "--text", clean_speech, "--write-media", str(tmp_mp3)] if shutil.which("edge-tts") else None)
    ]:
        if not cmd_list:
            continue
        try:
            subprocess.run(cmd_list, timeout=14, check=True, capture_output=True)
            if tmp_mp3.is_file() and tmp_mp3.stat().st_size > 512:
                mp3_bytes = tmp_mp3.read_bytes()
                tmp_mp3.unlink(missing_ok=True)
                _LAST_TTS_PATH = "edge-neural"
                try:
                    diag_log("INFO", "TTS path used: edge-neural (%s)" % v_edge)
                except Exception:
                    pass
                return mp3_bytes
        except Exception:
            tmp_mp3.unlink(missing_ok=True)

    # BMRBD v76 VOICE (A11): Piper bn_BD OFFLINE Bengali fallback — after
    # Edge Neural, before Google TTS. Absent Piper/voice skips cleanly.
    if has_bangla:
        try:
            _pw = _piper_tts_bn(clean_speech, speed=speed)
            if _pw:
                _LAST_TTS_PATH = "piper-bn_BD"
                try:
                    diag_log("INFO", "TTS path used: piper-bn_BD (offline fallback)")
                except Exception:
                    pass
                return _pw
        except Exception:
            pass

    # 2. Fallback to Google Neural TTS (`translate.googleapis.com/translate_tts`) — 100% Real Human Bengali/English Voice!
    try:
        tl_lang = "bn" if has_bangla else "en"
        words = clean_speech.split()
        chunks_txt = []
        cur_c = ""
        for w in words:
            if len(cur_c) + len(w) + 1 <= 170:
                cur_c = (cur_c + " " + w).strip()
            else:
                if cur_c:
                    chunks_txt.append(cur_c)
                cur_c = w
        if cur_c:
            chunks_txt.append(cur_c)
        mp3_parts = []
        for c_part in chunks_txt[:8]:
            q_enc = urllib.request.quote(c_part)
            g_url = f"https://translate.googleapis.com/translate_tts?ie=UTF-8&client=tw-ob&tl={tl_lang}&q={q_enc}"
            req_g = urllib.request.Request(g_url, headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(req_g, timeout=6) as rg:
                b_part = rg.read()
                if len(b_part) > 256:
                    mp3_parts.append(b_part)
        if mp3_parts:
            _LAST_TTS_PATH = "google-tts"
            try:
                diag_log("INFO", "TTS path used: google-tts")
            except Exception:
                pass
            return b"".join(mp3_parts)
    except Exception:
        pass

    # 3. Offline Linux `espeak-ng` speech fallback (never a sine-wave beep!)
    if shutil.which("espeak-ng"):
        try:
            tmp_es = Path(f"/tmp/es_{uuid.uuid4().hex[:8]}.wav")
            v_es = "bn" if has_bangla else "en-us"
            subprocess.run(["espeak-ng", "-v", v_es, "-s", "155", "-w", str(tmp_es), clean_speech[:500]], timeout=8, check=False)
            if tmp_es.is_file() and tmp_es.stat().st_size > 512:
                b_es = tmp_es.read_bytes()
                tmp_es.unlink(missing_ok=True)
                _LAST_TTS_PATH = "espeak-ng"
                try:
                    diag_log("INFO", "TTS path used: espeak-ng")
                except Exception:
                    pass
                return b_es
        except Exception:
            pass

    # LAST resort only: synthesized beep — NEVER silent (logged + tracked).
    _LAST_TTS_PATH = "beep-fallback"
    try:
        diag_log("WARNING", "TTS beep fallback hit: Kokoro/Edge/Piper/Google/espeak all failed (lang=%s)" % ("bn" if has_bangla else "en"))
    except Exception:
        pass
    return generate_synthesized_wav_bytes(clean_speech)

def generate_higgsfield_video_v38(
    prompt_text,
    size_str="1280x720",
    negative_prompt="",
    camera_motion="action_tracking",
    lens="85mm_f14",
    duration_sec=5.0,
    with_audio=True,
    voiceover_text="",
    video_model="wan2-1-t2v-1-3b"
):
    """
    v61.1 HONEST VIDEO ROUTE — keyframe + Ken Burns + ffmpeg (NOT a diffusion video model):
    Generates one high-resolution keyframe image, then renders slow Ken Burns
    pan/zoom crops of that still frame into an H.264 `.mp4` (plus synthesized
    audio muxed with `ffmpeg`). It does NOT run Wan2.1, CogVideoX, Veo, Seedance
    or any text-to-video diffusion model — `video_model` is a display label
    only, never a loaded model. Supports 5s–240s clips.
    """
    t0 = time.time()
    from PIL import Image, ImageEnhance, ImageOps
    import cv2, numpy as np
    pos_clean, neg_clean = parse_positive_and_negative_prompt(prompt_text, custom_negative=negative_prompt)
    _, w, h = extract_requested_image_size(f"{pos_clean} {size_str}", default_size=size_str or "1280x720")
    w, h = min(848, max(480, (w // 16) * 16)), min(480, max(272, (h // 16) * 16))
    dur = max(3.0, min(240.0, float(duration_sec or 5.0)))
    fps = 12.0 if dur <= 15.0 else 8.0
    n_frames = max(24, min(720, int(dur * fps)))

    # Generate high-res keyframe(s)
    img_res = generate_studio_image_v38(
        pos_clean,
        size_str=f"{int(w * 1.25)}x{int(h * 1.25)}",
        negative_prompt=neg_clean,
        model_preset="imagen-4-ultra",
        camera_motion=camera_motion,
        lens=lens
    )
    base_im = Image.open(io.BytesIO(base64.b64decode(img_res["b64_json"]))).convert("RGB")
    bw, bh = base_im.size
    frames_pil = []
    frames_bgr = []

    for step in range(n_frames):
        prog = step / float(max(1, n_frames - 1))
        if camera_motion == "dolly_in":
            zoom = 1.0 + 0.24 * prog
            pan_x, pan_y = 0.5, 0.5
        elif camera_motion == "crane_up":
            zoom = 1.08 + 0.08 * prog
            pan_x, pan_y = 0.5, 0.85 - 0.70 * prog
        elif camera_motion == "pan_lr":
            zoom = 1.18
            pan_x, pan_y = 0.10 + 0.80 * prog, 0.5
        elif camera_motion == "fpv_drone":
            zoom = 1.05 + 0.20 * math.sin(prog * math.pi)
            pan_x = 0.5 + 0.40 * math.sin(prog * 2 * math.pi)
            pan_y = 0.5 + 0.25 * math.cos(prog * 2 * math.pi)
        else:
            zoom = 1.04 + 0.18 * math.sin(prog * math.pi)
            pan_x = 0.5 + 0.42 * math.sin(prog * 2 * math.pi)
            pan_y = 0.5 + 0.30 * math.cos(prog * 2 * math.pi)

        crop_w = int(bw / zoom)
        crop_h = int(bh / zoom)
        left = int(max(0, bw - crop_w) * max(0.0, min(1.0, pan_x)))
        top = int(max(0, bh - crop_h) * max(0.0, min(1.0, pan_y)))
        f_im = base_im.crop((left, top, left + crop_w, top + crop_h)).resize(
            (w, h), Image.Resampling.LANCZOS if hasattr(Image, "Resampling") else Image.LANCZOS
        )
        bri = 1.0 + 0.04 * math.sin(prog * 2 * math.pi)
        f_im = ImageEnhance.Brightness(f_im).enhance(bri)
        if len(frames_pil) < 28:
            frames_pil.append(f_im)
        frames_bgr.append(cv2.cvtColor(np.array(f_im), cv2.COLOR_RGB2BGR))

    gif_buf = io.BytesIO()
    frames_pil[0].save(gif_buf, format="GIF", save_all=True, append_images=frames_pil[1:], duration=int(1000 / fps), loop=0, optimize=True)
    gif_bytes = gif_buf.getvalue()
    gif_url = save_media_and_get_url(gif_bytes, "gif", "higgs_gif")

    mp4_name = f"higgs_vid_{int(time.time()*1000)}_{uuid.uuid4().hex[:6]}.mp4"
    mp4_path = MEDIA_STORE_DIR / mp4_name
    tmp_raw_mp4 = Path(f"/tmp/raw_vid_{uuid.uuid4().hex[:8]}.mp4")
    tmp_aud_wav = Path(f"/tmp/raw_aud_{uuid.uuid4().hex[:8]}.wav")

    try:
        vw = cv2.VideoWriter(str(tmp_raw_mp4), cv2.VideoWriter_fourcc(*"mp4v"), float(fps), (w, h))
        for fb in frames_bgr:
            vw.write(fb)
        vw.release()

        if with_audio:
            aud_bytes = synthesize_rich_music_or_song_wav(pos_clean, lyrics=voiceover_text, duration_sec=dur)
            tmp_aud_wav.write_bytes(aud_bytes)
            subprocess.run([
                "ffmpeg", "-y", "-i", str(tmp_raw_mp4), "-i", str(tmp_aud_wav),
                "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p",
                "-c:a", "aac", "-b:a", "128k", "-shortest", str(mp4_path)
            ], capture_output=True, timeout=45)
        else:
            subprocess.run([
                "ffmpeg", "-y", "-i", str(tmp_raw_mp4),
                "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p", str(mp4_path)
            ], capture_output=True, timeout=45)

        if not mp4_path.is_file() or mp4_path.stat().st_size < 512:
            shutil.copy2(str(tmp_raw_mp4), str(mp4_path))
    except Exception:
        pass
    finally:
        for p in (tmp_raw_mp4, tmp_aud_wav):
            try: p.unlink()
            except Exception: pass

    # Convert mp4v to browser-native H.264 yuv420p and preserve original audio from tmp_in if present
    try:
        h264_path = MEDIA_STORE_DIR / f"h264_{mp4_name}"
        subprocess.run([
            "ffmpeg", "-y", "-i", str(mp4_path),
            "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p", str(h264_path)
        ], capture_output=True, timeout=45)
        if h264_path.is_file() and h264_path.stat().st_size > 512:
            shutil.move(str(h264_path), str(mp4_path))
    except Exception:
        pass
    mp4_url = f"/media/{mp4_name}" if (mp4_path.is_file() and mp4_path.stat().st_size > 512) else ""
    return {
        "b64_json": base64.b64encode(gif_bytes).decode("ascii"),
        "url": mp4_url or gif_url,
        "gif_url": gif_url,
        "mp4_url": mp4_url,
        "width": w,
        "height": h,
        "duration_sec": dur,
        "with_audio": bool(with_audio),
        "video_model": video_model,
        "positive_prompt": pos_clean,
        "negative_prompt": neg_clean,
        "elapsed_sec": round(time.time() - t0, 2)
    }

def handle_video_edit_api(req_j: dict) -> dict:
    """
    AI Video Editor (`/api/video/edit`):
    Takes an uploaded video (`video_b64`), applies requested AI edit instruction (`prompt`),
    color grading LUT (`cinema_warm`, `cyberpunk_neon`, `bw_noir`, `hdr_vivid`, `natural`),
    speed multiplier (`0.5x` slow-mo to `2.0x`), and optional new synchronized audio/voiceover!
    """
    import cv2, numpy as np
    t0 = time.time()
    vid_bytes = _decode_b64_to_bytes(req_j.get("video_b64") or req_j.get("target_b64") or "")
    edit_prompt = str(req_j.get("prompt") or "Enhance video clarity and add cinematic sound").strip()
    lut_style = str(req_j.get("lut_style") or "hdr_vivid").lower()
    speed_mult = max(0.5, min(2.0, float(req_j.get("speed") or 1.0)))
    add_audio = bool(req_j.get("add_audio", True))

    tmp_in = Path(f"/tmp/vedit_in_{uuid.uuid4().hex[:8]}.mp4")
    tmp_raw = Path(f"/tmp/vedit_raw_{uuid.uuid4().hex[:8]}.mp4")
    tmp_wav = Path(f"/tmp/vedit_aud_{uuid.uuid4().hex[:8]}.wav")
    out_name = f"edited_vid_{int(time.time()*1000)}_{uuid.uuid4().hex[:6]}.mp4"
    out_path = MEDIA_STORE_DIR / out_name
    tmp_in.write_bytes(vid_bytes)

    cap = cv2.VideoCapture(str(tmp_in))
    fps = (cap.get(cv2.CAP_PROP_FPS) or 24.0) * speed_mult
    vw = None
    n_frames = 0
    W, H = 640, 360
    try:
        while True:
            ret, frame = cap.read()
            if not ret or frame is None:
                break
            H, W = frame.shape[:2]
            if vw is None:
                vw = cv2.VideoWriter(str(tmp_raw), cv2.VideoWriter_fourcc(*"mp4v"), float(fps), (W, H))
            f_out = frame.astype(np.float32)
            if "cyberpunk" in lut_style or "neon" in edit_prompt.lower():
                f_out[:, :, 0] *= 1.25  # Boost blue
                f_out[:, :, 2] *= 1.18  # Boost magenta/red
            elif "warm" in lut_style or "gold" in edit_prompt.lower():
                f_out[:, :, 2] *= 1.18
                f_out[:, :, 1] *= 1.06
                f_out[:, :, 0] *= 0.88
            elif "noir" in lut_style or "black and white" in edit_prompt.lower():
                g = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
                f_out = cv2.cvtColor(cv2.equalizeHist(g), cv2.COLOR_GRAY2BGR).astype(np.float32)
            else:
                # HDR Vivid sharpening
                blur = cv2.GaussianBlur(frame, (0, 0), 1.5)
                f_out = cv2.addWeighted(frame, 1.25, blur, -0.25, 0).astype(np.float32)
            f_out = np.clip(f_out, 0, 255).astype(np.uint8)
            vw.write(f_out)
            n_frames += 1
    finally:
        cap.release()
        if vw is not None:
            vw.release()

    dur = max(3.0, n_frames / max(1.0, fps))
    if add_audio:
        wav_b = synthesize_rich_music_or_song_wav(edit_prompt, duration_sec=dur)
        tmp_wav.write_bytes(wav_b)
        subprocess.run([
            "ffmpeg", "-y", "-i", str(tmp_raw), "-i", str(tmp_wav),
            "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p",
            "-c:a", "aac", "-b:a", "128k", "-shortest", str(out_path)
        ], capture_output=True, timeout=45)
    else:
        subprocess.run([
            "ffmpeg", "-y", "-i", str(tmp_raw), "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p", str(out_path)
        ], capture_output=True, timeout=45)

    for p in (tmp_in, tmp_raw, tmp_wav):
        try: p.unlink()
        except Exception: pass

    return {
        "mp4_url": f"/media/{out_name}",
        "url": f"/media/{out_name}",
        "frames_processed": n_frames,
        "duration_sec": round(dur, 1),
        "elapsed_sec": round(time.time() - t0, 2)
    }

