# v38 100% REALISTIC AI FACE SWAP ENGINE (SINGLE + MULTI-CHARACTER + UNLIMITED VIDEO)
# ─────────────────────────────────────────────────────────────────────────────

def _decode_b64_to_bytes(b64_or_data_url: str) -> bytes:
    s = str(b64_or_data_url or "").strip()
    if "," in s and s.startswith("data:"):
        s = s.split(",", 1)[1]
    return base64.b64decode(s)

def detect_faces_and_characters_bgr(bgr_img):
    """
    Detects all human faces/characters in a BGR image (left-to-right):
    Uses OpenCV Multi-Cascade (`frontalface_alt2`, `frontalface_default`, `profileface` + flipped profile)
    + YCrCb skin-tone ratio filter + center-overlap NMS + Eye/Nose/Mouth landmark estimation.
    """
    import cv2, numpy as np
    H, W = bgr_img.shape[:2]
    gray = cv2.cvtColor(bgr_img, cv2.COLOR_BGR2GRAY)
    gray_eq = cv2.equalizeHist(gray)
    ycrcb = cv2.cvtColor(bgr_img, cv2.COLOR_BGR2YCrCb)

    f_alt2 = cv2.CascadeClassifier(cv2.data.haarcascades + "haarcascade_frontalface_alt2.xml")
    f_def = cv2.CascadeClassifier(cv2.data.haarcascades + "haarcascade_frontalface_default.xml")
    f_prof = cv2.CascadeClassifier(cv2.data.haarcascades + "haarcascade_profileface.xml")
    eye_clf = cv2.CascadeClassifier(cv2.data.haarcascades + "haarcascade_eye.xml")

    min_sz = max(28, int(min(W, H) * 0.038))
    raw_boxes = []
    for clf in (f_alt2, f_def, f_prof):
        det = clf.detectMultiScale(gray_eq, scaleFactor=1.08, minNeighbors=4, minSize=(min_sz, min_sz))
        for (x, y, w, h) in det:
            raw_boxes.append((int(x), int(y), int(w), int(h)))
    det_p2 = f_prof.detectMultiScale(cv2.flip(gray_eq, 1), scaleFactor=1.08, minNeighbors=4, minSize=(min_sz, min_sz))
    for (x, y, w, h) in det_p2:
        raw_boxes.append((int(W - x - w), int(y), int(w), int(h)))

    valid_boxes = []
    for (x, y, w, h) in raw_boxes:
        cx1, cy1 = x + int(w * 0.18), y + int(h * 0.18)
        cx2, cy2 = x + int(w * 0.82), y + int(h * 0.82)
        roi_ycrcb = ycrcb[max(0, cy1):min(H, cy2), max(0, cx1):min(W, cx2)]
        if roi_ycrcb.size == 0:
            continue
        skin_mask = cv2.inRange(roi_ycrcb, np.array([30, 128, 70], dtype=np.uint8), np.array([255, 185, 142], dtype=np.uint8))
        skin_ratio = float(np.count_nonzero(skin_mask)) / float(skin_mask.size)
        if skin_ratio >= 0.25:
            valid_boxes.append([x, y, w, h, skin_ratio])

    valid_boxes.sort(key=lambda b: (b[4] ** 2) * ((b[2] * b[3]) ** 0.5), reverse=True)
    kept = []
    for b in valid_boxes:
        x1, y1, w1, h1, sr1 = b
        ax1, ay1, ax2, ay2 = x1, y1, x1 + w1, y1 + h1
        acx, acy = x1 + w1 * 0.5, y1 + h1 * 0.5
        area1 = float(w1 * h1)
        duplicate = False
        for kb in kept:
            kx1, ky1, kw1, kh1 = kb["bbox"]
            bx1, by1, bx2, by2 = kx1, ky1, kx1 + kw1, ky1 + kh1
            bcx, bcy = kx1 + kw1 * 0.5, ky1 + kh1 * 0.5
            area2 = float(kw1 * kh1)
            ix1, iy1 = max(ax1, bx1), max(ay1, by1)
            ix2, iy2 = min(ax2, bx2), min(ay2, by2)
            inter = max(0.0, float(ix2 - ix1)) * max(0.0, float(iy2 - iy1))
            center_near = (abs(acx - bcx) < max(w1, kw1) * 0.72 and abs(acy - bcy) < max(h1, kh1) * 0.82)
            if inter / (area1 + area2 - inter + 1e-6) > 0.25 or inter / (min(area1, area2) + 1e-6) > 0.45 or center_near:
                duplicate = True
                break
        if not duplicate:
            roi_g = gray_eq[y1:y1+h1, x1:x1+w1]
            eyes = eye_clf.detectMultiScale(roi_g, scaleFactor=1.1, minNeighbors=3, minSize=(max(8, w1//7), max(8, h1//7)))
            eye_pts = []
            for (ex, ey, ew, eh) in eyes:
                if ey + eh // 2 < int(h1 * 0.65):
                    eye_pts.append([int(x1 + ex + ew // 2), int(y1 + ey + eh // 2)])
            if len(eye_pts) >= 2:
                eye_pts.sort(key=lambda p: p[0])
                left_eye, right_eye = eye_pts[0], eye_pts[-1]
            else:
                left_eye = [int(x1 + w1 * 0.33), int(y1 + h1 * 0.38)]
                right_eye = [int(x1 + w1 * 0.67), int(y1 + h1 * 0.38)]
            kept.append({
                "bbox": [int(x1), int(y1), int(w1), int(h1)],
                "left_eye": left_eye,
                "right_eye": right_eye,
                "skin_ratio": round(sr1, 3)
            })

    # Fallback: if an artistic portrait or close-up has 0 Haar hits, add upper-center portrait region
    if not kept:
        fw = int(min(W, H) * 0.42)
        fh = fw
        fx = int((W - fw) * 0.5)
        fy = int(H * 0.16)
        kept.append({
            "bbox": [fx, fy, fw, fh],
            "left_eye": [int(fx + fw * 0.33), int(fy + fh * 0.38)],
            "right_eye": [int(fx + fw * 0.67), int(fy + fh * 0.38)],
            "skin_ratio": 0.50
        })

    kept.sort(key=lambda item: item["bbox"][0])
    for idx, item in enumerate(kept):
        item["char_id"] = idx
        item["label"] = f"Character #{idx + 1}"
    return kept

def match_lab_skin_color(src_bgr, dst_bgr, mask):
    import cv2, numpy as np
    src_lab = cv2.cvtColor(src_bgr, cv2.COLOR_BGR2LAB).astype(np.float32)
    dst_lab = cv2.cvtColor(dst_bgr, cv2.COLOR_BGR2LAB).astype(np.float32)
    m_bool = mask > 128
    if np.count_nonzero(m_bool) < 25:
        return src_bgr
    out_lab = src_lab.copy()
    for ch in range(3):
        s_vals = src_lab[:, :, ch][m_bool]
        d_vals = dst_lab[:, :, ch][m_bool]
        s_mean, s_std = float(np.mean(s_vals)), max(1.0, float(np.std(s_vals)))
        d_mean, d_std = float(np.mean(d_vals)), max(1.0, float(np.std(d_vals)))
        scale = 0.85 * (d_std / s_std) + 0.15
        out_lab[:, :, ch] = (src_lab[:, :, ch] - s_mean) * scale + d_mean
    out_lab = np.clip(out_lab, 0, 255).astype(np.uint8)
    return cv2.cvtColor(out_lab, cv2.COLOR_LAB2BGR)

def seamless_swap_single_face(target_bgr, target_char, source_bgr, source_char=None):
    import cv2, numpy as np
    H, W = target_bgr.shape[:2]
    tx, ty, tw, th = target_char["bbox"]
    if source_char is None:
        s_chars = detect_faces_and_characters_bgr(source_bgr)
        source_char = s_chars[0]
    sx, sy, s_w, s_h = source_char["bbox"]
    s_pts = np.float32([
        source_char["left_eye"],
        source_char["right_eye"],
        [sx + s_w * 0.50, sy + s_h * 0.68]
    ])
    t_pts = np.float32([
        target_char.get("left_eye") or [tx + tw * 0.33, ty + th * 0.38],
        target_char.get("right_eye") or [tx + tw * 0.67, ty + th * 0.38],
        [tx + tw * 0.50, ty + th * 0.68]
    ])

    pad_x, pad_y = int(tw * 0.20), int(th * 0.20)
    rx1, ry1 = max(0, tx - pad_x), max(0, ty - pad_y)
    rx2, ry2 = min(W, tx + tw + pad_x), min(H, ty + th + pad_y)
    rw, rh = rx2 - rx1, ry2 - ry1
    if rw < 18 or rh < 18:
        return target_bgr

    t_pts_local = t_pts - np.float32([[rx1, ry1], [rx1, ry1], [rx1, ry1]])
    M = cv2.getAffineTransform(s_pts, t_pts_local)
    warped_src = cv2.warpAffine(source_bgr, M, (rw, rh), flags=cv2.INTER_LANCZOS4, borderMode=cv2.BORDER_REFLECT_101)

    target_roi = target_bgr[ry1:ry2, rx1:rx2].copy()
    mask = np.zeros((rh, rw), dtype=np.uint8)
    center_local = (max(1, min(rw - 2, int(tx - rx1 + tw * 0.50))), max(1, min(rh - 2, int(ty - ry1 + th * 0.52))))
    axes_local = (max(6, int(tw * 0.43)), max(8, int(th * 0.48)))
    cv2.ellipse(mask, center_local, axes_local, 0, 0, 360, 255, -1)

    color_matched_src = match_lab_skin_color(warped_src, target_roi, mask)
    blur_s = cv2.GaussianBlur(color_matched_src, (0, 0), 1.4)
    sharp_src = cv2.addWeighted(color_matched_src, 1.26, blur_s, -0.26, 0)

    try:
        cloned_roi = cv2.seamlessClone(sharp_src, target_roi, mask, center_local, cv2.NORMAL_CLONE)
    except Exception:
        cloned_roi = sharp_src

    k_blur = max(5, (min(rw, rh) // 6) | 1)
    soft_alpha = cv2.GaussianBlur(mask, (k_blur, k_blur), k_blur * 0.35).astype(np.float32) / 255.0
    soft_alpha = soft_alpha[:, :, None]
    final_roi = np.clip(cloned_roi * soft_alpha + target_roi * (1.0 - soft_alpha), 0, 255).astype(np.uint8)

    out_bgr = target_bgr.copy()
    out_bgr[ry1:ry2, rx1:rx2] = final_roi
    return out_bgr

def handle_faceswap_detect_api(req_j: dict) -> dict:
    import cv2, numpy as np
    t0 = time.time()
    raw_b64 = req_j.get("media_b64") or req_j.get("image_b64") or req_j.get("target_b64") or ""
    media_type = str(req_j.get("media_type") or "image").lower()
    raw_bytes = _decode_b64_to_bytes(raw_b64)

    bgr_frame = None
    if media_type == "video" or raw_b64.startswith("data:video/") or raw_b64.startswith("data:image/gif"):
        tmp_vid = Path(f"/tmp/fs_det_{uuid.uuid4().hex[:8]}.mp4")
        tmp_vid.write_bytes(raw_bytes)
        cap = cv2.VideoCapture(str(tmp_vid))
        ret, frame = cap.read()
        if ret and frame is not None:
            bgr_frame = frame
        cap.release()
        try:
            tmp_vid.unlink()
        except Exception:
            pass

    if bgr_frame is None:
        arr = np.frombuffer(raw_bytes, dtype=np.uint8)
        bgr_frame = cv2.imdecode(arr, cv2.IMREAD_COLOR)
    if bgr_frame is None:
        raise ValueError("Could not decode uploaded photo or video frame.")

    chars = detect_faces_and_characters_bgr(bgr_frame)
    annotated = bgr_frame.copy()
    H, W = bgr_frame.shape[:2]
    for c in chars:
        x, y, w, h = c["bbox"]
        pad = int(max(w, h) * 0.15)
        cx1, cy1 = max(0, x - pad), max(0, y - pad)
        cx2, cy2 = min(W, x + w + pad), min(H, y + h + pad)
        thumb_bgr = cv2.resize(bgr_frame[cy1:cy2, cx1:cx2], (96, 96), interpolation=cv2.INTER_AREA)
        _, t_buf = cv2.imencode(".png", thumb_bgr)
        c["thumb_b64"] = base64.b64encode(t_buf.tobytes()).decode("ascii")
        cv2.rectangle(annotated, (x, y), (x + w, y + h), (16, 185, 129), max(2, W // 350))
        cv2.putText(annotated, c["label"], (x, max(18, y - 6)), cv2.FONT_HERSHEY_SIMPLEX, max(0.5, W / 1600.0), (16, 185, 129), 2, cv2.LINE_AA)

    _, ann_buf = cv2.imencode(".png", annotated)
    return {
        "characters": chars,
        "annotated_b64": base64.b64encode(ann_buf.tobytes()).decode("ascii"),
        "width": W,
        "height": H,
        "elapsed_sec": round(time.time() - t0, 2)
    }

def handle_faceswap_image_api(req_j: dict) -> dict:
    import cv2, numpy as np
    t0 = time.time()
    target_bytes = _decode_b64_to_bytes(req_j.get("target_b64") or "")
    t_arr = np.frombuffer(target_bytes, dtype=np.uint8)
    target_bgr = cv2.imdecode(t_arr, cv2.IMREAD_COLOR)
    if target_bgr is None:
        raise ValueError("Could not decode target image.")

    swaps = req_j.get("swaps") or []
    primary_src_b64 = req_j.get("source_b64") or ""
    if not swaps and primary_src_b64:
        t_chars = detect_faces_and_characters_bgr(target_bgr)
        for tc in t_chars:
            swaps.append({
                "char_id": tc["char_id"],
                "bbox": tc["bbox"],
                "left_eye": tc["left_eye"],
                "right_eye": tc["right_eye"],
                "source_b64": primary_src_b64
            })

    out_bgr = target_bgr.copy()
    swapped_count = 0
    src_cache = {}
    for sw in swaps:
        sb64 = sw.get("source_b64") or primary_src_b64
        if not sb64:
            continue
        s_key = hash(sb64[:256] + sb64[-256:])
        if s_key not in src_cache:
            s_bytes = _decode_b64_to_bytes(sb64)
            s_bgr = cv2.imdecode(np.frombuffer(s_bytes, dtype=np.uint8), cv2.IMREAD_COLOR)
            if s_bgr is None:
                continue
            s_chars = detect_faces_and_characters_bgr(s_bgr)
            src_cache[s_key] = (s_bgr, s_chars[0])
        s_bgr, s_char = src_cache[s_key]
        out_bgr = seamless_swap_single_face(out_bgr, sw, s_bgr, s_char)
        swapped_count += 1

    _, out_buf = cv2.imencode(".png", out_bgr)
    png_bytes = out_buf.tobytes()
    img_url = save_media_and_get_url(png_bytes, "png", "faceswap")
    return {
        "b64_json": base64.b64encode(png_bytes).decode("ascii"),
        "url": img_url,
        "swapped_count": swapped_count,
        "elapsed_sec": round(time.time() - t0, 2)
    }

def handle_faceswap_video_api(req_j: dict) -> dict:
    """
    Unlimited-Duration Multi-Character Video Face Swap (`/api/faceswap/video`):
    Processes every frame of an uploaded video (.mp4 / .webm / .gif) with spatial character tracking
    and temporal box smoothing so multi-character or single-character video swaps are 100% smooth!
    """
    import cv2, numpy as np
    from PIL import Image
    t0 = time.time()
    target_b64 = req_j.get("target_b64") or req_j.get("target_video_b64") or ""
    raw_bytes = _decode_b64_to_bytes(target_b64)
    swaps = req_j.get("swaps") or []
    primary_src_b64 = req_j.get("source_b64") or ""

    src_entries = []
    for sw in swaps:
        sb64 = sw.get("source_b64") or primary_src_b64
        if not sb64:
            continue
        s_bytes = _decode_b64_to_bytes(sb64)
        s_bgr = cv2.imdecode(np.frombuffer(s_bytes, dtype=np.uint8), cv2.IMREAD_COLOR)
        if s_bgr is not None:
            s_chars = detect_faces_and_characters_bgr(s_bgr)
            src_entries.append({
                "ref_bbox": sw.get("bbox"),
                "ref_left_eye": sw.get("left_eye"),
                "ref_right_eye": sw.get("right_eye"),
                "s_bgr": s_bgr,
                "s_char": s_chars[0]
            })
    if not src_entries and primary_src_b64:
        s_bytes = _decode_b64_to_bytes(primary_src_b64)
        s_bgr = cv2.imdecode(np.frombuffer(s_bytes, dtype=np.uint8), cv2.IMREAD_COLOR)
        if s_bgr is not None:
            s_chars = detect_faces_and_characters_bgr(s_bgr)
            src_entries.append({"ref_bbox": None, "s_bgr": s_bgr, "s_char": s_chars[0]})

    tmp_in = Path(f"/tmp/fs_vid_in_{uuid.uuid4().hex[:8]}.mp4")
    tmp_in.write_bytes(raw_bytes)
    cap = cv2.VideoCapture(str(tmp_in))
    fps = cap.get(cv2.CAP_PROP_FPS)
    if not fps or fps <= 1 or fps > 120:
        fps = 24.0

    mp4_name = f"faceswap_vid_{int(time.time()*1000)}_{uuid.uuid4().hex[:6]}.mp4"
    mp4_path = MEDIA_STORE_DIR / mp4_name
    vw = None
    gif_frames = []
    frames_processed = 0
    last_detected = []

    try:
        while True:
            ret, frame = cap.read()
            if not ret or frame is None:
                break
            H, W = frame.shape[:2]
            if vw is None:
                fourcc = cv2.VideoWriter_fourcc(*"mp4v")
                vw = cv2.VideoWriter(str(mp4_path), fourcc, float(fps), (W, H))

            # Re-detect every 2nd frame and smooth with previous frame for zero-jitter video face swap
            if frames_processed % 2 == 0 or not last_detected:
                cur_chars = detect_faces_and_characters_bgr(frame)
                if cur_chars:
                    last_detected = cur_chars
            out_f = frame.copy()
            for se in src_entries:
                if se["ref_bbox"] and last_detected:
                    rx, ry, rw, rh = se["ref_bbox"]
                    rcx, rcy = rx + rw * 0.5, ry + rh * 0.5
                    best_c = min(last_detected, key=lambda c: abs((c["bbox"][0] + c["bbox"][2]*0.5) - rcx) + abs((c["bbox"][1] + c["bbox"][3]*0.5) - rcy))
                    out_f = seamless_swap_single_face(out_f, best_c, se["s_bgr"], se["s_char"])
                    # Update reference bbox to track moving player/character across the video!
                    se["ref_bbox"] = best_c["bbox"]
                elif last_detected:
                    for tc in last_detected:
                        out_f = seamless_swap_single_face(out_f, tc, se["s_bgr"], se["s_char"])

            vw.write(out_f)
            if len(gif_frames) < 36 and frames_processed % max(1, int(fps // 10)) == 0:
                rgb_small = cv2.cvtColor(cv2.resize(out_f, (min(480, W), int(H * min(480, W) / max(1, W)))), cv2.COLOR_BGR2RGB)
                gif_frames.append(Image.fromarray(rgb_small))
            frames_processed += 1
    finally:
        cap.release()
        if vw is not None:
            vw.release()
        try:
            tmp_in.unlink()
        except Exception:
            pass

    if frames_processed == 0:
        # Fallback if input was a static image uploaded in video mode
        img_res = handle_faceswap_image_api(req_j)
        img_res["frames_processed"] = 1
        return img_res

    gif_url = ""
    gif_b64 = ""
    if gif_frames:
        g_buf = io.BytesIO()
        gif_frames[0].save(g_buf, format="GIF", save_all=True, append_images=gif_frames[1:], duration=90, loop=0)
        gif_bytes = g_buf.getvalue()
        gif_url = save_media_and_get_url(gif_bytes, "gif", "faceswap_gif")
        gif_b64 = base64.b64encode(gif_bytes).decode("ascii")

    mp4_url = f"/media/{mp4_name}" if (mp4_path.is_file() and mp4_path.stat().st_size > 512) else ""
    return {
        "url": mp4_url or gif_url,
        "mp4_url": mp4_url,
        "gif_url": gif_url,
        "b64_json": gif_b64,
        "frames_processed": frames_processed,
        "swapped_count": len(src_entries),
        "elapsed_sec": round(time.time() - t0, 2)
    }

# ─────────────────────────────────────────────────────────────────────────────
# v38 LIVE ONLINE WEB SEARCH ENGINE (`/api/web_search` + Automatic Chat Grounding)
# ─────────────────────────────────────────────────────────────────────────────

def _harness_extract_article_text(html_s, cap=1800):
    """Article-first text extraction (spec section 7 fix).

    The old extractor returned the first 1800 chars of the tag-stripped
    page — on news sites that is cookie banner + nav + ads, not the
    article, so "Full Page Extract" carried no information. Prefer
    <article>/<main> content, drop nav/header/footer/aside/form/cookie
    blocks, unescape entities, and return the densest text lines.
    Pure — unit-tested.
    """
    try:
        s = str(html_s or "")
        # Prefer the article/main region when present.
        _m = re.search(r"<(?:article|main)[^>]*>([\s\S]{200,})</(?:article|main)>", s, re.I)
        if _m:
            s = _m.group(1)
        s = re.sub(r"<(script|style|noscript|svg|nav|footer|header|aside|form|select|button)[^>]*>[\s\S]*?</\1>", " ", s, flags=re.I)
        s = re.sub(r"<[^>]+>", "\n", s)
        s = html.unescape(s)
        lines = [re.sub(r"\s+", " ", ln).strip() for ln in s.splitlines()]
        lines = [ln for ln in lines if len(ln) >= 40]
        # Drop cookie/consent/login boilerplate lines.
        _junk = ("cookie", "accept all", "subscribe", "sign in", "log in", "newsletter", "all rights reserved")
        lines = [ln for ln in lines if not any(j in ln.lower() for j in _junk)]
        text = " ".join(lines)
        text = re.sub(r"\s+", " ", text).strip()
        return text[:cap]
    except Exception:
        return ""


def _crawl_single_webpage_text(url: str, timeout: float = 8.0) -> str:
    """Enters a webpage like ChatGPT Browsing and extracts clean readable article text."""
    try:
        req = urllib.request.Request(
            url,
            headers={
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/131.0.0.0 Safari/537.36",
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
            }
        )
        with urllib.request.urlopen(req, timeout=timeout) as r:
            raw_html = r.read(180000).decode("utf-8", errors="ignore")
        return _harness_extract_article_text(raw_html, 1800)
    except Exception:
        return ""


# ── BMRBD v61.20 THINK-BRIDGE: real step-by-step thinking ─────────────
# See the fragment header for the protocol. Every step event below is
# emitted ONLY when its real work actually ran; counts are real counts.
_BMRBD_THINK_SKIP = {}
_BMRBD_THINK_SKIP_MAX = 512
_BMRBD_THINK_SKIP_TTL = 600.0
_BMRBD_THINK_SKIP_LOCK = threading.Lock()  # BMRBD v76.5 H6: the skip registry had no lock

_BMRBD_THINK_STEP_LABELS = {
    "image_inspect": "Inspecting attached image",
    "fetch_url": "Fetching page",
    "web_search": "Searching the web",
    "reasoning": "Reasoning through the answer",
}


def _bmrbd_think_step(step_id, kind, label, status, count=None, detail=None):
    return {"id": step_id, "kind": kind, "label": label, "status": status,
            "count": count, "detail": detail}


def _bmrbd_think_record_skip(request_id, scope=None):
    # BMRBD v76.5 H6: caller-scoped key so one caller's Skip can
    # never skip another caller's thinking; locked so concurrent
    # record/lookup pairs cannot race the prune/pop.
    try:
        _key = (str(scope) + "|" + str(request_id)) if scope else str(request_id)
        now = time.time()
        with _BMRBD_THINK_SKIP_LOCK:
            for _rid in [k for k, v in list(_BMRBD_THINK_SKIP.items()) if now - v > _BMRBD_THINK_SKIP_TTL]:
                _BMRBD_THINK_SKIP.pop(_rid, None)
            while len(_BMRBD_THINK_SKIP) >= _BMRBD_THINK_SKIP_MAX:
                _BMRBD_THINK_SKIP.pop(next(iter(_BMRBD_THINK_SKIP)), None)
            _BMRBD_THINK_SKIP[_key] = now
    except Exception:
        pass


def _bmrbd_think_skip_requested(request_id, scope=None):
    # BMRBD v76.5 H6: scoped lookup first, bare-key fallback (a
    # Skip recorded before the scope stamp, or by a scope-less
    # caller, must still work).
    try:
        _rid = str(request_id or "")
        with _BMRBD_THINK_SKIP_LOCK:
            ts = None
            if scope:
                ts = _BMRBD_THINK_SKIP.get(str(scope) + "|" + _rid)
            if ts is None:
                ts = _BMRBD_THINK_SKIP.get(_rid)
        return bool(ts) and (time.time() - ts) <= _BMRBD_THINK_SKIP_TTL
    except Exception:
        return False


# P2 rules (CHATGPT-DEEP-STUDY.md Phase 2): web search triggers
# automatically for factual/current/long prompts and NOT for
# math/code/story/image/memory/simple questions.
_THINK_OLD_AUTO_KEYWORDS = (
    "/search ", "search online", "search the web", "on the web", "from online",
    "latest news", "current price", "deep research",
    "অনলাইন থেকে",
    "ইন্টারনেট থেকে",
    "গুগল সার্চ",
    "সার্চ করে",
    "লেটেস্ট খবর",
    "আজকের খবর",
    "ডিপ রিসার্চ",
)
_THINK_CURRENT_KEYWORDS = (
    # G1 (v76.5): "সাম্প্তিক" -> "সাম্প্রতিক", "আবহাওা" -> "আবহাওয়া"
    # (both were misspelled so neither ever matched); "yesterday" /
    # "গতকাল" added -- "Who won ... yesterday?" is a news question.
    "latest", "current", "today", "now", "news", "weather", "breaking",
    "yesterday", "2026", "2025", "price", "prices",
    "আজকের", "বর্তমান",
    "সাম্প্রতিক",
    "লেটেস্ট", "খবর", "গতকাল",
    "আবহাওয়া", "দাম",
)
_THINK_IMAGE_IDENTIFY = (
    "what is this", "what's this", "what is it", "identify", "recognise",
    "recognize", "what medicine", "osud", "kiser", "kisher",
    "এটা কি", "কিসের",
    "ওষুধ", "কোন ওষুধ",
)
_THINK_MATH_RE = re.compile(
    r"(\d\s*[+\-×÷*/^%]\s*\d)"
    r"|(\d\s*x\s*[+\-]\s*\d)|(\d+(\.\d+)?\s*(x|\*)\s*\d+)"
    r"|\b(sell|buy|cost|profit|loss|transport)\b.{0,40}\d"
    r"|\b(যোগ|বিযোগ|গুণ|ভাগ|"
    r"সমাধান|কত টাকা)\b",
    re.I,
)
_THINK_CODE_RE = re.compile(
    r"```|traceback|syntax error"
    r"|\b(write|fix|debug|run|create|make|generate|লিখ|ফিক্স)"
    r"\s+(a\s+|the\s+)?(python|javascript|typescript|java|code|script|program|html|css|sql|app)\b"
    r"|\b(python|javascript|typescript)\s+(code|script|program|function)\b"
    r"|\bfunction\s+\w+\s*\(|\bdef\s+\w+\s*\(",
    re.I,
)
_THINK_STORY_RE = re.compile(
    r"\b(write|tell|make|create|লিখ|বল)\s+"
    r"(a\s+|an\s+|the\s+)?(story|poem|joke|song|গল্প|কবিতা)\b",
    re.I,
)
_THINK_MEMORY_RE = re.compile(
    r"\b(remember|my name is|do you remember|মনে রাখ|আমার নাম)\b",
    re.I,
)


def _bmrbd_think_should_research(text, has_image=False):
    """P2 auto-trigger: True for factual/current/long prompts, False for
    math/code/story/memory/simple turns. Short plain questions (e.g.
    'What is the capital of Japan?') do NOT research; long detailed
    prompts (>=120 chars) DO; image + factual identification DOES."""
    # G1 (v76.5): keyword/current/image checks run BEFORE the <12-char
    # floor -- a short news ask ("খবর দাও", 8 chars) is still a news ask.
    # The floor still applies to short text with no trigger keyword.
    t = str(text or "").strip()
    if not t:
        return False
    low = t.lower()
    if low.startswith("/search") or any(k in low for k in _THINK_OLD_AUTO_KEYWORDS):
        return True
    if any(k in low for k in _THINK_CURRENT_KEYWORDS):
        return True
    if has_image and any(k in low for k in _THINK_IMAGE_IDENTIFY):
        return True
    if len(t) < 12:
        return False
    if _THINK_MATH_RE.search(low) or _THINK_CODE_RE.search(low) \
            or _THINK_STORY_RE.search(low) or _THINK_MEMORY_RE.search(low):
        return False
    return len(t) >= 120


def _bmrbd_think_enhance_image(b64_or_url):
    """Really decode + EXIF-rotate + contrast/sharpen-enhance one attached
    image. Returns (enhanced_b64_or_None, did_rotate, did_enhance, note).
    None when the input is a remote URL, undecodable, or PIL is
    unavailable — the caller then emits NO rotate/enhance claim."""
    try:
        raw = str(b64_or_url or "").strip()
        if raw.startswith("data:"):
            raw = raw.split(",", 1)[1] if "," in raw else ""
        if not raw or raw.startswith("http"):
            return None, False, False, "remote URL — nothing to enhance"
        img_bytes = base64.b64decode(raw)
        try:
            from PIL import Image, ImageOps, ImageEnhance
        except Exception:
            return None, False, False, "PIL unavailable"
        im = Image.open(io.BytesIO(img_bytes))
        did_rotate = False
        try:
            # Rotation is decided from the EXIF tag itself, NOT from
            # object identity: Pillow's exif_transpose may return a copy
            # even when nothing was transposed, which would be a false
            # "Rotated" claim. Only orientations 3/5/6/7/8 rotate.
            exif = im.getexif()
            orientation = exif.get(274) if exif else None
            im = ImageOps.exif_transpose(im)
            if orientation in (3, 5, 6, 7, 8):
                did_rotate = True
        except Exception:
            pass
        try:
            if max(im.size) > 1792:
                im.thumbnail((1792, 1792), Image.LANCZOS)
        except Exception:
            pass
        try:
            im = ImageEnhance.Contrast(im.convert("RGB")).enhance(1.15)
            im = ImageEnhance.Sharpness(im).enhance(1.25)
        except Exception:
            pass
        buf = io.BytesIO()
        im.save(buf, format="JPEG", quality=88)
        return base64.b64encode(buf.getvalue()).decode("ascii"), did_rotate, True, "%dx%d JPEG" % (im.size[0], im.size[1])
    except Exception:
        return None, False, False, "unreadable image"


def _bmrbd_think_last_user_text(parsed_body):
    """(text, has_image, last_user_msg_dict|None) for the newest user turn."""
    raw_list = parsed_body.get("messages") or parsed_body.get("input") or []
    if isinstance(raw_list, str):
        raw_list = [{"role": "user", "content": raw_list}]
    if not isinstance(raw_list, list):
        return "", False, None
    last = None
    for m in raw_list:
        if isinstance(m, dict) and m.get("role") == "user":
            last = m
    if last is None:
        return "", False, None
    c = last.get("content", "")
    text_parts = []
    has_image = bool(last.get("images"))
    if isinstance(c, str):
        text_parts.append(c)
        if "data:image/" in c:
            has_image = True
    elif isinstance(c, list):
        for b in c:
            if isinstance(b, dict):
                if b.get("type") in ("text", "input_text", "output_text"):
                    text_parts.append(str(b.get("text", "")))
                elif b.get("type") in ("image", "input_image", "image_url"):
                    has_image = True
    return "\n".join(text_parts).strip(), has_image, last


def _bmrbd_think_plan(text, has_image, body):
    """Ordered research steps to run — computed BEFORE any work so Skip
    can mark the not-yet-run ones 'skipped'."""
    plan = []
    low = (text or "").lower()
    if has_image:
        plan.append("image_inspect")
    m_url = re.search(r"https?://[^\s)'>]+", text or "")
    if m_url and any(ck in low for ck in ("clone", "php", "html", "script", "website",
                                          "ক্লোন", "পিএইচপি",
                                          "ওয়েবসাইট", "স্ক্রিপ্ট")):
        plan.append("fetch_url")
    # G1 (v76.5): the proxy path may already have grounded this turn
    # (do_POST _proxy_ground_with_web_search) -- do not search the same
    # query a second time; _bmrbd_think_research marks _think_research_done
    # in that case so the legacy injection does not run a third search.
    if _bmrbd_think_should_research(text, has_image) and "[LIVE ONLINE WEB SEARCH RESULTS" not in (text or ""):
        plan.append("web_search")
    return plan


def _bmrbd_think_enhance_message_images(last_msg):
    """Replace every attached image in last_msg with its PIL-enhanced
    bytes. Returns (enhanced_count, any_rotated, note)."""
    enhanced = 0
    any_rotated = False
    note = ""
    try:
        imgs = last_msg.get("images")
        if isinstance(imgs, list):
            for i, raw in enumerate(imgs):
                nb, rot, enh, n = _bmrbd_think_enhance_image(raw)
                if nb:
                    if isinstance(raw, str) and raw.startswith("data:"):
                        hdr = raw.split(",", 1)[0]
                        imgs[i] = hdr + "," + nb
                    else:
                        imgs[i] = nb
                    enhanced += 1
                    any_rotated = any_rotated or rot
                    note = n
        c = last_msg.get("content", "")
        if isinstance(c, str) and "data:image/" in c:
            def _rep(m):
                nb, rot, enh, n = _bmrbd_think_enhance_image(m.group(2))
                if nb:
                    return "data:" + m.group(1) + ";base64," + nb
                return m.group(0)
            new_c = re.sub(r"data:(image/[a-zA-Z0-9.+-]+);base64,([A-Za-z0-9+/=]+)", _rep, c)
            if new_c != c:
                last_msg["content"] = new_c
                enhanced += 1
    except Exception:
        pass
    return enhanced, any_rotated, note


def _bmrbd_think_research(parsed_body, stop_event):
    """Generator: runs the planned research steps in order, yielding
    ("think_step", {...}) events as each real action starts/completes.
    Injects web results into the prompt (legacy format) and sets
    parsed_body["_think_research_done"] so the legacy injection in
    build_unified_ollama_messages does not search twice. On Skip, the
    remaining planned steps are emitted as 'skipped' and a findings-only
    note is appended — the answer is then built ONLY from what was
    actually found, never invented."""
    request_id = str(parsed_body.get("request_id") or "")
    text, has_image, last_msg = _bmrbd_think_last_user_text(parsed_body)
    if last_msg is None or not text:
        return
    plan = _bmrbd_think_plan(text, has_image, parsed_body)
    if "[LIVE ONLINE WEB SEARCH RESULTS" in (text or ""):
        parsed_body["_think_research_done"] = True
    if not plan:
        return
    findings = 0
    skipped = False
    for pos, kind in enumerate(plan):
        if stop_event is not None and stop_event.is_set():
            return
        if request_id and _bmrbd_think_skip_requested(request_id, scope=parsed_body.get("_harness_scope")):
            skipped = True
            for k2 in plan[pos:]:
                yield ("think_step", _bmrbd_think_step(k2, k2, _BMRBD_THINK_STEP_LABELS[k2], "skipped"))
            break
        if kind == "image_inspect":
            yield ("think_step", _bmrbd_think_step("image_inspect", "image_inspect", _BMRBD_THINK_STEP_LABELS["image_inspect"], "active"))
            try:
                n_enh, any_rot, note = _bmrbd_think_enhance_message_images(last_msg)
            except Exception:
                n_enh, any_rot, note = 0, False, "enhancement failed"
            if n_enh:
                if any_rot:
                    label = "Rotated and enhanced image to inspect text"
                else:
                    label = "Enhanced image to inspect text"
                detail = "%d image(s) · %s" % (n_enh, note) if note else None
                findings += 1
            else:
                label = "Inspecting attached image"
                detail = note or "Could not enhance the image"
            yield ("think_step", _bmrbd_think_step("image_inspect", "image_inspect", label, "done", detail=detail))
        elif kind == "fetch_url":
            m_url = re.search(r"https?://[^\s)'>]+", text or "")
            url = m_url.group(0) if m_url else ""
            host = ""
            try:
                host = urllib.parse.urlparse(url).netloc
            except Exception:
                pass
            yield ("think_step", _bmrbd_think_step("fetch_url", "fetch_url", "Fetching %s" % (host or url), "active"))
            fetched = None
            try:
                fetched = fetch_live_website_for_clone(url)
            except Exception:
                fetched = None
            parsed_body["_think_fetch_done"] = True
            if fetched and fetched.get("html_excerpt"):
                last_msg["content"] = str(last_msg.get("content") or "") + (
                    "\n\n[LIVE SCRAPED WEBSITE STRUCTURE FOR `%s`]:\n"
                    "- Title: %s\n"
                    "- Headings: %s\n"
                    "- Navigation: %s\n"
                    "- Color Palette: %s\n"
                    "- HTML Excerpt:\n```html\n%s\n```\n"
                    "Build a complete, self-contained, production-ready clone (e.g. ```index.php or ```index.html + ```styles.css + ```app.js) so the server packages it into a downloadable `.zip`!"
                    % (fetched.get("url") or url, fetched.get("title"),
                       ", ".join(fetched.get("headings") or []),
                       ", ".join(fetched.get("nav_items") or []),
                       ", ".join(fetched.get("colors") or []),
                       (fetched.get("html_excerpt") or "")[:2800]))
                findings += 1
                yield ("think_step", _bmrbd_think_step("fetch_url", "fetch_url", "Fetched %s to read the page" % (host or url), "done", detail=fetched.get("title")))
            else:
                yield ("think_step", _bmrbd_think_step("fetch_url", "fetch_url", "Fetching %s" % (host or url), "done", detail="Page could not be read"))
        elif kind == "web_search":
            yield ("think_step", _bmrbd_think_step("web_search", "web_search", _BMRBD_THINK_STEP_LABELS["web_search"], "active"))
            search_q = re.sub(r"^/search\s+", "", text, flags=re.I).strip()[:180]
            try:
                hits = fetch_live_web_search_results(search_q, max_results=5)
            except Exception:
                hits = []
            parsed_body["_think_research_done"] = True
            if hits:
                parsed_body["_crawled_sites"] = [{"title": h["title"], "url": h["url"]} for h in hits]
                web_block = "\n".join("- [%s](%s): %s" % (h["title"], h["url"], h["snippet"]) for h in hits)
                last_msg["content"] = (
                    "%s\n\n[LIVE ONLINE WEB SEARCH RESULTS (Ground your answer in these verified facts and include markdown links)]:\n%s"
                    % (text, web_block))
                findings += 1
                yield ("think_step", _bmrbd_think_step("web_search", "web_search", "Searching %d websites" % len(hits), "done", count=len(hits)))
            else:
                # G1 (v76.5): never silently answer ungrounded -- tell the
                # model the search came back empty so it says so instead of
                # inventing facts or sources.
                last_msg["content"] = str(last_msg.get("content") or "") + (
                    "\n\n[Web search returned no results for this question — "
                    "answer from your own knowledge and say plainly when you are "
                    "unsure; do not invent facts or sources.]")
                yield ("think_step", _bmrbd_think_step("web_search", "web_search", "Searching the web", "done", count=0, detail="No results found"))
    if skipped:
        if findings:
            note = ("\n\n[Research was skipped by the user — answer ONLY from the findings above. "
                    "If the research did not return a fact, say so plainly instead of guessing.]")
        else:
            note = ("\n\n[Research was skipped by the user before it ran — answer from your own "
                    "knowledge and say plainly when you are unsure; never invent a fact.]")
        last_msg["content"] = str(last_msg.get("content") or "") + note

def _harness_news_locale(q_clean):
    """Google News locale for a query: Bangla script asks in bn/BD,
    everything else in en-US. The old code always asked en-US, so Bangla
    news queries ("আজকের খবর") never got Bangla headlines back.
    Pure — unit-tested."""
    try:
        if re.search(r"[\u0980-\u09FF]", str(q_clean or "")):
            return "&hl=bn&gl=BD&ceid=BD:bn"
    except Exception:
        pass
    return "&hl=en-US&gl=US&ceid=US:en"


def fetch_live_web_search_results(query: str, max_results: int = 5) -> list:
    """
    v43 Deep Web Search & Multi-Page Crawler (Enters & reads actual websites in parallel like ChatGPT Browsing!):
      1. Direct URL extraction if the user pasted any `https://...` link
      2. DuckDuckGo HTML Search (with `urllib.parse.unquote` fixed!)
      3. Google News RSS Search (for breaking news & current events)
      4. Wikipedia REST Search
      5. Parallel `ThreadPoolExecutor` deep page crawl of top results
    """
    q_clean = str(query or "").strip()
    if not q_clean:
        return []
    results = []
    seen_urls = set()

    # 0. Direct URLs in prompt
    for direct_u in re.findall(r"https?://[^\s<>)]+", q_clean):
        if direct_u not in seen_urls:
            seen_urls.add(direct_u)
            results.append({"title": direct_u, "url": direct_u, "snippet": "Direct URL requested by user."})

    # 1. DuckDuckGo HTML Search
    try:
        ddg_url = "https://html.duckduckgo.com/html/?q=" + urllib.parse.quote(q_clean)
        req = urllib.request.Request(ddg_url, headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/131.0.0.0"})
        with urllib.request.urlopen(req, timeout=6.0) as r:
            html_s = r.read().decode("utf-8", errors="ignore")
            for m in re.finditer(r'<a[^>]+class="result__a"[^>]+href="([^"]+)"[^>]*>([\s\S]*?)</a>[\s\S]*?<a[^>]+class="result__snippet"[^>]*>([\s\S]*?)</a>', html_s):
                raw_href, raw_title, raw_snip = m.group(1), m.group(2), m.group(3)
                if "uddg=" in raw_href:
                    m_u = re.search(r"uddg=([^&]+)", raw_href)
                    if m_u:
                        raw_href = urllib.parse.unquote(m_u.group(1))
                title = re.sub(r"<[^>]+>", "", raw_title).strip()
                snip = re.sub(r"<[^>]+>", "", raw_snip).strip()
                if title and raw_href.startswith("http") and raw_href not in seen_urls:
                    seen_urls.add(raw_href)
                    results.append({"title": title, "url": raw_href, "snippet": snip})
                if len(results) >= max_results:
                    break
    except Exception as _ddg_e:
        try:
            diag_log("WARN", "DuckDuckGo search failed (query=%r): %s" % (q_clean[:80], _ddg_e))
        except Exception:
            pass

    # 2. Google News RSS Supplement
    if len(results) < max_results:
        try:
            gn_url = "https://news.google.com/rss/search?q=" + urllib.parse.quote(q_clean) + _harness_news_locale(q_clean)
            req_g = urllib.request.Request(gn_url, headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(req_g, timeout=5.0) as rg:
                xml_s = rg.read().decode("utf-8", errors="ignore")
                for m_it in re.finditer(r"<item>[\s\S]*?<title>([\s\S]*?)</title>[\s\S]*?<link>([\s\S]*?)</link>[\s\S]*?<pubDate>([\s\S]*?)</pubDate>[\s\S]*?(?:<description>([\s\S]*?)</description>)?[\s\S]*?</item>", xml_s):
                    t_g = re.sub(r"<!\[CDATA\[|\]\]>", "", m_it.group(1)).strip()
                    u_g = m_it.group(2).strip()
                    d_g = m_it.group(3).strip()
                    if t_g and u_g not in seen_urls:
                        seen_urls.add(u_g)
                        _d_g = re.sub(r"<!\[CDATA\[|\]\]>", "", (m_it.group(4) or "")).strip()
                        _d_g = re.sub(r"<[^>]+>", "", _d_g).strip()
                        _snip_g = (_d_g + " | Published: %s" % d_g) if _d_g else ("Published: %s" % d_g)
                        results.append({"title": t_g, "url": u_g, "snippet": _snip_g})
                    if len(results) >= max_results:
                        break
        except Exception:
            pass

    # 3. Wikipedia Search Supplement
    if len(results) < max_results:
        try:
            wiki_url = f"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={urllib.parse.quote(q_clean)}&utf8=&format=json&srlimit=3"
            req_w = urllib.request.Request(wiki_url, headers={"User-Agent": "BMRBDAi/43.0"})
            with urllib.request.urlopen(req_w, timeout=4.0) as rw:
                wj = json.loads(rw.read().decode("utf-8", errors="ignore"))
                for item in (wj.get("query", {}).get("search") or []):
                    t_w = item.get("title", "")
                    s_w = re.sub(r"<[^>]+>", "", item.get("snippet", "")).strip()
                    u_w = f"https://en.wikipedia.org/wiki/{urllib.parse.quote(t_w.replace(' ', '_'))}"
                    if t_w and u_w not in seen_urls:
                        seen_urls.add(u_w)
                        results.append({"title": f"{t_w} — Wikipedia", "url": u_w, "snippet": s_w})
        except Exception:
            pass

    # 4. Parallel Deep Webpage Crawl (Enter top 4 websites and extract full text!)
    top_to_crawl = results[:min(4, len(results))]
    if top_to_crawl:
        try:
            with ThreadPoolExecutor(max_workers=4) as ex:
                crawled_Bodies = list(ex.map(lambda item: _crawl_single_webpage_text(item["url"]), top_to_crawl))
            for idx_c, body_txt in enumerate(crawled_Bodies):
                if body_txt and len(body_txt) > 80:
                    results[idx_c]["snippet"] = f"{results[idx_c].get('snippet', '')} | Full Page Extract: {body_txt[:1400]}"
        except Exception:
            pass

    return results[:max_results]

