def _append_capped_log(file_path: Path, line_str: str, max_bytes: int = 3 * 1024 * 1024):
    try:
        file_path.parent.mkdir(parents=True, exist_ok=True)
        if file_path.exists() and file_path.stat().st_size > max_bytes:
            tail_bytes = file_path.read_bytes()[-(max_bytes // 2):]
            file_path.write_bytes(tail_bytes)
        with open(file_path, "a", encoding="utf-8") as f:
            f.write(line_str + "\n")
    except Exception:
        pass

def diag_log(level, msg):
    now = datetime.now()
    ts = now.strftime("%Y-%m-%d %H:%M:%S")
    hour_slot = now.strftime("log_%Y-%m-%d_%H-00.log")
    line = f"[{ts}] [{level}] {msg}"
    with DIAG_LOCK:
        DIAG_RING.append(line)
        if len(DIAG_RING) > 500:
            DIAG_RING.pop(0)
        _append_capped_log(DIAG_LOG_FILE, line, 4 * 1024 * 1024)
        if Path("/kaggle/working").exists():
            _append_capped_log(KAGGLE_DIAG_FILE, line, 4 * 1024 * 1024)
        _append_capped_log(LOG_HISTORY_DIR / hour_slot, line, 2 * 1024 * 1024)
        if level in ("ERROR", "WARN"):
            _append_capped_log(LOG_HISTORY_DIR / "errors_only.log", line, 2 * 1024 * 1024)
        low_m = msg.lower()
        if "/v1/messages" in low_m or "claude" in low_m or "anthropic" in low_m:
            _append_capped_log(LOG_HISTORY_DIR / "client_claude_code.log", line, 2 * 1024 * 1024)
        if "/v1/chat/completions" in low_m or "opencode" in low_m:
            _append_capped_log(LOG_HISTORY_DIR / "client_opencode.log", line, 2 * 1024 * 1024)
        if "/v1/responses" in low_m or "codex" in low_m:
            _append_capped_log(LOG_HISTORY_DIR / "client_codex.log", line, 2 * 1024 * 1024)

# BMRBD v61.14 P6: seed the ring once at import so it is NEVER empty on a
# fresh/quiet kernel. diag_log() is otherwise only called from stream /
# error paths, so a kernel with no completed chat yet served
# live_logs == "" and the admin panel never left "Connecting...". One
# honest boot line; it also lands in the persisted diagnostic file.
diag_log("INFO", "BMRBD bridge diagnostic log started — live log ring initialised.")

def list_log_history_files():
    items = [{
        "id": "full",
        "name": "Full Combined Server & GPU Report",
        "size_kb": round(DIAG_LOG_FILE.stat().st_size / 1024, 1) if DIAG_LOG_FILE.exists() else 1.0,
        "updated": datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    }]
    try:
        for p in sorted(LOG_HISTORY_DIR.glob("*.log"), key=lambda x: x.stat().st_mtime, reverse=True):
            st = p.stat()
            items.append({
                "id": p.name,
                "name": p.name,
                "size_kb": round(max(0.1, st.st_size / 1024), 1),
                "updated": datetime.fromtimestamp(st.st_mtime).strftime("%Y-%m-%d %H:%M:%S")
            })
    except Exception:
        pass
    return items

def build_full_diagnostic_report():
    lines = [
        "================================================================================",
        f"STRATA / KAGGLE AI SERVER v61.1 (KEYFRAME+KEN BURNS VIDEO, REMOTE-HF IMAGE ENGINES, OLLAMA CHAT) — FULL DIAGNOSTIC & ERROR LOG REPORT",
        f"Generated At : {datetime.now().isoformat()}",
        f"Active Model : {DEFAULT_MODEL} | Context: {NUM_CTX} (launch; native 262144, YaRN 1M, effective unlimited via vault+compaction) | Active Streams: {METRICS['active_streams']}",
        "================================================================================",
        ""
    ]
    lines.append("--- [0] SERVER BOOT, CACHE & MODEL SETUP LOG (/tmp/cell3_startup.log) ---")
    try:
        if Path("/tmp/cell3_startup.log").exists():
            lines.append(Path("/tmp/cell3_startup.log").read_text(encoding="utf-8", errors="ignore")[-8000:])
        else:
            lines.append("(Startup log initialized)")
    except Exception as e:
        lines.append(f"startup log note: {e}")
    lines.append("")
    try:
        smi = json.dumps(get_hardware_stats(), indent=2)
        lines.append("--- [1] NVIDIA-SMI GPU STATUS ---")
        lines.append(smi.strip())
    except Exception as e:
        lines.append(f"cpu-ram-telemetry error: {e}")
    lines.append("")
    try:
        ps_raw = urllib.request.urlopen(f"{OLLAMA_URL}/api/ps", timeout=3).read().decode("utf-8", errors="ignore")
        lines.append("--- [2] OLLAMA /API/PS VRAM RESIDENCY ---")
        lines.append(ps_raw.strip())
    except Exception as e:
        lines.append(f"ollama /api/ps error: {e}")
    lines.append("")
    lines.append("--- [3] BRIDGE STRUCTURED DIAGNOSTIC & ERROR EVENTS (OLD -> LATEST) ---")
    with DIAG_LOCK:
        lines.extend(DIAG_RING[-250:] if DIAG_RING else ["No events recorded yet."])
    lines.append("")
    for log_path, title in [("/tmp/ollama-server.log", "OLLAMA SERVER LOG TAIL"), ("/tmp/bridge.log", "BRIDGE STDOUT/STDERR LOG TAIL")]:
        lines.append(f"--- [4] {title} ({log_path}) ---")
        try:
            if os.path.exists(log_path):
                with open(log_path, "r", encoding="utf-8", errors="ignore") as lf:
                    tail_lines = lf.readlines()[-120:]
                    lines.extend([x.rstrip("\r\n") for x in tail_lines])
            else:
                lines.append("(Log file not created yet)")
        except Exception as e:
            lines.append(f"Error reading {log_path}: {e}")
        lines.append("")
    return "\n".join(lines)

