def log_req(path, model_name, note="standard", prompt_toks=0, output_toks=0, dur_s=1.2):
    try:
        _RECENT_REQUESTS_LOG.append({
            "time": time.strftime("%H:%M:%S"),
            "time_iso": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),  # BMRBD v61.15 WC: ISO UTC so the admin panel can render Dhaka (+06)
            "path": str(path),
            "model": str(model_name),
            "note": str(note),
            "tokens": int(prompt_toks) + int(output_toks),
            "speed": METRICS.get("last_tok_per_sec", 0.0)
        })
        if len(_RECENT_REQUESTS_LOG) > 60:
            del _RECENT_REQUESTS_LOG[:-60]
    except Exception:
        pass
    METRICS["total_requests"] += 1
    METRICS["prompt_tokens_total"] += prompt_toks
    METRICS["output_tokens_total"] += output_toks
    # BMRBD v61.16 SETTINGS-A: daily counters for Settings > Account >
    # Usage and limits (UTC date; in-memory, resets on restart).
    try:
        _sa_u = _sa_usage_today()
        _sa_u["requests"] += 1
        _sa_u["prompt_tokens"] += int(prompt_toks or 0)
        _sa_u["output_tokens"] += int(output_toks or 0)
    except Exception:
        pass
    req_id = "req_" + uuid.uuid4().hex[:12]
    # BMRBD v61.20 UI-FIX (2026-11-17): return the id so the proxy can
    # update this row with REAL completion tokens + tok/s when the stream
    # finishes (rows used to stay at the request-start values forever).
    _RECENT_REQUESTS_LOG[-1]["req_id"] = req_id
    RECENT_REQUESTS.append({
        "id": req_id,
        "time": datetime.now().strftime("%H:%M:%S"),
        "started_at": int(time.time()),
        "path": path,
        "model": model_name,
        "note": note,
        "state": "completed",
        "finish": "stop",
        "http_status": 200,
        "prompt_tokens": prompt_toks,
        "reused": 0,
        "prompt_ms": int(dur_s * 150),
        "output_tokens": output_toks,
        "duration_s": round(dur_s, 2),
        "wallclock_s": round(dur_s, 2),
        "decode_tok_s": METRICS["last_tok_per_sec"],
        "hit_rate": 100,
        "pcie_share": 0,
        "projection": "GPU",
    })
    if len(RECENT_REQUESTS) > 50:
        RECENT_REQUESTS.pop(0)
    return req_id

_B3_CREDITED_REQ_IDS = set()  # B3-B4: req_ids already credited to Usage (idempotent reconcile)

def _bmrbd_update_req_completion(req_id, output_tokens, dur_s, tok_s):
    """BMRBD v61.20 UI-FIX (2026-11-17): after a proxied stream finishes,
    rewrite the request-start log rows with the REAL completion tokens,
    wall-clock duration and measured tok/s so the admin request stream
    never shows a finished request as "0 tok/s" forever.
    B3-B4: log_req() records output_tokens=0 at request start, and this
    reconcile was the ONLY place the real count landed — but it only
    rewrote the log rows, never the Usage counters, so every streamed
    chat contributed 0 output tokens to /api/usage (live: 25 requests,
    93514 prompt tokens, 72 output tokens). Credit the real count here,
    once per req_id (guarded set: the two call sites each run once per
    request, but a double reconcile must never double-count).
    """
    try:
        _ot = int(output_tokens or 0)
        if _ot > 0 and str(req_id) not in _B3_CREDITED_REQ_IDS:
            _B3_CREDITED_REQ_IDS.add(str(req_id))
            if len(_B3_CREDITED_REQ_IDS) > 5000:
                _B3_CREDITED_REQ_IDS.clear()
            try:
                _sa_usage_today()["output_tokens"] += _ot
            except Exception:
                pass
            try:
                METRICS["output_tokens_total"] = int(METRICS.get("output_tokens_total") or 0) + _ot
            except Exception:
                pass
    except Exception:
        pass
    try:
        for _row in RECENT_REQUESTS:
            if isinstance(_row, dict) and str(_row.get("id")) == str(req_id):
                _row["output_tokens"] = int(output_tokens)
                _row["duration_s"] = round(float(dur_s), 2)
                _row["wallclock_s"] = round(float(dur_s), 2)
                _row["decode_tok_s"] = round(float(tok_s), 2)
                _row["state"] = "completed"
                break
    except Exception:
        pass
    try:
        for _row in _RECENT_REQUESTS_LOG:
            if isinstance(_row, dict) and str(_row.get("req_id")) == str(req_id):
                _row["speed"] = round(float(tok_s), 2)
                try:
                    _row["tokens"] = int(_row.get("tokens") or 0) + int(output_tokens)
                except Exception:
                    pass
                break
    except Exception:
        pass


_HW_STATS_CACHE = {"data": None, "ts": 0.0, "disk_r_bytes": 0, "disk_w_bytes": 0, "disk_ts": 0.0}
_HW_STATS_LOCK = threading.Lock()
_SESSION_COMPACTION_STATE = {}
_SESSION_LOCK = threading.Lock()

def _read_disk_io_mb_per_sec():
    """Reads `/proc/diskstats` to compute real live disk read/write MB/s for Strata Monitor."""
    now = time.time()
    r_sectors, w_sectors = 0, 0
    try:
        with open("/proc/diskstats", "r") as df:
            for ln in df:
                parts = ln.split()
                if len(parts) >= 10:
                    dev = parts[2]
                    if re.match(r"^(?:sd[a-z]+|nvme\d+n\d+|vd[a-z]+|xvd[a-z]+|loop0)$", dev):
                        r_sectors += int(parts[5])
                        w_sectors += int(parts[9])
    except Exception:
        return 0.0, 0.0
    r_bytes = r_sectors * 512
    w_bytes = w_sectors * 512
    prev_ts = _HW_STATS_CACHE.get("disk_ts") or 0.0
    if prev_ts <= 0.0 or (now - prev_ts) <= 0.05:
        _HW_STATS_CACHE["disk_r_bytes"] = r_bytes
        _HW_STATS_CACHE["disk_w_bytes"] = w_bytes
        _HW_STATS_CACHE["disk_ts"] = now
        return 0.0, 0.0
    dt = max(0.1, now - prev_ts)
    dr_mb = max(0.0, round((r_bytes - _HW_STATS_CACHE.get("disk_r_bytes", r_bytes)) / (1024 * 1024 * dt), 2))
    dw_mb = max(0.0, round((w_bytes - _HW_STATS_CACHE.get("disk_w_bytes", w_bytes)) / (1024 * 1024 * dt), 2))
    _HW_STATS_CACHE["disk_r_bytes"] = r_bytes
    _HW_STATS_CACHE["disk_w_bytes"] = w_bytes
    _HW_STATS_CACHE["disk_ts"] = now
    return dr_mb, dw_mb


# ── v51 REAL KAGGLE 30H QUOTA, WEEKLY RESET COUNTDOWN & 6-ACCOUNT ROTATION TELEMETRY ──
_QUOTA_BOOT_TS = int(time.time())
_INSTANCE_BOOT_ID = os.environ.get('BMRBD_INSTANCE_ID') or ('node_' + uuid.uuid4().hex[:10])
try:
    with open("/proc/uptime", "r") as _uf:
        _QUOTA_BOOT_TS = int(time.time() - float(_uf.read().split()[0]))
except Exception:
    pass

def get_kaggle_quota_and_rotation_status() -> dict:
    """
    Kaggle 30h quota status. Values come from rotator-written state
    (`/tmp/kaggle_quota_state.json`, written by POST /api/quota/update) or the
    KAGGLE_QUOTA_* env vars; anything else is an UNCALIBRATED ESTIMATE and is
    labelled as such. There is NO automatic account rotation: handoff is
    log-only and manual (see the guardian in Cell 3).
    """
    now_ts = time.time()
    try:
        with open("/proc/uptime", "r") as uf:
            session_elapsed_sec = float(uf.read().split()[0])
    except Exception:
        session_elapsed_sec = max(1.0, now_ts - _QUOTA_BOOT_TS)

    # Read initial quota values passed from Cell 1 / environment (or `/tmp/kaggle_quota_state.json`)
    # v61.1: no hardcoded quota seeds. With no rotator state these are
    # uncalibrated estimates (flagged "estimated": true below).
    init_avail_hrs = float(os.environ.get("KAGGLE_QUOTA_AVAILABLE_HOURS") or 30.0)
    init_used_hrs = float(os.environ.get("KAGGLE_QUOTA_USED_HOURS") or 0.0)
    init_reset_hrs = float(os.environ.get("KAGGLE_QUOTA_RESET_HOURS") or 168.0)
    handoff_mins = float(os.environ.get("AUTO_ROTATE_TRIGGER_MINUTES") or 35.0)
    active_acct = str(os.environ.get("ACTIVE_KAGGLE_ACCOUNT_NAME") or os.environ.get("KAGGLE_USERNAME") or "Account #1 (marupibneyalid)")
    total_accts = int(os.environ.get("TOTAL_ROTATION_ACCOUNTS") or 6)

    if Path("/tmp/kaggle_quota_state.json").is_file():
        try:
            q_saved = json.loads(Path("/tmp/kaggle_quota_state.json").read_text(encoding="utf-8"))
            init_avail_hrs = float(q_saved.get("available_hours", init_avail_hrs))
            init_used_hrs = float(q_saved.get("used_hours", init_used_hrs))
            init_reset_hrs = float(q_saved.get("reset_hours", init_reset_hrs))
            active_acct = str(q_saved.get("active_account", active_acct))
        except Exception:
            pass

    elapsed_hrs = session_elapsed_sec / 3600.0
    rem_quota_hrs = max(0.0, init_avail_hrs - elapsed_hrs)
    cur_used_hrs = min(30.0, init_used_hrs + elapsed_hrs)
    rem_reset_hrs = max(0.0, init_reset_hrs - elapsed_hrs)
    # Single Kaggle session max is 12 hours (720 mins); safe handoff is at 11h 25m (11.42h)
    rem_session_hrs = max(0.0, 12.0 - elapsed_hrs)
    effective_rem_hrs = min(rem_quota_hrs, rem_session_hrs)
    effective_rem_mins = round(effective_rem_hrs * 60.0, 1)

    calibrated = Path("/tmp/kaggle_quota_state.json").is_file()
    return {
        "instance_id": _INSTANCE_BOOT_ID,
        "active_account": active_acct,
        "total_accounts_in_pool": total_accts,
        "estimated": not calibrated,
        # BMRBD v61.15a WC (A9): these numbers are the TRACKED ESTIMATE
        # (rotator state file, or uncalibrated without it) — never a
        # Kaggle-measured value. Kernel-live values, when Kaggle provides
        # them, come ONLY from GET /api/admin/quota-env.
        "source": "tracked-estimate",
        "calibration": ("rotator-written state (/tmp/kaggle_quota_state.json)" if calibrated
                        else "uncalibrated estimate — calibrate via POST /api/quota/update or /admin/rotator"),
        "auto_rotation": False,
        "handoff_mode": "log-only (manual — no automatic account switching)",
        "session_elapsed_sec": round(session_elapsed_sec, 1),
        "session_remaining_hours": round(rem_session_hrs, 2),
        "quota_total_hours": 30.0,
        "quota_used_hours": round(cur_used_hrs, 2),
        "quota_available_hours": round(rem_quota_hrs, 2),
        "quota_available_sec": int(rem_quota_hrs * 3600),
        "quota_reset_in_hours": round(rem_reset_hrs, 2),
        "quota_reset_in_sec": int(rem_reset_hrs * 3600),
        "effective_remaining_minutes": effective_rem_mins,
        "handoff_trigger_minutes": handoff_mins,
        "handoff_imminent": bool(effective_rem_mins <= handoff_mins),
    }

# ── BMRBD v76.1 QUOTA — REPO-SOURCED (Marup's order, 2026-11-19) ──────
# The admin dashboard quota comes DIRECTLY from the GitHub controller
# repo — never from a live Kaggle request and never from the tracked
# elapsed-time estimate (which read ~3.38h while live Kaggle said
# 1.02h on 2026-11-19). The controller workflow queries the live
# Kaggle quota and writes it to the controller repo; a sync step
# refreshes the local state file below (default
# /tmp/kaggle_quota_repo_state.json, override with
# KAGGLE_QUOTA_REPO_STATE_FILE). The bridge ONLY reads that file.
# Contract for the file (written by the controller workflow):
#   {"active_account": "Account #2 (...)", "total_hours": 30.0,
#    "used_hours": 28.98, "available_hours": 1.02, "reset_hours": 41.5,
#    "updated_at": "2026-11-19T07:22:00Z"}   (or "updated_ts": epoch)
# Missing file / bad JSON / missing fields / numbers out of range /
# older than KAGGLE_QUOTA_REPO_MAX_AGE_S (default 3600 s) -> fall back
# to the rotator-written state file (see the nested _rot_fallback() in
# get_repo_quota_status(), v76.4 Q1); only when THAT is missing/too
# old/invalid too does the status become "unknown" with every hour
# figure None — never a fabricated number.
_KAGGLE_QUOTA_REPO_STATE_FILE = os.environ.get(
    "KAGGLE_QUOTA_REPO_STATE_FILE") or "/tmp/kaggle_quota_repo_state.json"
_KAGGLE_QUOTA_REPO_MAX_AGE_S = float(os.environ.get("KAGGLE_QUOTA_REPO_MAX_AGE_S") or 3600.0)
# BMRBD v76.4 Q1: when the repo state is unusable the reader falls back
# to the rotator-written state file (/tmp/kaggle_quota_state.json,
# written by POST /api/quota/update; the same file
# get_kaggle_quota_and_rotation_status() reads) — see the nested
# _rot_fallback() in get_repo_quota_status(). A rotator file older
# than KAGGLE_QUOTA_ROTATOR_MAX_AGE_S (default 48h) is too stale to
# trust as a fallback. Path override: KAGGLE_QUOTA_ROTATOR_STATE_FILE.


def _repo_quota_num(v):
    """A quota number from the repo state file, or None if it is not a
    finite, non-negative number. Anything else is invalid state."""
    try:
        f = float(v)
    except Exception:
        return None
    if f != f or f in (float("inf"), float("-inf")) or f < 0:
        return None
    return f


def _validate_repo_quota_payload(payload, now_ts=None):
    """Validate a POST /api/admin/quota-repo payload (v76.2 Bug 6).

    Returns (state, None) on success — state is the NORMALISED payload
    (floats rounded to 2dp, updated_at as ISO-8601 UTC "Z", updated_ts as
    epoch, source defaulted) — or (None, reason) on failure. A rejected
    payload must NEVER be stored: the dashboard keeps showing "unknown"
    rather than a wrong number. Reads/writes nothing and touches no
    network; pure validation only.
    """
    if now_ts is None:
        now_ts = time.time()
    try:
        _now = float(now_ts)
    except Exception:
        return None, "invalid now_ts"
    if not isinstance(payload, dict):
        return None, "payload must be a JSON object"
    for _f in ("active_account", "total_hours", "used_hours",
               "available_hours", "reset_hours"):
        if payload.get(_f) is None:
            return None, "missing required field: %s" % _f
    _acct = payload.get("active_account")
    if not isinstance(_acct, str) or not _acct.strip():
        return None, "active_account must be a non-empty string"

    def _num(_v):
        # float(True) == 1.0, so booleans must be rejected explicitly.
        if isinstance(_v, bool):
            return None
        try:
            _f = float(_v)
        except Exception:
            return None
        if _f != _f or _f in (float("inf"), float("-inf")):
            return None
        return _f

    _total = _num(payload.get("total_hours"))
    _used = _num(payload.get("used_hours"))
    _avail = _num(payload.get("available_hours"))
    _reset = _num(payload.get("reset_hours"))
    if _total is None or _used is None or _avail is None or _reset is None:
        return None, "quota hours must be finite numbers"
    if _total <= 0 or _total > 100.0:
        return None, "total_hours out of range (0, 100]"
    if _used < 0 or _used > _total:
        return None, "used_hours out of range"
    if _avail < 0 or _avail > _total:
        return None, "available_hours out of range"
    if abs((_used + _avail) - _total) > 0.1:
        return None, "used_hours + available_hours does not match total_hours"
    if _reset < 0 or _reset > 168.0:
        return None, "reset_hours out of range (0, 168]"
    _upd_ts = None
    if payload.get("updated_ts") is not None:
        if isinstance(payload.get("updated_ts"), bool):
            return None, "updated_ts must be a number"
        try:
            _upd_ts = float(payload.get("updated_ts"))
        except Exception:
            return None, "updated_ts must be a number"
        if _upd_ts != _upd_ts or _upd_ts in (float("inf"), float("-inf")):
            return None, "updated_ts must be finite"
    elif payload.get("updated_at") is not None:
        try:
            _upd_ts = float(time.mktime(time.strptime(
                str(payload.get("updated_at"))[:19], "%Y-%m-%dT%H:%M:%S")) - time.timezone)
        except Exception:
            return None, "updated_at must be an ISO-8601 UTC timestamp"
    else:
        return None, "missing required field: updated_at"
    if _upd_ts > _now + 300.0:
        return None, "updated_at is in the future"
    if _now - _upd_ts > 3600.0:
        return None, "updated_at is stale (older than 3600s)"
    _source = payload.get("source") or "github-controller-repo"
    if not isinstance(_source, str):
        return None, "source must be a string"
    _state = {
        "active_account": _acct.strip(),
        "total_hours": round(_total, 2),
        "used_hours": round(_used, 2),
        "available_hours": round(_avail, 2),
        "reset_hours": round(_reset, 2),
        "updated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(_upd_ts)),
        "updated_ts": _upd_ts,
        "source": _source,
    }
    return _state, None


def get_repo_quota_status(max_age_s=None):
    """Repo-sourced Kaggle quota for the admin dashboard (v76.1).

    Reads the controller-repo-synced state file — no Kaggle
    request. Returns the quota numbers with
    source 'github-controller-repo', the active account (node), and
    the file's last-updated timestamp + age, so the dashboard can
    never show a silently stale number. When the repo state is
    missing/stale/invalid, falls back to the rotator-written state
    file (v76.4 Q1 — same numbers /api/quota/status uses), returned
    with source 'local-rotator-state' and estimated=True so the UI
    can label it an estimate. Only when BOTH files are unusable does
    it return status 'unknown' with all hour figures None.
    Session timing (elapsed/remaining) is measured locally from
    /proc/uptime and is included only as session info, never as quota.
    """
    if max_age_s is None:
        max_age_s = _KAGGLE_QUOTA_REPO_MAX_AGE_S
    now_ts = time.time()
    try:
        with open("/proc/uptime", "r") as _uf:
            _session_elapsed_sec = float(_uf.read().split()[0])
    except Exception:
        _session_elapsed_sec = max(1.0, now_ts - _QUOTA_BOOT_TS)
    _session_remaining_h = round(max(0.0, 12.0 - _session_elapsed_sec / 3600.0), 2)
    _res = {"ok": False, "status": "unknown", "source": "github-controller-repo",
            "active_account": None, "quota_total_hours": 30.0,
            "quota_used_hours": None, "quota_available_hours": None,
            "quota_available_sec": None, "quota_reset_in_hours": None,
            "quota_reset_in_sec": None, "effective_remaining_minutes": None,
            "handoff_imminent": None, "last_updated": None,
            "last_updated_age_sec": None, "estimated": None,
            "session_elapsed_sec": round(_session_elapsed_sec, 1),
            "session_remaining_hours": _session_remaining_h}
    def _rot_fallback():
        """BMRBD v76.4 Q1: numeric fallback when the repo state is
        missing/stale/invalid — nested here (not a module-level helper)
        so AST-extracted callers of get_repo_quota_status keep working
        standalone. Reads the rotator-written state file
        (/tmp/kaggle_quota_state.json, written by POST /api/quota/update)
        and applies the SAME elapsed-time adjustment as
        get_kaggle_quota_and_rotation_status(). Returns _res updated
        with ok=True, source 'local-rotator-state', estimated=True — or
        _res unchanged (unknown) when the rotator file is missing, too
        old, or invalid. Pure file read; no network, no Kaggle.
        """
        try:
            _rp = os.environ.get("KAGGLE_QUOTA_ROTATOR_STATE_FILE") or "/tmp/kaggle_quota_state.json"
            _rmax = float(os.environ.get("KAGGLE_QUOTA_ROTATOR_MAX_AGE_S") or 48 * 3600.0)
            _rp_p = Path(_rp)
            _rst = json.loads(_rp_p.read_text(encoding="utf-8"))
            if not isinstance(_rst, dict):
                return _res
            _rmtime = _rp_p.stat().st_mtime
            if now_ts - _rmtime > _rmax:
                return _res
            _avail0 = _repo_quota_num(_rst.get("available_hours"))
            _used0 = _repo_quota_num(_rst.get("used_hours"))
            _reset0 = _repo_quota_num(_rst.get("reset_hours"))
            if _avail0 is None or _used0 is None or _reset0 is None:
                return _res
            _total0 = 30.0
            if _avail0 > _total0 or _used0 > _total0:
                return _res
            _elapsed_h = float(_session_elapsed_sec) / 3600.0
            _avail_r = max(0.0, _avail0 - _elapsed_h)
            _used_r = min(_total0, _used0 + _elapsed_h)
            _reset_r = max(0.0, _reset0 - _elapsed_h)
            _updated_ts_r = _rmtime
            if _rst.get("updated_at"):
                try:
                    _ts_r = float(time.mktime(time.strptime(str(_rst.get("updated_at"))[:19], "%Y-%m-%dT%H:%M:%S")) - time.timezone)
                    if _ts_r > 0:
                        _updated_ts_r = _ts_r
                except Exception:
                    pass
            try:
                _handoff_mins_r = float(os.environ.get("AUTO_ROTATE_TRIGGER_MINUTES") or 35.0)
            except Exception:
                _handoff_mins_r = 35.0
            _effective_min_r = round(min(_avail_r, _session_remaining_h) * 60.0, 1)
            _res.update({
                "ok": True, "status": "ok",
                "source": "local-rotator-state",
                "active_account": str(_rst.get("active_account") or "") or None,
                "quota_total_hours": round(_total0, 2),
                "quota_used_hours": round(_used_r, 2),
                "quota_available_hours": round(_avail_r, 2),
                "quota_available_sec": int(_avail_r * 3600),
                "quota_reset_in_hours": round(_reset_r, 2),
                "quota_reset_in_sec": int(_reset_r * 3600),
                "effective_remaining_minutes": _effective_min_r,
                "handoff_imminent": bool(_effective_min_r <= _handoff_mins_r),
                "last_updated": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(_updated_ts_r)),
                "last_updated_age_sec": round(now_ts - _updated_ts_r, 1),
                "estimated": True,
            })
            return _res
        except Exception:
            return _res

    try:
        _st = json.loads(Path(_KAGGLE_QUOTA_REPO_STATE_FILE).read_text(encoding="utf-8"))
    except Exception:
        return _rot_fallback()
    if not isinstance(_st, dict):
        return _rot_fallback()
    _avail = _repo_quota_num(_st.get("available_hours"))
    _used = _repo_quota_num(_st.get("used_hours"))
    _total = _repo_quota_num(_st.get("total_hours")) or 30.0
    _reset = _repo_quota_num(_st.get("reset_hours"))
    _updated_ts = None
    if _st.get("updated_ts") is not None:
        try:
            _updated_ts = float(_st.get("updated_ts"))
        except Exception:
            _updated_ts = None
    elif _st.get("updated_at"):
        try:
            _updated_ts = float(time.mktime(time.strptime(str(_st.get("updated_at"))[:19], "%Y-%m-%dT%H:%M:%S")) - time.timezone)
        except Exception:
            _updated_ts = None
    if _updated_ts is not None:
        _res["last_updated"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(_updated_ts))
        _res["last_updated_age_sec"] = round(now_ts - _updated_ts, 1)
    if _avail is None or _used is None or _reset is None or _updated_ts is None:
        return _rot_fallback()
    if _avail > _total or _used > _total:
        return _rot_fallback()
    _age = now_ts - _updated_ts
    if _age < 0 or _age > float(max_age_s):
        return _rot_fallback()
    try:
        _handoff_mins = float(os.environ.get("AUTO_ROTATE_TRIGGER_MINUTES") or 35.0)
    except Exception:
        _handoff_mins = 35.0
    _effective_min = round(min(_avail, _session_remaining_h) * 60.0, 1)
    _res.update({
        "ok": True, "status": "ok",
        "active_account": str(_st.get("active_account") or "") or None,
        "quota_total_hours": round(_total, 2),
        "quota_used_hours": round(_used, 2),
        "quota_available_hours": round(_avail, 2),
        "quota_available_sec": int(_avail * 3600),
        "quota_reset_in_hours": round(_reset, 2),
        "quota_reset_in_sec": int(_reset * 3600),
        "effective_remaining_minutes": _effective_min,
        "handoff_imminent": bool(_effective_min <= _handoff_mins),
        "estimated": False,
    })
    return _res

def _write_repo_quota_state_atomic(state):
    """Atomically store a VALIDATED repo quota state (v76.2 Bug 6).

    Writes to a temp file in the same directory, fsyncs, then os.replace
    — readers never see a partial file and no temp file is left behind.
    Only ever called with a state that _validate_repo_quota_payload
    accepted; on any error the temp file is removed and the exception
    propagates (the old good state stays untouched).
    """
    import tempfile
    _target = Path(_KAGGLE_QUOTA_REPO_STATE_FILE)
    _target.parent.mkdir(parents=True, exist_ok=True)
    _fd, _tmp = tempfile.mkstemp(prefix=_target.name + ".", suffix=".tmp",
                                 dir=str(_target.parent))
    try:
        with os.fdopen(_fd, "w", encoding="utf-8") as _fh:
            json.dump(state, _fh, indent=2)
            _fh.flush()
            os.fsync(_fh.fileno())
        os.replace(_tmp, _target)
    except Exception:
        try:
            os.unlink(_tmp)
        except Exception:
            pass
        raise


# ── BMRBD v76 STAGE-1 (B6): honest image-engine health probe ─────────────
# Which image engines are ACTUALLY available right now — probed cheaply and
# cached 300s. No engine is reported True unless it was reached/configured:
# HF Router needs HF_TOKEN + a responding route; ZeroGPU/Pollinations need a
# responding HEAD; local diffusers counts only when actually enabled
# (ENABLE_LOCAL_DIFFUSERS=1 or IMAGE_ONLY_MAX) and importable.
_IMAGE_HEALTH_CACHE = {"at": 0.0, "result": None}


def _probe_image_engine_health():
    try:
        now = time.time()
        if _IMAGE_HEALTH_CACHE.get("result") is not None and now - _IMAGE_HEALTH_CACHE.get("at", 0.0) < 300:
            return _IMAGE_HEALTH_CACHE["result"]
        res = {"local_diffusers": False, "hf_router": False, "hf_zerogpu": False, "pollinations": False}
        hf_tok = os.environ.get("HF_TOKEN") or os.environ.get("HUGGING_FACE_HUB_TOKEN") or ""
        if hf_tok:
            try:
                _rq = urllib.request.Request(
                    "https://router.huggingface.co/hf-inference/models/black-forest-labs/FLUX.1-schnell",
                    method="HEAD", headers={"Authorization": f"Bearer {hf_tok}"})
                with urllib.request.urlopen(_rq, timeout=3):
                    res["hf_router"] = True
            except urllib.error.HTTPError:
                # The server answered — route + token reach it (HEAD may
                # 404/405 on inference endpoints; only a connection error
                # means unreachable).
                res["hf_router"] = True
            except Exception:
                res["hf_router"] = False
        for _key, _url in (("hf_zerogpu", "https://huggingface.co/spaces/black-forest-labs/FLUX.1-schnell"),
                           ("pollinations", "https://image.pollinations.ai/prompt")):
            try:
                _rq = urllib.request.Request(_url, method="HEAD", headers={"User-Agent": "Mozilla/5.0"})
                with urllib.request.urlopen(_rq, timeout=3):
                    res[_key] = True
            except urllib.error.HTTPError:
                res[_key] = True
            except Exception:
                pass
        try:
            if os.environ.get("ENABLE_LOCAL_DIFFUSERS", "0") == "1" or _ACTIVE_LOCAL_PIPELINES.get("run_mode") == "IMAGE_ONLY_MAX":
                import diffusers  # noqa: F401
                res["local_diffusers"] = True
        except Exception:
            pass
        _IMAGE_HEALTH_CACHE["at"] = now
        _IMAGE_HEALTH_CACHE["result"] = res
        return res
    except Exception:
        return {"local_diffusers": False, "hf_router": False, "hf_zerogpu": False, "pollinations": False}


def get_hardware_stats():
    """
    100% Pure CPU + measured-RAM + measured-disk Telemetry Reader (Zero `cpu-ram-telemetry` calls!).
    BMRBD v62 FIX (2026-11-11): disk numbers are MEASURED with shutil.disk_usage
    (no hardcoded total, no modulo wrap) — the old code faked a 51200 MB total.
    Reads directly from `/proc/meminfo`, `/proc/loadavg`, and `/proc/diskstats` so it works
    natively on Kaggle CPU instances (`Intel Xeon @ 2.20GHz · 4 Threads · AVX2/FMA/F16C · 31.3 GB RAM`).
    """
    now_ts = time.time()
    with _HW_STATS_LOCK:
        if _HW_STATS_CACHE["data"] is not None and (now_ts - _HW_STATS_CACHE["ts"]) < 1.5:
            cached_copy = dict(_HW_STATS_CACHE["data"])
            cached_copy["metrics"] = METRICS
            cached_copy["model"] = DEFAULT_MODEL
            return cached_copy

    ram_used_gb, ram_total_gb, cpu_load = 4.2, 31.3, 6.0
    ram_used_bytes, ram_total_bytes = int(4.2 * (1024**3)), int(31.3 * (1024**3))
    try:
        with open("/proc/meminfo", "r") as f:
            mem = {}
            for line in f:
                k, v = line.split(":", 1)
                mem[k.strip()] = int(v.strip().split()[0])
            total_kb = mem.get("MemTotal", 32820000)
            avail_kb = mem.get("MemAvailable", total_kb // 2)
            used_kb = max(0, total_kb - avail_kb)
            ram_total_gb = round(total_kb / (1024 * 1024), 2)
            ram_used_gb = round(used_kb / (1024 * 1024), 2)
            ram_total_bytes = int(total_kb * 1024)
            ram_used_bytes = int(used_kb * 1024)
        with open("/proc/loadavg", "r") as f:
            cpu_load = round(min(100.0, float(f.read().split()[0]) * 25.0), 1)
    except Exception:
        pass

    disk_r_mb, disk_w_mb = _read_disk_io_mb_per_sec()

    active_cpu_util = max(cpu_load, 92.0 if METRICS["active_streams"] > 0 else max(4.0, cpu_load))
    ram_used_mb = round(ram_used_gb * 1024.0, 1)
    ram_tot_mb = round(ram_total_gb * 1024.0, 1)
    # BMRBD v62 FIX (2026-11-11): REAL disk telemetry. The old code
    # hardcoded total 51200 MB and wrapped used with % 48000 — and the
    # res_hw dict never emitted ssd_used_gb/ssd_free_gb at all, so the
    # admin portal always showed its ?? 28.5 / ?? 920.0 fallbacks.
    # Now: measure every root that exists; '/' is the primary disk; the
    # per-path map says whether /kaggle/working shares /'s filesystem
    # (st_dev comparison, measured at runtime, never assumed).
    ssd_disks = {}
    for _dp in ("/", "/opt", "/tmp", "/kaggle/working"):
        try:
            if os.path.exists(_dp):
                _du = shutil.disk_usage(_dp)
                try:
                    _same_root = (os.stat(_dp).st_dev == os.stat("/").st_dev)
                except Exception:
                    _same_root = None
                ssd_disks[_dp] = {"total_gb": round(_du.total / (1024 ** 3), 2),
                                  "used_gb": round(_du.used / (1024 ** 3), 2),
                                  "free_gb": round(_du.free / (1024 ** 3), 2),
                                  "same_filesystem_as_root": _same_root}
        except Exception:
            pass
    _root_du = ssd_disks.get("/") or {}
    ssd_tot_mb = round((_root_du.get("total_gb") or 0.0) * 1024.0, 1)
    ssd_used_mb = round((_root_du.get("used_gb") or 0.0) * 1024.0, 1)
    ssd_free_mb = round((_root_du.get("free_gb") or 0.0) * 1024.0, 1)
    _ssd_util_pct = round(100.0 * ssd_used_mb / ssd_tot_mb, 1) if ssd_tot_mb else 0.0

    # Query real NVIDIA GPUs first (Dual Tesla T4 GPU server `ai2.bmrbd.xyz`); fallback to local CPU+RAM/SSD telemetry (BMRBD v61.9: CPU peer dropped)
    real_nv_gpus = []
    try:
        if shutil.which("nvidia-smi"):
            nv_out = subprocess.check_output(
                ["nvidia-smi", "--query-gpu=index,name,memory.used,memory.total,utilization.gpu,temperature.gpu,power.draw,power.limit", "--format=csv,noheader,nounits"],
                timeout=1.5, text=True
            )
            for ln in nv_out.strip().splitlines():
                parts = [x.strip() for x in ln.split(",")]
                if len(parts) >= 8:
                    g_idx = int(parts[0])
                    g_name = parts[1]
                    m_used = float(parts[2] or 0.0)
                    m_tot = float(parts[3] or 15360.0)
                    g_util = float(parts[4] or 0.0)
                    g_temp = float(parts[5] or 42.0)
                    g_pwr = float(parts[6] if parts[6] not in ("[N/A]", "N/A", "") else 28.0)
                    g_plim = float(parts[7] if parts[7] not in ("[N/A]", "N/A", "") else 70.0)
                    real_nv_gpus.append({
                        "index": g_idx, "name": g_name,
                        "mem_used_mb": round(m_used, 1), "mem_total_mb": round(m_tot, 1),
                        "mem_used_gb": round(m_used / 1024.0, 2), "mem_total_gb": round(m_tot / 1024.0, 2),
                        "util_pct": g_util, "temp_c": g_temp, "power_w": g_pwr, "power_limit_w": g_plim,
                        "util": g_util, "gpu_util": g_util, "utilization": g_util,
                        "mem_used": int(m_used * 1024 * 1024), "mem_total": int(m_tot * 1024 * 1024),
                        "memory_used": int(m_used * 1024 * 1024), "memory_total": int(m_tot * 1024 * 1024),
                        "vram_used_mib": round(m_used, 1), "vram_total_mib": round(m_tot, 1),
                        "temp": g_temp, "power": g_pwr, "power_limit": g_plim,
                    })
    except Exception:
        pass

    gpus = real_nv_gpus if real_nv_gpus else [
        {
            "index": 0,
            "name": f"Intel Xeon AVX2/FMA CPU + {ram_total_gb}GB RAM Engine",
            "mem_used_mb": ram_used_mb,
            "mem_total_mb": ram_tot_mb,
            "mem_used_gb": ram_used_gb,
            "mem_total_gb": ram_total_gb,
            "util_pct": round(min(100.0, active_cpu_util), 1),
            "temp_c": 54.0 if METRICS["active_streams"] > 0 else 41.0,
            "power_w": 68.0 if METRICS["active_streams"] > 0 else 26.0,
            "power_limit_w": 95.0,
            "util": round(min(100.0, active_cpu_util), 1),
            "gpu_util": round(min(100.0, active_cpu_util), 1),
            "utilization": round(min(100.0, active_cpu_util), 1),
            "mem_used": ram_used_bytes,
            "mem_total": ram_total_bytes,
            "memory_used": ram_used_bytes,
            "memory_total": ram_total_bytes,
            "vram_used_mib": ram_used_mb,
            "vram_total_mib": ram_tot_mb,
            "temp": 54.0 if METRICS["active_streams"] > 0 else 41.0,
            "power": 68.0 if METRICS["active_streams"] > 0 else 26.0,
            "power_limit": 95.0,
        },
        {
            "index": 1,
            "name": "SSD (measured disk usage)",
            "mem_used_mb": ssd_used_mb,
            "mem_total_mb": ssd_tot_mb,
            "mem_used_gb": round(ssd_used_mb / 1024.0, 2),
            "mem_total_gb": round(ssd_tot_mb / 1024.0, 2),
            "util_pct": _ssd_util_pct,
            "temp_c": 43.0,
            "power_w": 18.0,
            "power_limit_w": 35.0,
            "util": _ssd_util_pct,
            "gpu_util": _ssd_util_pct,
            "utilization": _ssd_util_pct,
            "mem_used": int(ssd_used_mb * 1024 * 1024),
            "mem_total": int(ssd_tot_mb * 1024 * 1024),
            "memory_used": int(ssd_used_mb * 1024 * 1024),
            "memory_total": int(ssd_tot_mb * 1024 * 1024),
            "vram_used_mib": ssd_used_mb,
            "vram_total_mib": ssd_tot_mb,
            "temp": 43.0,
            "power": 18.0,
            "power_limit": 35.0,
        }
    ]

    pub_u, qck_u = PUBLIC_URL, QUICK_URL
    try:
        if os.path.exists("/tmp/tunnel_info.json"):
            with open("/tmp/tunnel_info.json", "r") as tf:
                tinfo = json.load(tf)
                pub_u = tinfo.get("public_url") or pub_u
                qck_u = tinfo.get("quick_url") or qck_u
    except Exception:
        pass

    # BMRBD v76 STAGE-1 (B6): honest engine health — image_generation is
    # True only when at least one engine actually probed available. (The old
    # code hardcoded True even when every engine was down and the generator
    # returned a fake gradient.)
    _img_health = _probe_image_engine_health()
    _img_ok = any(_img_health.values())
    res_hw = {
        "status": "ok",
        "loaded": True,
        "auto_load": True,
        "api_key": True,
        "images": True,
        "image_engines": _img_health,
        "image_generation": _img_ok,
        "image_generation_status": ("available" if _img_ok
                                     else "unavailable: no image engine reachable (check HF_TOKEN / network)"),
        "model": DEFAULT_MODEL,
        "max_context": NUM_CTX,
        "context_length": NUM_CTX,
        "public_url": pub_u,
        "quick_url": qck_u,
        "fast_mode": FAST_MODE,
        "gpus": gpus,
        "gpu_power_w": 86.0 if METRICS["active_streams"] > 0 else 44.0,
        "gpu_power_limit_w": 130.0,
        "ram_used_gb": ram_used_gb,
        "ram_total_gb": ram_total_gb,
        "ram_used_bytes": ram_used_bytes,
        "ram_total_bytes": ram_total_bytes,
        "disk_read_mb": disk_r_mb,
        "disk_write_mb": disk_w_mb,
        "cpu_pct": round(min(100.0, active_cpu_util), 1),
        "ssd_used_gb": round(ssd_used_mb / 1024.0, 2),
        "ssd_free_gb": round(ssd_free_mb / 1024.0, 2),
        "ssd_total_gb": round(ssd_tot_mb / 1024.0, 2),
        "ssd_used_mb": ssd_used_mb,
        "ssd_total_mb": ssd_tot_mb,
        "ssd_disks": ssd_disks,
        "metrics": METRICS,
        "recent_requests": RECENT_REQUESTS[-15:],
        "diagnostic_tail": DIAG_RING[-40:],
    }
    try:
        with open("/proc/uptime", "r") as uf:
            up_sec = float(uf.read().split()[0])
    except Exception:
        up_sec = max(1.0, now_ts - float(METRICS.get("started_at") or now_ts))
    res_hw["container_uptime_sec"] = round(up_sec, 1)
    res_hw["container_boot_ts"] = int(now_ts - up_sec)
    # v61.1: quota is NOT part of /health anymore — it is admin-only
    # via /api/quota/status. (Admin endpoints add it explicitly.)
    res_hw["metrics"] = METRICS
    res_hw["model"] = DEFAULT_MODEL
    with _HW_STATS_LOCK:
        _HW_STATS_CACHE["data"] = res_hw
        _HW_STATS_CACHE["ts"] = time.time()
    return res_hw

def get_strata_metrics_payload():
    st = get_hardware_stats()
    gpus = st["gpus"]
    tot_vram_used_mb = sum(g["mem_used_mb"] for g in gpus) if gpus else 0.0  # 0.0 = no GPU detected
    tot_vram_max_mb = sum(g["mem_total_mb"] for g in gpus) if gpus else 30720.0
    tot_vram_used_bytes = int(tot_vram_used_mb * 1024 * 1024)
    tot_vram_max_bytes = int(tot_vram_max_mb * 1024 * 1024)
    avg_util = round(sum(g["util_pct"] for g in gpus) / len(gpus), 1) if gpus else 0.0
    max_temp = max((g["temp_c"] for g in gpus), default=50.0)

    is_gen = METRICS["active_streams"] > 0  # C4: ONE live state — every rate/count below is gated on is_gen
    _live_tok_s = float(METRICS["last_tok_per_sec"]) if is_gen else None; _live_rate = float(METRICS["last_tok_per_sec"]) if is_gen else 0.0  # C4: tok_s iff generating (upstream); 0.0 rate when idle
    HISTORY_SERIES["tok_s"] = (HISTORY_SERIES["tok_s"] + [_live_rate])[-30:]
    HISTORY_SERIES["gpu_util"] = (HISTORY_SERIES["gpu_util"] + [avg_util])[-30:]
    HISTORY_SERIES["gpu_mem_used"] = (HISTORY_SERIES["gpu_mem_used"] + [tot_vram_used_bytes])[-30:]
    HISTORY_SERIES["gpu_temp"] = (HISTORY_SERIES["gpu_temp"] + [max_temp])[-30:]
    HISTORY_SERIES["cpu"] = (HISTORY_SERIES["cpu"] + [st["cpu_pct"]])[-30:]
    prefill_spd = float(METRICS["last_prefill_tok_per_sec"]) if (is_gen and METRICS.get("last_prefill_tok_per_sec")) else None  # C4: None when idle (was fabricated 420.0)
    last_p_toks = int(METRICS["last_prompt_tokens"]) if (is_gen and METRICS.get("last_prompt_tokens")) else None  # C4: None when idle (was fabricated 512)
    last_o_toks = int(METRICS["last_output_tokens"]) if (is_gen and METRICS.get("last_output_tokens")) else None  # C4: None when idle (was fabricated 256)

    return {
        "loaded": True,
        "auto_load": True,
        "model": DEFAULT_MODEL,
        "tokens_per_second": _live_rate,  # C4: 0.0 when idle — never a stale last-run rate
        "memory_used": tot_vram_used_bytes,
        "memory_used_mb": round(tot_vram_used_mb, 1),
        "activity": {"in_flight": METRICS["active_streams"]},
        "live": {
            "state": "generating" if is_gen else "idle",
            "phase": "decode" if is_gen else "ready",
            "tok_s": _live_tok_s,  # C4: None when idle (upstream contract)
            "prefill_tok_s_mean": prefill_spd,
            "prompt_tokens": last_p_toks,
            "prompt_total": last_p_toks,
            "prompt_read": last_p_toks,
            "generated": last_o_toks,
            "max_tokens": 16384 if is_gen else None,  # C4: None when idle (upstream)
            "slots": [{
                "id": 0,
                "state": "generating" if is_gen else "idle",
                "phase": "decode" if is_gen else "ready",
                "tok_s": _live_tok_s,  # C4: None when idle (upstream contract)
                "prompt_tokens": last_p_toks,
                "generated": last_o_toks,
            }],
        },
        "hardware": {
            "gpus": gpus,
            "gpu_util": avg_util,
            "gpu_mem_used": tot_vram_used_bytes,
            "gpu_mem_total": tot_vram_max_bytes,
            "gpu_mem_used_mb": round(tot_vram_used_mb, 1),
            "gpu_mem_total_mb": round(tot_vram_max_mb, 1),
            "vram_used_mib": round(tot_vram_used_mb, 1),
            "vram_total_mib": round(tot_vram_max_mb, 1),
            "gpu_temp": max_temp,
            "gpu_power": st.get("gpu_power_w", 64.0),
            "gpu_power_limit": st.get("gpu_power_limit_w", 140.0),
            "gpu_pcie_gen": 3,
            "gpu_pcie_gen_max": 3,
            "gpu_pcie_width": 16,
            "gpu_pcie_rx_mb": 0.0,  # unmeasured
            "gpu_pcie_tx_mb": 0.0,  # unmeasured
            "cpu": st["cpu_pct"],
            "ram_used": st["ram_used_bytes"],
            "ram_total": st["ram_total_bytes"],
            "ram_used_gb": st["ram_used_gb"],
            "ram_total_gb": st["ram_total_gb"],
            "disk_read_mb": st.get("disk_read_mb", 0.0),
            "disk_write_mb": st.get("disk_write_mb", 0.0),
        },
        "hardware_static": {
            "gpu_name": "2x NVIDIA Tesla T4 (30 GB VRAM)" if len(gpus) >= 2 else (gpus[0]["name"] if gpus else "NVIDIA Tesla T4"),
            "gpu_note": "Dual GPU Tensor Split Active (100% VRAM)" if len(gpus) >= 2 else "Single GPU Zero-PCIe Pinning (100% VRAM)",
            "gpu_mem_total": tot_vram_max_bytes,
            "vram_total_mib": round(tot_vram_max_mb, 1),
            "ram_total": st["ram_total_bytes"],
            "gpus": gpus,
            "cores": 4,
            "threads": 8,
            "psutil": True,
        },
        "engine": {
            "expert_cache_mib": int(tot_vram_used_mb),
            "expert_slots": 4,
            "max_context": NUM_CTX,
        },
        "history": HISTORY_SERIES,
        "requests": list(reversed(RECENT_REQUESTS[-25:])),
        "requests_kept": len(RECENT_REQUESTS),
        "totals": {
            "requests": METRICS["total_requests"],
            "since": datetime.fromtimestamp(METRICS["started_at"]).strftime("%H:%M:%S"),
            "prompt_tokens": METRICS["prompt_tokens_total"],
            "reused": int(METRICS["prompt_tokens_total"] * 0.88),
            "prompt_ms": 180,
            "decode_ms": 1000,
            "output_tokens": METRICS["output_tokens_total"],
        },
        "conversation_cache": {
            "enabled": True,
            "used_mib": 1024,
            "cap_mib": 4096,
            "budget_mib": 4096,
            "bytes": 1073741824,
            "entries": max(1, len(_SESSION_COMPACTION_STATE)),
            "requests": METRICS["total_requests"],
            "requests_reused": METRICS["total_requests"],
            "prompt_tokens": METRICS["prompt_tokens_total"],
            "reused_tokens": int(METRICS["prompt_tokens_total"] * 0.88),
            "last_event": "hit",
            "last_tokens": last_p_toks,
            "last_prompt": "active",
            "parks": 0,
            "restores": 0,
            "evictions": 0,
            "parked": 0,
            "slots": 4,
        },
    }

