def _effort_profile(eff):
    # BMRBD v76.5 H5: High is the default now (was Fast/low since v76 A8).
    # "auto" resolves to the High profile (added by the R13 rebuild below).
    return _EFFORT_PROFILES.get(str(eff or "high").lower(), _EFFORT_PROFILES["high"])


def extract_effort_from_body(body):
    """
    Extracts effort level across OpenAI (/v1/chat/completions), Anthropic (/v1/messages),
    and Codex (/v1/responses), including Claude Desktop's `output_config.effort` and `thinking.budget_tokens`.
    """
    if not isinstance(body, dict):
        return None
    eff = body.get("reasoning_effort") or body.get("reasoningEffort") or body.get("effort")
    if not eff and isinstance(body.get("reasoning"), dict):
        eff = body["reasoning"].get("effort")
    if not eff and isinstance(body.get("output_config"), dict):
        eff = body["output_config"].get("effort")
    if not eff and isinstance(body.get("metadata"), dict):
        eff = body["metadata"].get("effort")
    if not eff and isinstance(body.get("thinking"), dict):
        th = body["thinking"]
        if th.get("type") in ("enabled", "adaptive"):
            b_toks = int(th.get("budget_tokens") or 16000)
            if b_toks >= 24000:
                eff = "max"
            elif b_toks >= 10000:
                eff = "high"
            elif b_toks >= 4000:
                eff = "medium"
            else:
                eff = "low"
    if not eff and body.get("task_mode"):
        eff = "max"
    if not eff and body.get("think") is True:
        eff = "high"
    if not eff and body.get("tools"):
        # H123 (v76.5 H1): never escalate a pure first-turn greeting
        # to high on tools alone — harness clients always declare
        # tools, so the old rule made every effort-less "hi" a Deep
        # turn (think=True, 16384 tokens).
        _msgs = body.get("messages") or body.get("input") or []
        _last_txt = ""
        if isinstance(_msgs, list) and _msgs:
            _lm = _msgs[-1] if isinstance(_msgs[-1], dict) else {}
            _rc = _lm.get("content", "")
            _last_txt = _rc.strip().lower() if isinstance(_rc, str) else ""
        if _last_txt not in ("hi", "hello", "hey", "yo", "hola", "sup",
                             "\u09b9\u09be\u0987", "\u09b9\u09cd\u09af\u09be\u09b2\u09cb", "\u09b8\u09be\u09b2\u09be\u09ae", "\u0986\u09b8\u09be\u09b8\u09be\u09b2\u09be\u09ae\u09c1 \u0986\u09b2\u09be\u0987\u0995\u09c1\u09ae"):
            eff = "high"
    return str(eff).lower() if eff else None



# ============================================================================
# BMRBD HARNESS v76 (2026-11-19) — HARNESS-SPEC-v1 section 10.
# Bridge-side harness: chat-completions hardening (1.1), Messages (1.2),
# Responses (1.3), models catalogue (1.4), effort (2.3), context (3),
# compaction (4), reconnect (5), subagents (6), web tools (7),
# code-first visuals (8). Frontend blobs untouched; Fix A / Fix B preserved.
# ============================================================================
HARNESS_LAUNCH_CTX = 32768

# ── BMRBD v76.3 (Agent D — 1M CONTEXT, HONEST PHYSICS) ──────────────────
# Marup's order: a 1M-token context window. The honest physics, verified
# 2026-11-20 against the official Qwen3.8-Flash-Next model card + config:
#   * Native context: 262,144 tokens, extensible to 1,000,000 with YaRN
#     (HF Qwen/Qwen3.8-Flash-Next README; Qwen blog; NVIDIA blog).
#   * Architecture (Qwen/Qwen3.8-Flash-Next config.json / GGUF metadata,
#     same shape as the Qwen3-Next-80B sibling config): qwen4exp,
#     48 layers = 36 Gated DeltaNet (linear attention, FIXED-size
#     recurrent state — NO KV that grows with context) + 12 Qwen Sparse
#     Attention layers (full_attention_interval = 4). Only those 12
#     layers carry a KV cache that grows with context.
#   * Full-attention KV: 24 Q heads / 2 KV heads (GQA), head_dim 256,
#     f16 KV MANDATORY (q8_0 breaks qwen4exp sparse attention).
# KV bytes/token = 12 layers x 2 (K+V) x 2 KV heads x 256 head_dim x 2 B
#                = 24,576 B/token (24 KiB/token).
# Cross-check that this is right: the naive dense formula (all 48
# layers) would give 98,304 B/token -> 32K tokens = 3.0 GiB of KV,
# which would already OOM — but the live server RUNS 32K today. Only
# the 12-layer figure (32K -> 768 MiB) is consistent with the live
# server, so the hybrid correction is load-bearing, not decorative.
# VRAM budget (2x Tesla T4 = 30 GiB; weights ~93% ~= 28 GiB resident):
# free VRAM is ~1-2 GiB (unverified inside that range). Reserve 256 MiB
# for activations + engine overhead — the largest reserve still
# consistent with 32K working at the pessimistic 1 GiB-free end.
#   free 1.0 GiB -> max safe window 32,768  |  48K needs 1,408 MiB free
#   free 1.5 GiB -> max safe window 54,613  |  64K needs 1,792 MiB free
#   free 2.0 GiB -> max safe window 76,458
# VERDICT (CALCULATED, not live-tested — no live kernel in this task):
# HARNESS_LAUNCH_CTX STAYS 32768. It is already the safe max across
# the whole unverified 1-2 GiB free range; raising it bets the kernel's
# boot on the optimistic end (a boot-time OOM = total outage, not one
# failed request). 1M native would need KV 24 GiB + weights ~28 GiB +
# margin ~= 52+ GiB VRAM: a single 80GB-class GPU (H100/A100 80GB)
# minimum, plus YaRN support in Strata (unverified). The 1M user
# experience is delivered as EFFECTIVE UNLIMITED CONTEXT instead: the
# full conversation is kept in the vault (see the round-trip block
# below) and the model is fed a compacted feed that always fits — the
# user never sees a context error.
V763_CTX1M_NATIVE_CTX = 262144
V763_CTX1M_YARN_CTX = 1048576
V763_CTX1M_TOTAL_LAYERS = 48
V763_CTX1M_LINEAR_LAYERS = 36
V763_CTX1M_FULL_ATTN_LAYERS = 12
V763_CTX1M_KV_HEADS = 2
V763_CTX1M_HEAD_DIM = 256
V763_CTX1M_KV_DTYPE_BYTES = 2  # f16, mandatory for qwen4exp QSA
V763_CTX1M_KV_BYTES_PER_TOKEN = (V763_CTX1M_FULL_ATTN_LAYERS * 2 * V763_CTX1M_KV_HEADS * V763_CTX1M_HEAD_DIM * V763_CTX1M_KV_DTYPE_BYTES)  # 24576
V763_CTX1M_FREE_VRAM_LO_BYTES = 1024 * 1024 * 1024      # pessimistic end of the ~1-2 GiB free range
V763_CTX1M_FREE_VRAM_HI_BYTES = 2 * 1024 * 1024 * 1024  # optimistic end
V763_CTX1M_RESERVE_BYTES = 256 * 1024 * 1024  # activations + engine overhead


def v763_ctx1m_kv_bytes(tokens):
    """KV-cache bytes for `tokens` context tokens (f16, 12 full-attention
    layers only — the 36 Gated DeltaNet layers carry fixed state). Pure."""
    try:
        return max(0, int(tokens or 0)) * V763_CTX1M_KV_BYTES_PER_TOKEN
    except Exception:
        return 0


def v763_ctx1m_kv_table():
    """[(tokens, kv_bytes, kv_mib)] for the standard window sizes. Pure."""
    return [(t, v763_ctx1m_kv_bytes(t), v763_ctx1m_kv_bytes(t) / (1024.0 * 1024.0))
            for t in (32768, 49152, 65536, 131072, 262144, 1048576)]


def v763_ctx1m_max_safe_window(free_vram_bytes, reserve_bytes=None):
    """Max context tokens whose KV fits in free VRAM minus the reserve
    (activations + engine overhead): floor((free-reserve)/24576),
    floored at 1024, never negative. CALCULATED — needs live verification
    after the push (no live kernel in this task). Pure."""
    try:
        r = V763_CTX1M_RESERVE_BYTES if reserve_bytes is None else int(reserve_bytes)
        room = int(free_vram_bytes or 0) - r
        if room <= 0:
            return 1024
        return max(1024, room // V763_CTX1M_KV_BYTES_PER_TOKEN)
    except Exception:
        return 1024


def v763_ctx1m_window_report(free_vram_bytes=None, reserve_bytes=None):
    """Honest window verdict dict: KV table, max safe window at the
    given free VRAM (default: the pessimistic 1 GiB end), whether the
    launch window is safe, and what 1M native would require. Pure."""
    try:
        free = V763_CTX1M_FREE_VRAM_LO_BYTES if free_vram_bytes is None else int(free_vram_bytes)
        r = V763_CTX1M_RESERVE_BYTES if reserve_bytes is None else int(reserve_bytes)
        table = [{"tokens": t, "kv_bytes": b, "kv_mib": m} for (t, b, m) in v763_ctx1m_kv_table()]
        max_safe = v763_ctx1m_max_safe_window(free, r)
        kv_1m = v763_ctx1m_kv_bytes(V763_CTX1M_YARN_CTX)
        weights = 28 * 1024 * 1024 * 1024  # ~28 GiB resident weights (task fact)
        need_1m = kv_1m + weights + r
        launch = int(globals().get("HARNESS_LAUNCH_CTX", 32768))
        return {"native_ctx": V763_CTX1M_NATIVE_CTX, "yarn_ctx": V763_CTX1M_YARN_CTX,
                "kv_bytes_per_token": V763_CTX1M_KV_BYTES_PER_TOKEN,
                "kv_table": table, "free_vram_bytes": free, "reserve_bytes": r,
                "max_safe_window": max_safe, "launch_ctx": launch,
                "launch_safe": launch <= max_safe,
                "fits_1m_native": False,
                "vram_needed_1m_bytes": need_1m,
                "verdict": "launch 32768 stays: it is the safe max at the pessimistic 1 GiB-free end; 1M native needs ~52+ GiB VRAM (single 80GB-class GPU) + YaRN in Strata - not possible on 2x T4."}
    except Exception:
        return {"native_ctx": V763_CTX1M_NATIVE_CTX, "yarn_ctx": V763_CTX1M_YARN_CTX,
                "kv_bytes_per_token": V763_CTX1M_KV_BYTES_PER_TOKEN,
                "max_safe_window": 32768, "fits_1m_native": False}


# Calculated max safe window at the pessimistic (1 GiB free) end: 32768.
# HARNESS_LAUNCH_CTX == this value, which is WHY the launch window is
# not raised. If free VRAM is ever MEASURED (not ranged) above 1,408
# MiB, this is the single number that justifies a raise to 49152.
V763_CTX1M_MAX_SAFE_WINDOW = v763_ctx1m_max_safe_window(V763_CTX1M_FREE_VRAM_LO_BYTES, V763_CTX1M_RESERVE_BYTES)  # 32768
HARNESS_COMPACT_AT_TOKENS = 22000  # ~70% of the 32K launch window (spec section 4; 22000 ~= 67% of 32768)
HARNESS_DEDUPE_WINDOW_S = 60
HARNESS_RETRY_GUIDANCE = ("Retry with exponential backoff 1s to 30s, max 5 retries, "
                          "only on 429/502/503/connection errors. Never retry a 400.")
