_HARNESS_EFFORT_PROFILES = {
    "low": {"name": "low", "label": "Fast", "max_tokens": 2048, "temperature": 0.7, "top_p": 0.9, "think": False,
            "instruction": "Answer briefly and directly - 2 to 5 short sentences unless the user asked for detail or for a file/code/build - then give the complete code/file, still without <think> blocks! Start your response immediately without <think> blocks!"},  # BMRBD v76.2 ACK-FIRST (Bug 3): same no-think instruction the unified path sends (was "Answer briefly and directly." only, so the live proxy path never told the engine not to think)
    "medium": {"name": "medium", "label": "Balanced", "max_tokens": 8192, "temperature": 0.7, "top_p": 0.9, "think": False,
               "instruction": "Answer completely at normal depth. Start your response immediately without <think> blocks!"},
    "high": {"name": "high", "label": "Deep", "max_tokens": 16384, "temperature": 0.6, "top_p": 0.9, "think": True,
             "instruction": "Think step by step, but stay FOCUSED on the exact question asked - no tangents, no unrelated background, no repeating the question. Think fully, then give a direct answer that addresses the question and nothing else. Keep the thinking concise (about 20% of the reply at most); the answer is the main part."},
    "max": {"name": "max", "label": "Max", "max_tokens": 16384, "temperature": 0.6, "top_p": 0.9, "think": True,
            "instruction": "Deepest, multi-step, self-check. Complete the WHOLE task in this reply - do not stop halfway, do not announce and stop. Stay focused on the exact task."},
    "challenge": {"name": "challenge", "label": "Challenge", "max_tokens": 16384, "temperature": 0.5, "top_p": 0.9, "think": True,
                  "instruction": "Max depth plus adversarial self-review. Complete the WHOLE task in this reply - do not stop halfway, do not announce and stop. Check your own work for mistakes, then give the finished result."},
}
# BMRBD v76 STAGE-1 (2026-11-19) — ROOT CAUSE of "Max doesn't work" and
# "Challenge doesn't work": the old aliases mapped the frontend's real values
# to the WRONG profiles — 'max_fast' (the UI's Max) -> 'low' (Fast: 1024 tok,
# no thinking), so Max behaved exactly like Fast; 'complex' (the UI's
# Challenge) -> 'high' (Deep), so Challenge behaved exactly like Deep and the
# 'challenge' profile (8192 tok, temp 0.5) was UNREACHABLE. Fixed: every UI
# value now resolves to its own profile. 'xhigh' is the legacy Challenge
# value (frontend maps it to Challenge too), so it also resolves to
# 'challenge' now.
_HARNESS_EFFORT_ALIASES = {"fast": "low", "balanced": "medium", "deep": "high", "xhigh": "challenge",
                           "max_fast": "max", "complex": "challenge", "auto": "high"}
# Canonical reasoning_effort values the engine actually understands
# (OpenAI set: minimal/low/medium/high/xhigh). The UI's 'max_fast' /
# 'complex' are NOT engine values — forwarding them raw made the engine
# resolve an unknown effort (the 'unknown resolving' symptom Marup saw on
# Challenge). The proxy path normalizes through this map before forwarding.
_HARNESS_ENGINE_EFFORT = {"low": "low", "medium": "medium", "high": "high",
                          "max": "xhigh", "challenge": "xhigh"}


def _harness_effort_profile(eff):
    key = str(eff or "").lower().strip()
    key = _HARNESS_EFFORT_ALIASES.get(key, key)
    if not key:
        # BMRBD v76.5 H5: NO effort sent -> High is the default (was
        # Balanced/medium via the unknown fallback). An explicitly sent
        # UNKNOWN value still falls back to Balanced below (spec 2.3).
        return dict(_HARNESS_EFFORT_PROFILES["high"])
    if key not in _HARNESS_EFFORT_PROFILES:
        return dict(_HARNESS_EFFORT_PROFILES["medium"])
    return dict(_HARNESS_EFFORT_PROFILES[key])


def _harness_canonical_effort(eff):
    """Canonical harness effort name for ANY client value ('max_fast',
    'complex', 'xhigh', 'deep', 'fast', ...). Never returns an alias —
    always one of low/medium/high/max/challenge. Used at every boundary so
    an unknown effort value can never reach the engine or a profile lookup."""
    return _harness_effort_profile(eff)["name"]


# BMRBD v76.5 H5 — DEFAULT EFFORT IS HIGH (Marup, 2026-11-20 ~23:52 +06).
# Single source of truth for "what effort when the client did not choose
# one". "auto" is the new first-class effort value (the dashboard Auto
# option): it means "let the server pick", and the server picks High.
# Missing (None/""), "auto", "automatic" and "default" all resolve to
# High; every explicitly sent value canonicalises unchanged (unknown
# explicit values still fall back to Balanced per harness spec 2.3).
DEFAULT_EFFORT = "high"


def _resolve_default_effort(eff):
    """Resolve any client effort value to its canonical harness effort.

    Missing/empty/"auto" -> "high" (the H5 default). Explicit values pass
    through _harness_canonical_effort unchanged, so low/medium/high/max/
    challenge and all aliases (fast/balanced/deep/max_fast/complex/xhigh)
    behave exactly as before. Pure — unit-tested.
    """
    if eff is None:
        return DEFAULT_EFFORT
    key = str(eff).strip().lower()
    if key in ("", "auto", "automatic", "default"):
        return DEFAULT_EFFORT
    return _harness_canonical_effort(key)


# BMRBD v76.2 FAST (R13): ONE source of truth for effort budgets. The two
# tables used to disagree (low 2048 vs 1024, medium 8192 vs 4096, high
# 32768 vs 8192, max 32768 vs 16384) and _EFFORT_PROFILES had no
# "challenge" key at all, so the unified path silently ran Challenge as
# Fast. Rebuild the legacy table from the harness table at import; the
# legacy-only keys (max_fast, xhigh, complex) map onto the harness
# profiles they alias to. Any future budget change edits the harness
# table only.
for _r13_k in ("low", "medium", "high", "max", "challenge"):
    _EFFORT_PROFILES[_r13_k] = dict(_HARNESS_EFFORT_PROFILES[_r13_k])
_EFFORT_PROFILES["xhigh"] = dict(_HARNESS_EFFORT_PROFILES["challenge"])
_EFFORT_PROFILES["complex"] = dict(_HARNESS_EFFORT_PROFILES["challenge"])
# BMRBD v76.5 H5: "auto" is a first-class effort value — it IS High.
_EFFORT_PROFILES["auto"] = dict(_HARNESS_EFFORT_PROFILES["high"])
del _r13_k


# ── BMRBD v76 STAGE-1: server-side tool-call leak strip ──────────────────
# The model sometimes emits raw tool-call syntax as VISIBLE text (e.g. a
# YouTube-clone request answered with 'tool call function … parameter
# command … function tool call' instead of real HTML). The frontend already
# has a render-side guard; this is the SERVER-side root fix, applied on
# every path before content reaches the client (proxy passthrough AND the
# unified streamer). Rules mirror the frontend guard: fenced code blocks
# survive unless the WHOLE block is tool-call JSON; a function DEFINITION
# schema (no "arguments" string) survives; prose leak lines are dropped.
_TOOL_CALL_LEAK_LINE_RES = (
    re.compile(r"^\s*(tool call|function call|calling function|calling the function)\b", re.I),
    re.compile(r"^\s*<\s*(tool_call|function\s*=|invoke)\b", re.I),
    re.compile(r"^\s*<\s*parameter\s*=", re.I),
    re.compile(r"^\s*\{\s*\"(function_call|tool_call)\"\s*:", re.I),
    re.compile(r"parameter\s+command", re.I),
)


def _strip_tool_call_leak(text):
    """Remove tool-call internals from VISIBLE reply text. Returns the
    cleaned text (may be empty when the whole input was a leak). Pure
    function — unit-tested with stubbed Strata responses."""
    if not text:
        return ""
    s = str(text)
    if ("<tool_call" not in s and "<function=" not in s and "<invoke" not in s
            and "<parameter=" not in s
            and "tool_call" not in s and "function_call" not in s
            and "tool call" not in s.lower() and "parameter command" not in s.lower()):
        return s
    # 1. Fenced blocks: drop only a block that is wholly tool-call JSON.
    def _fence_repl(m):
        body = m.group(1) or ""
        if re.search(r"\"(function_call|tool_call)\"\s*:", body) and "arguments" in body:
            return ""
        return m.group(0)
    s = re.sub(r"```[^\n]*\n([\s\S]*?)```", _fence_repl, s)
    # 2. Angle-bracket tool-call blocks (whole block, incl. unclosed tail).
    s = re.sub(r"<tool_call>[\s\S]*?(?:</tool_call>|$)", "", s)
    s = re.sub(r"<function=[^>]*>[\s\S]*?(?:</function>|$)", "", s)
    s = re.sub(r"<invoke>[\s\S]*?(?:</invoke>|$)", "", s)
    # v76.2: bare <parameter=...> blocks with no <tool_call>/<function=>
    # wrapper (the form the model emits for live-search fetch calls).
    # A bare <parameter=...> tag never occurs in legitimate answer prose
    # (real links are markdown), so removing the whole block is safe.
    s = re.sub(r"<parameter=tool_call>[\s\S]*?(?:</parameter>|$)", "", s)
    s = re.sub(r"<parameter=[^>\s]+>[\s\S]*?(?:</parameter>|$)", "", s)
    s = re.sub(r"<tool_call\b[^>]*/?>", "", s)
    # 3. JSON tool-call objects (brace-matched, only when they carry
    # function_call/tool_call + an arguments string — a bare function
    # schema without "arguments" is kept).
    out = []
    i = 0
    while True:
        m = re.search(r"\{\s*\"(function_call|tool_call)\"\s*:", s[i:])
        if not m:
            out.append(s[i:])
            break
        start = i + m.start()
        # Brace-match from start.
        depth = 0
        j = start
        in_str = False
        esc = False
        while j < len(s):
            ch = s[j]
            if in_str:
                if esc:
                    esc = False
                elif ch == "\\":
                    esc = True
                elif ch == '"':
                    in_str = False
            else:
                if ch == '"':
                    in_str = True
                elif ch == "{":
                    depth += 1
                elif ch == "}":
                    depth -= 1
                    if depth == 0:
                        j += 1
                        break
            j += 1
        obj = s[start:j]
        out.append(s[i:start])
        if "\"arguments\"" in obj:
            pass  # drop the whole tool-call object
        else:
            out.append(obj)
        i = j
    s = "".join(out)
    # 4. Leak lines (prose 'tool call function … parameter command …').
    kept = []
    for line in s.split("\n"):
        if any(rx.search(line) for rx in _TOOL_CALL_LEAK_LINE_RES):
            continue
        kept.append(line)
    s = "\n".join(kept)
    # 5. Stray leftovers.
    s = re.sub(r"</?tool_call>", "", s)
    s = re.sub(r"</?function[^>]*>", "", s)
    s = re.sub(r"</?parameter[^>]*>", "", s)
    return s.strip("\n").strip()


def _harness_error(code, message, retryable=False):
    return {"error": {"message": message, "code": code, "type": "harness_error",
                      "retry_guidance": HARNESS_RETRY_GUIDANCE if retryable else "Do not retry: fix the request and send a new one."}}


# ── BMRBD v76.2 ATTACHMENTS (items C+D, 2026-11-20) ─────────────────────
# C2/bridge: a 1 MB base64 phone photo is ~250,024 chars, and the token
# estimators counted the raw `images` array as prompt text (chars//4), so
# ANY real photo 400d with context_too_large against the 32,768 launch
# window before the engine was ever reached. _harness_text_only_json
# replaces attached image bytes with a short placeholder FOR ESTIMATES
# ONLY — the real request body is never touched here.
def _harness_text_only_json(obj):
    """Deep-copy of a request body / message list with attached image bytes
    replaced by '[attached image]', for TOKEN ESTIMATES ONLY. Pure."""
    try:
        if isinstance(obj, dict):
            _out = {}
            for _k, _v in obj.items():
                if _k in ("images", "image", "image_url") and isinstance(_v, (str, list)):
                    _out[_k] = "[attached image]"
                elif isinstance(_v, str) and _v.startswith("data:image/"):
                    _out[_k] = "[attached image]"
                else:
                    _out[_k] = _harness_text_only_json(_v)
            return _out
        if isinstance(obj, list):
            return [_harness_text_only_json(_v) for _v in obj]
        if isinstance(obj, str) and obj.startswith("data:image/"):
            return "[attached image]"
        return obj
    except Exception:
        return obj


def _harness_images_to_text_in_body(body):
    """v76.2 C2(iii) INTERIM vision fallback — NOT true vision. The live
    path is the Strata/colibri proxy, which forwards the raw body
    (Ollama-style `images` field) to a text-only llama-server that has no
    vision route, while _to_openai_messages explicitly drops `images`.
    Replace each attached image with a PIL summary line
    (inspect_attached_media_b64: dimensions / format / average colour)
    appended to the message text, and DROP the `images` field, so the
    model at least knows a picture was attached and what it looks like.
    Returns the SAME body object when nothing was attached. True vision
    (a VLM that actually sees the pixels) needs a model swap / second
    kernel — v77 Phase B — this only stops the silent drop."""
    try:
        if not isinstance(body, dict):
            return body
        _msgs = body.get("messages")
        if not isinstance(_msgs, list):
            return body
        _out_msgs = []
        _changed = False
        for _m in _msgs:
            if not isinstance(_m, dict):
                _out_msgs.append(_m)
                continue
            _imgs = _m.get("images")
            if not isinstance(_imgs, list) or not _imgs:
                _out_msgs.append(_m)
                continue
            _summaries = []
            for _im in _imgs:
                try:
                    _b64, _sum = inspect_attached_media_b64(_im, "image")
                except Exception:
                    _b64, _sum = None, "[Attached IMAGE]"
                _summaries.append(_sum or "[Attached IMAGE]")
            _new_m = {k: v for k, v in _m.items() if k != "images"}
            _text = str(_new_m.get("content") or "")
            _joined = "\n".join(_summaries)
            _new_m["content"] = ((_text + "\n\n" + _joined).strip() if _text else _joined)
            _out_msgs.append(_new_m)
            _changed = True
        if not _changed:
            return body
        _out = dict(body)
        _out["messages"] = _out_msgs
        return _out
    except Exception:
        return body


def _harness_context_check(parsed_body):
    # Spec section 3: launch stays 32K. A client asking for more gets 400
    # context_too_large naming the launch limit — never accept and crash.
    # v76.2 C2: image bytes are not prompt text — resolve the shared
    # stripper, falling back to an identical inline copy when this
    # function is loaded alone (unit tests exec each function in
    # isolation, where the module global is out of scope).
    _strip = globals().get("_harness_text_only_json")
    if _strip is None:
        def _strip(o):
            if isinstance(o, dict):
                return {_k: ("[attached image]" if _k in ("images", "image", "image_url") and isinstance(_v, (str, list)) else _strip(_v)) for _k, _v in o.items()}
            if isinstance(o, list):
                return [_strip(_v) for _v in o]
            if isinstance(o, str) and o.startswith("data:image/"):
                return "[attached image]"
            return o
    try:
        chars = 0
        sys_v = parsed_body.get("system") or parsed_body.get("instructions") or ""
        if isinstance(sys_v, str):
            chars += len(sys_v)
        elif isinstance(sys_v, list):
            chars += sum(len(str(b.get("text", ""))) for b in sys_v if isinstance(b, dict))
        raw = parsed_body.get("messages") or parsed_body.get("input") or ""
        chars += len(json.dumps(_strip(raw), ensure_ascii=False))  # v76.2 C2: image bytes are not prompt text
        est = max(1, chars // 4)
        client_max = 0
        for _k in ("max_tokens", "max_output_tokens"):
            try:
                if parsed_body.get(_k):
                    client_max = int(parsed_body[_k])
                    break
            except Exception:
                pass
        if est > HARNESS_LAUNCH_CTX:
            return {"error": {"message": "context_too_large: estimated prompt is ~%d tokens, above the launch context limit of %d tokens. Compact the conversation or shorten the prompt." % (est, HARNESS_LAUNCH_CTX),
                              "code": "context_too_large", "type": "invalid_request_error",
                              "launch_context_tokens": HARNESS_LAUNCH_CTX, "estimated_prompt_tokens": est,
                              "retry_guidance": "Do not retry: fix the request and send a new one."}}
        if client_max and est + client_max > HARNESS_LAUNCH_CTX:
            return {"error": {"message": "context_too_large: estimated prompt (~%d tokens) plus requested max_tokens (%d) exceeds the launch context limit of %d tokens." % (est, client_max, HARNESS_LAUNCH_CTX),
                              "code": "context_too_large", "type": "invalid_request_error",
                              "launch_context_tokens": HARNESS_LAUNCH_CTX, "estimated_prompt_tokens": est,
                              "retry_guidance": "Do not retry: fix the request and send a new one."}}
    except Exception:
        return None
    return None


# --- BMRBD v76 CONTEXT-ERRORS FIX (2026-11-19, Marup screenshots) --------
# Two live-v75 errors, same family:
#  (1) Claude Code 400: 'context_too_large: estimated prompt (~19946 tokens)
#      plus requested max_tokens (64000) exceeds the launch context limit of
#      32768 tokens.' The old _harness_context_check returned a raw 400 and
#      the dispatch returned it immediately — the client's work died even
#      though the prompt itself FITS. Fix: cap max_tokens to fit
#      (32768 - 19946 = 12822 max; the fit uses a 1024-token safety margin
#      for estimator error, so it caps to 11798 here) and proceed; compact
#      first when the prompt alone leaves no room for output.
#  (2) DeepSeek Harness stuck loop: after 'Output token limit reached', a
#      manual 'continue'/'go' re-sent the FULL bloated history (task + tool
#      calls + partial output), so the prompt was just as large and the
#      model produced one word ('Let') then hit the limit again — forever.
#      Fix: a bare 'continue' is rewritten to the minimal continuation
#      (system + original task + partial output + continue note), and the
#      history is compacted so there is room for output.
# The fit runs at dispatch for all three harness endpoints
# (/v1/chat/completions, /v1/messages, /v1/responses). It returns
# (fitted_body, error_dict_or_None). BMRBD v76.3 (Agent B, 2026-11-20):
# the error is ALWAYS None now — escalating compaction (L1 compact, L2
# aggressive cut + tool trim, L3 latest-turn-only, L4 truncate to budget)
# guarantees every request fits, so the context limit NEVER 400s. The
# old ONLY-400 branch (a prompt over the window even after compaction)
# is deleted: that was Marup's live Claude Code error (~39140 tokens).
# Compaction is marked on the body (_harness_compacted +
# _harness_compaction_level) instead of an error.
_HARNESS_FIT_SAFETY_MARGIN = 1024
_HARNESS_FIT_MIN_OUTPUT = 512
_HARNESS_FIT_MIN_OUTPUT_TOOLS = 2048
_HARNESS_CONTINUE_WORDS = frozenset({
    "continue", "go", "go on", "go ahead", "proceed", "resume", "keep going",
    "carry on", "continue please", "please continue",
    "continue from where you stopped", "continue from where it stopped",
    "continue from there", "continue the reply",
})


def _harness_message_text(msg):
    """Plain text of one message dict (OpenAI string content or Anthropic
    content-block list). Pure — unit-tested."""
    try:
        c = (msg or {}).get("content", "")
        if isinstance(c, str):
            return c
        if isinstance(c, list):
            return "\n".join(str(b.get("text", "")) for b in c if isinstance(b, dict))
        return str(c or "")
    except Exception:
        return ""


def _harness_fit_estimate(parsed_body):
    """Prompt-token estimate for the fit check: the same estimator as
    _harness_context_check (system + json.dumps(messages/input), chars//4)
    PLUS the tools (the engine counts tool schemas in the context window —
    the old check ignored them, so a 57-tool harness request under-counted
    by thousands of tokens). Returns (est, tools_est). Pure — unit-tested."""
    # v76.2 C2: image bytes are not prompt text — resolve the shared
    # stripper, falling back to an identical inline copy when this
    # function is loaded alone (unit tests exec each function in
    # isolation, where the module global is out of scope).
    _strip = globals().get("_harness_text_only_json")
    if _strip is None:
        def _strip(o):
            if isinstance(o, dict):
                return {_k: ("[attached image]" if _k in ("images", "image", "image_url") and isinstance(_v, (str, list)) else _strip(_v)) for _k, _v in o.items()}
            if isinstance(o, list):
                return [_strip(_v) for _v in o]
            if isinstance(o, str) and o.startswith("data:image/"):
                return "[attached image]"
            return o
    try:
        chars = 0
        sys_v = parsed_body.get("system") or parsed_body.get("instructions") or ""
        if isinstance(sys_v, str):
            chars += len(sys_v)
        elif isinstance(sys_v, list):
            chars += sum(len(str(b.get("text", ""))) for b in sys_v if isinstance(b, dict))
        raw = parsed_body.get("messages")
        if raw is None:
            raw = parsed_body.get("input") or ""
        chars += len(json.dumps(_strip(raw), ensure_ascii=False))  # v76.2 C2: image bytes are not prompt text
        est = max(1, chars // 4)
        tools_est = 0
        tools = parsed_body.get("tools")
        if isinstance(tools, list) and tools:
            tools_est = max(1, len(json.dumps(tools, ensure_ascii=False)) // 4)
        return est, tools_est
    except Exception:
        return 0, 0


def _harness_prune_response_input(items, parsed_body=None, force=False):
    """Prune a /v1/responses `input` item list the way the unified
    translator compacts long sessions (v34 fixed-anchor rule): keep the
    first item + the recent tail, drop the middle, and carry a ledger note
    (files created/inspected + commands executed in the dropped items) as
    a system message item so the work is not re-done. A function_call and
    its function_call_output are never split by the cut (the cutoff moves
    forward past a trailing output item, mirroring the translator).
    With force=True (v76.3 L2) the size thresholds are ignored and the
    list is always cut to first item + ledger + last 8 items.
    Returns (items, ledger_or_None) — the original list when nothing was
    pruned. Pure — unit-tested."""
    try:
        if not isinstance(items, list) or len(items) <= 2:
            return items, None
        total_chars = sum(len(json.dumps(m, ensure_ascii=False)) for m in items if isinstance(m, dict))
        if len(items) <= 28 and total_chars <= 68000 and not force:
            return items, None
        if force:
            # v76.3 L2: always cut to first item + ledger + last 8 items.
            cutoff = max(2, len(items) - 8)
        else:
            cutoff = max(1, ((len(items) - 14) // 16) * 16)
            cutoff = min(cutoff, max(1, len(items) - 8))
        while cutoff < len(items) - 4:
            cur = items[cutoff] if isinstance(items[cutoff], dict) else {}
            c_cur = json.dumps(cur.get("content", ""), ensure_ascii=False)
            if str(cur.get("role", "")) == "tool" or cur.get("type") == "function_call_output" or "tool_result" in c_cur or "<tool_response>" in c_cur:
                cutoff += 1
            else:
                break
        dropped = items[1:cutoff]
        files = []
        cmds = []
        decisions = []
        key_facts = []
        for om in dropped:
            if not isinstance(om, dict):
                continue
            om_str = json.dumps(om, ensure_ascii=False)
            # Unescape once: function_call `arguments` is a JSON string, so
            # its keys arrive backslash-escaped in the dump and the keyed
            # regexes below would miss them.
            om_unesc = om_str.replace('\\"', '"')
            for _txt in (om_str, om_unesc):
                for fm in re.finditer(r'"(?:file_path|filePath|path)"\s*:\s*"([^"]+)"', _txt):
                    fp = fm.group(1).strip()
                    if fp and fp not in files:
                        files.append(fp)
                for fm2 in re.finditer(r'<parameter=(?:file_path|filePath|path)>\s*([^<\n]+)', _txt):
                    fp = fm2.group(1).strip()
                    if fp and fp not in files:
                        files.append(fp)
                for cm in re.finditer(r'"command"\s*:\s*"([^"]{1,80})"', _txt):
                    cs = cm.group(1).strip()
                    if cs and cs not in cmds:
                        cmds.append(cs)
            for fm in re.finditer(r"([A-Za-z0-9_./\\-]+\.(?:py|js|ts|html|css|json|md|php|txt|sh))", om_unesc):
                fp = fm.group(1)
                if fp not in files:
                    files.append(fp)
            # v76.3 MERGE (item 6): the ledger also carries the
            # DECISIONS and KEY FACTS of the dropped items, so a
            # compacted /v1/responses session does not lose the main
            # thread the way the old files/commands-only ledger did.
            _om_txt = om_unesc.replace("\\n", "\n")
            for _ln in _om_txt.splitlines():
                _ls = _ln.strip().strip('"').strip()
                if not _ls or len(_ls) > 400:
                    continue
                if re.search(r"password|passwd|api[_ -]?key|secret\b|token\b|credential|private[_ -]?key", _ls, re.I):
                    continue
                _dm = re.match(r"(?i)^(?:[-\u2022*\d.)\s]*)?(?:decision|decided|agreed|chosen|choice)\s*:\s*(.+)$", _ls)
                if _dm:
                    _dv = _dm.group(1).strip().strip('"').strip()
                    if _dv and _dv not in decisions and len(decisions) < 10:
                        decisions.append(_dv[:160])
                    continue
                _fm2 = re.match(r"(?i)^(?:[-\u2022*\d.)\s]*)?(?:key fact|important|remember|note|fact)\s*:\s*(.+)$", _ls)
                if _fm2:
                    _fv = _fm2.group(1).strip().strip('"').strip()
                    if _fv and _fv not in key_facts and len(key_facts) < 10:
                        key_facts.append(_fv[:160])
        ledger_lines = ["[COMPACTED SESSION LEDGER — DO NOT REPEAT COMPLETED WORK]"]
        if files:
            ledger_lines.append("• Files already created/inspected in earlier steps: " + ", ".join(files[:40]))
        if cmds:
            ledger_lines.append("• Commands already executed in earlier steps: " + " | ".join(cmds[:15]))
        if decisions:
            ledger_lines.append("• Decisions made in earlier steps: " + "; ".join(decisions))
        if key_facts:
            ledger_lines.append("• Key facts from earlier steps: " + "; ".join(key_facts))
        ledger_lines.append("• Continue from the current step below without re-reading or recreating already-completed files.")
        ledger = "\n".join(ledger_lines)
        kept = [items[0]] + [{"type": "message", "role": "system", "content": ledger}] + list(items[cutoff:])
        return kept, ledger
    except Exception:
        return items, None


# --- BMRBD v76.3 CONTEXT NEVER-400 (Agent B, 2026-11-20) ------------------
# Marup's live Claude Code error (his PC, ~15:50): 'API Error: 400
# context_too_large: estimated prompt (~39140 tokens, tools included)
# leaves no room for output in the launch context limit of 32768 tokens.'
# The harness sent 'hi' but its full history + tool definitions totalled
# ~39,140 tokens. The v76.1 tight-fit only handled prompts that CAN fit;
# the outright-oversize case still returned the raw 400 (the ONLY-400
# branch in _harness_fit_request_body). Marup's HARD RULE: the context
# limit must NEVER happen. The helpers below implement ESCALATING
# COMPACTION so the fit ALWAYS returns (body, None):
#   L1 existing _harness_maybe_compact / _harness_prune_response_input
#   L2 aggressive cut (system + latest user + last 1-2 assistant turns)
#      AND tool-definition trim (the KEY GAP: L1 only touched messages,
#      never the tools list, so a tools-only oversize request could never
#      be fixed by compacting messages)
#   L3 latest-user-message-only + one-line summary + minimal/stubbed tools
#      (or no tools when the latest turn needs none)
#   L4 truncate the largest NON-SYSTEM message(s) to a token budget
#      (the system prompt is never truncated — v76.3 MERGE item 8)
# The fit targets total <= 32768 - floor - 256 (floor 512 with tools /
# 128 without, so a tool turn still has room for a complete call); L4
# truncates to the stricter 1024-token safety margin. The existing steps
# 4/5 then cap the output budget to the remaining room.
# The 400 is REMOVED as an outcome: the body carries _harness_compacted
# + _harness_compaction_level instead (do_POST pops both markers before
# the body reaches the engine, so the reply can say it was compacted).
_HARNESS_V763_TRUNC_MARKER = "\n[... %d characters truncated to fit the 32768-token context window ...]\n"


def _harness_truncate_text(text, max_chars):
    """Truncate long text keeping head + tail with a marker (v76.3 L4).
    Pure. Returns the original text when it already fits."""
    try:
        s = str(text or "")
        if max_chars is None or len(s) <= max_chars:
            return s
        if max_chars < 120:
            return s[:max(0, max_chars)]
        head = (max_chars * 2) // 3
        tail = max_chars - head
        # Resolve the marker defensively: unit tests exec this function
        # alone (AST extraction), where the module constant is out of
        # scope — same pattern as the _harness_text_only_json fallback.
        marker_tpl = globals().get(
            "_HARNESS_V763_TRUNC_MARKER",
            "\n[... %d characters truncated to fit the 32768-token context window ...]\n")
        marker = marker_tpl % (len(s) - max_chars)
        return s[:head] + marker + (s[-tail:] if tail > 0 else "")
    except Exception:
        return str(text or "")[:max_chars or 0]


def _harness_set_message_text(msg, new_text):
    """Copy of a message dict with its text replaced, preserving shape
    (plain-string content or Anthropic content-block list). Pure."""
    try:
        m = dict(msg or {})
        c = m.get("content", "")
        if isinstance(c, str) or c is None:
            m["content"] = new_text
        elif isinstance(c, list):
            new_list = []
            replaced = False
            for b in c:
                if isinstance(b, dict) and b.get("type") == "text" and not replaced:
                    nb = dict(b)
                    nb["text"] = new_text
                    new_list.append(nb)
                    replaced = True
                elif isinstance(b, dict) and b.get("type") == "text":
                    continue  # later text blocks are dropped: already truncated
                else:
                    new_list.append(b)
            if not replaced:
                new_list.insert(0, {"type": "text", "text": new_text})
            m["content"] = new_list
        else:
            m["content"] = new_text
        return m
    except Exception:
        return dict(msg or {})


def _harness_item_text(item):
    """Plain text of one /v1/responses `input` item: `content` (str/list),
    else `output` (function_call_output), else `arguments`
    (function_call). Pure."""
    try:
        if not isinstance(item, dict):
            return ""
        c = item.get("content", "")
        if isinstance(c, str) and c:
            return c
        if isinstance(c, list):
            return "\n".join(str(b.get("text", "")) for b in c if isinstance(b, dict))
        o = item.get("output", "")
        if isinstance(o, str) and o:
            return o
        if isinstance(o, list):
            return "\n".join(str(b.get("text", "")) if isinstance(b, dict) else str(b) for b in o)
        a = item.get("arguments", "")
        if isinstance(a, str):
            return a
        return _harness_message_text(item)
    except Exception:
        return ""


def _harness_set_item_text(item, new_text):
    """Copy of a /v1/responses `input` item with its text replaced
    (content, else output, else arguments). Pure."""
    try:
        it = dict(item or {})
        if "content" in it:
            return _harness_set_message_text(it, new_text)
        if "output" in it:
            it["output"] = new_text
            return it
        if "arguments" in it:
            it["arguments"] = new_text
            return it
        it["content"] = new_text
        return it
    except Exception:
        return dict(item or {})


def _harness_tool_names_referenced(body):
    """Tool names the conversation actually used: message `tool_calls`
    and /v1/responses `function_call` items. Pure."""
    names = set()
    try:
        msgs = (body or {}).get("messages") or []
        if isinstance(msgs, list):
            for m in msgs:
                if not isinstance(m, dict):
                    continue
                for tc in (m.get("tool_calls") or []):
                    if not isinstance(tc, dict):
                        continue
                    fn = tc.get("function") or {}
                    if isinstance(fn, dict) and fn.get("name"):
                        names.add(str(fn["name"]))
                    elif tc.get("name"):
                        names.add(str(tc["name"]))
        inp = (body or {}).get("input") or []
        if isinstance(inp, list):
            for it in inp:
                if isinstance(it, dict) and it.get("type") == "function_call" and it.get("name"):
                    names.add(str(it.get("name")))
    except Exception:
        pass
    return names


def _harness_latest_user_text(body):
    """Text of the latest user turn (messages, else responses input,
    else a plain-string input). Pure."""
    try:
        msgs = (body or {}).get("messages")
        if isinstance(msgs, list):
            for m in reversed(msgs):
                if isinstance(m, dict) and str(m.get("role") or "").lower() == "user":
                    return _harness_message_text(m)
        inp = (body or {}).get("input")
        if isinstance(inp, list):
            for it in reversed(inp):
                if isinstance(it, dict) and str(it.get("role") or "").lower() == "user":
                    return _harness_item_text(it)
        if isinstance(inp, str):
            return inp
    except Exception:
        pass
    return ""


def _harness_stub_tool(tool):
    """Minimal stub of one tool definition (v76.3 L2/L3): keeps the name
    + a short description so the model can still call it, drops the full
    JSON schema (the part that eats the window). Handles OpenAI
    {type:function, function:{...}} and flat {name, input_schema} shapes.
    Pure."""
    try:
        if not isinstance(tool, dict):
            return tool
        fn = tool.get("function")
        if isinstance(fn, dict):
            out = dict(tool)
            f2 = dict(fn)
            f2["description"] = str(f2.get("description") or "")[:120]
            f2["parameters"] = {"type": "object", "properties": {}}
            out["function"] = f2
            return out
        if tool.get("name"):
            out = dict(tool)
            out["description"] = str(out.get("description") or "")[:120]
            if "input_schema" in out:
                out["input_schema"] = {"type": "object", "properties": {}}
            if "parameters" in out:
                out["parameters"] = {"type": "object", "properties": {}}
            return out
        return tool
    except Exception:
        return tool


def _harness_trim_tools(tools, keep_full_names=None, drop_unreferenced=False):
    """Trim a tools list (v76.3 L2): tools in keep_full_names stay whole,
    every other tool becomes a stub (name + short description). With
    drop_unreferenced=True the unreferenced tools are removed entirely
    (L3). Pure — returns a new list."""
    try:
        keep = set(str(n) for n in (keep_full_names or []))
        out = []
        for t in (tools or []):
            if not isinstance(t, dict):
                continue
            name = None
            fn = t.get("function")
            if isinstance(fn, dict):
                name = fn.get("name")
            if name is None:
                name = t.get("name")
            if drop_unreferenced and name is not None and str(name) not in keep:
                continue
            if name is not None and str(name) in keep:
                out.append(t)
            else:
                out.append(_harness_stub_tool(t))
        return out
    except Exception:
        return list(tools or [])


def _harness_aggressive_cut_messages(msgs):
    """Level 2 cut (v76.3): keep the system message + the latest user
    message + the last 1-2 assistant turns (plus a tool-result turn that
    directly follows a kept assistant tool call), and a one-line summary
    naming the dropped turns + the original task. Returns
    (kept_msgs, dropped_count). Pure."""
    try:
        src = [m for m in (msgs or []) if isinstance(m, dict)]
        if len(src) <= 3:
            return list(src), 0
        sys_m = None
        sys_idx = None
        for i, m in enumerate(src):
            if str(m.get("role") or "").lower() in ("system", "developer"):
                sys_m, sys_idx = m, i
                break
        latest_user_idx = None
        for i in range(len(src) - 1, -1, -1):
            if str(src[i].get("role") or "").lower() == "user":
                latest_user_idx = i
                break
        asst_idxs = [i for i, m in enumerate(src)
                     if str(m.get("role") or "").lower() == "assistant"][-2:]
        keep_idx = set()
        if sys_idx is not None:
            keep_idx.add(sys_idx)
        if latest_user_idx is not None:
            keep_idx.add(latest_user_idx)
        for i in asst_idxs:
            keep_idx.add(i)
            if i + 1 < len(src) and str(src[i + 1].get("role") or "").lower() in ("tool", "function"):
                keep_idx.add(i + 1)
        kept = [src[i] for i in sorted(keep_idx)]
        dropped = len(src) - len(kept)
        if dropped <= 0:
            return list(src), 0
        goal = ""
        for m in src:
            if str(m.get("role") or "").lower() == "user":
                goal = _harness_message_text(m).strip()[:200]
                break
        summary = {"role": "system",
                   "content": "[Context compacted (level 2): %d earlier turn(s) dropped to fit the 32768-token window. Original task: %s]"
                   % (dropped, goal or "(not stated)")}
        out = []
        if sys_m is not None:
            out.append(sys_m)
        out.append(summary)
        out.extend([m for m in kept if m is not sys_m])
        return out, dropped
    except Exception:
        return list(msgs or []), 0


def _harness_latest_only_messages(msgs):
    """Level 3 cut (v76.3): keep ONLY the system message (truncated to
    2000 chars) + a one-line summary + the latest user message. Pure."""
    try:
        src = [m for m in (msgs or []) if isinstance(m, dict)]
        if len(src) <= 2:
            return list(src)
        sys_m = None
        for m in src:
            if str(m.get("role") or "").lower() in ("system", "developer"):
                sys_m = m
                break
        latest_user = None
        for m in reversed(src):
            if str(m.get("role") or "").lower() == "user":
                latest_user = m
                break
        goal = ""
        for m in src:
            if str(m.get("role") or "").lower() == "user":
                goal = _harness_message_text(m).strip()[:200]
                break
        out = []
        if sys_m is not None:
            txt = _harness_message_text(sys_m)
            if len(txt) > 2000:
                sys_m = _harness_set_message_text(sys_m, _harness_truncate_text(txt, 2000))
            out.append(sys_m)
        out.append({"role": "system",
                    "content": "[Context compacted (level 3): only the latest user message is kept; %d earlier turn(s) dropped. Original task: %s]"
                    % (len(src) - (2 if latest_user is not None else 1), goal or "(not stated)")})
        if latest_user is not None:
            out.append(latest_user)
        return out
    except Exception:
        return list(msgs or [])


def _harness_force_fit_to_budget(body, budget_tokens):
    """Last-resort guarantee (v76.3 L4): shrink `body` until the fit
    estimate is <= budget_tokens. Escalation inside one call: stub the
    tools, then drop unreferenced tools, then drop all tools (only when
    no tool is referenced), then truncate the largest shrinkable NON-SYSTEM message
    / input item. The system prompt (and top-level system/instructions)
    is NEVER truncated at L4 (v76.3 MERGE, item 8): history is shrunk
    to zero first; a system alone over budget is a configuration
    error, not a client error — the body is returned whole and the
    engine errors explicitly instead of running blind. Mutates
    the passed body dict (the fit's own copy) but NEVER the caller's
    original lists — every list/dict it rewrites is copied first.
    Returns True when the body fits, False only if nothing shrinkable
    remains (e.g. a lone system message over budget — the system is
    never truncated, so the fit returns the body whole instead of
    400ing). Pure apart from the passed body."""
    try:
        if not isinstance(body, dict):
            return False
        for _round in range(60):
            est, tools_est = _harness_fit_estimate(body)
            total = est + tools_est
            if total <= budget_tokens:
                return True
            over_chars = (total - budget_tokens) * 4 + 256
            # (a) Tools first: they are pure overhead once stubbed.
            tools = body.get("tools")
            if isinstance(tools, list) and tools:
                ref = _harness_tool_names_referenced(body)
                latest = _harness_latest_user_text(body)
                for t in tools:
                    if not isinstance(t, dict):
                        continue
                    _fn = t.get("function") or {}
                    _nm = (_fn.get("name") if isinstance(_fn, dict) else None) or t.get("name")
                    if _nm and str(_nm) in latest:
                        ref.add(str(_nm))
                trimmed = _harness_trim_tools(tools, ref)
                if trimmed != tools:
                    body["tools"] = trimmed
                    continue
                kept = _harness_trim_tools(tools, ref, drop_unreferenced=True)
                if kept != tools:
                    body["tools"] = kept
                    continue
                if not ref:
                    body["tools"] = []
                    continue
                # Referenced tools are already stubs: fall through to (b).
            # (b) Largest shrinkable message / input item.
            candidates = []
            for _kind in ("messages", "input"):
                _lst = body.get(_kind)
                if not isinstance(_lst, list):
                    continue
                for _i, _it in enumerate(_lst):
                    if not isinstance(_it, dict):
                        continue
                    try:
                        _n = len(json.dumps(_it, ensure_ascii=False))
                    except Exception:
                        _n = len(str(_it.get("content", "")))
                    candidates.append((_n, _kind, _i))
            candidates.sort(reverse=True)
            _shrunk = False
            for _n, _kind, _i in candidates:
                _lst = list(body.get(_kind) or [])
                if _i >= len(_lst):
                    continue
                _item = _lst[_i]
                _text = _harness_message_text(_item) if _kind == "messages" else _harness_item_text(_item)
                _protected = False
                if _kind == "messages":
                    _lu = -1
                    for _j, _mm in enumerate(_lst):
                        if isinstance(_mm, dict) and str(_mm.get("role") or "").lower() == "user":
                            _lu = _j
                    if _i == _lu or str(_item.get("role") or "").lower() in ("system", "developer"):
                        _protected = True
                elif _kind == "input":
                    if _i == 0:
                        _protected = True
                # v76.3 MERGE (item 8): a system/developer message is
                # NEVER truncated — shrink history to zero first. Skip
                # it and truncate the next-largest shrinkable item.
                if _kind == "messages" and str(_item.get("role") or "").lower() in ("system", "developer"):
                    continue
                if len(_text) > 120:
                    _new_chars = max(120, len(_text) - over_chars)
                    _new_text = _harness_truncate_text(_text, _new_chars)
                    if _kind == "messages":
                        _lst[_i] = _harness_set_message_text(_item, _new_text)
                    else:
                        _lst[_i] = _harness_set_item_text(_item, _new_text)
                    body[_kind] = _lst
                    _shrunk = True
                    break
                if len(_lst) > 1 and not _protected:
                    del _lst[_i]
                    body[_kind] = _lst
                    _shrunk = True
                    break
            if _shrunk:
                continue
            # (c) Plain-string responses input only. Top-level
            # system/instructions is NEVER truncated (v76.3 MERGE,
            # item 8): if nothing shrinkable remains, return False
            # and the fit returns the body whole (never a 400).
            _inp = body.get("input")
            if isinstance(_inp, str) and len(_inp) > 120:
                body["input"] = _harness_truncate_text(_inp, max(120, len(_inp) - over_chars))
                continue
            return False
        est, tools_est = _harness_fit_estimate(body)
        return est + tools_est <= budget_tokens
    except Exception:
        return False


# HARNESS v76.2 (F/R12): user-facing notice surfaced in the reply (and as
# an X-Harness-Compacted header on the proxy stream) whenever the history
# was compacted — silent compaction made the model "forgetting" earlier
# turns look like a bug.
_HARNESS_COMPACTED_NOTICE = (
    "Earlier turns in this conversation were compacted into a summary to fit "
    "the context window, so exact details of the earliest turns may not be "
    "recalled. Ask me to recap anything specific if a detail looks lost.")


def _harness_fit_request_body(parsed_body, target_path=None, default_max_tokens=None):
    """Fit a harness request into the 32768 launch window. Returns
    (body, error_or_None) — v76.3: the error is ALWAYS None (escalating
    compaction guarantees the fit; the 400 is removed as an outcome).
    The body is the original parsed_body when nothing changed, else a
    mutated copy (callers must re-serialize it). Never raises.
    Steps: (1) bare 'continue'/'go' -> minimal continuation; (2) compact
    when the prompt alone leaves no room for output; (2b) v76.3 L2/L3/L4
    escalating compaction when the prompt STILL leaves no room for the
    minimum output floor (512 with tools / 128 without) — aggressive cut
    + tool trim, then latest-turn-only, then truncate to budget; (3) cap
    max_tokens to fit; (4) cap EACH budget field independently, only ever
    reducing it (never copy one field into the other — the 2a4e88da fix);
    (5) when the client sent NO budget at all, cap the downstream
    effort-profile default (default_max_tokens, when given) to the SAME
    fit rule (prompt + default <= 32768 with the 1024-token safety margin)
    and inject it ONLY when capping actually bites — when the default
    already fits, the body is left untouched so downstream applies the
    full profile default. A prompt that fits but leaves little room
    proceeds on a small tight budget instead (v76.1)."""
    try:
        if not isinstance(parsed_body, dict):
            return parsed_body, None
        body = dict(parsed_body)
        changed = False
        # (1) Bare continuation: rewrite to the minimal continuation.
        msgs = body.get("messages")
        if isinstance(msgs, list) and msgs:
            last = msgs[-1] if isinstance(msgs[-1], dict) else None
            if last is not None and str(last.get("role") or "").lower() == "user":
                last_text = _harness_message_text(last).strip()
                low = last_text.lower()
                # Strip a trailing parenthetical note (Marup's actual text:
                # 'continue (aqnd slove Output token limit never come it agin)').
                core = re.sub(r"\s*\(.*?\)\s*$", "", low).strip()
                # Only a BARE continuation (exact phrase) is rewritten — a
                # 'continue …' carrying new instructions is left alone so
                # its detail is not dropped; the cap + compaction still
                # make it fit.
                is_bare = core in _HARNESS_CONTINUE_WORDS
                if is_bare:
                    # The partial output is the most recent assistant
                    # message WITH substantial text before the 'continue'
                    # (tool-call-only turns have no text — skip them); the
                    # task is the last user message before that. Require a
                    # substantial partial (else this is a fresh 'continue',
                    # not a resume).
                    partial = ""
                    for m in reversed(msgs[:-1]):
                        if isinstance(m, dict) and str(m.get("role") or "").lower() == "assistant":
                            _t = _harness_message_text(m)
                            if len(_t.strip()) >= 200:
                                partial = _t
                                break
                    if partial:
                        # The task is the most substantive user message
                        # (longest text) — in a multi-turn history the last
                        # user message before 'continue' is often a bare
                        # acknowledgment ('thanks, keep going'), not the
                        # task. Curate the input so the minimal continuation
                        # carries the real task, not the acknowledgment.
                        sys_m = None
                        task_m = None
                        for m in msgs[:-1]:
                            if not isinstance(m, dict):
                                continue
                            _r = str(m.get("role") or "").lower()
                            if _r in ("system", "developer") and sys_m is None:
                                sys_m = m
                            elif _r == "user":
                                if task_m is None or len(_harness_message_text(m)) > len(_harness_message_text(task_m)):
                                    task_m = m
                        _src = []
                        if sys_m is not None:
                            _src.append(sys_m)
                        if task_m is not None:
                            _src.append(task_m)
                        cont = _harness_minimal_continue_messages(_src, partial)
                        if cont and len(cont) < len(msgs):
                            body["messages"] = cont
                            msgs = cont
                            changed = True
        # (2) Estimate (messages + tools).
        est, tools_est = _harness_fit_estimate(body)
        total = est + tools_est
        has_tools = isinstance(body.get("tools"), list) and bool(body.get("tools"))
        min_out = _HARNESS_FIT_MIN_OUTPUT_TOOLS if has_tools else _HARNESS_FIT_MIN_OUTPUT
        # (3) If the prompt alone leaves no room for a minimum output plus
        # the safety margin, compact the history (forced — the 70%
        # threshold alone would not fire for a prompt under 22000 that is
        # still too large once tools are counted).
        # BMRBD v76.1 TIGHT FIT: when the prompt fits the window but leaves
        # less than min_out + margin room, do NOT 400 the long task —
        # proceed on a small output budget (steps 4/5 cap it to the real
        # remaining room) and let auto-continue / minimal continuation
        # carry the rest. Only total >= the window still errors.
        _tight_fit = False
        if total > HARNESS_LAUNCH_CTX - min_out - _HARNESS_FIT_SAFETY_MARGIN:
            msgs2 = body.get("messages")
            if isinstance(msgs2, list) and len(msgs2) > 2:
                compacted, _doc = _harness_maybe_compact(msgs2, body, force=True)
                if compacted is not msgs2:
                    body["messages"] = compacted
                    changed = True
                    # HARNESS v76.2 (F/R12): remember that this request was
                    # compacted — do_POST pops the marker into a per-request
                    # flag and the reply says so (see H11c/H11h-H11n).
                    body["_harness_compacted"] = True
                    est, tools_est = _harness_fit_estimate(body)
                    total = est + tools_est
            # BMRBD v76.1 CODEX: /v1/responses carries history as `input`
            # items (function_call / function_call_output), not `messages` —
            # the messages-only compaction above never ran for Codex, so a
            # long Codex session 400d once its input outgrew the window.
            # Prune it the same way the unified translator compacts long
            # sessions (first item + recent tail + ledger of dropped work).
            if total > HARNESS_LAUNCH_CTX - min_out - _HARNESS_FIT_SAFETY_MARGIN:
                inp = body.get("input")
                if isinstance(inp, list) and len(inp) > 2:
                    pruned, _ldoc = _harness_prune_response_input(inp, body)
                    if pruned is not inp:
                        body["input"] = pruned
                        changed = True
                        body["_harness_compacted"] = True
                        est, tools_est = _harness_fit_estimate(body)
                        total = est + tools_est
            if total > HARNESS_LAUNCH_CTX - min_out - _HARNESS_FIT_SAFETY_MARGIN:
                # BMRBD v76.3 NEVER-400 (Agent B): the prompt STILL leaves
                # no room for the minimum output floor even after L1
                # compaction. Escalate instead of 400ing — the old
                # ONLY-400 branch here was Marup's live Claude Code error
                # (~39140 tokens, latest message just 'hi'). The floor
                # below is the smallest output that can still complete a
                # turn (512 with tools — a complete tool call — else 128);
                # escalation targets total <= 32768 - floor - 256 so the
                # floor always fits with slack, and L4 truncates to the
                # stricter 1024-token safety margin so downstream
                # system-prompt additions stay inside the window too.
                _floor = 512 if has_tools else 128
                _room_needed = HARNESS_LAUNCH_CTX - _floor - 256
                # Level 2: aggressive cut (system + latest user + last
                # 1-2 assistant turns) + force-prune of responses input
                # + TRIM THE TOOL DEFINITIONS (L1 never touched tools).
                if total > _room_needed:
                    _did_l2 = False
                    _msgs_l2 = body.get("messages")
                    if isinstance(_msgs_l2, list) and len(_msgs_l2) > 3:
                        _cut, _dropped = _harness_aggressive_cut_messages(_msgs_l2)
                        if _dropped > 0:
                            body["messages"] = _cut
                            _did_l2 = True
                    _inp_l2 = body.get("input")
                    if isinstance(_inp_l2, list) and len(_inp_l2) > 3:
                        _pruned2, _ld2 = _harness_prune_response_input(_inp_l2, body, force=True)
                        if _pruned2 is not _inp_l2:
                            body["input"] = _pruned2
                            _did_l2 = True
                    _tools_l2 = body.get("tools")
                    if isinstance(_tools_l2, list) and _tools_l2:
                        _ref2 = _harness_tool_names_referenced(body)
                        _latest2 = _harness_latest_user_text(body)
                        for _t in _tools_l2:
                            if not isinstance(_t, dict):
                                continue
                            _fn2 = _t.get("function") or {}
                            _nm2 = (_fn2.get("name") if isinstance(_fn2, dict) else None) or _t.get("name")
                            if _nm2 and str(_nm2) in _latest2:
                                _ref2.add(str(_nm2))
                        _trimmed2 = _harness_trim_tools(_tools_l2, _ref2)
                        if _trimmed2 != _tools_l2:
                            body["tools"] = _trimmed2
                            _did_l2 = True
                    if _did_l2:
                        changed = True
                        body["_harness_compacted"] = True
                        body["_harness_compaction_level"] = 2
                        est, tools_est = _harness_fit_estimate(body)
                        total = est + tools_est
                        has_tools = isinstance(body.get("tools"), list) and bool(body.get("tools"))
                        _floor = 512 if has_tools else 128
                        _room_needed = HARNESS_LAUNCH_CTX - _floor - 256
                # Level 3: latest user message only + one-line summary +
                # minimal tool set (referenced tools as stubs; no tools at
                # all when the latest turn needs none).
                if total > _room_needed:
                    _did_l3 = False
                    _msgs_l3 = body.get("messages")
                    if isinstance(_msgs_l3, list) and len(_msgs_l3) > 2:
                        _only = _harness_latest_only_messages(_msgs_l3)
                        if len(_only) < len(_msgs_l3):
                            body["messages"] = _only
                            _did_l3 = True
                    _inp_l3 = body.get("input")
                    if isinstance(_inp_l3, list) and len(_inp_l3) > 2:
                        _first3 = _inp_l3[0]
                        _latest_u3 = None
                        for _it3 in reversed(_inp_l3):
                            if isinstance(_it3, dict) and str(_it3.get("role") or "").lower() == "user":
                                _latest_u3 = _it3
                                break
                        _new_inp3 = [_first3,
                                     {"type": "message", "role": "system",
                                      "content": "[Context compacted (level 3): earlier input items dropped to fit the 32768-token window.]"}]
                        if _latest_u3 is not None and _latest_u3 is not _first3:
                            _new_inp3.append(_latest_u3)
                        body["input"] = _new_inp3
                        _did_l3 = True
                    _tools_l3 = body.get("tools")
                    if isinstance(_tools_l3, list) and _tools_l3:
                        _ref3 = _harness_tool_names_referenced(body)
                        _latest3 = _harness_latest_user_text(body)
                        for _t in _tools_l3:
                            if not isinstance(_t, dict):
                                continue
                            _fn3 = _t.get("function") or {}
                            _nm3 = (_fn3.get("name") if isinstance(_fn3, dict) else None) or _t.get("name")
                            if _nm3 and str(_nm3) in _latest3:
                                _ref3.add(str(_nm3))
                        if not _ref3:
                            body["tools"] = []
                        else:
                            body["tools"] = [_harness_stub_tool(_t) for _t in
                                             _harness_trim_tools(_tools_l3, _ref3, drop_unreferenced=True)]
                        _did_l3 = True
                    if _did_l3:
                        changed = True
                        body["_harness_compacted"] = True
                        body["_harness_compaction_level"] = 3
                        est, tools_est = _harness_fit_estimate(body)
                        total = est + tools_est
                        has_tools = isinstance(body.get("tools"), list) and bool(body.get("tools"))
                        _floor = 512 if has_tools else 128
                        _room_needed = HARNESS_LAUNCH_CTX - _floor - 256
                # Level 4: a single message is still too large —
                # truncate the largest NON-SYSTEM text(s) to the budget.
                # The system prompt is never truncated (v76.3 MERGE,
                # item 8); if only a lone system remains over budget
                # the body is returned whole. The fit NEVER 400s.
                if total > _room_needed:
                    _budget_l4 = HARNESS_LAUNCH_CTX - _floor - _HARNESS_FIT_SAFETY_MARGIN
                    if _harness_force_fit_to_budget(body, _budget_l4):
                        changed = True
                        body["_harness_compacted"] = True
                        body["_harness_compaction_level"] = 4
                        est, tools_est = _harness_fit_estimate(body)
                        total = est + tools_est
                        has_tools = isinstance(body.get("tools"), list) and bool(body.get("tools"))
                    try:
                        diag_log("INFO", "Context fit: escalated compaction level %s (prompt ~%d incl. tools, limit %d)"
                                 % (body.get("_harness_compaction_level", "?"), total, HARNESS_LAUNCH_CTX))
                    except Exception:
                        pass
                # Prompt fits the window but leaves too little room:
                # tight fit — steps 4/5 cap the budget to the real
                # remaining room instead of erroring.
                _tight_fit = total > HARNESS_LAUNCH_CTX - min_out - _HARNESS_FIT_SAFETY_MARGIN
        # (4) Cap the requested output budget to fit the window. Cap EACH
        # budget field independently, only ever reducing it. A client may
        # send max_tokens and max_output_tokens with different values (or
        # one of them null/0), and the /v1/responses handler promotes
        # max_output_tokens into max_tokens downstream — so an uncapped
        # max_output_tokens would bypass the fit entirely. Never copy one
        # field into the other: the old sync line overwrote a correctly
        # capped max_output_tokens with a null/0 max_tokens, destroying
        # the cap (v76 re-check 2026-11-19: max_tokens None + max_output
        # 64000 came out as None; max_tokens 0 + max_output 64000 as 0).
        _capped_any = False
        for _k in ("max_tokens", "max_output_tokens"):
            try:
                _v = body.get(_k)
                if not _v:
                    continue
                _v = int(_v)
            except Exception:
                continue
            if total + _v > HARNESS_LAUNCH_CTX:
                capped = HARNESS_LAUNCH_CTX - total - _HARNESS_FIT_SAFETY_MARGIN
                if _tight_fit:
                    # A min_out floor here would push total + capped over
                    # the window. Use the real remaining room instead —
                    # but a tool turn needs room for a COMPLETE call
                    # (name + JSON args): 128 tokens truncates it mid-JSON
                    # and the client cannot execute it, so the turn
                    # "stops". Tool turns floor at 512 (cap 2048).
                    _tf_lo = 512 if has_tools else 128
                    _tf_hi = 2048 if has_tools else 512
                    capped = max(_tf_lo, min(_tf_hi, HARNESS_LAUNCH_CTX - total - 256))
                elif capped < min_out:
                    capped = min_out
                if _v != capped:
                    body[_k] = capped
                    _capped_any = True
                    try:
                        diag_log("INFO", "Context fit: %s capped %d -> %d (prompt ~%d incl. tools, limit %d)" % (_k, _v, capped, total, HARNESS_LAUNCH_CTX))
                    except Exception:
                        pass
        if _capped_any:
            changed = True
        # (5) BMRBD v76 §8 DEFAULT MAX_TOKENS HARDENING (2026-11-19):
        # when the client sent NO output budget at all, the effort profile
        # supplies a default downstream (up to 16384 for Max/Challenge) —
        # and a very large prompt + that default can still length-stop
        # (auto-continue catches it, not a 400, but the reply is cut).
        # Cap the default to fit the SAME rule as a client-sent budget:
        # prompt + default <= 32768 with the 1024-token safety margin.
        # The capped default is injected ONLY when capping actually bites
        # (capped < default); when the default already fits, the body is
        # left untouched so downstream applies the full profile default.
        # A falsy sent value (None/0) counts as "no budget sent": the old
        # downstream `if "max_tokens" not in body` check would see the key
        # present and never apply a default, leaving a null budget to the
        # engine. This step never copies one field into the other (step 4).
        if default_max_tokens is not None:
            try:
                _def = int(default_max_tokens)
            except Exception:
                _def = 0
            _sent_any = False
            for _k in ("max_tokens", "max_output_tokens"):
                try:
                    if body.get(_k):
                        _sent_any = True
                        break
                except Exception:
                    pass
            if _def > 0 and not _sent_any:
                _room = HARNESS_LAUNCH_CTX - total - _HARNESS_FIT_SAFETY_MARGIN
                if _tight_fit:
                    _room = max(512 if has_tools else 128, min(2048 if has_tools else 512, HARNESS_LAUNCH_CTX - total - 256))
                elif _room < min_out:
                    _room = min_out
                _capped_def = min(_def, _room)
                if _capped_def < _def:
                    body["max_tokens"] = _capped_def
                    changed = True
                    try:
                        diag_log("INFO", "Context fit: default max_tokens capped %d -> %d (prompt ~%d incl. tools, limit %d)" % (_def, _capped_def, total, HARNESS_LAUNCH_CTX))
                    except Exception:
                        pass
        return (body if changed else parsed_body), None
    except Exception:
        return parsed_body, None


# --- BMRBD v76 §8 ENGINE HTTP-ERROR RETRY (2026-11-19) -------------------
# The proxy's http_err branch used to pass an engine HTTP error through raw
# with no recovery. Dispatch fit prevents most context errors in practice,
# but the engine can still 400/429/5xx mid-flight (context full on the
# engine side, rate limit, transient 5xx). These pure helpers classify the
# error and build the recovery body; the proxy branches (streaming +
# non-streaming) drive the bounded retry loop (max 3 recovery attempts).
# Rules (checklist §8):
#  - Context error (context_too_long / context_length_exceeded /
#    model_context_window_exceeded, or a 400 naming a token/context limit):
#    compact/prune FIRST, then retry. A 400 token-limit error never
#    succeeds on retry as-is — it is never retried without compacting.
#  - stop_reason / finish_reason max_tokens (length): escalate max_tokens
#    (up to the fit cap) and retry; if still hitting the ceiling, append
#    the partial assistant output + inject a continue marker (the existing
#    auto-continue does that half; _px_continue_body escalates the budget).
#    NEVER treat a truncated string as complete.
#  - 429: classify BEFORE retrying. Transient rate limit -> follow
#    Retry-After when present, else capped exponential backoff + jitter.
#    credit_balance_exhausted / insufficient_quota / spend-limit / quota
#    429 -> NEVER retry (needs an account action). slow_down -> ramp
#    gradually (longer base delay, no spike).
#  - Streaming rule: retry ONLY failures BEFORE the first chunk arrives —
#    once partial tokens reached the client, a retry cannot replay cleanly.
_ENGINE_RETRY_MAX_ATTEMPTS = 3
_ENGINE_RETRY_BASE_DELAY_S = 1.0
_ENGINE_RETRY_MAX_DELAY_S = 30.0
_ENGINE_RETRY_QUOTA_PATTERNS = (
    "credit_balance_exhausted", "insufficient_quota", "insufficient quota",
    "quota_exceeded", "quota exceeded", "spend-limit", "spend limit",
    "billing", "payment_required", "account_suspended", "plan_limit",
    "rate_limit_exceeded_billing",
)
_ENGINE_RETRY_CONTEXT_PATTERNS = (
    "context_too_long", "context_length_exceeded",
    "model_context_window_exceeded", "context window", "context length",
    "maximum context", "too many tokens", "token limit", "tokens exceed",
    "exceeds the context", "exceeds the maximum", "prompt_too_long",
    "input_too_long", "max_tokens", "max_output_tokens",
)


def _engine_retry_parse_http_error(val):
    """Parse a proxy http_err value ('HTTP 429: {...}' or a raw transport
    error string) -> (status_or_None, message_text, retry_after_s_or_None).
    The streaming worker appends a ' retry_after=<secs>' marker from the
    engine's Retry-After header; it is parsed here (and stripped before
    any user-visible surfacing). Pure — unit-tested. Never raises."""
    try:
        s = str(val or "")
        status = None
        m = re.search(r"^\s*HTTP\s+(\d{3})\b", s)
        if m:
            try:
                status = int(m.group(1))
            except Exception:
                status = None
        ra = None
        mra = re.search(r"retry_after\s*=\s*(\d+(?:\.\d+)?)", s, re.I)
        if not mra:
            mra = re.search(r"retry-after\s*:\s*(\d+(?:\.\d+)?)", s, re.I)
        if mra:
            try:
                ra = float(mra.group(1))
            except Exception:
                ra = None
        return status, s, ra
    except Exception:
        return None, str(val or ""), None


def _engine_retry_backoff_delay(attempt, retry_after=None, slow_down=False):
    """Capped exponential backoff + jitter for one retry attempt (attempt
    is 1-based). Transient: 1s, 2s, 4s (+ up to 50% jitter), capped at 30s.
    slow_down ramps gradually instead: 5s, 10s, 20s. An explicit Retry-After
    (seconds) is followed, capped at 30s. Pure — unit-tested."""
    try:
        if retry_after is not None:
            try:
                ra = float(retry_after)
            except Exception:
                ra = 0.0
            if ra > 0:
                return max(0.0, min(float(ra), _ENGINE_RETRY_MAX_DELAY_S))
        base = 5.0 if slow_down else _ENGINE_RETRY_BASE_DELAY_S
        delay = base * (2.0 ** max(0, int(attempt) - 1))
        if slow_down:
            delay = min(delay, 20.0)
        else:
            delay = min(delay, _ENGINE_RETRY_MAX_DELAY_S)
        try:
            import random as _random
            delay = delay * (1.0 + _random.uniform(0.0, 0.5))
        except Exception:
            pass
        return min(delay, _ENGINE_RETRY_MAX_DELAY_S)
    except Exception:
        return _ENGINE_RETRY_BASE_DELAY_S


def _engine_retry_decide(val, first_chunk_seen=False):
    """Classify an engine failure -> decision dict:
    {"retry": bool, "action": "compact"|"escalate"|"backoff"|"no_retry",
     "delay": float, "reason": str, "status": int|None,
     "retry_after": float|None, "slow_down": bool}.
    The delay is the attempt-1 figure; callers recompute it per attempt
    with _engine_retry_backoff_delay(attempt, retry_after, slow_down).
    Pure — unit-tested. Never raises. first_chunk_seen=True (streaming,
    partial tokens already reached the client) forces no_retry."""
    try:
        if first_chunk_seen:
            return {"retry": False, "action": "no_retry", "delay": 0.0,
                    "reason": "partial tokens already streamed to the client; a retry cannot replay cleanly",
                    "status": None, "retry_after": None, "slow_down": False}
        status, text, retry_after = _engine_retry_parse_http_error(val)
        low = text.lower()
        # Quota / billing 429s are NEVER retried, whatever the status.
        if any(p in low for p in _ENGINE_RETRY_QUOTA_PATTERNS):
            return {"retry": False, "action": "no_retry", "delay": 0.0,
                    "reason": "quota/billing error — needs an account action, retrying cannot help",
                    "status": status, "retry_after": None, "slow_down": False}
        # Context errors: compact first, then retry. (Also covers a 400
        # naming a token/context limit, and a length finish signal.)
        if any(p in low for p in _ENGINE_RETRY_CONTEXT_PATTERNS):
            return {"retry": True, "action": "compact", "delay": 0.0,
                    "reason": "engine context error — compact/prune first, then retry",
                    "status": status, "retry_after": None, "slow_down": False}
        if status == 429:
            slow = "slow_down" in low or "slow down" in low
            delay = _engine_retry_backoff_delay(1, retry_after=retry_after, slow_down=slow)
            return {"retry": True, "action": "backoff", "delay": delay,
                    "reason": ("engine rate limit (slow_down — ramping gradually)" if slow
                               else "engine rate limit — backoff" + (" (Retry-After %.0fs)" % retry_after if retry_after else "")),
                    "status": status, "retry_after": retry_after, "slow_down": slow}
        if status in (408, 425, 500, 502, 503, 504, 529):
            return {"retry": True, "action": "backoff",
                    "delay": _engine_retry_backoff_delay(1, retry_after=retry_after),
                    "reason": "transient engine HTTP %d — backoff and retry" % status,
                    "status": status, "retry_after": retry_after, "slow_down": False}
        if status is None:
            # No HTTP status: transport error (timeout / connection reset /
            # DNS) — transient, backoff and retry.
            return {"retry": True, "action": "backoff",
                    "delay": _engine_retry_backoff_delay(1),
                    "reason": "transport error reaching the engine — backoff and retry",
                    "status": None, "retry_after": None, "slow_down": False}
        # Everything else (400 non-context, 401/403/404/405/422, ...) is a
        # request/client problem: retrying as-is cannot succeed.
        return {"retry": False, "action": "no_retry", "delay": 0.0,
                "reason": "engine HTTP %s is not retryable — fix the request" % (status,),
                "status": status, "retry_after": None, "slow_down": False}
    except Exception:
        return {"retry": False, "action": "no_retry", "delay": 0.0,
                "reason": "classification failed — surfacing the error honestly",
                "status": None, "retry_after": None, "slow_down": False}


def _engine_retry_for_finish_reason(finish_reason):
    """Map an engine finish/stop reason -> recovery action or None.
    'length' / 'max_tokens' -> escalate the budget and retry (the caller
    appends the partial output + continue marker). Anything else -> None
    (a 'stop' is complete; a truncated string is never treated as one).
    Pure — unit-tested."""
    try:
        fr = str(finish_reason or "").strip().lower()
        if fr in ("length", "max_tokens", "max-tokens", "output_limit", "token_limit"):
            return "escalate"
        return None
    except Exception:
        return None


def _engine_retry_recovery_body(body, partial_text, decision, orig_msgs=None):
    """Build the retry body for a classified engine failure. Returns a NEW
    body dict, or None when no recovery is possible (caller surfaces the
    original error honestly). Never raises. Actions:
    - compact: force-compact the history, then re-run the fit (caps the
      budget again). Returns None when the prompt cannot fit even compacted
      or when nothing was actually pruned/capped (a retry would fail
      identically — do not loop on it).
    - escalate: raise max_tokens toward the fit cap (double, min +1024)
      and, when partial output exists, rebuild as a minimal continuation
      (partial + continue marker) from the ORIGINAL messages so the retry
      does not re-send the bloated history.
    - backoff: same body, unchanged (a plain retry after the delay).
    Depends on _harness_maybe_compact / _harness_fit_request_body /
    _harness_minimal_continue_messages / _harness_fit_estimate (stubbed in
    tests the same way as the fit tests)."""
    try:
        if not isinstance(body, dict) or not isinstance(decision, dict):
            return None
        action = str(decision.get("action") or "")
        if action == "backoff":
            return dict(body)
        if action == "compact":
            new_body = dict(body)
            msgs = new_body.get("messages")
            if isinstance(msgs, list) and len(msgs) > 2:
                compacted, _doc = _harness_maybe_compact(msgs, new_body, force=True)
                if compacted is not msgs:
                    new_body["messages"] = compacted
            fitted, err = _harness_fit_request_body(new_body, None)
            if err is not None:
                return None
            if fitted is new_body and new_body.get("messages") is msgs:
                # Neither compaction nor the fit changed anything: the
                # retry would fail identically. Do not loop on it.
                return None
            return fitted
        if action == "escalate":
            new_body = dict(body)
            est, tools_est = _harness_fit_estimate(new_body)
            total = est + tools_est
            cap = HARNESS_LAUNCH_CTX - total - _HARNESS_FIT_SAFETY_MARGIN
            if cap < _HARNESS_FIT_MIN_OUTPUT:
                cap = _HARNESS_FIT_MIN_OUTPUT
            try:
                cur = int(new_body.get("max_tokens") or new_body.get("max_output_tokens") or 1024)
            except Exception:
                cur = 1024
            new_budget = min(cap, max(cur * 2, cur + 1024))
            if new_budget <= cur:
                # No headroom to escalate into: fall back to a plain
                # minimal continuation at the same budget (the partial +
                # continue marker still help), unless there is no partial
                # at all — then there is nothing to retry with.
                if not (partial_text or "").strip():
                    return None
                new_budget = cur
            new_body["max_tokens"] = new_budget
            if (partial_text or "").strip():
                src = orig_msgs if isinstance(orig_msgs, list) and orig_msgs else new_body.get("messages")
                if isinstance(src, list) and src:
                    cont = _harness_minimal_continue_messages(src, partial_text)
                    if cont:
                        new_body["messages"] = cont
            return new_body
        return None
    except Exception:
        return None


# --- Spec section 5: request_id dedupe (60s window) -----------------------
_HARNESS_DEDUPE = {}
_HARNESS_DEDUPE_LOCK = threading.Lock()
_HARNESS_DEDUPE_INFLIGHT = {}


def _harness_request_id(parsed_body, headers=None):
    rid = ""
    try:
        if isinstance(parsed_body, dict):
            rid = str(parsed_body.get("request_id") or parsed_body.get("requestId") or "").strip()
        if not rid and headers is not None:
            rid = str(headers.get("X-Request-Id") or headers.get("x-request-id") or "").strip()
    except Exception:
        pass
    return rid or None


def _h6_caller_scope(handler):
    """v76.5 H6: caller scope string for one chat request.

    "key:<api-key id>" for managed-key callers, "user:<username>" for
    session-token (web dashboard) callers, "anon" otherwise. The API-key
    id is a non-secret public id; no secret is ever placed in the scope.
    Namespaces the harness session key, the request_id dedupe/inflight
    registries, the cancel registry and the think-skip registry, so a
    web chat message and an API/harness call can never share (or
    cancel / skip / replay) each other's state. Never raises.
    """
    caller = "anon"
    try:
        hdrs = getattr(handler, "headers", None) or {}
        _tok = str(hdrs.get("Authorization") or "").replace("Bearer ", "").replace("bearer ", "").strip()
        if not _tok:
            _tok = str(hdrs.get("x-api-key") or "").strip()
        if _tok:
            try:
                _rec = _v76_apikey_find_by_secret(_BMRBD_STATE, _tok)
            except Exception:
                _rec = None
            if isinstance(_rec, dict) and _rec.get("id"):
                caller = "key:" + str(_rec.get("id"))
        if caller == "anon":
            try:
                _u = _get_user_by_token(hdrs.get("Authorization"), hdrs.get("x-api-key"))
            except Exception:
                _u = None
            if isinstance(_u, dict) and (_u.get("username") or _u.get("email")):
                caller = "user:" + str(_u.get("username") or _u.get("email"))
    except Exception:
        pass
    return caller


def _h6_active_key(scope, cid):
    """v76.5 H6: cancel-registry key — caller scope + request_id when a
    scope is known, the bare request_id otherwise (pre-patch /
    scope-less callers)."""
    try:
        _c = str(cid or "")
        _s = str(scope or "")
        return (_s + "|" + _c) if _s else _c
    except Exception:
        return str(cid or "")


def _h6_dedupe_key(path, request_id, scope=None):
    """v76.5 H6: dedupe/inflight key — (scope, path, request_id) when a
    caller scope is known, the legacy (path, request_id) otherwise."""
    try:
        if scope:
            return (str(scope), str(path), str(request_id))
        return (str(path), str(request_id))
    except Exception:
        return (str(path), str(request_id))


def _harness_dedupe_lookup(path, request_id, scope=None):
    if not request_id:
        return None
    key = _h6_dedupe_key(path, request_id, scope)
    with _HARNESS_DEDUPE_LOCK:
        ent = _HARNESS_DEDUPE.get(key)
        if not ent:
            return None
        if time.time() - ent["ts"] > HARNESS_DEDUPE_WINDOW_S:
            _HARNESS_DEDUPE.pop(key, None)
            return None
        return ent


def _harness_dedupe_store(path, request_id, status, ctype, body_bytes, scope=None):
    if not request_id or not isinstance(body_bytes, (bytes, bytearray)):
        return
    key = _h6_dedupe_key(path, request_id, scope)
    with _HARNESS_DEDUPE_LOCK:
        _HARNESS_DEDUPE[key] = {"ts": time.time(), "status": int(status), "ctype": ctype, "body": bytes(body_bytes)}
        _now = time.time()
        for _k in [k for k, v in _HARNESS_DEDUPE.items() if _now - v["ts"] > HARNESS_DEDUPE_WINDOW_S]:
            _HARNESS_DEDUPE.pop(_k, None)


def _harness_inflight_check(path, request_id, scope=None):
    if not request_id:
        return False
    key = _h6_dedupe_key(path, request_id, scope)
    with _HARNESS_DEDUPE_LOCK:
        ts = _HARNESS_DEDUPE_INFLIGHT.get(key)
        if ts is None:
            return False
        if time.time() - ts > HARNESS_DEDUPE_WINDOW_S:
            _HARNESS_DEDUPE_INFLIGHT.pop(key, None)
            return False
        return True


def _harness_inflight_mark(path, request_id, scope=None):
    if not request_id:
        return
    with _HARNESS_DEDUPE_LOCK:
        _HARNESS_DEDUPE_INFLIGHT[_h6_dedupe_key(path, request_id, scope)] = time.time()


# --- Spec section 4: compaction (70% trigger, vault-persisted state doc) ---
_HARNESS_SESSIONS = {}
_HARNESS_SESSION_LOCK = threading.Lock()


def _harness_session_key(parsed_body):
    try:
        first_user = ""
        raw = parsed_body.get("messages") or parsed_body.get("input") or []
        if isinstance(raw, str):
            first_user = raw
        elif isinstance(raw, list):
            for _m in raw:
                if isinstance(_m, dict) and _m.get("role") == "user":
                    _c = _m.get("content", "")
                    if isinstance(_c, list):
                        _c = "\n".join(str(b.get("text", "")) for b in _c if isinstance(b, dict))
                    first_user = str(_c or "")
                    break
        # BMRBD v76.5 H6: namespace the session by caller+path when
        # the request carries the do_POST stamps (_harness_scope =
        # caller, _harness_path = endpoint). Before this, the key
        # was ONLY the first user message — a web chat and an
        # API/harness call starting with the same text (e.g. "hi")
        # shared one session record, so state_doc / turns /
        # delegations / the vault full-conversation record
        # overwrote each other. No stamp -> the old key.
        _scope = ""
        _spath = ""
        try:
            if isinstance(parsed_body, dict):
                _scope = str(parsed_body.get("_harness_scope") or "")
                _spath = str(parsed_body.get("_harness_path") or "")
        except Exception:
            _scope = ""
            _spath = ""
        _prefix = ((_scope + "|") if _scope else "") + ((_spath + "|") if _spath else "")
        seed = _prefix + (first_user or "default")[:200] + "|harness"
        return hashlib.md5(seed.encode("utf-8", errors="ignore")).hexdigest()[:16]
    except Exception:
        return "default"


# BMRBD v76.1 — KEY-FACTS PRESERVATION (2026-11-19): the old builder never
# populated `decisions` (always "(none recorded)") and kept no key facts at
# all, so compaction could silently drop the main thread. The state doc now
# carries a KEY FACTS block: explicitly marked facts/decisions from the
# thread, plus any KEY FACTS / DECISIONS carried forward from a previous
# [STATE — compacted ...] block, so a second compaction never drops them.
# File paths are also scanned out of tool_call arguments (coding tools
# carry the paths there, not in content). Lines naming credentials are
# NEVER captured as facts/decisions — secrets live in the vault, never in
# a state document.
_HARNESS_STATE_FACT_RES = (
    re.compile(r"^[\s\-•*\d.)]*(key fact|important|remember|note|fact)\s*:", re.I),
)
_HARNESS_STATE_DECISION_RES = (
    re.compile(r"^[\s\-•*\d.)]*(decision|decided|agreed|chosen|choice)\s*:", re.I),
    re.compile(r"\bwe (decided|will use|are using|chose|agreed)\b", re.I),
    re.compile(r"\b(decision is|decided to|going with)\b", re.I),
)
# BMRBD v76.3 QUALITY (G) — durable preserved block: decisions + key facts
# live in a dedicated section of the state doc, one verbatim item per line,
# so re-compaction can carry them forward WITHOUT ";"-splitting or
# truncating them (the v76.1 legacy "DECISIONS: a; b" line did both).
_HARNESS_PRESERVED_HDR = ("[PRESERVED — DECISIONS AND KEY FACTS — NEVER DROP: "
                          "carry this block verbatim into every later summary]")
_HARNESS_PRESERVED_END = "[END PRESERVED]"
# v76.3 (Agent D): `token`/`secret` carry a RIGHT word boundary.
# The old bare `token` matched the ordinary word "tokens", so every
# decision/fact line mentioning token budgets ("launch window is
# 32768 tokens") was silently dropped from the state doc — exactly
# the "compaction loses the main things" failure. `token\b` still
# catches "my_token", "api token", "token:" but not "tokens".
_HARNESS_STATE_SECRET_RES = re.compile(r"password|passwd|api[_ -]?key|secret\b|token\b|credential|private[_ -]?key", re.I)


def _harness_build_state_document(messages):
    # BMRBD v76.3 QUALITY (G) — compaction NEVER loses the main things.
    # Design: a dedicated, durable [PRESERVED ...] block at the TOP of the doc
    # holds every decision + key fact VERBATIM, one item per line ("DECISION:
    # <text>" / "KEY FACT: <text>"). Re-compaction parses that block
    # line-by-line and merges it with freshly extracted items (append/merge,
    # exact-dedupe, never overwrite-and-lose). The legacy single-line
    # "DECISIONS: a; b" / "KEY FACTS: a; b" lines are still emitted for older
    # readers, but the new parser ignores them whenever the preserved block
    # is present (splitting them on ";" would corrupt items that contain
    # ";" and the old 160-char cap truncated long items). Items are stored
    # whole (cap 1000 chars/item, 40 items per section — a bound against
    # unbounded growth, far above any real decision/fact). The block is
    # emitted FIRST so even a doc-size cap cuts DONE/LEFT/ERRORS, never it.
    # Secrets are never captured (fresh extraction AND carry-forward).
    _hdr = globals().get("_HARNESS_PRESERVED_HDR", "[PRESERVED — DECISIONS AND KEY FACTS — NEVER DROP: carry this block verbatim into every later summary]")
    _end = globals().get("_HARNESS_PRESERVED_END", "[END PRESERVED]")
    goal = ""
    _carried_goal = ""
    decisions = []
    key_facts = []
    files = []
    done = []
    left = []
    errors = []

    def _strip_label(item):
        return re.sub(r"^(decision|decided|key fact|fact|important|remember|note)\s*:\s*", "", (item or "").strip(), flags=re.I).strip()

    def _add(lst, item, cap=40):
        item = (item or "").strip()
        if not item or item in lst:
            return
        # NOTE: no secret check here — the line-level filter in the
        # fresh-extraction pass already blocks secret-bearing lines at
        # capture, and a check here would also drop legitimate policy
        # decisions ABOUT keys/passwords ("all API keys stay in the
        # vault"). Carried-forward items were filtered at creation.
        if len(lst) < cap:
            lst.append(item[:1000])

    def _msg_text(m):
        c = m.get("content", "")
        if isinstance(c, list):
            c = "\n".join(str(b.get("text", "")) for b in c if isinstance(b, dict))
        return str(c or "")

    # Carry forward (pass 0): the GOAL line of a previous state doc is
    # the goal — re-deriving it from the first surviving user turn
    # would turn GOAL into a filler turn after the original goal turn
    # was compacted away.
    for m in (messages or []):
        if not isinstance(m, dict):
            continue
        c = _msg_text(m)
        if "[STATE" not in c or "compacted" not in c:
            continue
        for line in c.splitlines():
            _gm = re.match(r"^GOAL:\s*(.*)$", line.strip())
            if (_gm and _gm.group(1).strip() and _gm.group(1).strip() != "(not stated)"
                    and not _HARNESS_STATE_SECRET_RES.search(_gm.group(1))):
                # v76.3 MERGE (D F2): a carried GOAL is secret-checked
                # too — a pre-v76.3 doc could carry a credential goal.
                _carried_goal = _gm.group(1).strip()[:600]
                break
        if _carried_goal:
            break
    if _carried_goal:
        goal = _carried_goal
    # Carry forward (pass 1): parse the [PRESERVED] block line-by-line.
    # Fall back to the legacy ";"-joined lines ONLY when no preserved
    # block exists anywhere (docs written by pre-v76.3 code).
    _found_block = False
    for m in (messages or []):
        if not isinstance(m, dict):
            continue
        c = _msg_text(m)
        if _hdr not in c:
            continue
        _in = False
        for line in c.splitlines():
            ls = line.strip()
            if ls == _hdr:
                _in = True
                _found_block = True
                continue
            if _in and ls == _end:
                _in = False
                continue
            if not _in:
                continue
            if ls.startswith("DECISION:"):
                _add(decisions, _strip_label(ls[len("DECISION:"):]))
            elif ls.startswith("KEY FACT:"):
                _add(key_facts, _strip_label(ls[len("KEY FACT:"):]))
    if not _found_block:
        for m in (messages or []):
            if not isinstance(m, dict):
                continue
            c = _msg_text(m)
            if "[STATE" not in c or "compacted" not in c:
                continue
            for line in c.splitlines():
                ls = line.strip()
                _mm = re.match(r"^(KEY FACTS|DECISIONS)\s*:\s*(.*)$", ls)
                if not _mm:
                    continue
                _body = _mm.group(2).strip()
                if not _body or _body == "(none recorded)":
                    continue
                _target = key_facts if _mm.group(1) == "KEY FACTS" else decisions
                for _part in _body.split(";"):
                    _add(_target, _strip_label(_part))
    for m in (messages or []):
        if not isinstance(m, dict):
            continue
        c = _msg_text(m)
        # File paths also live in tool_call arguments (coding tools carry
        # the paths there, not in content) — scan them even when the
        # message has no visible content (tool-call-only turns), so the
        # scan runs BEFORE the empty-content guard below.
        _scan = c
        _tc = m.get("tool_calls")
        if isinstance(_tc, list) and _tc:
            _scan = _scan + "\n" + json.dumps(_tc, ensure_ascii=False)
        for fm in re.finditer(r"([A-Za-z0-9_./\\-]+\.(?:py|js|ts|html|css|json|md|php|txt|sh))", _scan):
            fp = fm.group(1)
            if fp not in files:
                files.append(fp)
        if not c.strip():
            continue
        # v76.3 (Agent D): a previous [STATE — compacted] block is
        # already distilled — the carry-forward above re-extracted its
        # GOAL / DECISIONS / KEY FACTS / FILES. Scanning it again only
        # re-injects its own summary lines ("DONE: (see kept turns)"
        # becomes "DONE: DONE: ...") and stale errors, so skip it here.
        if "[STATE" in c and "compacted" in c:
            continue
        # v76.3 (Agent D): a credential-bearing message must never
        # become the GOAL — secrets live in the vault, never in a state
        # document (the old code took the first user message blindly,
        # so "password: ..." became the GOAL line).
        if not goal and m.get("role") == "user" and len(c.strip()) > 8 and not _HARNESS_STATE_SECRET_RES.search(c):
            goal = c.strip()[:600]
        _in_block = False
        for line in c.splitlines():
            ls = line.strip()
            if not ls:
                continue
            # State-doc structure is carried forward by passes 0/1, never
            # re-ingested as fresh facts: the [PRESERVED] block lines,
            # the "[STATE — compacted ...]" stamp, and the GOAL:/
            # DECISIONS:/KEY FACTS:/DONE:/... lines of a previous doc.
            if ls == _hdr:
                _in_block = True
                continue
            if _in_block and ls == _end:
                _in_block = False
                continue
            if _in_block:
                continue
            if ls.startswith("[STATE") and "compacted" in ls:
                continue
            if re.match(r"^(GOAL|DECISIONS|KEY FACTS|FILES CHANGED/CREATED|DONE|LEFT|OPEN ERRORS|MUST-NOT-RE-DERIVE)\s*:", ls):
                continue
            if re.match(r"^(done|completed|finished)\b", ls, re.I):
                done.append(ls[:160])
            elif re.match(r"^(todo|left|remaining|next)\b", ls, re.I):
                left.append(ls[:160])
            elif "error" in ls.lower()[:80] and len(ls) < 200:
                errors.append(ls[:160])
            # Secrets are never captured as facts/decisions (the vault
            # holds them); done/left/error lines above are unaffected.
            if not _HARNESS_STATE_SECRET_RES.search(ls):
                if any(rx.search(ls) for rx in _HARNESS_STATE_DECISION_RES):
                    _add(decisions, _strip_label(ls))
                elif any(rx.search(ls) for rx in _HARNESS_STATE_FACT_RES):
                    _add(key_facts, _strip_label(ls))
    _block_lines = [_hdr]
    for _d in decisions:
        _block_lines.append("DECISION: " + _d)
    for _f in key_facts:
        _block_lines.append("KEY FACT: " + _f)
    _block_lines.append(_end)
    _block = "\n".join(_block_lines)
    _rest_lines = ["GOAL: " + (goal or "(not stated)"),
             "DECISIONS: " + ("; ".join(decisions) if decisions else "(none recorded)"),
             "KEY FACTS: " + ("; ".join(key_facts) if key_facts else "(none recorded)"),
             "FILES CHANGED/CREATED: " + (", ".join(files[:30]) if files else "(none recorded)"),
             "DONE: " + ("; ".join(done[:10]) if done else "(see kept turns)"),
             "LEFT: " + ("; ".join(left[:10]) if left else "(see kept turns)"),
             "OPEN ERRORS: " + ("; ".join(errors[:10]) if errors else "(none recorded)"),
             "MUST-NOT-RE-DERIVE: API key is ollama; engine is Strata on :8080; credentials live in the vault, never in this document; launch context is 32768 tokens."]
    _rest = "\n".join(_rest_lines)
    # Cap the whole doc at 16000 chars, but NEVER cut the preserved block:
    # the tail (DONE/LEFT/ERRORS) is truncated first.
    _cap = 16000
    _doc = _block + "\n" + _rest
    if len(_doc) > _cap:
        _doc = _block + "\n" + _rest[:max(0, _cap - len(_block) - 1)]
    return _doc


def _harness_persist_state(session_key, state_doc, extra=None):
    # In-memory + bridge vault (_BMRBD_STATE via _save_bmrbd_state_local, the
    # sanctioned vault path) + local JSONL fallback under BMRBD_DATA_DIR.
    try:
        with _HARNESS_SESSION_LOCK:
            rec = _HARNESS_SESSIONS.setdefault(session_key, {"state_doc": "", "turns": [], "delegations": [], "updated": 0})
            rec["state_doc"] = state_doc
            rec["updated"] = time.time()
            if isinstance(extra, dict):
                for _k, _v in extra.items():
                    if _k == "delegation":
                        rec["delegations"].append(_v)
    except Exception:
        pass
    try:
        if isinstance(_BMRBD_STATE, dict):
            hs = _BMRBD_STATE.setdefault("harness_sessions", {})
            hs[session_key] = {"state_doc": state_doc, "updated": time.time()}
            _save_bmrbd_state_local(push_peer=False, mark_cloud_dirty=False)
    except Exception:
        pass
    try:
        BMRBD_DATA_DIR.mkdir(parents=True, exist_ok=True)
        _p = BMRBD_DATA_DIR / "harness_state.jsonl"
        with open(_p, "a", encoding="utf-8") as _f:
            _f.write(json.dumps({"session": session_key, "ts": time.time(), "state_doc": state_doc}, ensure_ascii=False) + "\n")
    except Exception:
        pass


def _harness_persist_turn(parsed_body, assistant_text, tool_calls):
    try:
        sk = _harness_session_key(parsed_body)
        rec_text = (assistant_text or "")[:4000]
        with _HARNESS_SESSION_LOCK:
            rec = _HARNESS_SESSIONS.setdefault(sk, {"state_doc": "", "turns": [], "delegations": [], "updated": 0})
            rec["turns"].append({"ts": time.time(), "assistant": rec_text,
                                 "tool_calls": [str((tc or {}).get("name")) for tc in (tool_calls or [])]})
            rec["turns"] = rec["turns"][-20:]
            rec["updated"] = time.time()
        try:
            if isinstance(_BMRBD_STATE, dict):
                hs = _BMRBD_STATE.setdefault("harness_sessions", {})
                ent = hs.setdefault(sk, {"state_doc": "", "updated": 0})
                ent["last_turn"] = {"ts": time.time(), "assistant": rec_text}
                ent["updated"] = time.time()
                _save_bmrbd_state_local(push_peer=False, mark_cloud_dirty=False)
        except Exception:
            pass
        # BMRBD v76.3 (Agent D — 1M CONTEXT): full-conversation vault
        # record. The lines above keep only the last 20 assistant
        # replies (truncated to 4000 chars) + tool names; user messages
        # were never saved, so a restart or a compaction lost the
        # thread. Record the FULL thread (client messages + this
        # assistant turn) so the vault holds it faithfully. The record
        # is replace-only-if-fuller, so a fitted/compacted body can
        # never shrink the stored thread. Never raises; never blocks.
        try:
            _sk2 = _harness_session_key(parsed_body)
            _client_msgs = None
            if isinstance(parsed_body, dict):
                _raw = parsed_body.get("messages")
                if isinstance(_raw, list):
                    _client_msgs = [dict(m) for m in _raw if isinstance(m, dict)]
                elif isinstance(parsed_body.get("input"), list):
                    _client_msgs = [dict(m) for m in parsed_body.get("input") if isinstance(m, dict)]
            if _client_msgs:
                _asst = {"role": "assistant", "content": assistant_text or ""}
                if tool_calls:
                    _asst["tool_calls"] = tool_calls
                _v763_ctx1m_record_full_conversation(_sk2, _client_msgs + [_asst])
        except Exception:
            pass
    except Exception:
        pass


# ── BMRBD v76.3 (Agent D) — FULL-CONVERSATION VAULT ROUND-TRIP ──────────
# GAP (v76.2): _harness_persist_turn kept only the last 20 ASSISTANT
# replies (truncated to 4000 chars) + tool NAMES. User messages were
# never saved anywhere, and a compaction or a kernel restart lost the
# thread. The "effective unlimited context" promise needs the opposite:
# the server keeps the FULL conversation (vault/Drive, the durable path)
# and feeds the model a compacted version that fits. These functions are
# that record: every completed turn stores the full thread (every
# user/assistant/tool message, full text, tool calls + results) in
# memory + the vault (_BMRBD_STATE["harness_full_conversations"], the
# sanctioned vault path — it rides vault.enc + the locked zip to Drive
# exactly like harness_sessions) + a one-line JSONL audit entry.
# Fidelity rules: (1) replace-only-if-fuller — a fitted/compacted body
# must NEVER overwrite a longer stored thread (the fit step shortens
# messages; the vault keeps the longest version seen under the key);
# (2) identical content is a no-op (dedup, no wasted vault saves);
# (3) caps bound the vault entry (400 turns / 2M chars ~= 500K tokens),
# dropping the OLDEST non-system turns first — the state doc still
# carries their decisions/key facts; (4) never raises, never blocks a
# turn. Restore is in-memory first, vault second.
_V763_CTX1M_FULL_MAX_TURNS = 400
_V763_CTX1M_FULL_MAX_CHARS = 2000000  # ~500K tokens at ~4 chars/token


def _v763_ctx1m_json_safe(obj):
    """Deep-copy through JSON (drops non-serialisable values via str).
    Never raises — returns a str fallback for unserialisable input."""
    try:
        return json.loads(json.dumps(obj, ensure_ascii=False, default=str))
    except Exception:
        try:
            return str(obj)
        except Exception:
            return None


def _v763_ctx1m_record_full_conversation(session_key, messages, save_vault=True):
    """Store the FULL message list for a harness session. Returns the
    stored record dict (or None when there is nothing storable / every
    store failed). Replace-only-if-fuller + identical-content no-op.
    save_vault=False stores in-memory + JSONL audit only (used for the
    pre-send record mid-turn, so no extra full-state serialisation);
    the durable vault save happens on the completed-turn record."""
    try:
        sk = str(session_key or "default")
        raw = _v763_ctx1m_json_safe(messages)
        if not isinstance(raw, list):
            return None
        msgs = [dict(m) for m in raw if isinstance(m, dict)]
        if not msgs:
            return None
        _chars = 0
        for _m in msgs:
            try:
                _chars += len(json.dumps(_m, ensure_ascii=False))
            except Exception:
                _chars += len(str(_m.get("content", "")))
        _dropped = 0
        while (len(msgs) > _V763_CTX1M_FULL_MAX_TURNS or _chars > _V763_CTX1M_FULL_MAX_CHARS) and len(msgs) > 1:
            _idx = 1 if str((msgs[0] or {}).get("role") or "").lower() in ("system", "developer") and len(msgs) > 1 else 0
            _gone = msgs.pop(_idx)
            _dropped += 1
            try:
                _chars -= len(json.dumps(_gone, ensure_ascii=False))
            except Exception:
                pass
        try:
            _sha = hashlib.sha256(json.dumps(msgs, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()
        except Exception:
            _sha = ""
        _old = None
        try:
            _sessions = globals().get("_HARNESS_SESSIONS")
            if isinstance(_sessions, dict):
                _old = (_sessions.get(sk) or {}).get("full_record")
            if not isinstance(_old, dict):
                _state0 = globals().get("_BMRBD_STATE")
                if isinstance(_state0, dict):
                    _old = ((_state0.get("harness_full_conversations") or {}).get(sk) or {})
        except Exception:
            _old = None
        if isinstance(_old, dict) and _old.get("sha256") == _sha and _old.get("turns") == msgs:
            return _old
        if isinstance(_old, dict) and isinstance(_old.get("turns"), list):
            try:
                _old_chars = int(_old.get("chars") or 0)
            except Exception:
                _old_chars = 0
            if _chars < _old_chars and len(msgs) < len(_old["turns"]):
                return _old  # fitted/compacted body: never shrink the vault record
        _receipts = []
        try:
            if isinstance(_old, dict) and isinstance(_old.get("receipts"), list):
                _receipts = list(_old["receipts"])
        except Exception:
            _receipts = []
        _record = {"turns": msgs, "turns_total": len(msgs) + _dropped,
                   "dropped_early_turns": _dropped, "chars": _chars,
                   "sha256": _sha, "updated": time.time(), "receipts": _receipts}

        def _store_mem():
            _sessions = globals().get("_HARNESS_SESSIONS")
            if isinstance(_sessions, dict):
                _rec = _sessions.setdefault(sk, {"state_doc": "", "turns": [], "delegations": [], "updated": 0})
                _rec["full_turns"] = _v763_ctx1m_json_safe(msgs)
                _rec["full_record"] = _record
                _rec["updated"] = time.time()
        try:
            _lock = globals().get("_HARNESS_SESSION_LOCK")
            if _lock is not None:
                with _lock:
                    _store_mem()
            else:
                _store_mem()
        except Exception:
            pass
        if save_vault:
            try:
                _state = globals().get("_BMRBD_STATE")
                if isinstance(_state, dict):
                    _fc = _state.setdefault("harness_full_conversations", {})
                    _fc[sk] = _record
                    _save = globals().get("_save_bmrbd_state_local")
                    if callable(_save):
                        _save(push_peer=False, mark_cloud_dirty=False)
            except Exception:
                pass
        try:
            _dd = globals().get("BMRBD_DATA_DIR")
            if _dd is not None:
                from pathlib import Path as _P
                _p = _P(str(_dd)) / "harness_full_conversations.jsonl"
                _p.parent.mkdir(parents=True, exist_ok=True)
                with open(_p, "a", encoding="utf-8") as _f:
                    _f.write(json.dumps({"session": sk, "ts": time.time(), "turns": len(msgs), "dropped": _dropped, "chars": _chars, "sha256": _sha}, ensure_ascii=False) + "\n")
        except Exception:
            pass
        return _record
    except Exception:
        return None


def _v763_ctx1m_restore_full_conversation(session_key):
    """Return the stored FULL message list for a session (deep copy),
    in-memory first, vault second; None when nothing is stored. Never
    raises."""
    try:
        sk = str(session_key or "default")
        _sessions = globals().get("_HARNESS_SESSIONS")
        if isinstance(_sessions, dict):
            _rec = _sessions.get(sk) or {}
            _turns = _rec.get("full_turns")
            if isinstance(_turns, list) and _turns:
                _copy = _v763_ctx1m_json_safe(_turns)
                if isinstance(_copy, list):
                    return _copy
        _state = globals().get("_BMRBD_STATE")
        if isinstance(_state, dict):
            _fc = _state.get("harness_full_conversations") or {}
            _ent = _fc.get(sk) or {}
            _turns = _ent.get("turns")
            if isinstance(_turns, list) and _turns:
                _copy = _v763_ctx1m_json_safe(_turns)
                if isinstance(_copy, list):
                    return _copy
        return None
    except Exception:
        return None


def _v763_ctx1m_record_compaction_receipt(session_key, turns_before, est_tokens_before, state_doc):
    """Proof that a compaction kept the full history: the pre-compaction
    turn count + token estimate + state-doc hash ride on the vault
    record, so the full thread (recorded separately) can be audited
    against what was compacted away. Returns the receipt dict."""
    try:
        sk = str(session_key or "default")
        try:
            _dsha = hashlib.sha256(str(state_doc or "").encode("utf-8")).hexdigest()
        except Exception:
            _dsha = ""
        _receipt = {"ts": time.time(), "turns_before": int(turns_before or 0),
                    "est_tokens_before": int(est_tokens_before or 0),
                    "state_doc_sha256": _dsha,
                    "state_doc_chars": len(str(state_doc or ""))}

        def _append():
            _sessions = globals().get("_HARNESS_SESSIONS")
            if isinstance(_sessions, dict):
                _rec = _sessions.setdefault(sk, {"state_doc": "", "turns": [], "delegations": [], "updated": 0})
                _rl = _rec.setdefault("compaction_receipts", [])
                _rl.append(dict(_receipt))
                _rec["compaction_receipts"] = _rl[-20:]
                _fr = _rec.get("full_record")
                if isinstance(_fr, dict):
                    _fr.setdefault("receipts", []).append(dict(_receipt))
                    _fr["receipts"] = _fr["receipts"][-20:]
                _rec["updated"] = time.time()
            _state = globals().get("_BMRBD_STATE")
            if isinstance(_state, dict):
                _fc = _state.setdefault("harness_full_conversations", {})
                _ent = _fc.setdefault(sk, {"turns": [], "turns_total": 0, "dropped_early_turns": 0, "chars": 0, "sha256": "", "updated": time.time(), "receipts": []})
                _ent.setdefault("receipts", []).append(dict(_receipt))
                _ent["receipts"] = _ent["receipts"][-20:]
                _ent["updated"] = time.time()
                _save = globals().get("_save_bmrbd_state_local")
                if callable(_save):
                    _save(push_peer=False, mark_cloud_dirty=False)
        try:
            _lock = globals().get("_HARNESS_SESSION_LOCK")
            if _lock is not None:
                with _lock:
                    _append()
            else:
                _append()
        except Exception:
            pass
        return _receipt
    except Exception:
        return None


def _v763_ctx1m_compacted_feed_ok(compacted_msgs, original_msgs, launch_ctx=None):
    """Audit a compacted feed (pure): the feed fits the launch window
    (chars//4 estimate, the same estimator compaction uses), the FULL
    system prompt survives verbatim, a [STATE — compacted] doc is
    present, the latest user turn is present, and every decision /
    key-fact line from the state doc survives in the feed. Returns a
    dict of checks + an overall `ok`. Used by tests and operators;
    never on the hot path."""
    try:
        lc = int(launch_ctx or globals().get("HARNESS_LAUNCH_CTX", 32768))
        comp = [m for m in (compacted_msgs or []) if isinstance(m, dict)]
        orig = [m for m in (original_msgs or []) if isinstance(m, dict)]

        def _txt(m):
            c = m.get("content", "")
            if isinstance(c, list):
                c = "\n".join(str(b.get("text", "")) for b in c if isinstance(b, dict))
            return str(c or "")

        def _est(ms):
            t = 0
            for m in ms:
                try:
                    t += max(1, len(json.dumps(m, ensure_ascii=False)) // 4)
                except Exception:
                    t += max(1, len(_txt(m)) // 4)
            return t
        est = _est(comp)
        sys_orig = ""
        for m in orig:
            if str(m.get("role") or "").lower() in ("system", "developer"):
                sys_orig = _txt(m)
                break
        sys_comp = ""
        for m in comp:
            if str(m.get("role") or "").lower() in ("system", "developer"):
                sys_comp = _txt(m)
                break
        # v76.3 MERGE: has_doc reads the UNstripped compacted system
        # (the [STATE] wrapper must be present in the feed); the
        # system_whole comparison below strips the wrapper on both sides.
        has_doc = "[STATE" in sys_comp and "compacted" in sys_comp
        # v76.3 MERGE: system_whole compares the underlying system PROMPT,
        # not a previous round's timestamped [STATE] wrapper. G's strip
        # removes the old wrapper on re-compaction (correct — no state-doc
        # archaeology), so a naive verbatim check of the stamped round-1
        # system fails whenever the clock ticks between rounds (a 1-second
        # race: the audit passed only when both compactions landed in the
        # same second). Strip the wrapper on both sides first; the prompt
        # itself must still survive whole. Resolved via globals() with an
        # inline fallback, the file's isolated-load idiom.
        _strip_state = globals().get("_v763_strip_prior_state_block")
        if _strip_state is None:
            def _strip_state(c):
                _cc = str(c or "")
                _mm = re.match(r"^\[STATE — compacted [^\n]*\]\n", _cc)
                if not _mm:
                    return _cc
                _rest = _cc[_mm.end():]
                _ix = _rest.find("\n\n")
                return "" if _ix == -1 else _rest[_ix + 2:]
        sys_orig = _strip_state(sys_orig)
        sys_comp = _strip_state(sys_comp)
        system_whole = (not sys_orig) or (sys_orig in sys_comp)
        latest_user = ""
        for m in reversed(orig):
            if str(m.get("role") or "").lower() == "user":
                latest_user = _txt(m)
                break
        feed_text = "\n".join(_txt(m) for m in comp)
        latest_ok = (not latest_user) or (latest_user in feed_text)
        # Facts kept = every explicit Decision:/Key fact: line from the
        # ORIGINAL thread survives (at least its first 60 chars — the
        # builder truncates items to 160 chars) in the feed's state doc.
        # Lines naming credentials are skipped: the builder rightly
        # never carries secrets into a state document.
        facts_ok = True
        if has_doc:
            _dec_rx = re.compile(r"^\s*(decision|decided|agreed|chosen|choice)\s*:", re.I)
            _fact_rx = re.compile(r"^\s*(key fact|important|remember|note|fact)\s*:", re.I)
            _sec_rx = re.compile(r"password|passwd|api[_ -]?key|secret|token|credential", re.I)
            for _m in orig:
                for _ln in _txt(_m).splitlines():
                    _ls = _ln.strip()
                    if not _ls or _sec_rx.search(_ls):
                        continue
                    if _dec_rx.search(_ls) or _fact_rx.search(_ls):
                        if _ls[:60] not in sys_comp:
                            facts_ok = False
        fits = est <= lc
        ok = bool(fits and system_whole and has_doc and latest_ok and facts_ok)
        return {"fits": fits, "est_tokens": est, "launch_ctx": lc,
                "system_whole": system_whole, "has_state_doc": has_doc,
                "latest_user_present": latest_ok, "facts_kept": facts_ok,
                "ok": ok}
    except Exception:
        return {"fits": False, "est_tokens": 0, "launch_ctx": 32768,
                "system_whole": False, "has_state_doc": False,
                "latest_user_present": False, "facts_kept": False, "ok": False}


def _harness_estimate_tokens(msgs):
    """Rough prompt-token estimate (chars//4) for a message list. Same
    estimator the compaction threshold uses — unit-tested. Counts the
    WHOLE message (content + tool_calls + tool results, v76.1): the old
    content-only count missed tool_call arguments entirely, so a
    tool-heavy history could pass 22K true tokens while the estimate
    said ~12K and the 70% compaction trigger fired late."""
    # v76.2 C2: image bytes are not prompt text — resolve the shared
    # stripper, falling back to an identical inline copy when this
    # function is loaded alone (unit tests exec each function in
    # isolation, where the module global is out of scope).
    _strip = globals().get("_harness_text_only_json")
    if _strip is None:
        def _strip(o):
            if isinstance(o, dict):
                return {_k: ("[attached image]" if _k in ("images", "image", "image_url") and isinstance(_v, (str, list)) else _strip(_v)) for _k, _v in o.items()}
            if isinstance(o, list):
                return [_strip(_v) for _v in o]
            if isinstance(o, str) and o.startswith("data:image/"):
                return "[attached image]"
            return o
    try:
        _total = 0
        for _m in (msgs or []):
            if not isinstance(_m, dict):
                continue
            try:
                _total += max(1, len(json.dumps(_strip(_m), ensure_ascii=False)) // 4)  # v76.2 C2: image bytes are not prompt text
            except Exception:
                _total += max(1, len(str(_m.get("content", ""))) // 4)
        return _total
    except Exception:
        return 0


# ── BMRBD v76 STAGE-1: minimal-context auto-continue ─────────────────────
# CONTEXT-LIMIT RULE (Marup 2026-11-19): a continuation must NEVER re-send
# the full conversation history and NEVER duplicate already-generated output
# into the context. The continuation carries only: the system message, the
# ORIGINAL last user message (the task itself), the partial output so far
# (as the assistant turn), and one short "continue" instruction. Older turns
# are dropped — the partial output already carries what the model derived.
# A small task therefore stays a small fraction of the 32768 window even
# after several continuation rounds.
_HARNESS_MAX_CONTINUE_ROUNDS = 4
_HARNESS_CONTINUE_NOTE = (
    "[Continue the reply from exactly where it stopped. Do not repeat "
    "anything already said — just continue. Finish the task completely.]"
)
_HARNESS_CONTINUE_NOTE_NO_THINK = (
    "[Continue: your reply was cut off before any visible answer appeared "
    "because the thinking used the whole budget. Answer the original question "
    "DIRECTLY now — do NOT think again, do NOT repeat anything, just give "
    "the answer and finish the task.]"
)


def _harness_minimal_continue_messages(msgs, partial_text, no_visible_content=False, note=None):
    """Build the minimal continuation message list from a full thread.
    Pure function — unit-tested (token counts: small task stays small)."""
    try:
        src = [m for m in (msgs or []) if isinstance(m, dict)]
        out = []
        # BMRBD v76.3 QUALITY (G): merge EVERY system/developer message
        # into one full system message — the old code kept only the
        # FIRST and silently dropped the rest, so a client system prompt
        # (or the harness prompt appended as a second system message)
        # never reached the engine on a continuation turn.
        _sys_texts = []
        # v76.3 MERGE: resolve _harness_message_text via globals() with an
        # inline fallback — the file's isolated-load idiom. Agent G's
        # version called it directly, which NameErrored (and silently
        # returned the un-continued thread) in any AST-isolated namespace
        # that loads only this function, e.g. test_v76_3_stability.py.
        _msg_text_fn = globals().get("_harness_message_text")
        for m in src:
            if str(m.get("role") or "").lower() in ("system", "developer"):
                if _msg_text_fn is not None:
                    _t = _msg_text_fn(m).strip()
                else:
                    _c = m.get("content", "")
                    if isinstance(_c, list):
                        _c = "\n".join(str(b.get("text", "")) for b in _c if isinstance(b, dict))
                    _t = str(_c or "").strip()
                if _t:
                    _sys_texts.append(_t)
        if _sys_texts:
            out.append({"role": "system", "content": "\n\n".join(_sys_texts)})
        last_user = None
        for m in reversed(src):
            if str(m.get("role") or "").lower() == "user":
                last_user = m
                break
        if last_user is not None:
            out.append(dict(last_user))
        out.append({"role": "assistant", "content": str(partial_text or "")})
        out.append({"role": "user",
                    "content": note or (_HARNESS_CONTINUE_NOTE_NO_THINK if no_visible_content else _HARNESS_CONTINUE_NOTE)})
        return out
    except Exception:
        return list(msgs or [])


# Steering note for the promise-only round (S1): the model announced a
# result and stopped. One bounded round to deliver the actual result.
_HARNESS_PROMISE_STEER_NOTE = (
    "[You stopped after a short announcement. Continue now: deliver the actual "
    "result / complete answer in full. If the task is already finished, give the "
    "complete answer as a summary instead of another announcement. Do not stop "
    "after an announcement again.]"
)


def _v763_strip_prior_state_block(content):
    """Strip a stale "[STATE — compacted ...]" block from the FRONT of a
    system message, returning the original system text underneath (or ""
    when the content was ONLY a prior state doc). v76.3 (G): without this,
    every compaction prepended a new state doc on top of the old ones, so
    the system prompt sank under ever-growing stale state and the engine
    eventually saw state-doc archaeology instead of its instructions."""
    try:
        c = str(content or "")
        if not c.startswith("[STATE"):
            return c
        _m = re.match(r"^\[STATE — compacted [^\n]*\]\n", c)
        if not _m:
            return c
        rest = c[_m.end():]
        idx = rest.find("\n\n")
        if idx == -1:
            return ""
        return rest[idx + 2:]
    except Exception:
        return str(content or "")


def _v763_retry_compact(msgs, target_chars):
    """Context-error retry compaction that NEVER truncates the system
    prompt (v76.3 (G) fix for the old `sys_m["content"][:1800]` in both
    stream retry loops). The first message (the system message) is kept
    whole; the tail shrinks instead (fewer turns, then shorter turns).
    Returns a NEW list; never raises."""
    try:
        if not msgs:
            return [{"role": "system", "content": "You are a helpful assistant."}]
        sys_m = dict(msgs[0])
        sys_text = str(sys_m.get("content") or "")
        tail = [dict(m) for m in msgs[1:]]
        if len(sys_text) >= target_chars:
            keep_n = 1
        elif len(sys_text) >= target_chars // 2:
            keep_n = 2
        else:
            keep_n = 4
        tail = tail[-keep_n:] if tail else []
        per = max(500, (target_chars - len(sys_text)) // max(1, len(tail))) if tail else 0
        for tm in tail:
            tc_s = str(tm.get("content") or "")
            if len(tc_s) > per:
                tm["content"] = tc_s[:int(per * 0.45)] + "\n...[condensed]...\n" + tc_s[-int(per * 0.45):]
        return [sys_m] + tail
    except Exception:
        return list(msgs or [])


# v76.3 MERGE (overlap 2): ONE context-error retry-compact helper.
# Agent E built the same helper as _stability_compact_for_context_error;
# the canonical implementation is _v763_retry_compact above (G's is
# more thorough) and this alias keeps E's name callable with
# identical behaviour. Both retry call sites use _v763_retry_compact.
_stability_compact_for_context_error = _v763_retry_compact



def _harness_maybe_compact(ollama_msgs, parsed_body, force=False):
    # Returns (msgs, state_doc_or_None). At ~70% of the 32K window, replace
    # older turns with a persisted state document; resume format is
    # "[STATE — compacted <time>]" + state doc + kept recent turns (~8K tokens).
    # force=True compacts even below the threshold (used by the context-fit
    # step when the prompt + tools + requested output exceed the window).
    try:
        est = sum(max(1, len(json.dumps(m, ensure_ascii=False)) // 4) for m in (ollama_msgs or []) if isinstance(m, dict))
        if est <= HARNESS_COMPACT_AT_TOKENS and not force:
            return ollama_msgs, None
        doc = _harness_build_state_document(ollama_msgs)
        sk = _harness_session_key(parsed_body)
        _harness_persist_state(sk, doc)
        # v76.3 (Agent D): compaction receipt — the pre-compaction turn
        # count + token estimate + state-doc hash ride on the vault
        # record, so the full thread stays auditable after compaction.
        try:
            _v763_ctx1m_record_compaction_receipt(sk, len(ollama_msgs), est, doc)
        except Exception:
            pass
        stamp = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
        # BMRBD v76.1: the state doc rides on the SYSTEM message. When the
        # thread has no leading system/developer message, INSERT one —
        # prepending the doc to a user message would present server state
        # as user text and corrupt the roles the engine sees.
        if ollama_msgs and str((ollama_msgs[0] or {}).get("role") or "").lower() in ("system", "developer"):
            sys_m = dict(ollama_msgs[0])
            # BMRBD v76.3 QUALITY (G): strip any stale [STATE] block the
            # previous compaction left on this system message, so the
            # system prompt itself is never buried or duplicated and a
            # re-compaction never grows it. Resolved via globals() with
            # an inline fallback, the file\u2019s isolated-load idiom.
            _strip = globals().get("_v763_strip_prior_state_block")
            if _strip is None:
                def _strip(c):
                    _cc = str(c or "")
                    _mm = re.match(r"^\[STATE — compacted [^\n]*\]\n", _cc)
                    if not _mm:
                        return _cc
                    _rest = _cc[_mm.end():]
                    _ix = _rest.find("\n\n")
                    return "" if _ix == -1 else _rest[_ix + 2:]
            _orig_sys = _strip(str(sys_m.get("content") or ""))
            sys_m["content"] = ("[STATE — compacted %s]\n%s" % (stamp, doc)) if not _orig_sys else ("[STATE — compacted %s]\n%s\n\n%s" % (stamp, doc, _orig_sys))
            tail = list(ollama_msgs[1:])
        else:
            sys_m = {"role": "system", "content": "[STATE \u2014 compacted %s]\n%s" % (stamp, doc)}
            tail = list(ollama_msgs)
        # v76.3 (Agent D): kept tail is 25% of the launch window (was a
        # hardcoded 8*1024*4 = 32768 chars — identical at the 32768
        # launch window, now derived so the window stays single-sourced).
        keep_chars = int(HARNESS_LAUNCH_CTX * 0.25) * 4
        kept = []
        total = 0
        for m in reversed(tail):
            try:
                c = len(json.dumps(m, ensure_ascii=False))
            except Exception:
                c = len(str(m.get("content", "")))
            if total + c > keep_chars and kept:
                break
            kept.append(m)
            total += c
        kept.reverse()
        return [sys_m] + kept, doc
    except Exception:
        return ollama_msgs, None


# --- Spec section 7: server-side web tools ---------------------------------
class _HarnessRedirectLimiter(urllib.request.HTTPRedirectHandler):
    def __init__(self, max_redirects=3):
        super().__init__()
        self._count = 0
        self._max = max_redirects

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        self._count += 1
        if self._count > self._max:
            raise urllib.error.HTTPError(newurl, 310, "too many redirects (limit 3)", headers, fp)
        # BMRBD v76.2 BUGHUNT: a redirect target is a NEW fetch — re-run the
        # SSRF guard on it (a public URL 302-ing to 169.254.169.254 or
        # localhost used to be fetched). urljoin first: a relative Location
        # would otherwise crash super() with ValueError (unknown url type).
        _abs = urllib.parse.urljoin(req.full_url, newurl)
        _blocked = _ssrf_blocked_url(_abs)
        if _blocked:
            raise urllib.error.HTTPError(newurl, 403, "blocked redirect: " + _blocked, headers, fp)
        return super().redirect_request(req, fp, code, msg, headers, _abs)


def _harness_web_fetch(url, timeout=60):
    url = str(url or "").strip()
    blocked = _ssrf_blocked_url(url)
    if blocked:
        return {"url": url, "source_url": url, "error": blocked}
    try:
        opener = urllib.request.build_opener(_HarnessRedirectLimiter(3))
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (BMRBD Ai web_fetch)"})
        with opener.open(req, timeout=timeout) as r:
            raw = r.read(200 * 1024 + 1)
            truncated = len(raw) > 200 * 1024
            raw = raw[:200 * 1024]
            # D3 (v76.5): a URL that serves a FILE (image/PDF/ZIP/...) is not
            # a web page. The old code decoded the raw bytes as text and
            # returned binary garbage as "text" with no error (verified live:
            # /api/fetch-url on a PNG returned ok:true + 4360 chars of PNG
            # bytes). Fail loudly and point at the download tool instead.
            _bctype = ""
            try:
                _bctype = str(r.headers.get_content_type() or "").lower()
            except Exception:
                _bctype = ""
            _berr = _web_binary_error(_bctype, raw)
            if _berr:
                return {"url": url, "source_url": url, "error": _berr,
                        "content_type": _bctype, "suggested_tool": "web_download"}
            html_s = raw.decode("utf-8", errors="ignore")
            title = ""
            _tm = re.search(r"<title[^>]*>([\s\S]{0,300})</title>", html_s, re.I)
            if _tm:
                title = re.sub(r"\s+", " ", re.sub(r"<[^>]+>", "", _tm.group(1))).strip()
            text = _harness_extract_article_text(html_s, 12000)
            _heads = [re.sub(r"\s+", " ", re.sub(r"<[^>]+>", "", h)).strip() for h in re.findall(r"<h[12][^>]*>([\s\S]{0,200}?)</h[12]>", html_s, re.I)][:10]
            return {"url": url, "source_url": url, "title": title, "text": text, "headings": [h for h in _heads if h], "truncated_200kb": truncated}
    except Exception as e:
        return {"url": url, "source_url": url, "error": str(e)}


class _HarnessImgParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.imgs = []

    def handle_starttag(self, tag, attrs):
        if tag in ("img", "source"):
            d = dict(attrs)
            src = d.get("src") or d.get("data-src") or ""
            if not src and d.get("srcset"):
                # D3: <picture>/<img srcset> carries the real image URL;
                # the old parser only read src/data-src and missed it.
                # Take the LAST (usually largest) candidate.
                _cands = [p.strip().split(" ")[0] for p in str(d.get("srcset")).split(",") if p.strip()]
                src = _cands[-1] if _cands else ""
            if src:
                self.imgs.append({"src": src, "alt": d.get("alt", ""), "width": d.get("width", ""), "height": d.get("height", "")})
        elif tag == "meta":
            # D3: og:image / twitter:image is often the ONLY image URL on
            # pages whose <img> tags are lazy-loaded placeholders.
            _d = dict(attrs)
            _prop = str(_d.get("property") or _d.get("name") or "").lower()
            if _prop in ("og:image", "twitter:image") and _d.get("content"):
                self.imgs.append({"src": str(_d.get("content")), "alt": "", "width": "", "height": ""})


def _harness_web_images(page_url):
    page_url = str(page_url or "").strip()
    blocked = _ssrf_blocked_url(page_url)
    if blocked:
        return {"url": page_url, "source_url": page_url, "error": blocked, "images": []}
    try:
        opener = urllib.request.build_opener(_HarnessRedirectLimiter(3))
        req = urllib.request.Request(page_url, headers={"User-Agent": "Mozilla/5.0 (BMRBD Ai web_images)"})
        with opener.open(req, timeout=60) as r:
            raw = r.read(200 * 1024 + 1)[:200 * 1024]
            html_s = raw.decode("utf-8", errors="ignore")
        p = _HarnessImgParser()
        p.feed(html_s)
        out = []
        seen = set()
        for im in p.imgs[:40]:
            abs_u = urllib.parse.urljoin(page_url, im["src"])
            if not abs_u.startswith(("http://", "https://")):
                continue
            if abs_u in seen:
                continue
            seen.add(abs_u)
            out.append({"url": abs_u, "source_url": page_url, "alt": im["alt"], "width": im["width"], "height": im["height"]})
            if len(out) >= 20:
                break
        return {"url": page_url, "source_url": page_url, "images": out}
    except Exception as e:
        return {"url": page_url, "source_url": page_url, "error": str(e), "images": []}


def _harness_web_search(query, max_results=10):
    # Real search index via the bridge's existing live search
    # (DuckDuckGo HTML + Google News RSS + Wikipedia). Never invented.
    q = str(query or "").strip()
    if not q:
        return {"query": q, "results": []}
    try:
        raw = fetch_live_web_search_results(q, max_results=int(max_results))
    except Exception:
        raw = []
    out = []
    for r in (raw or [])[:10]:
        if not isinstance(r, dict):
            continue
        u = str(r.get("url") or "")
        if not u.startswith("http"):
            continue
        _snip = str(r.get("snippet") or "")
        _content = ""
        if " | Full Page Extract: " in _snip:
            _snip, _content = _snip.split(" | Full Page Extract: ", 1)
        out.append({"title": str(r.get("title") or u), "url": u, "snippet": _snip, "content": _content, "source_url": u})
    # G1 (v76.5, R6): the hop loop injects this JSON sliced raw [:16000];
    # 10 full crawl extracts are ~19k chars, so the slice cut mid-string
    # and the model received INVALID JSON (unterminated string). Fit the
    # payload to a 14000-char budget instead -- shrink page content first
    # (600 -> 200 -> 0 chars), then drop trailing results -- so what the
    # model gets is always complete, parseable JSON.
    try:
        _g1_budget = 14000
        for _cap in (600, 200, 0):
            _s = json.dumps({"query": q, "results": out}, ensure_ascii=False)
            if len(_s) <= _g1_budget:
                break
            for _r in out:
                if len(str(_r.get("content") or "")) > _cap:
                    _r["content"] = str(_r.get("content") or "")[:_cap]
        while out and len(json.dumps({"query": q, "results": out}, ensure_ascii=False)) > _g1_budget:
            out.pop()
    except Exception:
        pass
    return {"query": q, "results": out}


# --- D3 (v76.5): shared binary / HTML-error-page guards ----------------------
# One predicate for every web path, so web_fetch, /api/fetch-url and
# web_download all agree on what counts as "a file, not a page" and on
# what counts as "an HTML page served where a file was expected".
_WEB_BINARY_MAGIC = (
    (b"\x89PNG", "png"), (b"\xff\xd8\xff", "jpg"), (b"GIF87a", "gif"),
    (b"GIF89a", "gif"), (b"%PDF", "pdf"), (b"PK\x03\x04", "zip"),
    (b"PK\x05\x06", "zip"), (b"ID3", "mp3"),
    (b"\x00\x00\x00\x18ftyp", "mp4"), (b"\x00\x00\x00\x20ftyp", "mp4"),
    (b"\x1a\x45\xdf\xa3", "mkv"), (b"OggS", "ogg"),
)  # NOTE: RIFF is handled separately below (WEBP vs WAVE share the prefix).
_WEB_TEXT_CONTENT_TYPES = ("text/", "application/xhtml", "application/json",
                          "application/xml", "application/rss", "application/atom")


def _web_binary_error(content_type, raw):
    """Error string when (content_type, raw bytes) are a FILE, not a web
    page — else ''. Content-Type wins; magic bytes catch servers that lie
    about the type (or omit it). Pure — unit-tested."""
    ctype = str(content_type or "").lower().split(";")[0].strip()
    if ctype and not ctype.startswith(_WEB_TEXT_CONTENT_TYPES):
        return "URL is a %s file, not a web page — use web_download to download it" % (ctype or "binary")
    try:
        head = bytes(raw or b"")[:12]
    except Exception:
        head = b""
    for _magic, _ext in _WEB_BINARY_MAGIC:
        if head.startswith(_magic):
            return "URL serves binary file data (magic %s), not a web page — use web_download to download it" % _ext
    if head[:4] == b"RIFF" and len(bytes(raw or b"")) >= 12:
        _sub = bytes(raw or b"")[8:12]
        _riff_ext = "webp" if _sub == b"WEBP" else ("wav" if _sub == b"WAVE" else "riff")
        return "URL serves binary file data (magic %s), not a web page — use web_download to download it" % _riff_ext
    return ""


def _web_is_html_bytes(raw):
    """True when the bytes are (almost certainly) an HTML document — used
    to reject HTML error/block pages served where a file was expected."""
    try:
        head = bytes(raw or b"")[:512].lstrip().lower()
    except Exception:
        return False
    return head.startswith((b"<!doctype html", b"<html", b"<head", b"<!doctype"))


_WEB_DOWNLOAD_MAX_BYTES = 25 * 1024 * 1024
_WEB_DOWNLOAD_EXT_BY_TYPE = {
    "image/png": "png", "image/jpeg": "jpg", "image/gif": "gif",
    "image/webp": "webp", "image/svg+xml": "svg", "image/bmp": "bmp",
    "image/avif": "avif", "application/pdf": "pdf",
    "application/zip": "zip", "application/x-zip-compressed": "zip",
    "application/x-rar-compressed": "rar", "application/x-7z-compressed": "7z",
    "application/gzip": "gz", "application/x-tar": "tar",
    "audio/mpeg": "mp3", "audio/wav": "wav", "audio/ogg": "ogg",
    "audio/mp4": "m4a", "video/mp4": "mp4", "video/webm": "webm",
    "video/x-matroska": "mkv", "text/plain": "txt", "text/markdown": "md",
    "text/csv": "csv", "application/json": "json",
    "application/octet-stream": "bin",
    "application/msword": "doc",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document": "docx",
    "application/vnd.ms-excel": "xls",
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": "xlsx",
    "application/vnd.ms-powerpoint": "ppt",
    "application/vnd.openxmlformats-officedocument.presentationml.presentation": "pptx",
}


def _harness_web_download(url, timeout=60, filename=""):
    """D3 (v76.5) DEMAND 3(d)/(c): download a file from the web and return
    its /media/ URL. There was NO such tool before this fix: web_fetch only
    reads pages as text (binary URLs came back as garbage) and web_images
    only LISTS image URLs — neither ever saved a file, so "download it"
    always failed. SSRF guard + 3-redirect limit are the same as web_fetch
    (unchanged); max 25 MB; an HTML page served where a file was expected
    (error/block page, wrong URL) is REJECTED, never saved as the file."""
    url = str(url or "").strip()
    blocked = _ssrf_blocked_url(url)
    if blocked:
        return {"url": url, "source_url": url, "error": blocked}
    try:
        opener = urllib.request.build_opener(_HarnessRedirectLimiter(3))
        req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (BMRBD Ai web_download)"})
        with opener.open(req, timeout=timeout) as r:
            ctype = ""
            try:
                ctype = str(r.headers.get_content_type() or "").lower().split(";")[0].strip()
            except Exception:
                ctype = ""
            try:
                _clen = int(r.headers.get("Content-Length") or 0)
            except Exception:
                _clen = 0
            if _clen > _WEB_DOWNLOAD_MAX_BYTES:
                return {"url": url, "source_url": url, "error": "File too large (%d bytes, limit %d bytes)" % (_clen, _WEB_DOWNLOAD_MAX_BYTES), "content_type": ctype}
            raw = r.read(_WEB_DOWNLOAD_MAX_BYTES + 1)
            if len(raw) > _WEB_DOWNLOAD_MAX_BYTES:
                return {"url": url, "source_url": url, "error": "File too large (over %d bytes)" % _WEB_DOWNLOAD_MAX_BYTES, "content_type": ctype}
        if not raw:
            return {"url": url, "source_url": url, "error": "Downloaded file is empty", "content_type": ctype}
        # HTML where a file was expected = an error/block page, not the file.
        _path = urllib.parse.urlparse(url).path.lower()
        _html_ext = _path.endswith((".html", ".htm"))
        if _web_is_html_bytes(raw) or ctype == "text/html":
            if not _html_ext:
                return {"url": url, "source_url": url, "error": "Server returned an HTML page instead of a file (often an error or bot-block page) — use web_fetch to read it", "content_type": ctype or "text/html"}
        # Extension: explicit filename > URL path > Content-Type > magic.
        ext = ""
        _want = str(filename or "").strip()
        if _want:
            _want = _want.replace("/", "_").replace("\\", "_")
            if "." in _want:
                ext = _want.rsplit(".", 1)[1].lower()[:10]
        if not ext and "." in _path.rsplit("/", 1)[-1]:
            ext = _path.rsplit(".", 1)[1].lower().split("?")[0][:10]
            if not ext.isalnum():
                ext = ""
        if not ext:
            ext = _WEB_DOWNLOAD_EXT_BY_TYPE.get(ctype, "")
        if not ext:
            for _magic, _mext in _WEB_BINARY_MAGIC:
                if raw.startswith(_magic):
                    ext = _mext
                    break
            if not ext and len(raw) >= 12 and raw[:4] == b"RIFF" and raw[8:12] == b"WEBP":
                ext = "webp"
        if not ext:
            ext = "bin" if ctype.startswith(("application/", "image/", "audio/", "video/")) else "txt"
        media_url = save_media_and_get_url(raw, ext, "dl")
        fname = media_url.rsplit("/", 1)[-1]
        return {"url": url, "source_url": url, "media_url": media_url,
                "markdown": "[Download `%s`](%s?download=1)" % (fname, media_url),
                "filename": fname, "size_bytes": len(raw),
                "content_type": ctype or "application/octet-stream", "ext": ext}
    except Exception as e:
        return {"url": url, "source_url": url, "error": str(e)}


_HARNESS_SERVER_TOOLS = ("web_fetch", "web_search", "web_images", "image", "web_download")


def _harness_image_generate(args):
    """v76.2 IMAGE: server-side executor for the "image" tool call.
    Returns a SMALL result dict (url + markdown only — never the full
    base64 data URL: the harness re-issues the tool result into the
    model context and _sres is truncated to 16000 chars there)."""
    try:
        args = args if isinstance(args, dict) else {}
        prompt = str(args.get("prompt") or args.get("input") or args.get("text") or args.get("query") or "").strip()
        if not prompt:
            return {"error": "image tool requires a 'prompt' (what to draw)"}
        size = str(args.get("size") or "1024x1024")
        _norm = {}
        try:
            _norm, _nerr = _image_gen_normalize_request({"prompt": prompt, "size": size}, default_tier="fast")
            if _nerr:
                return {"error": _nerr}
            size = str((_norm or {}).get("size") or size)
        except Exception:
            _norm = {}
        _preset = str(args.get("model") or args.get("model_preset") or ((_norm or {}).get("preset") or "flux-1-schnell-turbo"))
        ires = generate_studio_image_v38(prompt, size_str=size, negative_prompt=str(args.get("negative_prompt") or ""), model_preset=_preset)
        png_bytes = base64.b64decode(ires["b64_json"])
        png_url = save_media_and_get_url(png_bytes, "png", "img")
        return {"prompt": prompt, "url": png_url, "markdown": "![Generated image](%s)" % png_url, "width": ires.get("width"), "height": ires.get("height"), "model_used": ires.get("model_used")}
    except RuntimeError as e:
        return {"error": "Image generation failed: " + str(e)}
    except Exception as e:
        return {"error": "Image generation failed: " + str(e)}


def _harness_run_server_tool(name, args):
    # Returns (result_json_str, ok_bool); never raises.
    try:
        args = args if isinstance(args, dict) else {}
        # v76.2: the model may name the tool "fetch"/"search" (aliases
        # resolved in parse_model_tool_calls, but engine-native
        # tool_calls bypass that parser) — normalise to server names.
        _alias = {"fetch": "web_fetch", "webfetch": "web_fetch",
                  "search": "web_search", "websearch": "web_search",
                  "google_search": "web_search",
                  "download": "web_download", "download_file": "web_download",
                  "fetch_file": "web_download", "webdownload": "web_download",
                  "download_image": "web_download", "save_image": "web_download",
                  "image_generation": "image", "generate_image": "image",
                  "create_image": "image", "draw_image": "image"}
        name = _alias.get(str(name or "").lower().strip(), name)
        # v76.2: unwrap a whole call passed as one "tool_call" argument.
        if isinstance(args.get("tool_call"), (str, dict)):
            _tcv = args.get("tool_call")
            try:
                _tcj = _tcv if isinstance(_tcv, dict) else json.loads(str(_tcv).strip())
            except Exception:
                _tcj = None
            if isinstance(_tcj, dict) and _tcj.get("name"):
                name = _alias.get(str(_tcj["name"]).lower().strip(), _tcj["name"])
                _ta = _tcj.get("arguments") or _tcj.get("parameters") or _tcj.get("input") or {}
                args = _ta if isinstance(_ta, dict) else {"input": _ta}
        if name == "image":
            _ires = _harness_image_generate(args)
            return json.dumps(_ires, ensure_ascii=False), ("error" not in _ires)
        if name == "web_fetch":
            return json.dumps(_harness_web_fetch(args.get("url") or args.get("input") or ""), ensure_ascii=False), True
        if name == "web_search":
            return json.dumps(_harness_web_search(args.get("query") or args.get("input") or "", args.get("max_results") or 10), ensure_ascii=False), True
        if name == "web_images":
            return json.dumps(_harness_web_images(args.get("url") or args.get("page_url") or args.get("input") or ""), ensure_ascii=False), True
        if name == "web_download":
            return json.dumps(_harness_web_download(args.get("url") or args.get("input") or "", filename=args.get("filename") or args.get("name") or ""), ensure_ascii=False), True
        return json.dumps({"error": "unknown server tool: " + str(name)}), False
    except Exception as e:
        return json.dumps({"error": str(e)}), False


def _harness_run_subagent(args, engine_call=None):
    """Execute ONE spawn_subagent call server-side (spec section 6).

    Runs the brief as a single bounded engine turn (no tools: one level
    only — a subagent never spawns sub-subagents) and returns the
    structured result text the parent continues from. Never raises and
    never returns silence: an engine failure is a failure REPORT.
    engine_call is an injectable (brief_prompt, max_tokens) -> text hook
    for unit tests; None uses the live engine (OpenAI-compatible).
    Returns (result_text, ok_bool).
    """
    try:
        args = args if isinstance(args, dict) else {}
        err = _harness_validate_subagent_brief(args)
        if err:
            return ("SUBAGENT RESULT \u2014 FAILED\nwhat it did: nothing (brief rejected)\n"
                    "evidence: (none)\nwhat it could NOT do: %s\n"
                    "what the parent should do next: fix the brief and call spawn_subagent again." % err), False
        brief = str(args.get("brief") or "").strip()
        if not brief:
            parts = []
            for k in ("task", "outcome", "constraints", "facts"):
                if str(args.get(k) or "").strip():
                    parts.append("%s: %s" % (k.upper(), str(args.get(k)).strip()))
            brief = "\n".join(parts)
        prompt = ("You are a subagent. Work ONLY from this self-contained brief \u2014 you have no parent transcript.\n"
                  "Return a structured block with exactly these sections:\n"
                  "what it did / evidence (file paths, log lines, server responses) / what it could NOT do / what the parent should do next.\n"
                  "Never claim done without evidence. Never spawn another subagent.\n\n[BRIEF]\n" + brief)
        if engine_call is not None:
            text = str(engine_call(prompt, 2048) or "").strip()
            if not text:
                return ("SUBAGENT RESULT \u2014 FAILED\nwhat it did: nothing (empty subagent reply)\nevidence: (none)\n"
                        "what it could NOT do: the subagent returned no text\nwhat the parent should do next: retry once with a shorter brief.", False)
            return ("SUBAGENT RESULT\n" + text), True
        # Live path: one non-streaming OpenAI-compatible call, no tools.
        _eng, _model, _why = _v62_active_engine_info()
        _base = _active_engine_base_url()
        _req = {"model": _model, "messages": [{"role": "system", "content": "You are a focused subagent. Answer with the structured result block only."}, {"role": "user", "content": prompt}], "stream": False, "max_tokens": 2048, "temperature": 0.6}
        _payload = json.dumps(_req).encode("utf-8")
        _http = urllib.request.Request(_base.rstrip("/") + "/v1/chat/completions", data=_payload, headers={"Content-Type": "application/json", "Authorization": "Bearer " + MASTER_API_KEY, "X-API-Key": MASTER_API_KEY}, method="POST")
        with urllib.request.urlopen(_http, timeout=300) as _resp:
            _data = json.loads(_resp.read().decode("utf-8", errors="ignore"))
        _ch = ((_data.get("choices") or [{}])[0] or {})
        _txt = str(((_ch.get("message") or {}).get("content") or "")).strip()
        if not _txt:
            return ("SUBAGENT RESULT \u2014 FAILED\nwhat it did: nothing (empty subagent reply)\nevidence: (none)\n"
                    "what it could NOT do: the engine returned no content\nwhat the parent should do next: retry once with a shorter brief.", False)
        return ("SUBAGENT RESULT\n" + _txt), True
    except Exception as e:
        return ("SUBAGENT RESULT \u2014 FAILED\nwhat it did: nothing (subagent run failed)\nevidence: (none)\n"
                "what it could NOT do: %s\nwhat the parent should do next: retry once, or do this step in the parent turn." % str(e)), False


