def sanitize_claude_windows_paths(text_or_path, is_file_arg=False):
    """
    Fixes the exact Windows Claude Desktop (`<> Code` mode) bug seen in image_9a8c5e.jpg & image_9a8c1e.jpg:
    Claude Desktop injects virtual Linux paths like `/home/lh/claude/projects/-workspace/ext-src/src/content.js`
    even when `Bash` runs in Windows Git Bash at `/g/ext` (`G:\\ext`), causing Windows Python & Bash to fail with:
      `can't open file 'F:\\AI-Workspace\\tools\\git\\home\\lh\\claude\\projects\\-workspace\\...': [Errno 2] No such file or directory`
    Rewrites `/home/.../claude/projects/-workspace/` -> `./` (or relative path) so Write, Edit, Read, and Bash all target the real workspace!
    """
    if not isinstance(text_or_path, str) or not text_or_path:
        return text_or_path
    s = text_or_path
    s = re.sub(r"/home/[a-zA-Z0-9_.-]+/claude/projects/[a-zA-Z0-9_.-]+/", "./", s)
    s = re.sub(r"/home/[a-zA-Z0-9_.-]+/claude/projects/[a-zA-Z0-9_.-]+\b", ".", s)
    s = re.sub(r"/workspace/", "./", s)
    if is_file_arg:
        s = s.strip()
        if s.startswith("./") and len(s) > 2:
            s = s[2:]
    return s

def normalize_declared_tools(raw_tools, user_hint=""):
    """
    Normalizes OpenAI, Anthropic, DeepSeek Harness (`dsh`), OpenCode, or Codex Responses tool definitions
    into a clean list of {"name": str, "description": str, "parameters": dict}.
    CRITICAL v34 FIX:
      - Preserves all up to 64 client tools (including `pwsh`, `skill`, `subagent*`, `spawn_teammate`,
        `terminal*`, `browser*`, `cordis*`, `web_search`, `web_fetch`) instead of cutting off at 22!
    """
    if not isinstance(raw_tools, list):
        return []
    out = []
    for t in raw_tools:
        if not isinstance(t, dict):
            continue
        t_type = str(t.get("type") or "").lower()
        if t_type in BLOCKED_CLOUD_TOOLS:
            continue
        if isinstance(t.get("function"), dict):
            fn = t["function"]
            name = str(fn.get("name") or "").strip()
            desc = str(fn.get("description") or "")[:280]
            params = fn.get("parameters") or {"type": "object", "properties": {}}
        else:
            name = str(t.get("name") or "").strip()
            desc = str(t.get("description") or "")[:280]
            params = t.get("input_schema") or t.get("parameters") or {"type": "object", "properties": {}}
        if not name or name.lower() in BLOCKED_CLOUD_TOOLS:
            continue
        out.append({"name": name, "description": desc, "parameters": params if isinstance(params, dict) else {}})

    # Detect if this request is already inside a Subagent (no TodoWrite/Plan tools) -> prevent recursive subagent spawning!
    declared_low_set = {x["name"].lower() for x in out}
    is_subagent_turn = ("todowrite" not in declared_low_set and "todo_write" not in declared_low_set and "update_plan" not in declared_low_set and len(out) < 12)

    core_tools = []
    other_tools = []
    for x in out:
        nl = x["name"].lower()
        if is_subagent_turn and nl in ("agent", "task", "subagent", "delegate", "subagent_fork"):
            continue
        if nl in PRIORITY_CODE_TOOLS or nl.startswith(("browser", "subagent", "terminal", "cordis", "mcp_")):
            core_tools.append(x)
        else:
            other_tools.append(x)

    # Keep up to 64 tools so DeepSeek Harness (57 tools) and OpenCode MCP/Skill/Browser suites are 100% preserved!
    out = (core_tools + other_tools)[:64]
    return out

def format_tools_system_block(norm_tools):
    if not norm_tools:
        return ""
    lines = [
        "\n# Tools",
        "You have access to the following tools to inspect files, run commands, control the built-in browser, invoke skills/subagents, and build software:",
        "<tools>"
    ]
    for t in norm_tools:
        props = (t.get("parameters") or {}).get("properties") or {}
        req = (t.get("parameters") or {}).get("required") or []
        p_summary = {}
        for k, v in list(props.items())[:8]:
            if isinstance(v, dict):
                t_str = str(v.get("type") or ("object" if k == "input" else "string"))
                if v.get("enum"):
                    p_summary[k] = {"type": t_str, "enum": v["enum"][:6]}
                else:
                    p_summary[k] = t_str
            else:
                p_summary[k] = "string"
        lines.append(json.dumps({
            "name": t["name"],
            "desc": str(t.get("description") or "")[:80],
            "params": p_summary,
            "req": req[:8]
        }, ensure_ascii=False))
    declared_names_str = ", ".join(t["name"] for t in norm_tools)
    lines.extend([
        "</tools>",
        "CRITICAL AGENT EXECUTION RULES:",
        f"1. You may ONLY call tool names from this exact list: [{declared_names_str}].",
        "2. Do NOT reply with just 'I will research/build this, please wait' or stop without calling a tool! You MUST immediately output a <tool_call> block to execute your step right now:",
        "<tool_call>",
        "<function=TOOL_NAME>",
        "<parameter=PARAM_NAME>",
        "PARAM_VALUE",
        "</parameter>",
        "</function>",
        "</tool_call>",
        "3. Stop immediately after </tool_call>. Build all files completely using Write/Edit.",
        "4. BUILT-IN BROWSER & SKILL RULE: When the user asks to use the browser, inspect a web page/tab (e.g. `tab_...`, `@e1`), or check a logged-in account (like Gmail/Kaggle), DO NOT say you cannot access the browser and DO NOT launch a blank external Chrome! Immediately call `skill` with `{'name': 'browser'}` (if `skill` is in your tools) or call `browser*` / `cordis*` / `web_fetch` tools directly to interact with the user's active logged-in browser session!",
        "5. DO NOT HUNT FOR `PROJECT_MEMORY.md`: Never waste your first turn running `glob` or `read` to search for `PROJECT_MEMORY.md` or unrelated `.md` files unless the user explicitly asked for them. Start executing the user's exact request on Turn 1!",
        "6. STRICT FILE CREATION & WINDOWS POWERSHELL RULE: Always use `write` / `edit` tools directly to create or modify files. When using `shell` or `pwsh` on Windows, write valid PowerShell commands (NEVER use Linux `export VAR=1` or wrap PowerShell inside `powershell -Command '...'` which strips `$_` variables)!"
    ])
    return "\n".join(lines)

def _harness_openai_tools(norm_tools):
    """Client/server tools -> OpenAI function-tool objects for the engine.

    The unified interceptor never sent tools to the engine, so Strata
    could never return native tool_calls — the only tool path was the
    <tool_call> text hack. Returns [] when nothing is declared.
    Pure — unit-tested.
    """
    out = []
    for t in (norm_tools or []):
        if not isinstance(t, dict):
            continue
        name = str(t.get("name") or "").strip()
        if not name:
            continue
        out.append({"type": "function", "function": {"name": name, "description": str(t.get("description") or "")[:500], "parameters": t.get("parameters") or {"type": "object", "properties": {}}}})
    return out


def parse_model_tool_calls(text, norm_tools=None):
    if not text:
        return "", []
    text = re.sub(r"(?:<think>|◁think▷)[\s\S]*?(?:</think>|◁/think▷)\s*", "", text)
    if "<tool_call>" not in text and "<function=" not in text and "<parameter=" not in text:
        return _f6_apply_patch_fallback(text, norm_tools)

    tool_name_map = {}
    param_type_map = {}
    param_schema_map = {}
    required_map = {}
    for t in (norm_tools or []):
        tname = t["name"]
        tl = tname.lower()
        tool_name_map[tl] = tname
        props = (t.get("parameters") or {}).get("properties") or {}
        req = (t.get("parameters") or {}).get("required") or []
        required_map[tl] = req if isinstance(req, list) else []
        if isinstance(props, dict):
            param_schema_map[tl] = props
            param_type_map[tl] = {
                k: (v.get("type") if isinstance(v, dict) else "string")
                for k, v in props.items()
            }

    calls = []

    def resolve_name(raw_name):
        if not raw_name:
            return None
        rn = str(raw_name).strip()
        rl = rn.lower()
        if rl in tool_name_map:
            return tool_name_map[rl]
        shell_targets = ["pwsh", "bash", "shell", "shell_command", "exec_command", "local_shell", "run_command", "execute_command", "container.exec", "powershell", "cmd", "terminal_send"]
        alias_groups = [
            ({"list_files", "ls", "list_dir", "dir", "find_files", "glob"}, ["glob", "list", "ls"] + shell_targets),
            ({"search", "grep", "ripgrep", "rg", "find_in_files", "code_search", "codesearch"}, ["grep", "search", "codesearch", "code_search", "glob"] + shell_targets),
            ({"exec", "execute", "run_command", "execute_command", "exec_command", "local_shell", "cmd", "shell", "bash", "pwsh", "powershell", "shell_command", "terminal"}, shell_targets),
            ({"write_file", "create_file", "save_file", "write"}, ["write", "write_file", "edit", "apply_patch"] + shell_targets),
            ({"read_file", "view_file", "cat", "read"}, ["read", "read_file"] + shell_targets),
            ({"edit_file", "replace", "patch", "edit", "multiedit", "multi_edit", "apply_patch"}, ["edit", "edit_file", "multiedit", "apply_patch", "write"] + shell_targets),
            ({"task", "agent", "subagent", "delegate", "spawn_teammate", "subagent_fork"}, ["subagent", "agent", "task", "subagent_fork", "spawn_teammate"]),
            ({"todo", "todowrite", "todo_write", "tasks", "plan", "update_plan", "taskupdate", "taskcreate", "tasklist", "taskget"}, ["todo_write", "todowrite", "taskupdate", "taskcreate", "tasklist", "taskget", "update_plan", "task"]),
            ({"web_search", "websearch", "google_search"}, ["web_search", "websearch", "webfetch", "web_fetch"]),
            ({"web_fetch", "webfetch", "fetch", "curl"}, ["web_fetch", "webfetch", "web_search", "websearch"]),
            ({"web_download", "download", "download_file", "fetch_file", "webdownload", "download_image", "save_image"}, ["web_download"]),
            ({"image", "image_generation", "generate_image", "create_image", "draw_image"}, ["image"]),
        ]
        for group_set, target_prefs in alias_groups:
            if rl in group_set:
                for tp in target_prefs:
                    if tp in tool_name_map:
                        return tool_name_map[tp]
        # Fuzzy substring fallback across declared tool_name_map
        for k_low, orig_name in tool_name_map.items():
            if rl in k_low or k_low in rl:
                return orig_name
        for k_low, orig_name in tool_name_map.items():
            if any(sh_w in k_low for sh_w in ("shell", "exec", "bash", "pwsh", "cmd", "command")):
                if rl in ("ls", "dir", "find", "pwd", "mkdir", "rm", "cp", "mv", "cat", "grep", "sh", "bash", "pwsh", "shell", "run"):
                    return orig_name
        # v76.2 IMAGE: "image" is a server tool like web_fetch — it is
        # always executable even when the caller's norm_tools list does
        # not declare it (the proxy EOF handler parses with web-only norms).
        if rl in ("image", "image_generation", "generate_image", "create_image", "draw_image"):
            return "image"
        if tool_name_map:
            return None
        return rn

    def _try_parse_structured_value(val_str):
        """Parses JSON or Python-literal dicts/lists cleanly (fixes single-quoted list/dict args in DSH & OpenCode)."""
        s = val_str.strip()
        if not s:
            return None
        try:
            return json.loads(s)
        except Exception:
            pass
        if (s.startswith("{") and s.endswith("}")) or (s.startswith("[") and s.endswith("]")):
            try:
                import ast as _ast_mod
                return _ast_mod.literal_eval(s)
            except Exception:
                pass
        return None

    def coerce_val(tool_lower, param_name, raw_val):
        val_str = str(raw_val).strip("\r\n")
        if not tool_lower:
            return val_str
        expected_type = param_type_map.get(tool_lower, {}).get(param_name)
        # Note: in DeepSeek Harness `cordis_inspect_query`, `properties["input"]` has NO `"type"` field,
        # yet DSH requires `"input"` to be a JSON object (`dict`)!
        if expected_type in ("integer", "number", "boolean", "array", "object") or param_name in ("input", "todos", "args", "arguments", "parameters", "options", "headers", "data"):
            parsed = _try_parse_structured_value(val_str)
            if parsed is not None:
                return parsed
            if expected_type == "integer":
                try:
                    return int(float(val_str.strip()))
                except Exception:
                    pass
            elif expected_type == "number":
                try:
                    return float(val_str.strip())
                except Exception:
                    pass
        if val_str.lower() in ("true", "false") and (expected_type == "boolean" or param_name in (" background", "run_in_background", "replace_all", "recursive")):
            return val_str.lower() == "true"
        return val_str

    def sanitize_windows_powershell_command(cmd_str):
        """
        Fixes all Windows PowerShell (`shell` / `pwsh`) failures seen in `master-instruction-kaggle-account-creation-verificati.json`:
          1. Never use Linux `export K=V; ` (which throws `export : The term 'export' is not recognized`).
             Automatically converts `export VAR=VAL;` -> `$env:VAR='VAL'; `.
          2. Unwraps redundant `powershell [-NoProfile] [-ExecutionPolicy Bypass] -Command "..."` wrappers
             when the shell tool is ALREADY PowerShell, preventing outer double quotes from stripping `$_` and `$p`!
          3. Translates Linux idioms (`2>/dev/null`, `2>nul`, `&&`, `|| true`, `ls -la`, `head -n N`) into native PowerShell.
        """
        c = str(cmd_str).strip()
        # 1. Convert leading/inline `export KEY=VAL;` into PowerShell `$env:KEY='VAL';`
        def _repl_export(m):
            assigns = m.group(1).strip()
            ps_parts = []
            for pair in re.findall(r"([A-Za-z_][A-Za-z0-9_]*)=([^\s;]+)", assigns):
                k, v = pair[0], pair[1].strip(chr(34) + chr(39))
                ps_parts.append(f"$env:{k}='{v}'")
            return ("; ".join(ps_parts) + "; ") if ps_parts else ""
        c = re.sub(r"\bexport\s+((?:[A-Za-z_][A-Za-z0-9_]*=[^\s;]+\s*)+);?\s*", _repl_export, c)

        # 2. Unwrap redundant outer `powershell ... -Command "..."` or `pwsh ... -Command "..."` anywhere in the command
        def _unwrap_pwsh(m):
            q_char = m.group(1)
            inner_ps = m.group(2)
            if q_char == chr(34):
                inner_ps = inner_ps.replace(chr(92) + chr(34), chr(34)).replace(chr(96) + chr(34), chr(34)).replace(chr(96) + chr(36), chr(36))
            return inner_ps.strip()
        c = re.sub(
            r"(?:powershell(?:\.exe)?|pwsh(?:\.exe)?)\s+(?:-[A-Za-z]+(?:\s+(?:Bypass|Hidden|NonInteractive|NoLogo|NoProfile))?\s+)*-(?:Command|c)\s+([\x22\x27])([\s\S]+)\1\s*$",
            _unwrap_pwsh,
            c,
            flags=re.I
        )

        # 3. Translate Linux redirections & pipeline helpers into native PowerShell
        c = re.sub(r"2>/dev/null", "2>$null", c)
        c = re.sub(r"2>nul\b", "2>$null", c)
        c = re.sub(r"\bls\s+-la\b", "Get-ChildItem -Force", c)
        c = re.sub(r"\bls\s+-l\b", "Get-ChildItem", c)
        c = re.sub(r"\bls\s+-a\b", "Get-ChildItem -Force", c)
        c = re.sub(r"find\s+\.\s+-maxdepth\s+\d+\s+-type\s+d", "Get-ChildItem -Recurse -Depth 2 -Directory -ErrorAction SilentlyContinue", c)
        c = re.sub(r"find\s+([^\s|;]+)\s+-maxdepth\s+\d+\s+-type\s+f", r"Get-ChildItem -Path \1 -Recurse -Depth 2 -File -ErrorAction SilentlyContinue", c)
        c = re.sub(r"\|\s*head\s+-n?\s*(\d+)", r"| Select-Object -First \1", c)
        c = re.sub(r"\bmkdir\s+-p\s+", "New-Item -ItemType Directory -Force -Path ", c)
        c = re.sub(r"\brm\s+-rf\s+", "Remove-Item -Recurse -Force -ErrorAction SilentlyContinue ", c)
        c = re.sub(r"\s+\|\|\s+echo\s+[^;&|\n]+", "", c)
        c = c.replace(" || true", "").replace(" && ", " ; ")
        return c

    def validate_and_append_call(resolved_fn, args):
        if not resolved_fn or not isinstance(resolved_fn, str):
            return
        if not isinstance(args, dict):
            args = {}
        fn_low = resolved_fn.lower()
        if fn_low in BLOCKED_CLOUD_TOOLS:
            return

        expected_props = param_schema_map.get(fn_low) or {}
        req_fields = required_map.get(fn_low) or []

        # 0A. Fix DeepSeek Harness `cordis_inspect_query` (`"input" must be an object`)
        if "cordis_inspect" in fn_low or "input" in req_fields:
            if "input" in args and isinstance(args["input"], str):
                parsed_inp = _try_parse_structured_value(args["input"])
                if isinstance(parsed_inp, dict):
                    args["input"] = parsed_inp
                else:
                    args["input"] = {"query": args["input"]}
            elif "input" in req_fields and not isinstance(args.get("input"), dict):
                extra_k = {k: v for k, v in args.items() if k not in expected_props}
                args["input"] = extra_k if extra_k else {}

        # 0B. Fix `todo_write` / `todowrite` (`todos` array items must NOT contain undeclared `activeForm` when `additionalProperties: false`)
        if fn_low in ("todo_write", "todowrite"):
            raw_todos = args.get("todos")
            if isinstance(raw_todos, str):
                raw_todos = _try_parse_structured_value(raw_todos)
            if not isinstance(raw_todos, list):
                raw_todos = []
            todos_prop_schema = expected_props.get("todos") if isinstance(expected_props.get("todos"), dict) else {}
            items_schema = todos_prop_schema.get("items") if isinstance(todos_prop_schema.get("items"), dict) else {}
            allowed_item_keys = set((items_schema.get("properties") or {}).keys()) or {"content", "status", "id", "priority"}
            req_item_keys = set(items_schema.get("required") or ["content", "status"])
            clean_todos = []
            for idx_t, item in enumerate(raw_todos):
                if isinstance(item, str):
                    item = {"content": item, "status": "in_progress" if idx_t == 0 else "pending"}
                if isinstance(item, dict):
                    filtered_item = {}
                    for ik, iv in item.items():
                        if ik in allowed_item_keys:
                            filtered_item[ik] = iv
                    if "content" not in filtered_item:
                        filtered_item["content"] = str(item.get("content") or item.get("task") or item.get("title") or item.get("activeForm") or f"Step {idx_t + 1}")
                    if "status" not in filtered_item:
                        filtered_item["status"] = str(item.get("status") or "pending")
                    if "id" in req_item_keys and "id" not in filtered_item:
                        filtered_item["id"] = str(item.get("id") or f"todo_{idx_t + 1}")
                    if "priority" in req_item_keys and "priority" not in filtered_item:
                        filtered_item["priority"] = str(item.get("priority") or "medium")
                    clean_todos.append(filtered_item)
            args["todos"] = clean_todos

        # 1. Auto-repair Agent / Task / Subagent tool calls (fixes OpenCode `subagent`, DSH `subagent*`/`spawn_teammate`, and Claude Code `Agent`)
        if fn_low in ("agent", "task", "subagent", "subagent_codex", "subagent_claude_code", "subagent_fork", "spawn_teammate"):
            if not args.get("prompt") and ("prompt" in expected_props or "prompt" in req_fields or fn_low in ("agent", "task", "subagent")):
                args["prompt"] = (
                    args.get("task")
                    or args.get("instructions")
                    or args.get("goal")
                    or args.get("query")
                    or args.get("message")
                    or args.get("description")
                    or "Inspect the workspace and implement the required project components."
                )
            if "task" in req_fields and not args.get("task"):
                args["task"] = args.get("prompt") or args.get("description") or "Execute the assigned subtask."
            if "goal" in req_fields and not args.get("goal"):
                args["goal"] = args.get("prompt") or args.get("task") or args.get("description") or "Execute the assigned subtask."
            if "name" in req_fields and not args.get("name"):
                args["name"] = args.get("agent") or args.get("role") or "worker"
            if ("description" in expected_props or "description" in req_fields) and not args.get("description"):
                words = str(args.get("prompt") or args.get("task") or "Subagent task").split()[:6]
                args["description"] = " ".join(words)[:48] or "Subagent task"
            if "agent" in expected_props or "agent" in req_fields or fn_low == "subagent":
                if not args.get("agent"):
                    ag_enum = (expected_props.get("agent") or {}).get("enum") if isinstance(expected_props.get("agent"), dict) else None
                    args["agent"] = (ag_enum[0] if isinstance(ag_enum, list) and ag_enum else None) or args.get("subagent_type") or args.get("type") or "general"
            if "subagent_type" in expected_props or "subagent_type" in req_fields or fn_low == "agent":
                if not args.get("subagent_type"):
                    st_enum = (expected_props.get("subagent_type") or {}).get("enum") if isinstance(expected_props.get("subagent_type"), dict) else None
                    args["subagent_type"] = (st_enum[0] if isinstance(st_enum, list) and st_enum else None) or args.get("agent") or args.get("type") or "general-purpose"

        # 2. Auto-repair Skill tool (fixes `skill` in OpenCode & DSH so `skill({"name": "browser"})` always succeeds!)
        if fn_low == "skill":
            sk_val = args.get("name") or args.get("id") or args.get("skill") or "browser"
            if "id" in expected_props or "id" in req_fields:
                args["id"] = sk_val
            if "name" in expected_props or "name" in req_fields:
                args["name"] = sk_val
            if "skill" in expected_props or "skill" in req_fields:
                args["skill"] = sk_val
            if not args:
                args["name"] = sk_val

        # 3. Auto-repair Glob / Grep when mapped from list_files / search
        if fn_low == "glob" and not args.get("pattern"):
            args["pattern"] = str(args.get("path") or args.get("query") or "*")
        if fn_low in ("grep", "search") and not args.get("pattern"):
            args["pattern"] = str(args.get("query") or args.get("search") or args.get("text") or ".*")

        # 4. Auto-repair Bash / PowerShell / shell / pwsh commands
        if fn_low in ("bash", "pwsh", "powershell", "cmd", "shell", "shell_command", "run_command", "execute_command", "exec_command", "local_shell"):
            if not args.get("command"):
                cmd_alt = args.get("cmd") or args.get("script") or args.get("input") or args.get("path") or args.get("query")
                if cmd_alt:
                    args["command"] = f"Get-ChildItem {cmd_alt}" if (fn_low in ("pwsh", "powershell", "shell") and args.get("path") and not args.get("cmd")) else str(cmd_alt)
                else:
                    return
            raw_cmd = sanitize_claude_windows_paths(str(args["command"]), is_file_arg=False)
            raw_cmd = re.sub(r"[═─╔╗╚╝║━┏┓┗┛┃]+", "=", raw_cmd)
            if fn_low in ("pwsh", "powershell", "cmd", "shell", "shell_command", "exec_command", "local_shell"):
                raw_cmd = sanitize_windows_powershell_command(raw_cmd)
            else:
                m_cat_write = re.match(r"^\s*(?:#[^\n]*\n\s*)*cat\s+>\s*([^\s<|;&]+)\s+<<\s*[\x27\"]?(\w+)[\x27\"]?\s*\n([\s\S]*?)\n\2\s*$", raw_cmd.strip())
                if m_cat_write and ("write" in tool_name_map or "write_file" in tool_name_map):
                    target_w_tool = tool_name_map.get("write") or tool_name_map.get("write_file")
                    clean_fp = sanitize_claude_windows_paths(m_cat_write.group(1).strip(), is_file_arg=True)
                    file_body = m_cat_write.group(3)
                    diag_log("INFO", f"Auto-converted Bash cat heredoc into native Write({clean_fp})!")
                    return validate_and_append_call(target_w_tool, {"file_path": clean_fp, "content": file_body})
                if re.search(r"\bwc\s+-l\b", raw_cmd) and "|| true" not in raw_cmd:
                    raw_cmd = re.sub(r"(\bwc\s+-l\s+[^;&|\n]+)\s*$", r"\1 2>/dev/null || true", raw_cmd)
            args["command"] = raw_cmd
            if "description" in req_fields and not args.get("description"):
                args["description"] = f"Execute: {str(args['command'])[:40]}"

        # 5. Auto-repair file path key names + Strip fake /home/lh/claude/projects/-workspace/ prefixes
        if fn_low in ("write", "write_file", "read", "read_file", "edit", "edit_file", "multiedit", "multi_edit", "glob", "grep"):
            for pk in ("file_path", "filePath", "path", "file", "filename", "directory", "workdir"):
                if isinstance(args.get(pk), str):
                    args[pk] = sanitize_claude_windows_paths(args[pk], is_file_arg=True)
        if fn_low in ("write", "write_file", "read", "read_file", "edit", "edit_file", "multiedit", "multi_edit"):
            fp_val = args.get("file_path") or args.get("filePath") or args.get("path") or args.get("file") or args.get("filename")
            if fp_val:
                fp_val = sanitize_claude_windows_paths(str(fp_val), is_file_arg=True)
                if "filePath" in expected_props and "filePath" not in args:
                    args["filePath"] = fp_val
                elif "file_path" in expected_props and "file_path" not in args:
                    args["file_path"] = fp_val
                elif "path" in expected_props and "path" not in args:
                    args["path"] = fp_val
                elif "file_path" not in args and "filePath" not in args:
                    args["file_path"] = fp_val
            elif fn_low in ("write", "write_file", "read", "read_file"):
                return
            if fn_low in ("write", "write_file") and "content" not in args:
                args["content"] = args.get("text") or args.get("code") or args.get("data") or ""

        # 6. Universal Schema-Driven Fallback for any remaining required fields
        for rf in req_fields:
            if rf not in args or args[rf] is None or args[rf] == "":
                p_schema = expected_props.get(rf) if isinstance(expected_props.get(rf), dict) else {}
                p_enum = p_schema.get("enum")
                p_type = p_schema.get("type", "string")
                if isinstance(p_enum, list) and p_enum:
                    args[rf] = p_enum[0]
                elif rf == "input":
                    args[rf] = {}
                elif rf == "todos":
                    args[rf] = []
                elif rf == "agent":
                    args[rf] = args.get("subagent_type") or "general"
                elif rf == "subagent_type":
                    args[rf] = args.get("agent") or "general-purpose"
                elif rf in ("id", "name", "skill"):
                    args[rf] = str(args.get("name") or args.get("id") or "browser")
                elif rf in ("prompt", "query", "instruction", "description", "task", "message", "goal"):
                    args[rf] = str(args.get("prompt") or args.get("description") or args.get("query") or "Proceed with task")
                elif rf in ("file_path", "filePath", "path"):
                    args[rf] = str(args.get("file_path") or args.get("filePath") or args.get("path") or ".")
                elif rf in ("pattern",):
                    args[rf] = "*"
                elif p_type == "boolean":
                    args[rf] = False
                elif p_type in ("integer", "number"):
                    args[rf] = 1
                elif p_type == "array":
                    args[rf] = []
                elif p_type == "object":
                    args[rf] = {}
                else:
                    args[rf] = str(next((v for v in args.values() if isinstance(v, str) and v), "default"))

        calls.append({
            "id": "call_" + uuid.uuid4().hex[:20],
            "name": resolved_fn,
            "arguments": args
        })

    def parse_single_block(inner):
        inner_s = inner.strip()
        fn_matches = list(re.finditer(r"<function=([^>\s]+)>\s*([\s\S]*?)(?:</function>|$)", inner_s))
        if fn_matches:
            for fm in fn_matches:
                raw_fn = fm.group(1).strip()
                fn_body = fm.group(2)
                resolved_fn = resolve_name(raw_fn)
                if not resolved_fn:
                    diag_log("WARN", f"Skipped undeclared tool call '{raw_fn}' (declared={list(tool_name_map.values())})")
                    continue
                args = {}
                for pm in re.finditer(r"<parameter=([^>\s]+)>\s*([\s\S]*?)(?:</parameter>|$)", fn_body):
                    pname = pm.group(1).strip()
                    pval = pm.group(2)
                    args[pname] = coerce_val(resolved_fn.lower(), pname, pval)
                # v76.2: the whole call may arrive as ONE parameter
                # (<parameter=tool_call>{"name": "fetch", ...}).
                # Unwrap it into the real tool name + arguments.
                if isinstance(args.get("tool_call"), (str, dict)):
                    _tcv = args.pop("tool_call")
                    _tcj = _tcv if isinstance(_tcv, dict) else _try_parse_structured_value(str(_tcv).strip())
                    if isinstance(_tcj, dict) and _tcj.get("name"):
                        _rn3 = resolve_name(str(_tcj["name"]))
                        if _rn3:
                            resolved_fn = _rn3
                            _ta = _tcj.get("arguments") or _tcj.get("parameters") or _tcj.get("input") or {}
                            args = _ta if isinstance(_ta, dict) else {"input": _ta}
                validate_and_append_call(resolved_fn, args)
            return

        try:
            j = _try_parse_structured_value(inner_s)
            if isinstance(j, dict) and j.get("name"):
                resolved_fn = resolve_name(str(j["name"]))
                if not resolved_fn:
                    return
                args = j.get("arguments") or j.get("parameters") or j.get("input") or {}
                if isinstance(args, str):
                    parsed_a = _try_parse_structured_value(args)
                    args = parsed_a if isinstance(parsed_a, dict) else {"input": args}
                if isinstance(args, dict):
                    coerced_args = {}
                    for ak, av in args.items():
                        coerced_args[ak] = coerce_val(resolved_fn.lower(), ak, av) if isinstance(av, str) else av
                    args = coerced_args
                validate_and_append_call(resolved_fn, args)
        except Exception:
            m_name = re.search(r'"name"\s*:\s*"([^"]+)"', inner_s)
            if m_name:
                resolved_fn = resolve_name(m_name.group(1))
                if resolved_fn:
                    args = {}
                    for k_field in ("file_path", "filePath", "path", "command", "cmd", "pattern", "description", "prompt"):
                        mk = re.search(rf'"{k_field}"\s*:\s*"((?:[^"\\]|\\.)*)"', inner_s)
                        if mk:
                            try:
                                args[k_field] = json.loads('"' + mk.group(1) + '"')
                            except Exception:
                                args[k_field] = mk.group(1)
                    mc = re.search(r'"content"\s*:\s*"([\s\S]+)$', inner_s)
                    if mc and "content" not in args:
                        raw_c = re.sub(r'"\s*\}\s*\}\s*$', "", mc.group(1))
                        args["content"] = raw_c.replace("\\n", "\n").replace("\\t", "\t").replace('\\"', '"')
                    validate_and_append_call(resolved_fn, args)

    pattern = re.compile(r"<tool_call>\s*([\s\S]*?)(?:</tool_call>|$)")
    clean_parts = []
    last_idx = 0
    for m in pattern.finditer(text):
        clean_parts.append(text[last_idx:m.start()])
        parse_single_block(m.group(1))
        last_idx = m.end()
    clean_parts.append(text[last_idx:])
    cleaned = "".join(clean_parts).strip()

    if not calls and "<function=" in cleaned:
        bare_pat = re.compile(r"<function=[^>\s]+>[\s\S]*?(?:</function>|$)")
        clean_parts2 = []
        last_idx = 0
        for m in bare_pat.finditer(cleaned):
            clean_parts2.append(cleaned[last_idx:m.start()])
            parse_single_block(m.group(0))
            last_idx = m.end()
        clean_parts2.append(cleaned[last_idx:])
        cleaned = "".join(clean_parts2).strip()

    if not calls:
        # v76.2: bare <parameter=tool_call>{JSON}</parameter> — the model
        # emits the whole call as ONE parameter (no <tool_call> /
        # <function=> wrapper). Parse the JSON value, resolve the inner
        # name (fetch -> web_fetch via the resolve_name aliases) and
        # record the call; the block itself never reaches visible text.
        _bare_parts = []
        _last_b = 0
        _bare_found = False
        for _bm in re.finditer(r"<parameter=(?:tool_call|function_call)\s*>\s*([\s\S]*?)\s*</parameter>", cleaned):
            _j = _try_parse_structured_value(_bm.group(1).strip())
            if not isinstance(_j, dict) or not _j.get("name"):
                continue
            _rn = resolve_name(str(_j["name"]))
            if not _rn:
                continue
            _a = _j.get("arguments") or _j.get("parameters") or _j.get("input") or {}
            if isinstance(_a, str):
                _pa = _try_parse_structured_value(_a)
                _a = _pa if isinstance(_pa, dict) else {"input": _a}
            if isinstance(_a, dict):
                _a = {_ak: (coerce_val(_rn.lower(), _ak, _av) if isinstance(_av, str) else _av) for _ak, _av in _a.items()}
            _bare_parts.append(cleaned[_last_b:_bm.start()])
            _last_b = _bm.end()
            _bare_found = True
            validate_and_append_call(_rn, _a)
        if _bare_found:
            _bare_parts.append(cleaned[_last_b:])
            cleaned = "".join(_bare_parts).strip()
    if not calls:
        # v76.2: bare single-parameter form <parameter=url>...</parameter>
        # (no function named): infer the web tool from the parameter —
        # url -> web_fetch, query -> web_search. Web tools only; never
        # infer a shell/file tool from a bare parameter.
        for _pm in re.finditer(r"<parameter=(url|query)\s*>\s*([\s\S]+?)\s*</parameter>", cleaned):
            _pname, _pval = _pm.group(1), _pm.group(2).strip()
            # D3: a bare url parameter ending in a FILE extension is a
            # download request, not a page read (web_fetch would return
            # binary garbage for it). Page URLs still infer web_fetch.
            _infer = "web_fetch" if _pname == "url" else "web_search"
            if _pname == "url" and re.search(r"\.(png|jpe?g|gif|webp|avif|bmp|svg|pdf|zip|rar|7z|gz|tar|mp3|wav|ogg|mp4|webm|mkv|docx?|xlsx?|pptx?)(?:[?#]|$)", _pval, re.I):
                _infer = "web_download"
            _rn2 = resolve_name(_infer)
            if _rn2:
                validate_and_append_call(_rn2, {"url": _pval} if _pname == "url" else {"query": _pval})
        if calls:
            cleaned = re.sub(r"<parameter=(?:url|query)\s*>\s*[\s\S]+?\s*</parameter>", "", cleaned).strip()
    if not calls:
        # v76.2 IMAGE: bare <parameter=prompt>...</parameter> (no function
        # named): the prompt is an image prompt — infer the image tool
        # (mirrors the url -> web_fetch / query -> web_search rule above).
        for _pm in re.finditer(r"<parameter=prompt\s*>\s*([\s\S]+?)\s*</parameter>", cleaned):
            _rn3 = resolve_name("image")
            if _rn3:
                validate_and_append_call(_rn3, {"prompt": _pm.group(1).strip()})
        if calls:
            cleaned = re.sub(r"<parameter=prompt\s*>\s*[\s\S]+?\s*</parameter>", "", cleaned).strip()

    _pc, _pcalls = _f6_apply_patch_fallback(cleaned, norm_tools); return (_pc, calls + _pcalls)

def is_casual_conversational_turn(body):
    """
    STRICT FIRST-TURN GREETING DETECTOR (v29 Fix for `tools=0 msgs=4` & 30-minute 1-word stall bug!):
    Only returns True if:
      1. This is the VERY FIRST user turn of a conversation (zero prior assistant or tool messages in history!), AND
      2. The user's message is a pure short greeting ('hi', 'hello', 'হাই', 'কেমন আছো?') or identity question ('তুমি কোন মডেল?').
    NEVER strips tools (`norm_tools = []`) on multi-turn sessions (`msgs > 1`) or short follow-up commands ('ok', 'হ্যাঁ', 'করো', 'continue')!
    """
    if not isinstance(body, dict):
        return False
    # H123 (v76.5 H1): effort must NEVER defeat greeting detection. A
    # harness client sends Medium (or a thinking budget that maps to
    # High) on every turn, so the old effort check made a first-turn
    # "hi" take the full harness path (huge system prompt + tools)
    # and the engine took 40-75s to first token on one word. The
    # streamer downgrades a greeting turn to low effort (P2) instead.
    if body.get("web_search"):
        return False
    raw_list = body.get("messages") or body.get("input") or []
    if isinstance(raw_list, str):
        raw_list = [{"role": "user", "content": raw_list}]
    if not isinstance(raw_list, list) or not raw_list:
        return False

    non_sys_msgs = [
        m for m in raw_list
        if isinstance(m, dict) and m.get("role") not in ("system", "developer")
    ]
    # NEVER strip tools if there is already conversation history (more than 1 user message or any assistant/tool turn)!
    if len(non_sys_msgs) > 1:
        return False

    last_m = non_sys_msgs[-1] if non_sys_msgs else (raw_list[-1] if isinstance(raw_list[-1], dict) else {})
    if last_m.get("role") == "tool" or last_m.get("type") in ("function_call", "function_call_output"):
        return False

    last_txt = ""
    rc = last_m.get("content", "")
    if isinstance(rc, str):
        last_txt = rc.strip()
    elif isinstance(rc, list):
        for b in rc:
            if isinstance(b, dict):
                if b.get("type") in ("tool_result", "tool_use", "image", "image_url", "input_image"):
                    return False
                if b.get("type") in ("text", "input_text", "output_text"):
                    last_txt += " " + str(b.get("text", ""))
        last_txt = last_txt.strip()

    if not last_txt or "<tool_response>" in last_txt:
        return False

    clean_u = re.sub(r"<system-reminder>[\s\S]*?</system-reminder>", "", last_txt).strip()
    low_u = re.sub(r"[!?.।,]+", "", clean_u.lower()).strip()

    identity_questions = ("কোন মডেল", "কি মডেল", "তোমার নাম কি", "what model are you", "which model are you", "who are you")
    if any(iq in low_u for iq in identity_questions) and len(clean_u) < 120:
        return True

    exact_greetings = {
        "hi", "hello", "hey", "yo", "hola", "sup", "good morning", "good evening",
        # G1 (v76.5): "কি খবর" removed -- it asks for the news, it is
        # not a greeting; leaving it here stripped tools and forced the
        # greeting path (no research) on a news question.
        "হাই", "হ্যালো", "কেমন আছো", "কেমন আছেন", "সালাম", "আসসালামু আলাইকুম", "assalamu alaikum"
    }
    if low_u in exact_greetings:
        return True
    # BMRBD v76 STAGE-1 (benchmark gap 1): a natural multi-word greeting
    # ("হ্যাঁ হ্যালো, কি অবস্থা, কেমন আছো?") is a casual turn too — the
    # greeting-only check (no real content word) keeps short real questions
    # at full intelligence. NOTE: the looser "<=85 chars, no coding keyword"
    # detector below this function is deliberately DEAD code (v50 fix) — a
    # short factual question ("আকাশ নীল কেন?") must NOT become a greeting.
    if len(clean_u) < 80 and _is_greeting_only_text(low_u):
        return True
    # v50 Intelligence Restoration Fix:
    # NEVER classify non-greeting prompts as casual turns! Only true 1-3 word greetings ('hi', 'hello', 'হাই', 'কেমন আছো')
    # and model identity questions ('তুমি কোন মডেল?') are casual turns; all real questions get 100% full model intelligence!
    return False
    raw_list = body.get("messages") or body.get("input") or []
    if isinstance(raw_list, str):
        raw_list = [{"role": "user", "content": raw_list}]
    if not isinstance(raw_list, list) or not raw_list:
        return False

    # If the last message is a tool result or assistant tool call, it is definitely an active agentic coding turn
    last_m = raw_list[-1] if isinstance(raw_list[-1], dict) else {}
    if last_m.get("role") == "tool" or last_m.get("type") in ("function_call", "function_call_output"):
        return False

    last_txt = ""
    rc = last_m.get("content", "")
    if isinstance(rc, str):
        last_txt = rc.strip()
    elif isinstance(rc, list):
        for b in rc:
            if isinstance(b, dict):
                if b.get("type") in ("tool_result", "tool_use"):
                    return False
                if b.get("type") in ("text", "input_text", "output_text"):
                    last_txt += " " + str(b.get("text", ""))
        last_txt = last_txt.strip()

    if not last_txt or "<tool_response>" in last_txt:
        return False

    # Strip any <system-reminder> injected by Claude Code before checking message length/intent
    clean_u = re.sub(r"<system-reminder>[\s\S]*?</system-reminder>", "", last_txt).strip()
    low_u = clean_u.lower()

    # Exact or short greetings / casual chat (< 90 chars without coding/file/project keywords)
    identity_questions = ("কোন মডেল", "কি মডেল", "তোমার নাম কি", "what model are you", "which model are you", "who are you")
    if any(iq in low_u for iq in identity_questions) and len(clean_u) < 140:
        return True
    coding_keywords = (
        "code", "file", "build", "create", "fix", "error", "bug", "script", "python", "js", "html",
        "css", "ext", "app", "project", "run", "test", "install", "git", "repo", "function", "class",
        "write", "edit", "read", "bash", "cmd", "folder", "dir", "api", "json", " প্রজেক্ট", "কোড",
        "ফাইল", "তৈরি", "ফিক্স", "এক্সটেনশন", "স্ক্রিপ্ট", "বাগ", "ইরোর", "এরর"
    )
    if len(clean_u) <= 85 and not any(ck in low_u for ck in coding_keywords):
        return True
    return False


_RESPONSE_HISTORY_CACHE = {}
_RESPONSE_CACHE_LOCK = threading.Lock()

# ── BMRBD v76 PARITY (§6): file text extraction + thread fork/edit/regenerate ──
# Pure helpers (no I/O, no globals except the caps below) so the v76 test
# file can extract and exec them standalone. Endpoints in do_POST below.
_BMRBD_FILE_TEXT_MAX_BYTES = 20 * 1024 * 1024
_BMRBD_FILE_TEXT_MAX_CHARS = 45000
_BMRBD_FILE_TEXT_EXTS = {
    ".txt", ".md", ".markdown", ".csv", ".tsv", ".json", ".jsonl", ".xml",
    ".html", ".htm", ".log", ".py", ".js", ".ts", ".jsx", ".tsx", ".css",
    ".yaml", ".yml", ".toml", ".ini", ".cfg", ".sql", ".sh", ".bat", ".php",
    ".java", ".c", ".cpp", ".h", ".go", ".rs", ".rb", ".r", ".tex", ".rst",
}
_BMRBD_FILE_BINARY_EXTS = {".pdf", ".docx", ".xlsx", ".pptx"}


def _bmrbd_pdf_unescape(raw: bytes) -> str:
    """Decode one PDF literal string (escapes + octal), best effort."""
    out = bytearray()
    i = 0
    while i < len(raw):
        c = raw[i:i + 1]
        if c == b"\\" and i + 1 < len(raw):
            n = raw[i + 1:i + 2]
            if n in b"nrtbf":
                out += {b"n": b"\n", b"r": b"\r", b"t": b"\t", b"b": b"\b", b"f": b"\f"}[n]
                i += 2
            elif n in b"()\\":
                out += n
                i += 2
            elif 48 <= n[0] <= 55:
                j = i + 1
                oct_digits = bytearray()
                while j < len(raw) and len(oct_digits) < 3 and 48 <= raw[j] <= 55:
                    oct_digits.append(raw[j])
                    j += 1
                try:
                    out.append(int(bytes(oct_digits), 8) & 0xFF)
                except Exception:
                    pass
                i = j
            else:
                i += 2
        else:
            out += c
            i += 1
    if out[:2] == b"\xfe\xff":
        try:
            return bytes(out[2:]).decode("utf-16-be", errors="ignore")
        except Exception:
            pass
    return bytes(out).decode("utf-8", errors="replace")


def _bmrbd_extract_pdf_text(raw: bytes) -> str:
    """Stdlib-only PDF text extraction (no PyPDF on the kernel).

    Finds every stream, Flate-decodes it when the dictionary says so, and
    pulls the text-showing operators (Tj / TJ, literal + hex strings).
    Returns "" when nothing readable is found.
    """
    import zlib as _zlib
    parts = []
    for _m in re.finditer(rb"stream\r?\n", raw):
        _start = _m.end()
        _end = raw.find(b"endstream", _start)
        if _end < 0:
            continue
        _chunk = raw[_start:_end]
        _dict = raw[max(0, _m.start() - 400):_m.start()]
        if b"FlateDecode" in _dict:
            try:
                _chunk = _zlib.decompress(_chunk.strip(b"\r\n"))
            except Exception:
                try:
                    _chunk = _zlib.decompressobj().decompress(_chunk.strip(b"\r\n"))
                except Exception:
                    continue
        for _bt in re.finditer(rb"BT(.*?)ET", _chunk, re.S):
            _blk = _bt.group(1)
            for _t in re.finditer(rb"\((?:[^()\\]|\\.)*\)\s*Tj", _blk, re.S):
                _s = _t.group(0)
                _inner = _s[1:_s.rfind(b")")]
                parts.append(_bmrbd_pdf_unescape(_inner))
            for _t in re.finditer(rb"\[((?:[^\[\]\\]|\\.)*)\]\s*TJ", _blk, re.S):
                for _lit in re.finditer(rb"\((?:[^()\\]|\\.)*\)", _t.group(1), re.S):
                    _inner = _lit.group(0)[1:-1]
                    parts.append(_bmrbd_pdf_unescape(_inner))
            for _t in re.finditer(rb"<([0-9A-Fa-f\s]+)>\s*Tj", _blk):
                try:
                    _hx = bytes.fromhex(_t.group(1).decode("ascii", errors="ignore"))
                    parts.append(_bmrbd_pdf_unescape(_hx) if _hx[:2] != b"\xfe\xff" else _hx[2:].decode("utf-16-be", errors="ignore"))
                except Exception:
                    pass
    if not parts:
        # Fallback: any literal string in any stream (untagged text).
        for _m in re.finditer(rb"stream\r?\n", raw):
            _start = _m.end()
            _end = raw.find(b"endstream", _start)
            if _end < 0:
                continue
            _chunk = raw[_start:_end]
            if b"FlateDecode" in raw[max(0, _m.start() - 400):_m.start()]:
                try:
                    _chunk = _zlib.decompress(_chunk.strip(b"\r\n"))
                except Exception:
                    continue
            for _lit in re.finditer(rb"\((?:[^()\\]|\\.){4,}\)", _chunk):
                parts.append(_bmrbd_pdf_unescape(_lit.group(0)[1:-1]))
    text = "\n".join(p for p in (p.strip() for p in parts) if p)
    return re.sub(r"[ \t]+", " ", text)


def _bmrbd_extract_office_text(raw: bytes, kind: str) -> str:
    """Stdlib-only OOXML text extraction (.docx/.xlsx/.pptx via zipfile)."""
    import xml.etree.ElementTree as _ET
    import html as _html

    def _texts(xml_bytes: bytes, tag_suffix: str):
        try:
            _root = _ET.fromstring(xml_bytes)
        except Exception:
            return []
        _out = []
        _bare = tag_suffix.lstrip("}")
        for _el in _root.iter():
            if _el.tag.endswith(tag_suffix) or _el.tag == _bare:
                if _el.text:
                    _out.append(_el.text)
        return _out

    try:
        _zf = zipfile.ZipFile(io.BytesIO(raw), "r")
    except Exception:
        return ""
    if kind == "docx":
        try:
            _xml = _zf.read("word/document.xml")
        except Exception:
            return ""
        _paras = []
        for _p in re.split(rb"</w:p>", _xml):
            _ts = re.findall(rb"<w:t[^>]*>(.*?)</w:t>", _p, re.S)
            if _ts:
                _paras.append("".join(_html.unescape(t.decode("utf-8", errors="ignore")) for t in _ts))
        return "\n".join(_paras)
    if kind == "xlsx":
        _shared = []
        try:
            _xml = _zf.read("xl/sharedStrings.xml")
            for _si in re.findall(rb"<si>(.*?)</si>", _xml, re.S):
                _shared.append("".join(_html.unescape(t) for t in _texts(_si, "}t")))
        except Exception:
            pass
        _rows = []
        for _name in _zf.namelist():
            if re.match(r"xl/worksheets/sheet\d+\.xml$", _name):
                try:
                    _xml = _zf.read(_name)
                except Exception:
                    continue
                for _row in re.findall(rb"<row[^>]*>(.*?)</row>", _xml, re.S):
                    _cells = []
                    for _c in re.findall(rb"<c[^>]*>.*?</c>", _row, re.S):
                        _v = re.search(rb"<v>(.*?)</v>", _c, re.S)
                        _is = re.search(rb"<is>(.*?)</is>", _c, re.S)
                        if _is:
                            _cells.append("".join(_html.unescape(t) for t in _texts(_is.group(1), "}t")))
                        elif _v:
                            _val = _v.group(1).decode("utf-8", errors="ignore")
                            _t = re.search(rb't="([^"]+)"', _c)
                            if _t and _t.group(1) == b"s":
                                try:
                                    _val = _shared[int(_val)]
                                except Exception:
                                    pass
                            _cells.append(_val)
                    if _cells:
                        _rows.append("\t".join(_cells))
        return "\n".join(_rows)
    if kind == "pptx":
        _slides = []
        for _name in sorted(_zf.namelist()):
            if re.match(r"ppt/slides/slide\d+\.xml$", _name):
                try:
                    _xml = _zf.read(_name)
                except Exception:
                    continue
                _ts = _texts(_xml, "}t")
                if _ts:
                    _slides.append(" ".join(_html.unescape(t) for t in _ts))
        return "\n\n".join(_slides)
    return ""


def _bmrbd_extract_file_text(filename, raw_bytes, max_chars=_BMRBD_FILE_TEXT_MAX_CHARS):
    """Extract readable text from an uploaded file so it can reach the model.

    Returns {"ok": bool, "text": str, "truncated": bool, "format": str,
             "chars": int, "error": str}. Binary formats (pdf/docx/xlsx/pptx)
    are really parsed — never the raw bytes as text (the old client bug:
    readAsText on a PDF produced mojibake that was sent to the model).
    """
    _name = str(filename or "file")
    _ext = "." + _name.rsplit(".", 1)[-1].lower() if "." in _name else ""
    if raw_bytes is None:
        return {"ok": False, "text": "", "truncated": False, "format": _ext or "unknown", "chars": 0, "error": "empty file"}
    if len(raw_bytes) > _BMRBD_FILE_TEXT_MAX_BYTES:
        return {"ok": False, "text": "", "truncated": False, "format": _ext or "unknown", "chars": 0, "error": "file too large (max 20 MB)"}
    _text = ""
    _fmt = _ext or "unknown"
    if _ext in _BMRBD_FILE_BINARY_EXTS:
        if _ext == ".pdf":
            _text = _bmrbd_extract_pdf_text(raw_bytes)
            _fmt = "pdf"
        else:
            _text = _bmrbd_extract_office_text(raw_bytes, _ext[1:])
            _fmt = _ext[1:]
        if not _text.strip():
            return {"ok": False, "text": "", "truncated": False, "format": _fmt, "chars": 0, "error": "no readable text found in this " + _fmt.upper() + " file"}
    elif _ext in _BMRBD_FILE_TEXT_EXTS or _ext == "":
        try:
            _text = raw_bytes.decode("utf-8")
        except Exception:
            _text = raw_bytes.decode("utf-8", errors="replace")
        _text = _text.replace("\x00", "")
        _printable = sum(1 for _ch in _text[:2000] if _ch.isprintable() or _ch in "\n\r\t")
        if _text.strip() and _printable < max(1, int(len(_text[:2000]) * 0.7)):
            return {"ok": False, "text": "", "truncated": False, "format": _fmt, "chars": 0, "error": "unsupported binary format — only pdf/docx/xlsx/pptx and plain-text files can be read"}
        _fmt = "text"
    else:
        return {"ok": False, "text": "", "truncated": False, "format": _fmt, "chars": 0, "error": "unsupported file type (" + _ext + ") — upload pdf, docx, xlsx, pptx or a plain-text file"}
    _text = _text.strip("\n")
    _truncated = len(_text) > max_chars
    if _truncated:
        _text = _text[:max_chars]
    return {"ok": True, "text": _text, "truncated": _truncated, "format": _fmt, "chars": len(_text), "error": ""}


def _bmrbd_copy_messages(messages):
    try:
        return json.loads(json.dumps(messages))
    except Exception:
        import copy as _copy
        return _copy.deepcopy(messages)


def _bmrbd_fork_thread_messages(messages, idx, version_idx=None):
    """Fork a thread at message idx: new thread carries history up to and
    including that message (ChatGPT parity #38). If the fork point is an
    assistant message with versions and version_idx is given, the fork pins
    that version's content and drops the versions list. Raises ValueError
    on a bad index. Never mutates the input."""
    if not isinstance(messages, list) or not messages:
        raise ValueError("no messages to fork from")
    if not isinstance(idx, int) or isinstance(idx, bool) or idx < 0 or idx >= len(messages):
        raise ValueError("message index out of range")
    _snap = _bmrbd_copy_messages(messages[:idx + 1])
    _last = _snap[-1]
    if isinstance(_last, dict) and _last.get("role") == "assistant":
        _vers = _last.get("versions")
        if isinstance(_vers, list) and _vers and version_idx is not None:
            if not isinstance(version_idx, int) or version_idx < 0 or version_idx >= len(_vers):
                raise ValueError("version index out of range")
            _last["content"] = _vers[version_idx].get("content", "") if isinstance(_vers[version_idx], dict) else ""
            _last.pop("versions", None)
            _last.pop("versionIdx", None)
            _last.pop("version_idx", None)
    return _snap


def _bmrbd_edit_thread_message(messages, idx, new_text):
    """Edit a sent message (ChatGPT parity #39, server side): replace the
    content at idx and drop everything after it — the reply is re-run from
    the edited message. Returns the new message list. The client keeps its
    branch history locally; the server stores the edited line only."""
    if not isinstance(messages, list) or not messages:
        raise ValueError("no messages to edit")
    if not isinstance(idx, int) or isinstance(idx, bool) or idx < 0 or idx >= len(messages):
        raise ValueError("message index out of range")
    _text = str(new_text or "").strip()
    if not _text:
        raise ValueError("edited message is empty")
    _out = _bmrbd_copy_messages(messages[:idx + 1])
    _out[-1]["content"] = _text
    _out[-1].pop("branches", None)
    _out[-1].pop("branchIdx", None)
    return _out


def _bmrbd_truncate_for_regenerate(messages, assistant_idx):
    """Regenerate a reply (ChatGPT parity #39, server side): given an
    assistant message index, find the user message it answers, truncate
    the thread from that user message on, and return (truncated, user_text)
    so the caller can re-send the same question. Raises ValueError when
    there is no user message to regenerate from."""
    if not isinstance(messages, list) or not messages:
        raise ValueError("no messages to regenerate from")
    if not isinstance(assistant_idx, int) or isinstance(assistant_idx, bool) or assistant_idx < 0 or assistant_idx >= len(messages):
        raise ValueError("message index out of range")
    _u = assistant_idx
    while _u >= 0 and messages[_u].get("role") != "user":
        _u -= 1
    if _u < 0:
        raise ValueError("no user message before this reply")
    _user_text = str(messages[_u].get("content") or "")
    return _bmrbd_copy_messages(messages[:_u]), _user_text


def _clean_utf8_str_v42(val) -> str:
    if val is None:
        return ""
    if not isinstance(val, str):
        try:
            val = json.dumps(val, ensure_ascii=False)
        except Exception:
            val = str(val)
    val = val.replace("\x00", "")
    val = re.sub(r"\x1b\[[0-9;]*[a-zA-Z]", "", val)
    return val.encode("utf-8", errors="replace").decode("utf-8", errors="replace")

def build_unified_ollama_messages(body, norm_tools=None, effort=None, user_obj=None):
    chat_msgs = []
    sys_parts = []

    sys_val = body.get("system") or body.get("instructions")
    if isinstance(sys_val, str) and sys_val.strip():
        sys_parts.append(sys_val.strip())
    elif isinstance(sys_val, list):
        s_txt = "\n".join(b.get("text", "") for b in sys_val if isinstance(b, dict) and b.get("text"))
        if s_txt.strip():
            sys_parts.append(s_txt.strip())

    raw_list = body.get("messages")
    if raw_list is None:
        raw_list = body.get("input")

    if isinstance(raw_list, str):
        raw_list = [{"role": "user", "content": raw_list}]
    elif not isinstance(raw_list, list):
        raw_list = []

    prev_resp_id = body.get("previous_response_id")
    if prev_resp_id and isinstance(prev_resp_id, str):
        with _RESPONSE_CACHE_LOCK:
            cached_prior = _RESPONSE_HISTORY_CACHE.get(prev_resp_id)
            if cached_prior:
                raw_list = list(cached_prior) + list(raw_list)

    # Sanitize Codex / OpenCode special item types (`reasoning`, `item_reference`, `local_shell_call`, `custom_tool_call`)
    _cleaned_raw_list = []
    for _it in raw_list:
        if not isinstance(_it, dict):
            if isinstance(_it, str) and _it.strip():
                _cleaned_raw_list.append({"role": "user", "content": _clean_utf8_str_v42(_it.strip())})
            continue
        _mt = str(_it.get("type") or "").lower()
        if _mt in ("reasoning", "item_reference"):
            _sums = _it.get("summary") or []
            if isinstance(_sums, list):
                _stxt = "\n".join(_clean_utf8_str_v42(s.get("text", "")) for s in _sums if isinstance(s, dict) and s.get("text")).strip()
                if _stxt:
                    _cleaned_raw_list.append({"role": "assistant", "content": _stxt[:2000]})
            continue
        if _mt in ("local_shell_call", "custom_tool_call"):
            _it = dict(_it)
            _it["type"] = "function_call"
            _it["name"] = _it.get("name") or ("shell" if _mt == "local_shell_call" else "tool")
            _it["arguments"] = _it.get("arguments") or _it.get("input") or _it.get("action") or "{}"
        elif _mt in ("local_shell_call_output", "custom_tool_call_output", "computer_call_output"):
            _it = dict(_it)
            _it["type"] = "function_call_output"
        _cleaned_raw_list.append(_it)
    raw_list = _cleaned_raw_list

    # Extract the first real user query (BEFORE slicing!)
    first_real_user_msg = None
    for rm in raw_list:
        if isinstance(rm, dict) and rm.get("role") == "user":
            rc = rm.get("content", "")
            if isinstance(rc, list):
                rc_txt = "\n".join(str(b.get("text", "")) for b in rc if isinstance(b, dict) and b.get("type") in ("text", "input_text", "output_text")).strip()
            else:
                rc_txt = str(rc or "").strip()
            if rc_txt and not rc_txt.startswith("<tool_response>"):
                first_real_user_msg = {"role": "user", "content": rc_txt[:4000]}
                break

    # ── FIXED-ANCHOR KV-CACHE BLOCK COMPACTION & STRICT PER-CLIENT SESSION ISOLATION (v34) ──
    # Root Cause of the 4.2s pre-reply delay (`erased invalidated context checkpoint` in `/tmp/ollama-server.log`):
    # In v33, `cutoff_idx = max(1, len(raw_list) - 10)` shifted by +1 on EVERY turn after message 16,
    # mutating `raw_list[1]` on every single step and forcing Ollama to throw away 100% of its KV cache!
    # In v34, `cutoff_idx` is quantized to fixed 16-message anchor boundaries (`16, 32, 48, 64...`) ONLY when
    # `len(raw_list) > 28` or `total_raw_chars > 68000`! Within each 16-turn window, the prefix stays 100%
    # byte-for-byte identical, giving a 100% GPU KV cache hit (`<0.18s` prefill time!) on consecutive turns!
    session_seed = (first_real_user_msg["content"][:200] if first_real_user_msg else "default") + f"|tools={len(norm_tools or [])}"
    session_key = hashlib.md5(session_seed.encode("utf-8", errors="ignore")).hexdigest()[:16]

    compacted_ledger_note = ""
    total_raw_chars = sum(len(json.dumps(m, ensure_ascii=False)) for m in raw_list if isinstance(m, dict))
    if len(raw_list) > 28 or total_raw_chars > 68000:
        # Quantize anchor to fixed blocks of 16 so `cutoff_idx` stays constant for 16 consecutive turns!
        raw_target_cut = max(1, ((len(raw_list) - 14) // 16) * 16)
        with _SESSION_LOCK:
            cached_state = _SESSION_COMPACTION_STATE.get(session_key)
            if cached_state and cached_state["anchor_idx"] == raw_target_cut and cached_state["anchor_idx"] < len(raw_list):
                cutoff_idx = cached_state["anchor_idx"]
                compacted_ledger_note = cached_state["ledger_note"]
            else:
                cutoff_idx = min(raw_target_cut, max(1, len(raw_list) - 8))
                while cutoff_idx < len(raw_list) - 4:
                    m_cur = raw_list[cutoff_idx] if isinstance(raw_list[cutoff_idx], dict) else {}
                    r_cur = m_cur.get("role", "")
                    c_cur = json.dumps(m_cur.get("content", ""), ensure_ascii=False)
                    if r_cur == "tool" or m_cur.get("type") == "function_call_output" or "tool_result" in c_cur or "<tool_response>" in c_cur:
                        cutoff_idx += 1
                    else:
                        break
                older_slice = raw_list[1:cutoff_idx]
                completed_files = []
                executed_cmds = []
                for om in older_slice:
                    if not isinstance(om, dict):
                        continue
                    om_str = json.dumps(om, ensure_ascii=False)
                    for fm in re.finditer(r'"(?:file_path|filePath|path)"\s*:\s*"([^"]+)"', om_str):
                        fp = fm.group(1).strip()
                        if fp and fp not in completed_files:
                            completed_files.append(fp)
                    for fm2 in re.finditer(r'<parameter=(?:file_path|filePath|path)>\s*([^<\n]+)', om_str):
                        fp = fm2.group(1).strip()
                        if fp and fp not in completed_files:
                            completed_files.append(fp)
                    for cm in re.finditer(r'"command"\s*:\s*"([^"]{1,80})"', om_str):
                        cmd_s = cm.group(1).strip()
                        if cmd_s and cmd_s not in executed_cmds:
                            executed_cmds.append(cmd_s)
                ledger_lines = ["[COMPACTED SESSION LEDGER — DO NOT REPEAT COMPLETED WORK]"]
                if completed_files:
                    ledger_lines.append("• Files already created/inspected in earlier steps: " + ", ".join(completed_files[:40]))
                if executed_cmds:
                    ledger_lines.append("• Commands already executed in earlier steps: " + " | ".join(executed_cmds[:15]))
                ledger_lines.append("• Continue from the current step below without re-reading or recreating already-completed files.")
                compacted_ledger_note = "\n".join(ledger_lines)
                _SESSION_COMPACTION_STATE[session_key] = {
                    "anchor_idx": cutoff_idx,
                    "ledger_note": compacted_ledger_note,
                    "ts": time.time()
                }
        raw_list = [raw_list[0]] + raw_list[cutoff_idx:]

    raw_len_now = len(raw_list)
    for idx_raw, m in enumerate(raw_list):
        if not isinstance(m, dict):
            continue
        mtype = m.get("type", "")
        role = m.get("role", "")
        # Keep up to 16,000 chars of tool output for recent turns (last 6 messages) so files like `content-script.js`
        # are read in a SINGLE call instead of 8 repeated offset reads!
        tool_out_cap = 16000 if (raw_len_now - idx_raw) <= 6 else 6000

        if mtype == "function_call":
            fn_name = m.get("name", "tool")
            raw_args = m.get("arguments", "{}")
            try:
                args_dict = json.loads(raw_args) if isinstance(raw_args, str) else (raw_args or {})
            except Exception:
                args_dict = {"input": str(raw_args)}
            xml_params = "\n".join(f"<parameter={k}>\n{v}\n</parameter>" for k, v in args_dict.items())
            _fc_id = m.get("call_id") or m.get("id") or ""
            chat_msgs.append({
                "role": "assistant",
                "content": (f"[Tool call id: {_fc_id}]\n" if _fc_id else "") + f"<tool_call>\n<function={fn_name}>\n{xml_params}\n</function>\n</tool_call>"
            })
            continue

        if mtype == "function_call_output":
            out_val = m.get("output", "")
            if not isinstance(out_val, str):
                out_val = json.dumps(out_val, ensure_ascii=False)
            _fco_id = m.get("call_id") or m.get("id") or ""
            chat_msgs.append({
                "role": "user",
                "content": f"[Tool Output" + (f" for call_id {_fco_id}" if _fco_id else "") + f"]\n<tool_response>\n{out_val[:tool_out_cap]}\n</tool_response>"
            })
            continue

        if role in ("system", "developer"):
            c = m.get("content", "")
            if isinstance(c, str) and c.strip():
                sys_parts.append(c.strip())
            elif isinstance(c, list):
                t_str = "\n".join(str(b.get("text", "")) for b in c if isinstance(b, dict) and b.get("text"))
                if t_str.strip():
                    sys_parts.append(t_str.strip())
            continue

        if role == "tool":
            c = m.get("content", "")
            if not isinstance(c, str):
                c = json.dumps(c, ensure_ascii=False)
            chat_msgs.append({
                "role": "user",
                "content": f"[Tool Output]\n<tool_response>\n{c[:tool_out_cap]}\n</tool_response>"
            })
            continue

        c = m.get("content", "")
        text_parts = []
        msg_images_b64 = []
        if isinstance(m.get("images"), list):
            for raw_im in m["images"]:
                b64_clean, im_desc = inspect_attached_media_b64(raw_im, "image")
                if b64_clean:
                    msg_images_b64.append(b64_clean)
                if im_desc:
                    text_parts.append(im_desc)
        if isinstance(c, str):
            if c:
                for dm in re.finditer(r"data:(image/[a-zA-Z0-9.+-]+);base64,([A-Za-z0-9+/=]+)", c):
                    b64_clean, im_desc = inspect_attached_media_b64(dm.group(2), dm.group(1))
                    if b64_clean:
                        msg_images_b64.append(b64_clean)
                    if im_desc:
                        text_parts.append(im_desc)
                c_clean_inline = re.sub(r"data:image/[a-zA-Z0-9.+-]+;base64,[A-Za-z0-9+/=]+", "[Embedded Base64 Image Attached]", c)
                text_parts.append(c_clean_inline)
        elif isinstance(c, list):
            for b in c:
                if isinstance(b, dict):
                    btype = b.get("type", "")
                    if btype in ("text", "input_text", "output_text"):
                        text_parts.append(str(b.get("text", "")))
                    elif btype in ("image", "input_image", "image_url"):
                        im_src = ""
                        if isinstance(b.get("source"), dict):
                            im_src = b["source"].get("data") or b["source"].get("url") or ""
                        elif isinstance(b.get("image_url"), dict):
                            im_src = b["image_url"].get("url") or ""
                        elif isinstance(b.get("image_url"), str):
                            im_src = b["image_url"]
                        else:
                            im_src = b.get("data") or b.get("url") or ""
                        b64_clean, im_desc = inspect_attached_media_b64(im_src, "image")
                        if b64_clean:
                            msg_images_b64.append(b64_clean)
                        if im_desc:
                            text_parts.append(im_desc)
                    elif btype in ("document", "file", "video", "input_file"):
                        f_name = b.get("name") or b.get("filename") or btype
                        f_data = ""
                        if isinstance(b.get("source"), dict):
                            f_data = str(b["source"].get("data") or b["source"].get("text") or "")[:6000]
                        text_parts.append(f"[Attached {btype.upper()}: {f_name}]\n{f_data}".strip())
                    elif btype == "tool_use":
                        tname = b.get("name", "tool")
                        tinp = b.get("input") or {}
                        xml_p = "\n".join(f"<parameter={k}>\n{v}\n</parameter>" for k, v in (tinp.items() if isinstance(tinp, dict) else []))
                        text_parts.append(f"<tool_call>\n<function={tname}>\n{xml_p}\n</function>\n</tool_call>")
                    elif btype == "tool_result":
                        tr_content = b.get("content", "")
                        if isinstance(tr_content, list):
                            tr_content = "\n".join(str(x.get("text", "")) for x in tr_content if isinstance(x, dict))
                        _tr_id = b.get("tool_use_id") or b.get("id") or ""
                        text_parts.append(f"[Tool Output" + (f" for tool_use_id {_tr_id}" if _tr_id else "") + f"]\n<tool_response>\n{str(tr_content)[:tool_out_cap]}\n</tool_response>")
                elif isinstance(b, str):
                    text_parts.append(b)

        if role == "assistant" and isinstance(m.get("tool_calls"), list):
            for tc in m["tool_calls"]:
                if isinstance(tc, dict) and isinstance(tc.get("function"), dict):
                    fn = tc["function"]
                    tname = fn.get("name", "tool")
                    raw_args = fn.get("arguments", "{}")
                    try:
                        args_d = json.loads(raw_args) if isinstance(raw_args, str) else (raw_args or {})
                    except Exception:
                        args_d = {}
                    xml_p = "\n".join(f"<parameter={k}>\n{v}\n</parameter>" for k, v in (args_d.items() if isinstance(args_d, dict) else []))
                    text_parts.append(f"<tool_call>\n<function={tname}>\n{xml_p}\n</function>\n</tool_call>")

        joined_content = "\n".join(p for p in text_parts if p).strip()
        if joined_content or msg_images_b64:
            m_entry = {
                "role": "assistant" if role == "assistant" else "user",
                "content": joined_content or "Analyze the attached image/media."
            }
            # HARNESS v76 section 1.1 (DeepSeek rule): never strip reasoning_content from assistant turns.
            if role == "assistant" and isinstance(m.get("reasoning_content"), str) and m.get("reasoning_content"):
                m_entry["reasoning_content"] = m["reasoning_content"]
            if msg_images_b64:
                m_entry["images"] = msg_images_b64
            chat_msgs.append(m_entry)

    id_info = get_true_model_identity_info()
    true_identity_banner = (
        f"[TRUE MODEL IDENTITY DIRECTIVE: Your real active model preset is `{id_info['preset']}` "
        f"(Loaded Engine ID: `{id_info['model_id']}`, GGUF Source: `{id_info['source_gguf']}`), "
        f"running on a Kaggle 32GB Dual NVIDIA Tesla T4 3-Tier Server (GPU VRAM + System RAM + SSD Mmap). "
        f"When the user asks what model you are ('তুমি কোন মডেল?', 'what model are you?', 'who are you?'), "
        f"ALWAYS state your TRUE model name (`{id_info['preset']}` / `{id_info['model_id']}` from `{id_info['source_gguf']}`). "
        f"NEVER claim to be Claude, Sonnet, Opus, ChatGPT, or GPT-4!]"
    )

    casual_turn = is_casual_conversational_turn(body)
    if casual_turn:
        norm_tools = []
        last_u_low = str((chat_msgs[-1].get("content") if chat_msgs else "") or "").lower()
        is_id_q = any(k in last_u_low for k in ("model", "who are you", "মডেল", "তুমি কে", "নাম কি", "কোন এআই"))
        if is_id_q:
            full_sys = "You are a fast, friendly, uncensored AI assistant. " + true_identity_banner + "\nReply concisely without <think> tags. /no_think"
        else:
            full_sys = _CLEAN_SYSTEM_PROMPT
    else:
        # v61.1: the clean natural multilingual prompt is the default for ALL
        # turns. Caller-supplied system text is appended after it, never replaces it.
        if not sys_parts:
            # HARNESS v76: BMRBD Ai system prompt is the DEFAULT — prepended whenever the request carries no system message (UI chat + API).
            base_sys = HARNESS_SYSTEM_PROMPT + "\n\n" + _CLEAN_SYSTEM_PROMPT
        else:
            raw_joined_sys = "\n\n".join(sys_parts)
            raw_joined_sys = re.sub(r"<system-reminder>[\s\S]*?</system-reminder>", "", raw_joined_sys).strip()
            raw_joined_sys = re.sub(r"You are powered by the model named[^.\n]+\.?", "", raw_joined_sys, flags=re.I)
            raw_joined_sys = re.sub(r"The exact model ID is claude-[^.\n]+\.?", "", raw_joined_sys, flags=re.I)
            # BMRBD v76.3 QUALITY (G): NEVER truncate the client system
            # prompt — the old ">3600 chars -> first 2000 + last 1500"
            # condense silently deleted the middle of any long system
            # prompt (an ~8k-token prompt lost ~85% of its instructions).
            # Fitting is the fit layer\u2019s job (history compacts first);
            # the system prompt itself always reaches the engine whole.
            base_sys = _CLEAN_SYSTEM_PROMPT + "\n\n" + raw_joined_sys

        eff_str = str(effort or "high").lower()
        # v61.1: deep thinking is ONLY on when the USER explicitly asks for it
        # (an explicit `thinking: {type: enabled|adaptive}` parameter, or the user
        # literally asking for step-by-step / deep thinking). Effort levels
        # (medium/high/xhigh/max/complex) never turn it on by themselves, and no
        # <think> block is ever appended by the server.
        thinking_cfg = body.get("thinking")
        _last_user_text = str((chat_msgs[-1].get("content") if chat_msgs else "") or "").lower()
        explicit_think_on = (
            (isinstance(thinking_cfg, dict) and thinking_cfg.get("type") in ("enabled", "adaptive"))
            or any(k in _last_user_text for k in ("think step by step", "step-by-step reasoning", "deep think", "chain of thought", "\u0997\u09be\u09aa\u09c7\u09b0\u09ad\u09be\u09ac\u09c7 \u099a\u09bf\u09a8\u09cd\u09a4\u09be", "\u09a7\u09be\u09aa\u09c7 \u09a7\u09be\u09aa\u09c7 \u099a\u09bf\u09a8\u09cd\u09a4\u09be", "\u09a7\u09be\u09aa\u09c7 \u09a7\u09be\u09aa\u09c7 \u09ad\u09be\u09ac"))
        )
        final_sys_parts = [base_sys, true_identity_banner, _F6_AGENTIC_PROMPT, _f6_project_context_block(body)]
        # BMRBD v76.1: the ack-first + light-updates rule rides here for
        # EVERY non-casual turn — web UI, Claude Code (/v1/messages) and
        # Codex (/v1/responses) alike. It cannot live only in
        # HARNESS_SYSTEM_PROMPT: Claude Code and Codex always send their
        # own system prompt / instructions, and then base_sys skips the
        # harness prompt entirely, so the model never saw the rule.
        final_sys_parts.append(_HARNESS_ACK_RULE)
        _personal_block = _bmrbd_user_personal_block(user_obj)
        if _personal_block:
            final_sys_parts.append(_personal_block)
        _prof = _effort_profile(eff_str)
        _reasoning_on = (_prof["think"] or explicit_think_on) and not norm_tools
        if _reasoning_on:
            # v61.11: Deep Think / Task effort REALLY reasons. The model is
            # asked to write its reasoning first inside ONE literal
            # <think>...</think> block (the dashboard renders it as the live
            # Thought Process card). NEVER send "think": True to Ollama -
            # v0.40.15+ returns 400 on GGUF models whose Modelfile template
            # lacks {{ .Thinking }} - the prompt alone elicits the block.
            final_sys_parts.append(
                "DEEP REASONING (Deep Think mode): think step by step and write your reasoning inside ONE <think>...</think> block (concise, in the user's language, no more than ~20% of the reply), then give the final answer after the closing tag. NEVER write an acknowledgment line before the <think> block or anywhere in the reply — the first visible line is the answer itself. Do not repeat the question inside the think block."
            )
        elif eff_str in ("low", "max_fast"):
            final_sys_parts.append(
                "DIRECT FAST EXECUTION & NATURAL BENGALI RULE: " + _prof["instruction"] + " "
                "Provide 100% complete, accurate, high-intelligence answers and production-grade code. "
                "When speaking Bengali (বাংলা), always use simple, natural, everyday fluent Bengali (সহজ, সাবলীল ও স্বাভাবিক বাংলা ভাষা ব্যবহার করবে)।"
            )
        else:
            final_sys_parts.append(
                "Answer completely and accurately in the user's language. When speaking Bengali (বাংলা), always use simple, natural, everyday fluent Bengali (সহজ, সাবলীল ও স্বাভাবিক বাংলা ভাষা ব্যবহার করবে)।"
            )
        final_sys_parts.append(
            "CAPABILITIES, FILE/ZIP GENERATION & TOOL PRECISION RULES:\n"
            "1. Execute the user's exact request immediately with 100% full benchmark intelligence (Carbon / Claude Opus 4.6 / Kimi K3.1 Pro depth).\n"
            "2. SERVER FILE, HTML, PHP & .ZIP PACKAGER: Whenever the user asks for ANY downloadable file (`.html`, `.php`, `.py`, `.js`, `.css`, `.sql`, `.md`, `.json`, or `.zip` bundle) or an all-in-one web player / full-stack PHP script, NEVER say you cannot provide downloadable files! Write the complete, 100% functional code inside fenced code blocks with the filename tag (e.g. ```index.html, ```index.php, ```styles.css, ```app.js, ```database.sql), and the BMRBD Ai Server will automatically compile them into real hosted files and append 1-click Direct Download & `.ZIP` links!\n"
            "3. STRICT TOOL & SKILL DISCIPLINE: When `tools` are provided, call ONLY the exact tool names declared in `<tools>`. NEVER call `Skill` with `{'name': 'browser'}` unless `'browser'` is explicitly listed as an available skill in the system prompt; use standard file/bash/web tools (`Write`, `Read`, `Edit`, `Bash`, `WebFetch`, `WebSearch`) instead."
        )
        if eff_str in ("high", "max", "xhigh", "complex"):
            final_sys_parts.append("When coding or building software, provide complete, production-grade code and execute necessary steps without placeholders or refusals.")
        if body.get("task_mode"):
            final_sys_parts.append(
                "TASK-MODE OUTPUT RULE (BMRBD v61.13 P2 — OUTPUT, NOT CODE): when the user asks for a file, "
                "presentation, document, spreadsheet, app or website, BUILD the file and deliver the file. Put ALL "
                "code inside fenced code blocks with the filename (e.g. ```index.html) so the server packages it into "
                "a real downloadable file with download links. Outside those fenced blocks, give only a brief summary: "
                "what was built, the file names, and the download links. NEVER paste the full code again as plain chat "
                "text, and NEVER dump raw code when a file was requested."
            )
        if norm_tools:
            final_sys_parts.append(format_tools_system_block(norm_tools))
        full_sys = "\n\n".join(final_sys_parts)
    if not chat_msgs:
        chat_msgs.append({"role": "user", "content": "Hello"})

    full_sys = sanitize_claude_windows_paths(full_sys, is_file_arg=False)

    had_bash_heredoc_error = False
    assistant_tool_targets = []
    assistant_text_snippets = []
    total_msgs_len = len(chat_msgs)

    for idx_m, m in enumerate(chat_msgs):
        c_raw = str(m.get("content") or "")
        if "<system-reminder>" in c_raw:
            c_raw = re.sub(r"<system-reminder>[\s\S]*?</system-reminder>", "", c_raw).strip()
            if not c_raw:
                c_raw = "Continue with the task."
        c_raw = sanitize_claude_windows_paths(c_raw, is_file_arg=False)
        if any(err_k in c_raw for err_k in ("UnicodeEncodeError", "unexpected EOF while looking for matching", "build_content_")):
            had_bash_heredoc_error = True

        is_recent_turn = (total_msgs_len - idx_m) <= 8
        if m.get("role") == "assistant":
            for fm in re.finditer(r"<function=([^>\s]+)>([\s\S]*?)</function>", c_raw):
                fn_n = fm.group(1).strip()
                fn_b = fm.group(2)
                pm_fp = re.search(r"<parameter=(?:file_path|filePath|path|command)>\s*([^<\n]+)", fn_b)
                tgt = pm_fp.group(1).strip()[:80] if pm_fp else fn_n
                assistant_tool_targets.append(f"{fn_n}:{tgt}")
            plain_a = re.sub(r"<tool_call>[\s\S]*?</tool_call>", "", c_raw).strip()
            if plain_a:
                dedup_lines = []
                for ln in plain_a.splitlines():
                    ln_s = ln.strip()
                    if ln_s and dedup_lines and dedup_lines[-1].strip() == ln_s:
                        continue
                    dedup_lines.append(ln)
                plain_a = "\n".join(dedup_lines)
                assistant_text_snippets.append(plain_a[:160])

            # Only compact old assistant messages BEFORE the recent 8 turns so prefix tokens don't mutate mid-window
            if not is_recent_turn and len(c_raw) > 4500 and "<parameter=content>" in c_raw:
                def _compact_xml_content(match_obj):
                    body_txt = match_obj.group(1)
                    if len(body_txt) <= 1500:
                        return match_obj.group(0)
                    n_lines = body_txt.count("\n") + 1
                    return f"<parameter=content>\n{body_txt[:450]}\n... [File content written: {n_lines} lines, {len(body_txt)} chars] ...\n{body_txt[-350:]}\n</parameter>"
                c_raw = re.sub(r"<parameter=content>\s*([\s\S]*?)</parameter>", _compact_xml_content, c_raw)
        else:
            max_u_len = 16000 if is_recent_turn else 6000
            if len(c_raw) > max_u_len:
                if "</tool_response>" in c_raw:
                    c_raw = c_raw[:max_u_len - 2200] + "\n...[tool output condensed]...\n" + c_raw[-2000:] + "\n</tool_response>"
                else:
                    c_raw = c_raw[:max_u_len - 2200] + "\n...[middle condensed]...\n" + c_raw[-2000:]
        m["content"] = c_raw

    if compacted_ledger_note and chat_msgs:
        chat_msgs[0]["content"] = str(chat_msgs[0].get("content") or "") + "\n\n" + compacted_ledger_note

    if had_bash_heredoc_error and chat_msgs:
        chat_msgs[-1]["content"] = (
            str(chat_msgs[-1].get("content") or "")
            + "\n\n[IMPORTANT SYSTEM NOTE: Do NOT use Bash, python builder scripts, or cat heredocs to write code files! "
            "Call the Write tool (<function=Write>) directly using relative file paths in the current directory.]"
        )

    loop_warning = ""
    if len(assistant_tool_targets) >= 2 and assistant_tool_targets[-1] == assistant_tool_targets[-2]:
        rep_target = assistant_tool_targets[-1]
        loop_warning = (
            f"\n\n[ANTI-LOOP GUARDIAN: You already executed `{rep_target}` in the previous steps! "
            f"Do NOT repeat `{rep_target}` again. Proceed immediately to the NEXT step in the task!]"
        )
    elif len(assistant_text_snippets) >= 2 and assistant_text_snippets[-1] and assistant_text_snippets[-1] == assistant_text_snippets[-2]:
        loop_warning = (
            "\n\n[ANTI-LOOP GUARDIAN: Do NOT repeat your previous status sentence! "
            "Immediately emit the next required <tool_call> or provide your final answer.]"
        )
    if loop_warning and chat_msgs:
        chat_msgs[-1]["content"] = str(chat_msgs[-1].get("content") or "") + loop_warning

    merged_msgs = []
    for m in chat_msgs:
        r = "assistant" if m.get("role") == "assistant" else "user"
        c = str(m.get("content") or "").replace("\x00", "").strip()
        if not c:
            continue
        c = c.encode("utf-8", errors="ignore").decode("utf-8", errors="ignore")
        if merged_msgs and merged_msgs[-1]["role"] == r:
            combined = merged_msgs[-1]["content"] + "\n\n" + c
            if len(combined) > 22000:
                combined = combined[:8000] + "\n...\n" + combined[-13500:]
            merged_msgs[-1]["content"] = combined
            if m.get("images"):
                merged_msgs[-1].setdefault("images", []).extend(m["images"])
        else:
            new_m = {"role": r, "content": c}
            if m.get("images"):
                new_m["images"] = list(m["images"])
            merged_msgs.append(new_m)

    seed_q = (first_real_user_msg["content"] if first_real_user_msg else "Execute the requested software engineering task step by step using the available tools.")
    if not merged_msgs:
        merged_msgs.append({"role": "user", "content": seed_q})
    elif merged_msgs[0]["role"] != "user":
        merged_msgs.insert(0, {"role": "user", "content": seed_q})
    elif merged_msgs[0]["content"].lstrip().startswith("<tool_response>"):
        merged_msgs[0]["content"] = seed_q + "\n\n" + merged_msgs[0]["content"]

    if merged_msgs[-1]["role"] == "assistant":
        merged_msgs.append({"role": "user", "content": "Continue with the next step."})

    # v49 Automatic Smart Live Web Search & Deep Research Injection:
    # Triggers when `web_search: true`, `/search`, OR when the user asks for online/latest/current facts or research!
    last_u_txt = str(merged_msgs[-1].get("content") or "").strip() if merged_msgs else ""
    low_u_web = last_u_txt.lower()
    auto_web_keywords = (
        "/search ", "search online", "search the web", "on the web", "from online", "latest news", "current price",
        "deep research", "অনলাইন থেকে", "ইন্টারনেট থেকে", "গুগল সার্চ", "সার্চ করে", "লেটেস্ট খবর", "আজকের খবর", "ডিপ রিসার্চ"
    )
    # G1 (v76.5, R1): ONE trigger rule everywhere -- the narrow phrase
    # list above was the ONLY grounding path at effort "low" (the web UI
    # default), and it missed most news phrasings ("news"/"today"/
    # "breaking"/"খবর" alone). _bmrbd_think_should_research is the same
    # rule think-research and the proxy grounding already use.
    want_web = bool(body.get("web_search")) or any(wk in low_u_web for wk in auto_web_keywords) or _bmrbd_think_should_research(last_u_txt)
    # G1 (R3): never ground twice -- if the proxy/think path already
    # injected the block, do not search the same query again.
    if want_web and last_u_txt and "[LIVE ONLINE WEB SEARCH RESULTS" not in last_u_txt and not _harness_norm_has_web_tool(norm_tools) and not body.get("voice_call_mode") and not body.get("_think_research_done"):
        search_q = re.sub(r"^/search\s+", "", last_u_txt, flags=re.I).strip()[:180]
        hits = fetch_live_web_search_results(search_q, max_results=5)
        if hits:
            body["_crawled_sites"] = [{"title": h["title"], "url": h["url"]} for h in hits]
            web_block = "\n".join(f"- [{h['title']}]({h['url']}): {h['snippet']}" for h in hits)
            merged_msgs[-1]["content"] = (
                f"{last_u_txt}\n\n[LIVE ONLINE WEB SEARCH RESULTS (Ground your answer in these verified facts and include markdown links)]:\n{web_block}"
            )
        else:
            # G1 (R2): search found nothing -- say so, never silently
            # answer ungrounded.
            merged_msgs[-1]["content"] = (
                f"{last_u_txt}\n\n[Web search returned no results for this question — "
                "answer from your own knowledge and say plainly when you are "
                "unsure; do not invent facts or sources.]"
            )

    clean_sys = full_sys.replace("\x00", "").encode("utf-8", errors="ignore").decode("utf-8", errors="ignore")
    # v42 Hard Character-Budget Guard & Old Image Stripper for 100+ turn Codex / OpenCode sessions
    for _idx_m, _m in enumerate(merged_msgs):
        if _idx_m < len(merged_msgs) - 2 and "images" in _m:
            del _m["images"]
    # v50 Live Website Clone Scraper (when user asks to clone/scrape a URL into PHP/HTML/JS):
    m_url_clone = re.search(r"https?://[^\s)'>]+", last_u_txt)
    if m_url_clone and not norm_tools and not body.get("_think_fetch_done") and any(ck in low_u_web for ck in ("clone", "php", "html", "script", "website", "ক্লোন", "পিএইচপি", "ওয়েবসাইট", "স্ক্রিপ্ট")):
        clone_info = fetch_live_website_for_clone(m_url_clone.group(0))
        if clone_info.get("html_excerpt"):
            merged_msgs[-1]["content"] += (
                f"\n\n[LIVE SCRAPED WEBSITE STRUCTURE FOR `{clone_info['url']}`]:\n"
                f"- Title: {clone_info.get('title')}\n"
                f"- Headings: {', '.join(clone_info.get('headings') or [])}\n"
                f"- Navigation: {', '.join(clone_info.get('nav_items') or [])}\n"
                f"- Color Palette: {', '.join(clone_info.get('colors') or [])}\n"
                f"- HTML Excerpt:\n```html\n{clone_info['html_excerpt'][:2800]}\n```\n"
                "Build a complete, self-contained, production-ready clone (e.g. ```index.php or ```index.html + ```styles.css + ```app.js) so the server packages it into a downloadable `.zip`!"
            )

    # v50 Strict Dynamic Context-Window Budget Guard (100% Immune to `exceeds the available context size (6144 tokens)`!):
    try:
        _active_ctx = int(os.environ.get("NUM_CTX") or NUM_CTX or 16384)
    except Exception:
        _active_ctx = 16384
    _safe_char_budget = max(11500, int(_active_ctx * 2.15))
    # BMRBD v76.3 QUALITY (G): the system prompt is NEVER condensed —
    # the old guard cut clean_sys to head 22% + tail 14% once it passed
    # 38% of the budget (an ~8k-token system prompt was gutted here even
    # after surviving the 3600-char condense). The HISTORY budget shrinks
    # instead: Steps A/B/C below trim merged_msgs to fit what is left.
    _rem_budget = max(7500, _safe_char_budget - len(clean_sys))
    _cur_total_chars = sum(len(str(_m.get("content") or "")) for _m in merged_msgs)
    if _cur_total_chars > _rem_budget:
        # Step A: Condense older middle messages first
        if len(merged_msgs) > 2:
            for _idx_m in range(0, max(1, len(merged_msgs) - 2)):
                _c_txt = str(merged_msgs[_idx_m].get("content") or "")
                _cap_m = 900 if _idx_m == 0 else 550
                if len(_c_txt) > _cap_m:
                    merged_msgs[_idx_m]["content"] = (
                        _c_txt[:int(_cap_m * 0.55)]
                        + f"\n...[condensed ({len(_c_txt)} chars)]...\n"
                        + _c_txt[-int(_cap_m * 0.35):]
                    )
        # Step B: If still above budget, drop oldest middle turns (keeping Turn 0 + most recent turns)
        while len(merged_msgs) > 3 and sum(len(str(_m.get("content") or "")) for _m in merged_msgs) > _rem_budget:
            merged_msgs.pop(1)
        # Step C: Ensure the last message itself fits inside `_rem_budget`
        _cur_total_chars = sum(len(str(_m.get("content") or "")) for _m in merged_msgs)
        if _cur_total_chars > _rem_budget and merged_msgs:
            _last_c = str(merged_msgs[-1].get("content") or "")
            _allow_last = max(3500, _rem_budget - sum(len(str(_m.get("content") or "")) for _m in merged_msgs[:-1]))
            if len(_last_c) > _allow_last:
                merged_msgs[-1]["content"] = _last_c[:int(_allow_last * 0.45)] + "\n...[middle truncated to fit context window]...\n" + _last_c[-int(_allow_last * 0.48):]

    return [{"role": "system", "content": clean_sys}] + merged_msgs



_SHARED_BROWSER_THREADS = []
_SHARED_SCHEDULES = []
_SHARED_SYNC_LOCK = threading.Lock()


def _sched_visible_schedules(owner, is_admin=False):
    # Own entries only (admins see all, including ownerless legacy
    # entries). Ownerless entries are visible to admins only — a
    # pre-fix entry has no owner to match against. (R3)
    try:
        if is_admin:
            return list(_SHARED_SCHEDULES)
        return [dict(s) for s in _SHARED_SCHEDULES if str(s.get("owner") or "") == str(owner or "")]
    except Exception:
        return []
# BMRBD v61.15a WD2: a fresh kernel rehydrates these from the vault
# state restored at boot (restore_bmrbd_vault_on_boot ran before this
# point in the file), so schedules and shared threads survive rotation.
try:
    _seed_bt = _BMRBD_STATE.get("shared_browser_threads")
    if isinstance(_seed_bt, list):
        _SHARED_BROWSER_THREADS[:] = list(_seed_bt)[:80]
    _seed_ss = _BMRBD_STATE.get("shared_schedules")
    if isinstance(_seed_ss, list):
        _SHARED_SCHEDULES[:] = list(_seed_ss)
except Exception:
    pass

def _background_task_scheduler_daemon():
    while True:
        time.sleep(20)
        now_ts = time.time()
        with _SHARED_SYNC_LOCK:
            # BMRBD v76 STAGE-1 (ITEM 2 guard): fire ONLY when explicitly
            # enabled — a schedule entry missing the key must NOT fire (the
            # old .get("enabled", True) default-fired any malformed entry).
            due_tasks = [s for s in _SHARED_SCHEDULES if s.get("enabled") is True and now_ts >= float(s.get("next_run_ts") or 0)]
        for task in due_tasks:
            try:
                # BMRBD v76 STAGE-1 (§8 self-hunt): the daemon used to POST
                # to OLLAMA_URL (/api/chat) unconditionally — that URL is
                # DEAD on Strata/colibri/llama-server engines, so every
                # scheduled run failed with a connection error and stored
                # only "Scheduled check note: ...". Route via the ACTIVE
                # engine (OpenAI shape + master key); the Ollama route is
                # kept only when the active engine really is Ollama.
                _prompt = str(task.get("prompt") or "Status check")
                _eng, _emid, _ewhy = _v62_active_engine_info()
                if _eng in ("llama-server", "colibri", "strata"):
                    req_b = json.dumps({
                        "model": _emid or DEFAULT_MODEL,
                        "messages": [
                            {"role": "system", "content": "You are BMRBD Ai Scheduled Task Runner. Execute this scheduled prompt concisely and accurately."},
                            {"role": "user", "content": _prompt}
                        ],
                        "stream": False,
                        "temperature": 0.6,
                        "max_tokens": 600
                    }).encode("utf-8")
                    req = urllib.request.Request(
                        f"{_active_engine_base_url()}/v1/chat/completions", data=req_b,
                        headers={"Content-Type": "application/json", "Authorization": "Bearer " + MASTER_API_KEY},
                        method="POST")
                    with urllib.request.urlopen(req, timeout=45) as r:
                        rj = json.loads(r.read().decode("utf-8", errors="ignore"))
                        ans = str((((rj.get("choices") or [{}])[0] or {}).get("message") or {}).get("content") or "").strip()
                else:
                    live_m = get_live_ollama_model()
                    req_b = json.dumps({
                        "model": live_m,
                        "messages": [
                            {"role": "system", "content": "You are BMRBD Ai Scheduled Task Runner. Execute this scheduled prompt concisely and accurately."},
                            {"role": "user", "content": _prompt}
                        ],
                        "stream": False,
                        "keep_alive": -1,
                        "options": {"temperature": 0.6, "num_predict": 600}
                    }).encode("utf-8")
                    req = urllib.request.Request(f"{OLLAMA_URL}/api/chat", data=req_b, headers={"Content-Type": "application/json"}, method="POST")
                    with urllib.request.urlopen(req, timeout=45) as r:
                        rj = json.loads(r.read().decode("utf-8", errors="ignore"))
                        ans = str((rj.get("message") or {}).get("content") or "").strip()
                with _SHARED_SYNC_LOCK:
                    task["last_run_at"] = time.strftime("%H:%M:%S")
                    task["last_result"] = ans[:1500]
                    interval_m = max(1, int(task.get("interval_minutes") or 60))
                    task["next_run_ts"] = time.time() + interval_m * 60
                _bmrbd_sync_shared_state_to_vault()  # BMRBD v61.15a WD2
            except Exception as e:
                with _SHARED_SYNC_LOCK:
                    task["last_run_at"] = time.strftime("%H:%M:%S")
                    task["last_result"] = f"Scheduled check note: {e}"
                    task["next_run_ts"] = time.time() + 300
                _bmrbd_sync_shared_state_to_vault()  # BMRBD v61.15a WD2

threading.Thread(target=_background_task_scheduler_daemon, daemon=True).start()


# ══════════════════════════════════════════════════════════════════════════════
# BMRBD v76 §4 STATUS PAGE — admin-gated, Atlassian Statuspage v2 shape.
# (Agent A, 2026-11-19. Region: _status_* only. Do not edit from other agents.)
#
# Endpoints (all admin-gated via _status_admin_gate; unauthenticated -> 401,
# signed-in non-admin -> 403; HTML /status uses _shell_gate(admin=True)
# -> 302 to /login unauthenticated, 403 page for non-admin):
#   GET  /status                              HTML page, polls summary ~60s
#   GET  /api/v2/status.json                  {page, status{indicator, description}}
#   GET  /api/v2/summary.json                 page + status + components[] +
#                                              incidents[] (unresolved) +
#                                              scheduled_maintenances[]
#   GET  /api/v2/components.json              {page, components[]}
#   GET  /api/v2/incidents.json?page=N        50 most recent, newest first
#   GET  /api/v2/incidents/unresolved.json    unresolved only
#   GET  /api/v2/incidents/<id>.json          one incident + update timeline
#   GET  /api/v2/scheduled-maintenances.json
#   POST /api/v2/incidents                    create (admin)
#   POST /api/v2/incidents/<id>/updates       add update / change status (admin)
#   POST /api/v2/incidents/<id>/resolve       resolve, canned closing text (admin)
#   POST /api/v2/scheduled-maintenances       create (admin)
#   POST /api/v2/scheduled-maintenances/<id>/cancel
#
# Status is NEVER "the bridge process is up". Every component word comes from
# a live probe (engine /v1/models, TTS/STT reachability, image engines,
# disk, vault, GPU kernel). A page reporting operational while the
# engine/GPU is down is a false green — the probes above prevent it.
#
# Storage: incidents live in _BMRBD_STATE["status_incidents"] (the same key
# the Drive-persistence bundle exports as status_log.json) and the
# append-only change log in _BMRBD_STATE["status_change_log"]; both are
# vault-persisted via _save_bmrbd_state_local(push_peer=False), so they
# survive kernel restarts. Uptime % = 1 - degraded/outage minutes / window
# minutes, computed from the change log (history starts the day this ships).
#
# Privacy: NO model id, VRAM/disk numbers, request history or tunnel URLs
# appear anywhere in these payloads — probe details are qualitative words
# only ("engine reachable, model loaded"). Public /health stays minimal.
# ══════════════════════════════════════════════════════════════════════════════
_STATUS_PAGE_ID = "bmrbd-ai"
_STATUS_PAGE_NAME = "BMRBD Ai"
_STATUS_PAGE_URL = "https://ai2.bmrbd.xyz/status"
_STATUS_PAGE_INDICATORS = ("none", "minor", "major", "critical", "maintenance")
_STATUS_COMPONENT_STATUSES = ("operational", "degraded_performance", "partial_outage", "major_outage", "under_maintenance")
_STATUS_INCIDENT_IMPACTS = ("none", "minor", "major", "critical")
_STATUS_INCIDENT_STATUSES = ("investigating", "identified", "monitoring", "resolved")
_STATUS_INCIDENT_RESOLVED_TEXT = "All affected services are operating normally again. We're sorry for the disruption, and we appreciate your patience."
_STATUS_PROBE_TTL_S = 30.0
# BMRBD v76.1 (2026-11-19, live bug #1 — status page FALSE RED): the
# engine probe fired at 2.5 s while a long generation held the single
# engine, so one slow probe flipped Chat to partial_outage, the page to
# major, and auto-opened an incident while every chat call succeeded.
# Three guards now: (a) a 10 s probe timeout, (b) a failure counts only
# after _STATUS_FAIL_STREAK_REQUIRED consecutive failed runs, and (c) a
# failure during an active generation (METRICS["active_streams"] > 0)
# is inconclusive — the engine is demonstrably serving — so it neither
# grows nor resets the streak. _STATUS_UPTIME_MIN_MEASURED_S is the
# minimum measured span before an uptime % is stated at all.
_STATUS_PROBE_TIMEOUT_S = 10.0
_STATUS_FAIL_STREAK_REQUIRED = 3
_STATUS_FAIL_STREAK = {}
_STATUS_UPTIME_MIN_MEASURED_S = 3600.0
_STATUS_CHANGE_LOG_MAX = 5000
_STATUS_INCIDENTS_MAX = 500
_STATUS_COMPONENTS = (
    {"id": "chat-completions", "name": "Chat Completions", "group": "Chat",
     "description": "Chat completions via the active inference engine"},
    {"id": "voice", "name": "Voice — TTS & STT", "group": "Voice",
     "description": "Voice replies (TTS) and speech transcription (STT)"},
    {"id": "images", "name": "Image Generation", "group": "Images",
     "description": "Image generation engines"},
    {"id": "api", "name": "API Gateway", "group": "API",
     "description": "HTTP API gateway and request serving"},
    {"id": "admin", "name": "Admin Console", "group": "Admin",
     "description": "Admin console, users and vault state"},
    {"id": "kernel", "name": "GPU Kernel", "group": "Kernel",
     "description": "GPU kernel, memory and disk"},
)
_STATUS_COMPONENT_BY_ID = {c["id"]: c for c in _STATUS_COMPONENTS}
_STATUS_LOCK = threading.Lock()
_STATUS_PROBE_CACHE = {"at": 0.0, "probes": None, "components": None}


def _status_iso(ts):
    try:
        return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(float(ts)))
    except Exception:
        return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def _status_parse_iso(s):
    """ISO 'YYYY-MM-DDTHH:MM:SSZ' -> epoch float, or None."""
    try:
        return float(time.mktime(time.strptime(str(s), "%Y-%m-%dT%H:%M:%SZ")) - time.timezone)
    except Exception:
        try:
            return float(time.mktime(time.strptime(str(s)[:19], "%Y-%m-%dT%H:%M:%S")) - time.timezone)
        except Exception:
            return None


def _status_page_info():
    return {"id": _STATUS_PAGE_ID, "name": _STATUS_PAGE_NAME, "url": _STATUS_PAGE_URL,
            "updated_at": _status_iso(time.time())}


def _status_incidents():
    v = _BMRBD_STATE.get("status_incidents")
    if not isinstance(v, list):
        v = []
        _BMRBD_STATE["status_incidents"] = v
    return v


def _status_change_log():
    v = _BMRBD_STATE.get("status_change_log")
    if not isinstance(v, list):
        v = []
        _BMRBD_STATE["status_change_log"] = v
    return v


def _status_maintenances():
    v = _BMRBD_STATE.get("status_maintenances")
    if not isinstance(v, list):
        v = []
        _BMRBD_STATE["status_maintenances"] = v
    return v


def _status_save():
    try:
        _save_bmrbd_state_local(push_peer=False)
    except Exception:
        pass


def _status_admin_gate(handler):
    """Reuse the v76 gate: session cookie / Bearer / x-api-key via
    _require_admin (master key maps to admin). Returns ("ok", user),
    ("unauth", None) when no credential was presented at all, or
    ("forbidden", None) when a credential was presented but is not admin."""
    try:
        u = _require_admin(handler)
    except Exception:
        u = None
    if u:
        return ("ok", u)
    try:
        presented = bool(_parse_session_cookie(handler.headers.get("Cookie"))
                         or str(handler.headers.get("Authorization") or "").strip()
                         or str(handler.headers.get("x-api-key") or "").strip())
    except Exception:
        presented = False
    return ("forbidden", None) if presented else ("unauth", None)


# ── Live probes. Each returns (ok, degraded, detail) and NEVER raises.
# Detail strings are qualitative words only — no model ids, VRAM/disk
# numbers, URLs or request data (these payloads are admin-gated, but the
# words stay safe for any surface). ──
def _status_probe_engine():
    """Is the inference engine up AND serving a model? GET /v1/models on
    the active engine base URL (ollama / llama-server / colibri / strata)."""
    try:
        base = _active_engine_base_url()
        req = urllib.request.Request(base.rstrip("/") + "/v1/models", method="GET",
                                     headers={"User-Agent": "BMRBDAi-StatusProbe/1.0"})
        with urllib.request.urlopen(req, timeout=_STATUS_PROBE_TIMEOUT_S) as r:
            j = json.loads(r.read().decode("utf-8", errors="ignore"))
        models = j.get("data") or []
        if models:
            return (True, False, "engine reachable, model loaded")
        return (True, True, "engine reachable, no model listed")
    except Exception:
        return (False, False, "engine unreachable")


def _status_probe_tts():
    """Is any TTS path usable? Kokoro importable, piper binary, or the
    edge-tts endpoint answering (an HTTP error still proves reachability)."""
    try:
        import kokoro  # noqa: F401
        return (True, False, "TTS engine available")
    except Exception:
        pass
    try:
        if shutil.which("piper"):
            return (True, False, "TTS engine available")
    except Exception:
        pass
    try:
        req = urllib.request.Request("https://speech.platform.bing.com", method="HEAD",
                                     headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=3):
            return (True, False, "TTS engine available")
    except urllib.error.HTTPError:
        return (True, False, "TTS engine available")
    except Exception:
        pass
    return (False, False, "no TTS engine reachable")


def _status_probe_stt():
    """Is server STT usable? Whisper model dir present, or faster-whisper
    importable (it can download the model on first use)."""
    try:
        if _find_whisper_model_dir() is not None:
            return (True, False, "STT model available")
    except Exception:
        pass
    try:
        import faster_whisper  # noqa: F401
        return (True, False, "STT engine available")
    except Exception:
        pass
    return (False, False, "no STT model available")


def _status_probe_images():
    try:
        health = _probe_image_engine_health() or {}
        if any(health.values()):
            return (True, False, "image engine reachable")
    except Exception:
        pass
    return (False, False, "no image engine reachable")


def _status_probe_disk():
    try:
        hw = get_hardware_stats() or {}
        free = float(hw.get("ssd_free_gb") or 0.0)
        total = float(hw.get("ssd_total_gb") or 0.0)
        if total and free < 1.0:
            return (False, False, "disk critically low")
        if total and free / total < 0.10:
            return (True, True, "disk low")
        return (True, False, "disk OK")
    except Exception:
        return (False, False, "disk probe failed")


def _status_probe_kernel():
    """GPU kernel: a real NVIDIA GPU visible, RAM headroom, disk headroom.
    No GPU at all on a GPU kernel is degraded (CPU fallback), not green."""
    try:
        hw = get_hardware_stats() or {}
        gpus = hw.get("gpus") or []
        real = [g for g in gpus
                if "xeon" not in str(g.get("name", "")).lower()
                and "ssd" not in str(g.get("name", "")).lower()]
        ram_free = float(hw.get("ram_total_gb") or 0.0) - float(hw.get("ram_used_gb") or 0.0)
        disk_free = float(hw.get("ssd_free_gb") or 0.0)
        if disk_free < 1.0 or ram_free < 0.5:
            return (False, False, "kernel resources exhausted")
        if not real:
            return (True, True, "no GPU detected — CPU fallback")
        return (True, False, "GPU detected, kernel up")
    except Exception:
        return (False, False, "kernel probe failed")


def _status_probe_vault():
    try:
        if BMRBD_STATE_FILE.is_file():
            return (True, False, "vault state readable")
    except Exception:
        pass
    return (True, True, "vault state file missing")


def _status_run_probes(force=False):
    """Run all live probes (cached _STATUS_PROBE_TTL_S). Returns
    {probe_name: {"ok": bool, "degraded": bool, "detail": str}}."""
    now = time.time()
    with _STATUS_LOCK:
        if (not force and _STATUS_PROBE_CACHE.get("probes") is not None
                and now - _STATUS_PROBE_CACHE.get("at", 0.0) < _STATUS_PROBE_TTL_S):
            return dict(_STATUS_PROBE_CACHE["probes"])
    out = {}
    for name, fn in (("engine", _status_probe_engine), ("tts", _status_probe_tts),
                     ("stt", _status_probe_stt), ("images", _status_probe_images),
                     ("disk", _status_probe_disk), ("kernel", _status_probe_kernel),
                     ("vault", _status_probe_vault)):
        try:
            ok, deg, detail = fn()
        except Exception:
            ok, deg, detail = False, False, "probe failed"
        out[name] = {"ok": bool(ok), "degraded": bool(deg), "detail": str(detail)}
    # v76.1 consecutive-failure gate (see _STATUS_PROBE_TIMEOUT_S note
    # above): a single failed run is unconfirmed, never an outage. A
    # failure while a generation is in flight is inconclusive — the
    # engine is serving — so the streak neither grows nor resets.
    try:
        _gen_active = int((globals().get("METRICS") or {}).get("active_streams", 0) or 0) > 0
    except Exception:
        _gen_active = False
    for _pname, _pres in out.items():
        if _pres.get("ok"):
            _STATUS_FAIL_STREAK[_pname] = 0
        elif _gen_active and _pname == "engine":
            _pres["inconclusive"] = True
        else:
            _STATUS_FAIL_STREAK[_pname] = _STATUS_FAIL_STREAK.get(_pname, 0) + 1
        _pres["fail_streak"] = _STATUS_FAIL_STREAK.get(_pname, 0)
        _pres["confirmed"] = bool(_pres.get("ok")) or _STATUS_FAIL_STREAK.get(_pname, 0) >= _STATUS_FAIL_STREAK_REQUIRED
    with _STATUS_LOCK:
        _STATUS_PROBE_CACHE["at"] = now
        _STATUS_PROBE_CACHE["probes"] = dict(out)
    return out


def _status_word(ok, degraded):
    if ok and not degraded:
        return "operational"
    if ok and degraded:
        return "degraded_performance"
    return "partial_outage"


def _status_component_states(probes):
    """Map probe results onto the six components. Pure given `probes`."""
    now_iso = _status_iso(time.time())
    eng = probes.get("engine") or {}
    tts = probes.get("tts") or {}
    stt = probes.get("stt") or {}
    img = probes.get("images") or {}
    dsk = probes.get("disk") or {}
    ker = probes.get("kernel") or {}
    vlt = probes.get("vault") or {}
    voice_ok = bool(tts.get("ok")) and bool(stt.get("ok"))
    voice_deg = (bool(tts.get("ok")) != bool(stt.get("ok"))) or bool(tts.get("degraded")) or bool(stt.get("degraded"))
    if not voice_ok and (bool(tts.get("ok")) or bool(stt.get("ok"))):
        voice_word, voice_detail = "degraded_performance", "one voice path down"
    elif voice_ok and voice_deg:
        voice_word, voice_detail = "degraded_performance", "voice path degraded"
    elif voice_ok:
        voice_word, voice_detail = "operational", "TTS and STT reachable"
    else:
        voice_word, voice_detail = "partial_outage", "no voice path reachable"
    defs = (
        ("chat-completions", _status_word(bool(eng.get("ok")), bool(eng.get("degraded"))), str(eng.get("detail") or "")),
        ("voice", voice_word, voice_detail),
        ("images", _status_word(bool(img.get("ok")), bool(img.get("degraded"))), str(img.get("detail") or "")),
        ("api", _status_word(bool(dsk.get("ok")), bool(dsk.get("degraded"))), str(dsk.get("detail") or "")),
        ("admin", _status_word(bool(vlt.get("ok")), bool(vlt.get("degraded"))), str(vlt.get("detail") or "")),
        ("kernel", _status_word(bool(ker.get("ok")), bool(ker.get("degraded"))), str(ker.get("detail") or "")),
    )
    out = []
    for pos, (cid, word, detail) in enumerate(defs):
        base = _STATUS_COMPONENT_BY_ID[cid]
        out.append({"id": cid, "name": base["name"], "group": base["group"],
                    "description": base["description"], "status": word,
                    "detail": detail, "position": pos, "page_id": _STATUS_PAGE_ID,
                    "created_at": now_iso, "updated_at": now_iso})
    return out


def _status_gated_component_states(probes):
    """Raw probe states with the v76.1 consecutive-failure gate applied:
    a component whose probe failure is NOT yet confirmed (fewer than
    _STATUS_FAIL_STREAK_REQUIRED consecutive failed runs, or a failure
    that happened while a generation was in flight) stays
    'operational' with an explicit 'unconfirmed' detail. Confirmed
    failures pass through unchanged. This is what
    _status_build_summary feeds to _status_record_transitions and the
    page indicator — a single slow probe can no longer flip the page
    to major or auto-open an incident. _status_component_states stays
    ungated (pure, single-run) so a genuinely dead engine is still
    visible there on demand."""
    comps = _status_component_states(probes)
    _probe_for = {"chat-completions": ("engine",), "images": ("images",),
                  "api": ("disk",), "admin": ("vault",), "kernel": ("kernel",),
                  "voice": ("tts", "stt")}
    for c in comps:
        if c.get("status") == "operational":
            continue
        failing = [probes.get(p) or {} for p in _probe_for.get(c["id"], ())]
        failing = [p for p in failing if not p.get("ok")]
        if not failing:
            continue  # non-operational from a degraded-but-OK probe: real
        if all(p.get("confirmed") for p in failing):
            continue  # every failing probe behind it is confirmed: real
        worst = max(int(p.get("fail_streak") or 0) for p in failing)
        c["status"] = "operational"
        c["detail"] = ("probe failure unconfirmed (%d/%d consecutive failures%s)"
                       % (worst, _STATUS_FAIL_STREAK_REQUIRED,
                          "; during active generation"
                          if any(p.get("inconclusive") for p in failing) else ""))
    return comps


def _status_last_state(component_id):
    for e in reversed(_status_change_log()):
        if e.get("component") == component_id:
            return e.get("to") or "operational"
    return "operational"


def _status_record_transitions(components):
    """Append every component status change to the append-only log.
    Auto-open an incident when a component leaves operational (deduped:
    one unresolved incident per component); on recovery, append a
    monitoring update to the auto-opened incident. Resolution stays
    manual — nothing here ever resolves an incident."""
    changed = False
    now = time.time()
    # v76.1 honest history: the first watchdog run starts measurement.
    # Days before this marker were never measured — uptime/bars must
    # show them as unknown, never as backfilled 100%.
    if not _BMRBD_STATE.get("status_history_since"):
        _BMRBD_STATE["status_history_since"] = now
        changed = True
    for comp in components:
        cid = comp["id"]
        prev = _status_last_state(cid)
        new = comp["status"]
        if prev == new:
            continue
        _status_change_log().append({"ts": now, "at": _status_iso(now), "component": cid,
                                     "from": prev, "to": new, "reason": comp.get("detail") or ""})
        changed = True
        if new != "operational":
            open_for = [i for i in _status_incidents()
                        if i.get("status") != "resolved" and cid in (i.get("components") or [])]
            if not open_for:
                impact = "major" if new in ("partial_outage", "major_outage") else "minor"
                _status_create_incident(
                    "%s — %s" % (_STATUS_COMPONENT_BY_ID[cid]["name"], new.replace("_", " ")),
                    impact, [cid],
                    "Auto-opened by the status watchdog: live probe failed (%s)." % (comp.get("detail") or "probe failed"),
                    auto=True, _now=now)
        else:
            for inc in _status_incidents():
                if (inc.get("status") != "resolved" and inc.get("auto_opened")
                        and cid in (inc.get("components") or [])):
                    _status_add_incident_update(inc["id"], "monitoring",
                                                "Probe passing again — monitoring.", _now=now)
    if changed:
        log = _status_change_log()
        if len(log) > _STATUS_CHANGE_LOG_MAX:
            del log[:len(log) - _STATUS_CHANGE_LOG_MAX]
        _status_save()


def _status_history_since():
    """Epoch when status measurement actually started, or None when the
    watchdog has never run. Prefers the persisted marker (set on the
    first _status_record_transitions call); falls back to the earliest
    change-log entry so seeded/imported history still anchors
    honestly. Days before this timestamp were NEVER measured — they
    must render as unknown, never as 100% uptime."""
    v = _BMRBD_STATE.get("status_history_since")
    try:
        if v:
            return float(v)
    except Exception:
        pass
    entries = [e for e in _status_change_log() if e.get("ts")]
    if entries:
        try:
            return min(float(e.get("ts") or 0.0) for e in entries)
        except Exception:
            return None
    return None


def _status_uptime(component_id, days, now_ts=None):
    """Uptime % over the last `days` days from the change log:
    pct = 100 * (1 - degraded/outage minutes / MEASURED minutes).
    Honest-history rule (v76.1): only minutes AFTER
    _status_history_since() count. If the window extends before
    measurement started, pct covers the measured part only and
    coverage is 'partial'; with <= 1h measured (or no history at all)
    pct is None and coverage is 'none' — never a fabricated 100%."""
    now_ts = float(now_ts or time.time())
    window_start = now_ts - float(days) * 86400.0
    since = _status_history_since()
    if since is None:
        return {"pct": None, "down_minutes": None,
                "window_minutes": int(float(days) * 1440),
                "measured_minutes": 0, "measured_from": None, "coverage": "none"}
    start = max(window_start, since)
    entries = sorted([e for e in _status_change_log()
                      if e.get("component") == component_id
                      and float(e.get("ts") or 0.0) <= now_ts],
                     key=lambda e: float(e.get("ts") or 0.0))
    state = "operational"
    for e in entries:
        if float(e.get("ts") or 0.0) < start:
            state = e.get("to") or "operational"
        else:
            break
    down = 0.0
    cursor = start
    cur = state
    for e in entries:
        ts = float(e.get("ts") or 0.0)
        if ts < start:
            continue
        if cur != "operational":
            down += ts - cursor
        cursor = ts
        cur = e.get("to") or "operational"
    if cur != "operational":
        down += now_ts - cursor
    measured = now_ts - start
    coverage = "full" if start <= window_start else "partial"
    if measured <= _STATUS_UPTIME_MIN_MEASURED_S:
        pct = None
        coverage = "none"
    else:
        pct = round(100.0 * (1.0 - down / measured), 2) if measured > 0 else None
    return {"pct": pct, "down_minutes": round(down / 60.0, 1),
            "window_minutes": int(float(days) * 1440),
            "measured_minutes": int(measured // 60),
            "measured_from": _status_iso(start),
            "coverage": coverage}



def _status_daily_bars(component_id, days=90, now_ts=None):
    """Worst state per UTC day, oldest first — the 90-day colour bars.
    Rank: operational 0 < degraded/under_maintenance 1 < partial 2 < major 3."""
    now_ts = float(now_ts or time.time())
    rank = {"operational": 0, "degraded_performance": 1, "under_maintenance": 1,
            "partial_outage": 2, "major_outage": 3}
    entries = sorted([e for e in _status_change_log()
                      if e.get("component") == component_id],
                     key=lambda e: float(e.get("ts") or 0.0))
    bars = []
    today = time.gmtime(now_ts)
    base_day = int(time.mktime((today.tm_year, today.tm_mon, today.tm_mday, 0, 0, 0, 0, 0, 0)) - time.timezone)
    since = _status_history_since()
    for d in range(days - 1, -1, -1):
        day_start = base_day - d * 86400
        day_end = day_start + 86400
        if since is None or day_end <= since:
            # v76.1: this day ended before measurement started (or
            # measurement never started) — unknown, never a green
            # backfill.
            bars.append({"date": time.strftime("%Y-%m-%d", time.gmtime(day_start)), "state": "unknown"})
            continue
        state = "operational"
        for e in entries:
            if float(e.get("ts") or 0.0) < day_start:
                state = e.get("to") or "operational"
            else:
                break
        worst = state
        for e in entries:
            ts = float(e.get("ts") or 0.0)
            if day_start <= ts < day_end:
                if rank.get(e.get("to") or "operational", 0) > rank.get(worst, 0):
                    worst = e.get("to") or "operational"
        bars.append({"date": time.strftime("%Y-%m-%d", time.gmtime(day_start)), "state": worst})
    return bars


def _status_active_maintenance(now_ts=None):
    now_ts = float(now_ts or time.time())
    out = []
    for m in _status_maintenances():
        if m.get("status") not in ("scheduled", "in_progress"):
            continue
        start = _status_parse_iso(m.get("scheduled_for"))
        end = _status_parse_iso(m.get("scheduled_until"))
        if start is not None and end is not None and start <= now_ts <= end:
            out.append(m)
    return out


def _status_page_indicator(components, maintenances=None, now_ts=None):
    """Worst component wins: major_outage -> critical, partial_outage ->
    major, degraded -> minor, active maintenance -> maintenance, else none."""
    statuses = [c.get("status") for c in components]
    if "major_outage" in statuses:
        return ("critical", "Major System Outage")
    if "partial_outage" in statuses:
        return ("major", "Partial System Outage")
    if "degraded_performance" in statuses:
        return ("minor", "Minor Service Degradation")
    if _status_active_maintenance(now_ts):
        return ("maintenance", "Scheduled Maintenance in Progress")
    return ("none", "All Systems Operational")


def _status_serialize_incident(inc):
    return {"id": inc.get("id"), "name": inc.get("name"), "status": inc.get("status"),
            "impact": inc.get("impact"), "created_at": inc.get("created_at"),
            "updated_at": inc.get("updated_at"), "resolved_at": inc.get("resolved_at"),
            "page_id": _STATUS_PAGE_ID, "components": list(inc.get("components") or []),
            "auto_opened": bool(inc.get("auto_opened")),
            "incident_updates": [dict(u) for u in (inc.get("incident_updates") or [])]}


def _status_create_incident(name, impact, components, body, auto=False, _now=None):
    """Create an incident (admin). Validates impact enum + component ids.
    Returns the incident dict. Raises ValueError on bad input."""
    if impact not in _STATUS_INCIDENT_IMPACTS:
        raise ValueError("invalid impact %r (must be one of %s)" % (impact, "/".join(_STATUS_INCIDENT_IMPACTS)))
    name = str(name or "").strip()[:200]
    if not name:
        raise ValueError("incident name required")
    comps = [c for c in (components or []) if c in _STATUS_COMPONENT_BY_ID]
    if not comps:
        raise ValueError("at least one known component required")
    now = float(_now or time.time())
    inc_id = "inc_" + uuid.uuid4().hex[:12]
    upd = {"id": "upd_" + uuid.uuid4().hex[:12], "incident_id": inc_id,
           "status": "investigating", "body": str(body or "").strip()[:4000] or "Investigating.",
           "created_at": _status_iso(now), "display_at": _status_iso(now), "updated_at": _status_iso(now)}
    inc = {"id": inc_id, "name": name, "status": "investigating", "impact": impact,
           "created_at": _status_iso(now), "updated_at": _status_iso(now), "resolved_at": None,
           "components": comps, "auto_opened": bool(auto), "incident_updates": [upd]}
    with _STATUS_LOCK:
        _status_incidents().append(inc)
        lst = _status_incidents()
        if len(lst) > _STATUS_INCIDENTS_MAX:
            resolved = [i for i in lst if i.get("status") == "resolved"]
            for old in sorted(resolved, key=lambda i: i.get("created_at") or "")[:len(lst) - _STATUS_INCIDENTS_MAX]:
                lst.remove(old)
    _status_save()
    return inc


def _status_add_incident_update(incident_id, status, body, _now=None):
    """Append an update; the update's status becomes the incident status.
    Resolved sets resolved_at. Raises KeyError (unknown id) / ValueError."""
    if status not in _STATUS_INCIDENT_STATUSES:
        raise ValueError("invalid status %r (must be one of %s)" % (status, "/".join(_STATUS_INCIDENT_STATUSES)))
    body = str(body or "").strip()[:4000]
    if not body:
        raise ValueError("update body required")
    now = float(_now or time.time())
    for inc in _status_incidents():
        if inc.get("id") == incident_id:
            upd = {"id": "upd_" + uuid.uuid4().hex[:12], "incident_id": incident_id,
                   "status": status, "body": body,
                   "created_at": _status_iso(now), "display_at": _status_iso(now), "updated_at": _status_iso(now)}
            inc.setdefault("incident_updates", []).append(upd)
            inc["status"] = status
            inc["updated_at"] = _status_iso(now)
            if status == "resolved":
                inc["resolved_at"] = _status_iso(now)
            _status_save()
            return inc
    raise KeyError("unknown incident %r" % (incident_id,))


def _status_resolve_incident(incident_id, body=None, _now=None):
    """Resolve with the canned closing text unless the admin supplies one."""
    return _status_add_incident_update(incident_id, "resolved",
                                       body or _STATUS_INCIDENT_RESOLVED_TEXT, _now=_now)


def _status_create_maintenance(name, scheduled_for, scheduled_until, impact, components, _now=None):
    if impact not in _STATUS_INCIDENT_IMPACTS:
        raise ValueError("invalid impact %r" % (impact,))
    name = str(name or "").strip()[:200]
    if not name:
        raise ValueError("maintenance name required")
    start = _status_parse_iso(scheduled_for)
    end = _status_parse_iso(scheduled_until)
    if start is None or end is None or end <= start:
        raise ValueError("scheduled_for/scheduled_until must be ISO UTC and until > for")
    comps = [c for c in (components or []) if c in _STATUS_COMPONENT_BY_ID]
    if not comps:
        raise ValueError("at least one known component required")
    now = float(_now or time.time())
    m = {"id": "mnt_" + uuid.uuid4().hex[:12], "name": name, "status": "scheduled",
         "impact": impact, "scheduled_for": _status_iso(start), "scheduled_until": _status_iso(end),
         "components": comps, "created_at": _status_iso(now), "updated_at": _status_iso(now)}
    _status_maintenances().append(m)
    _status_save()
    return m


def _status_cancel_maintenance(maint_id, _now=None):
    for m in _status_maintenances():
        if m.get("id") == maint_id:
            if m.get("status") in ("completed", "cancelled"):
                raise ValueError("maintenance already %s" % m.get("status"))
            m["status"] = "cancelled"
            m["updated_at"] = _status_iso(float(_now or time.time()))
            _status_save()
            return m
    raise KeyError("unknown maintenance %r" % (maint_id,))


def _status_paginate(items, page, per_page=50):
    """Newest-first list -> one page. Returns (page_items, total_pages)."""
    try:
        page = int(page or 1)
    except Exception:
        page = 1
    page = max(1, page)
    total_pages = max(1, (len(items) + per_page - 1) // per_page)
    start = (page - 1) * per_page
    return list(items[start:start + per_page]), total_pages


def _status_build_summary(force_probes=False):
    """Full summary payload: live probes -> GATED components (+ honest
    uptime + 90d bars) -> transitions recorded + incidents auto-opened
    -> indicator. A single unconfirmed probe failure never flips a
    component here (see _status_gated_component_states)."""
    probes = _status_run_probes(force=force_probes)
    # v76.1: transitions + indicator use the GATED states; the raw
    # states remain available via _status_component_states for diagnosis.
    components = _status_gated_component_states(probes)
    _status_record_transitions(components)
    now = time.time()
    enriched = []
    for comp in components:
        c = dict(comp)
        u30 = _status_uptime(comp["id"], 30, now)
        u90 = _status_uptime(comp["id"], 90, now)
        c["uptime_30d_pct"] = u30["pct"]
        c["uptime_90d_pct"] = u90["pct"]
        c["uptime_30d_coverage"] = u30["coverage"]
        c["uptime_90d_coverage"] = u90["coverage"]
        c["uptime_measured_from"] = u90["measured_from"]
        c["uptime_bars_90d"] = _status_daily_bars(comp["id"], 90, now)
        enriched.append(c)
    maintenances = [dict(m) for m in _status_maintenances()
                    if m.get("status") in ("scheduled", "in_progress")]
    indicator, desc = _status_page_indicator(components, maintenances, now)
    unresolved = sorted([i for i in _status_incidents() if i.get("status") != "resolved"],
                        key=lambda i: i.get("created_at") or "", reverse=True)
    return {"page": _status_page_info(),
            "status": {"indicator": indicator, "description": desc},
            "components": enriched,
            "incidents": [_status_serialize_incident(i) for i in unresolved],
            "scheduled_maintenances": maintenances,
            "last_checked_at": _status_iso(now)}


