        if path in ("/api/admin/remote_shutdown", "/api/admin/remote-shutdown", "/api/vault/remote_shutdown"):
            # BMRBD v61.15a A15 (STOP): fast + reliable remote stop.
            # (1) The stop flag is written FIRST, before any vault work,
            # so the notebook guardians see the stop even if the flush
            # hangs. (2) The vault flush runs in a background daemon
            # thread (best effort, never blocks the 200 or the exit — the
            # old code ran it synchronously first: up to ~100s of
            # webhook+rclone+kaggle timeouts before the flag was even
            # written, and any exception returned 500 with NO stop at
            # all). (3) The delayed stop sleeps 5s (a head start for the
            # flush), then kills llama-server + ollama + cloudflared
            # (V10-23: llama-server is a detached daemon and would
            # otherwise survive as an orphan) and exits UNCONDITIONALLY:
            # the exit lives in a `finally`, and each pkill is wrapped,
            # so a missing pkill binary can never swallow the exit again.
            if not _require_admin(self):
                return self._send_json(403, {"error": "Admin or master API key required"}, req_id=req_id)
            try:
                stop_flag = Path("/dev/shm/.bmrbd_remote_stop") if Path("/dev/shm").exists() else Path("/tmp/.bmrbd_remote_stop")
                stop_flag.write_text("STOP_REQUESTED_BY_GITHUB_ACTION", encoding="utf-8")
                def _bmrbd_stop_flush_bg():
                    try:
                        sync_bmrbd_vault_to_cloud()
                    except Exception:
                        pass
                threading.Thread(target=_bmrbd_stop_flush_bg, daemon=True).start()
                def _delayed_stop():
                    try:
                        time.sleep(5)
                        _kill_engine_processes()
                    finally:
                        os._exit(0)
                threading.Thread(target=_delayed_stop, daemon=True).start()
                return self._send_json(200, {
                    "ok": True,
                    "status": "shutting_down",
                    "message": "🌙 Stop flag written; vault flush running in the background. Kaggle GPU session stopping in ~5 seconds!"
                }, req_id=req_id)
            except Exception as e:
                return self._send_json(500, {"error": str(e)}, req_id=req_id)

        if path == "/api/sandbox/exec":
            # v61.1 AUTHED sandboxed code runner. Accepts {"code", "lang": "python"}.
            # Runs `python3 <file>` with NO shell, a minimal env (no secrets),
            # a timeout and an output cap. Generated .mp4 files are returned as
            # media URLs. (The old /api/work/exec stays admin-gated below.)
            if not _require_valid_token(self):
                return self._send_json(401, {"error": "Valid token required"}, req_id=req_id)
            try:
                req_j = json.loads(raw_body.decode("utf-8", errors="ignore"))
                code_txt = str(req_j.get("code") or "")
                lang = str(req_j.get("lang") or "python").strip().lower()
                if lang not in ("python", "py"):
                    return self._send_json(400, {"error": "Only lang 'python' is supported"}, req_id=req_id)
                if len(code_txt) > 200000:
                    return self._send_json(400, {"error": "Code exceeds 200000 characters"}, req_id=req_id)
                import tempfile
                sb_dir = Path(tempfile.mkdtemp(prefix="bmrbd_sandbox_"))
                sb_file = sb_dir / "main.py"
                sb_file.write_text(code_txt, encoding="utf-8")
                sb_env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "HOME": str(sb_dir),
                          "LANG": "C.UTF-8", "PYTHONPATH": "", "TMPDIR": str(sb_dir)}
                try:
                    proc = subprocess.run([sys.executable, str(sb_file)],
                                          cwd=str(sb_dir), env=sb_env,
                                          capture_output=True, text=True, timeout=60)
                    out_txt, err_txt = (proc.stdout or "")[:8000], (proc.stderr or "")[:8000]
                    exit_code = proc.returncode
                except subprocess.TimeoutExpired:
                    out_txt, err_txt, exit_code = "", "Sandbox timeout (60s)", 124
                mp4_files = []
                for mp in sorted(sb_dir.rglob("*.mp4")):
                    if mp.is_file() and mp.stat().st_size <= 250 * 1024 * 1024:
                        try:
                            mp4_files.append({"name": mp.name, "bytes": mp.stat().st_size,
                                              "url": save_media_and_get_url(mp.read_bytes(), "mp4", "sandbox")})
                        except Exception:
                            pass
                shutil.rmtree(str(sb_dir), ignore_errors=True)
                return self._send_json(200, {"ok": True, "exit_code": exit_code,
                                              "stdout": out_txt, "stderr": err_txt,
                                              "mp4_files": mp4_files}, req_id=req_id)
            except Exception as e:
                return self._send_json(500, {"error": str(e)}, req_id=req_id)

