        # BMRBD v61.15 WC: POST /api/voice/clean — {"text": "<raw transcript>", "lang": "bn-BD"|"en"|"auto"}
        # -> {"ok": true, "cleaned": "<corrected text>"}. SHORT local-model
        # call (fast effort, tiny max tokens). Token-only
        # (BMRBD v61.18 LOGIN-BRIDGE). NEVER 500s on
        # model failure: returns {"ok": false, "cleaned": <original>} so
        # the UI falls back to sending the raw transcript.
        if path == "/api/voice/clean":
            try: req_j = json.loads(raw_body.decode("utf-8", errors="ignore"))
            except Exception: req_j = {}
            _vc_text = str(req_j.get("text") or "").strip()
            _vc_lang = str(req_j.get("lang") or "auto").strip() or "auto"
            if not _vc_text:
                return self._send_json(400, {"ok": False, "cleaned": "", "error": "text required"}, req_id=req_id)
            if not _require_valid_token(self):
                return self._send_json(401, {"ok": False, "cleaned": _vc_text, "error": "Valid token required"}, req_id=req_id)
            _vc_sys = ("You are a speech-transcript cleaner for BMRBD Ai. The user speaks Bengali (bn-BD) or English; the live speech recogniser often mishears words. Fix only the misheard words using the sentence context, keep the same language as the input, and keep the meaning and the speaker's words. Return ONLY the corrected text — no quotes, no explanation, no extra words.")
            if _vc_lang in ("bn-BD", "bn"):
                _vc_sys += " The input language is Bengali; answer in Bengali."
            elif _vc_lang in ("en", "en-US", "en-GB"):
                _vc_sys += " The input language is English; answer in English."
            else:
                _vc_sys += " The input language is Bengali; answer in Bengali."
