        if path == "/api/fetch-url":
            # BMRBD v61.18 LOGIN-BRIDGE: token-only now.
            if not _require_valid_token(self):
                return self._send_json(401, {"error": "Valid token required"}, req_id=req_id)
            try:
                _fj = json.loads(raw_body.decode("utf-8", errors="ignore"))
                _url = str(_fj.get("url") or "").strip()
                if not _url.startswith(("http://", "https://")):
                    return self._send_json(400, {"error": "URL must start with http:// or https://"}, req_id=req_id)
                _host = urllib.parse.urlparse(_url).hostname or ""
                try:
                    _infos = socket.getaddrinfo(_host, None)
                except Exception:
                    _infos = []
                if not _infos:
                    return self._send_json(400, {"error": "Cannot resolve host"}, req_id=req_id)
                for _fam, _typ, _proto, _canon, _sock in _infos:
                    _ip = ipaddress.ip_address(_sock[0])
                    if _ip.is_private or _ip.is_loopback or _ip.is_link_local or _ip.is_reserved:
                        return self._send_json(400, {"error": "Private/local URLs are not allowed"}, req_id=req_id)
                _req = urllib.request.Request(_url, headers={"User-Agent": "Mozilla/5.0 (BMRBD Ai link preview)"}, method="GET")
                with urllib.request.build_opener(_HarnessRedirectLimiter(3)).open(_req, timeout=10) as _resp:
                    _raw = _resp.read(200 * 1024)
                    try:
                        _fu_ct = str(_resp.headers.get_content_type() or "").lower()
                    except Exception:
                        _fu_ct = ""
                # D3 (v76.5): a file URL used to come back 200 ok:true with
                # raw binary bytes as the "excerpt" (verified live on a PNG:
                # text_len 4360 of PNG bytes). Reject it like web_fetch does.
                _fu_berr = _web_binary_error(_fu_ct, _raw)
                if _fu_berr:
                    return self._send_json(415, {"error": _fu_berr, "content_type": _fu_ct, "suggested_tool": "web_download"}, req_id=req_id)
                _html_txt = _raw.decode("utf-8", errors="ignore")
                _title = ""
                _tm = re.search(r"<title[^>]*>(.*?)</title>", _html_txt, re.I | re.S)
                if _tm:
                    _title = re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", "", _tm.group(1)))).strip()[:120]
                _text = re.sub(r"(?is)<(script|style|nav|header|footer|svg)[^>]*>.*?</\1>", " ", _html_txt)
                _text = re.sub(r"(?is)<[^>]+>", " ", _text)
                _text = re.sub(r"\s+", " ", html.unescape(_text)).strip()
                _links = []
                for _h in re.findall(r'href\s*=\s*["\']([^"\']+)', _html_txt)[:200]:
                    _abs = urllib.parse.urljoin(_url, _h.strip())
                    if _abs.startswith(("http://", "https://")) and _abs not in _links:
                        _links.append(_abs)
                    if len(_links) >= 20:
                        break
                _imgs = []
                for _s in re.findall(r'<img[^>]+src\s*=\s*["\']([^"\']+)', _html_txt, re.I)[:100]:
                    _abs2 = urllib.parse.urljoin(_url, _s.strip())
                    if _abs2.startswith(("http://", "https://")) and _abs2 not in _imgs:
                        _imgs.append(_abs2)
                    if len(_imgs) >= 12:
                        break
                return self._send_json(200, {"ok": True, "url": _url, "title": _title, "excerpt": _text[:6000], "text_len": len(_text), "links": _links, "images": _imgs}, req_id=req_id)
            except Exception as e:
                return self._send_json(500, {"error": str(e)[:200]}, req_id=req_id)

