                                _note = {"id": "chatcmpl-" + uuid.uuid4().hex[:12], "object": "chat.completion.chunk", "created": int(time.time()), "model": requested_model, "choices": [{"index": 0, "delta": {"content": "\n[Note: this reply hit the output limit repeatedly and is still incomplete after %d continuations. The answer above is partial — ask me to continue from a specific point.]" % _HARNESS_MAX_CONTINUE_ROUNDS}, "finish_reason": None}]}
