                                        if _px_chips:
                                            _px_chip_chunk = {"id": "chatcmpl-" + uuid.uuid4().hex[:12], "object": "chat.completion.chunk", "created": int(time.time()), "model": requested_model, "choices": [{"index": 0, "delta": {"content": "\n\n" + _px_chips}, "finish_reason": None}]}
                                            self.wfile.write(("data: %s\n\n" % json.dumps(_px_chip_chunk)).encode("utf-8"))
