                            try:
                                _rj = json.loads(_txt)
                            except Exception:
                                q.put(_txt.encode("utf-8"))
                                return
                            if isinstance(_rj, dict) and _rj.get("error"):
                                q.put(_txt.encode("utf-8"))
                                return
                            _ch = ((_rj.get("choices") or [{}])[0] or {})
                            _msg = _ch.get("message") or {}
                            _content = str(_msg.get("content") or "")
                            _fr = _ch.get("finish_reason")
                            _tcalls = _msg.get("tool_calls")
                            # Server-side leak strip on the visible content.
